-- ============================================================================
-- Axessyo · Procédures de test détaillées (méthodologie officielle)
-- ----------------------------------------------------------------------------
-- Ajoute la colonne `criteria.test_procedures` (jsonb) : pour chaque critère,
-- un objet { reference -> procédure markdown détaillée }.
--
--   - RGAA 4.1.2  : clé = numéro de test ("1.1.1")  · source DISIC (Etalab 2.0)
--   - RAWeb 1.1   : clé = numéro de test ("1.1.1")  · source SIP Luxembourg
--   - RAAM 1.1    : clé = numéro de critère ("1.1")  · source SIP Luxembourg
--   - WCAG 2.2    : pas de procédure numérotée → l'"Intent" reste dans
--                   `methodology` (cf. migration 12), l'UI l'affiche en repli.
--
-- Données = markdown (listes numérotées, sous-puces, `code`, **gras**, liens).
-- Le rendu côté UI nettoie/formate ce markdown.
--
-- Idempotent · généré par .tmp-ref/gen-migration.mjs (ne pas éditer à la main).
-- ============================================================================

begin;

alter table public.criteria
  add column if not exists test_procedures jsonb;

-- ============================================================================
-- RGAA 4.1.2
-- ============================================================================

update public.criteria set test_procedures = '{"1.1.1":"1. Retrouver dans le document les images structurées au moyen d’un élément `<img>` ou d’un élément possédant l’attribut WAI-ARIA `role=\"img\"` ;\n2. Pour chaque image, déterminer si l’image est porteuse d’information ;\n3. Dans le cas où il s’agit d’un élément `<img>`, vérifier que l’image est pourvue au moins d’une alternative textuelle parmi les suivantes :\n   - Passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - Contenu de l’attribut WAI-ARIA `aria-label` ;\n   - Contenu de l’attribut `alt` ;\n   - Contenu de l’attribut `title`.\n4. Dans le cas où il s’agit d’un élément possédant l’attribut WAI-ARIA `role=\"img\"`, vérifier que l’image est pourvue au moins d’une alternative textuelle parmi les suivantes :\n   - Passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - Contenu de l’attribut WAI-ARIA `aria-label`.\n5. Si au moins une alternative textuelle est trouvée, **le test est validé**.\n","1.1.2":"1. Retrouver dans le document les éléments `<area>` ;\n2. Pour chaque élément `<area>`, déterminer si la zone réactive est porteuse d’information ;\n3. Vérifier que la zone réactive est pourvue au moins d’une alternative textuelle parmi les suivantes :\n   - Contenu de l’attribut WAI-ARIA `aria-label` ;\n   - Contenu de l’attribut `alt` ;\n4. Si au moins une alternative textuelle est trouvée, **le test est validé**.\n","1.1.3":"1. Retrouver dans le document les éléments `<input>` pourvus de l’attribut `type=\"image\"` ;\n2. Pour chaque élément `<input>` pourvu de l’attribut type=\"image\", déterminer si l’image utilisée est porteuse d’information ;\n3. Vérifier que l’élément `<input>` est pourvu au moins d’une alternative textuelle parmi les suivantes :\n   - Passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - Contenu de l’attribut WAI-ARIA `aria-label` ;\n   - Contenu de l’attribut `alt` ;\n   - Contenu de l’attribut `title`.\n4. Si au moins une alternative textuelle est trouvée, **le test est validé**.\n","1.1.4":"1. Retrouver dans le document les éléments `<img>` pourvus de l’attribut `ismap` ;\n2. Pour chaque élément `<img>` pourvu de l’attribut `ismap`, vérifier la présence d’un lien ou d’un ensemble de liens (ou bien d’un autre type de composant d’interface qui jouerait un rôle similaire comme une liste de sélection, par exemple) permettant d’accéder aux mêmes ressources que lorsque l’image fait l’objet d’un clic.\n3. Si c’est le cas, **le test est validé**.\n","1.1.5":"1. Retrouver dans le document les éléments `<svg>` ;\n2. Pour chaque élément `<svg>`, déterminer si l’image est porteuse d’information ;\n3. S’assurer que l’élément `<svg>` est pourvu d’un attribut WAI-ARIA `role=\"img\"` ;\n4. Si ce n’est pas le cas, le test est invalidé.\n5. Le cas échéant, vérifier que l’élément `<svg>` est pourvu au moins d’une alternative textuelle parmi les suivantes :\n   - Contenu de l’élément `<title>` ;\n   - Passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - Contenu de l’attribut WAI-ARIA `aria-label` ;\n6. Si au moins une alternative textuelle est trouvée, **le test est validé**.\n","1.1.6":"1. Retrouver dans le document les balises ouvrantes `<object>` pourvues de l''attribut `type=\"image/…\"` ;\n2. Pour chaque balise ouvrante `<object>` pourvue de l''attribut `type=\"image/…\"`, déterminer si l’image utilisée est porteuse d''information ;\n3. Vérifier que l’élément `<object>` est pourvu d’un attribut WAI-ARIA `role=\"img\"` ;\n4. Vérifier que l’élément `<object>` est pourvu au moins d’une alternative textuelle parmi les suivantes :\n   - Passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - Contenu de l’attribut WAI-ARIA `aria-label` ;\n   - Contenu de l’attribut `title`.\n5. Si au moins une alternative textuelle est trouvée, **le test est validé** ;\n6. Sinon, vérifier que l''élément `<object>` est :\n   - Soit immédiatement suivi d''un lien ou bouton adjacent permettant d''accéder à un contenu alternatif ;\n   - Soit un mécanisme permet à l''utilisateur de remplacer l''élément `<object>` par un contenu alternatif.\n7. Si c''est le cas, **le test est validé**.\n","1.1.7":"1. Pour chaque élément `<embed>` pourvu de l’attribut `type=\"image/…\"`, déterminer si l’image utilisée est porteuse d’information ;\n2. Vérifier que l’élément `<embed>` est pourvu d’un attribut WAI-ARIA `role=\"img\"` ;\n3. Vérifier que l’élément `<embed>` est pourvu au moins d’une alternative textuelle parmi les suivantes :\n   - Passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - Contenu de l’attribut WAI-ARIA `aria-label` ;\n   - Contenu de l’attribut `title`.\n4. Si au moins une alternative textuelle est trouvée, **le test est validé** ;\n5. Sinon, vérifier que l’élément `<embed>` est :\n   - Soit immédiatement suivi d’un lien ou bouton adjacent permettant d’accéder à un contenu alternatif ;\n   - Soit un mécanisme permet à l’utilisateur de remplacer l’élément `<embed>` par un contenu alternatif.\n6. Si c’est le cas, **le test est validé**.\n","1.1.8":"1. Retrouver dans le document les éléments `<canvas>` ;\n2. Pour chaque élément `<canvas>`, déterminer si l’image utilisée est porteuse d’information ;\n3. Vérifier que l’élément `<canvas>` est pourvu d’un attribut WAI-ARIA `role=\"img\"` ;\n4. Vérifier que la balise ouvrante `<canvas>` est pourvue au moins d’une alternative textuelle parmi les suivantes :\n   - Passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - Contenu de l’attribut WAI-ARIA `aria-label`.\n5. Si au moins une alternative textuelle est trouvée, **le test est validé**.\n6. Si les étapes 3 et 4 ne sont pas satisfaites, vérifier que l’élément `<canvas>` est :\n   - Soit pourvu d’un contenu alternatif présent entre les balises `<canvas>` et `</canvas>` ;\n   - Soit immédiatement suivi d’un lien ou bouton adjacent permettant d’accéder à un contenu alternatif ;\n   - Soit un mécanisme permet à l’utilisateur de remplacer l’élément `<canvas>` par un contenu alternatif.\n7. Si c’est le cas, **le test est validé**.\n\nNote : si l''élément `<canvas>` dispose d''un rôle `img`, son alternative ne peut  être fournie que par les techniques listées à l''étape 4.\n"}'::jsonb
where identifier = '1.1' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"1.2.1":"1. Retrouver dans le document les images décoratives dépourvues de légende structurées au moyen d’un élément `<img>` ;\n2. Pour chaque image, vérifier que l’image ne possède pas d’attributs `aria-labelledby`, `aria-label` ou `title` et qu’elle possède :\n   - Soit un attribut `alt` vide (`alt=\"\"`) ;\n   - Soit un attribut WAI-ARIA `aria-hidden=\"true\"` ou `role=\"presentation\"`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.2.2":"1. Retrouver dans le document les images décoratives structurées au moyen d’un élément `<area>` (sans attribut `href`) ;\n2. Pour chaque image, vérifier que l’élément `<area>` ne possède pas d’attributs `aria-labelledby`, `aria-label` ou `title` et qu’il possède :\n   - Soit un attribut `alt` vide (`alt=\"\"`) ;\n   - Soit un attribut WAI-ARIA `aria-hidden=\"true\"` ou `role=\"presentation\"`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.2.3":"1. Retrouver dans le document les images décoratives structurées dépourvues de légende au moyen d’un élément `<object>` (avec un attribut `type=\"image/…\"`) ;\n2. Pour chaque image, vérifier que la balise ouvrante `<object>` ne possède pas d’attributs `aria-labelledby`, `aria-label` ou `title` et qu’elle :\n   - Possède un attribut WAI-ARIA `aria-hidden=\"true\"` ;\n   - Et est dépourvue d’alternative textuelle ;\n   - Et est dépourvue d’un contenu alternatif présent entre les balises `<object>` et `</object>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.2.4":"1. Retrouver dans le document les images décoratives dépourvues de légende structurées au moyen d’un élément `<svg>` ;\n2. Pour chaque image, vérifier que l’élément `<svg>` ne possède pas d’attributs `aria-labelledby` ou `aria-label` et qu’il :\n   - Possède un attribut WAI-ARIA `aria-hidden=\"true\"` ;\n   - Et est dépourvu d’alternative textuelle (ainsi que ses éléments enfants) ;\n   - Et ne contient pas d’éléments `<title>` et `<desc>` à moins que vides de contenu ;\n   - Et est dépourvu d’attribut `title` (ainsi que ses éléments enfants).\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.2.5":"1. Retrouver dans le document les images décoratives dépourvues de légende structurées au moyen d’un élément `<canvas>` ;\n2. Pour chaque image, vérifier que l’élément `<canvas>` ne possède pas d’attributs `aria-labelledby`, `aria-label` ou `title` et qu’il :\n   - Possède un attribut WAI-ARIA `aria-hidden=\"true\"` ;\n   - Et est dépourvu d’alternative textuelle ;\n   - Et est dépourvu d’un contenu alternatif présent entre les balises `<canvas>` et `</canvas>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.2.6":"1. Retrouver dans le document les images décoratives dépourvues de légende structurées au moyen d’un élément `<embed>` (avec un attribut `type=\"image/…\"`) ;\n2. Pour chaque image, vérifier que l’élément `<embed>` ne possède pas d’attributs `aria-labelledby`, `aria-label` ou `title` et qu’il :\n   - Possède un attribut WAI-ARIA `aria-hidden=\"true\"` ;\n   - Et est dépourvu d’alternative textuelle ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.2' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"1.3.1":"1. Retrouver dans le document les images structurées au moyen d’un élément `<img>` (ou d’un élément possédant l’attribut WAI-ARIA `role=\"img\"`) pourvues d’une alternative textuelle ;\n2. Pour chaque image, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.2":"1. Retrouver dans le document les éléments `<area>` pourvus d’une alternative textuelle ;\n2. Pour chaque élément `<area>`, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.3":"1. Retrouver dans le document les éléments `<input>` pourvus de l’attribut `type=\"image\"` et d’une alternative textuelle ;\n2. Pour chaque élément `<input>` pourvu de l’attribut `type=\"image\"`, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.4":"1. Retrouver dans le document les éléments `<object>` pourvus de l’attribut `type=\"image/…\"` et d’une alternative textuelle ;\n2. Pour chaque élément `<object>` pourvu de l’attribut `type=\"image/…\"`, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.5":"1. Retrouver dans le document les éléments `<embed>` pourvus de l’attribut `type=\"image/…\"` et d’une alternative textuelle ;\n2. Pour chaque élément `<embed>` pourvu de l’attribut `type=\"image/…\"`, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.6":"1. Retrouver dans le document les éléments `<svg>` pourvus d’une alternative textuelle ;\n2. Pour chaque élément `<svg>`, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.7":"1. Retrouver dans le document les éléments `<canvas>` pourvus d’une alternative textuelle ;\n2. Pour chaque élément `<canvas>`, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.8":"1. Retrouver dans le document les éléments `<canvas>` pourvus d’un contenu alternatif entre les balises `<canvas>` et `</canvas>` ;\n2. Pour chaque élément `<canvas>`, vérifier que le contenu alternatif est correctement restitué par les technologies d’assistance ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.9":"1. Retrouver dans le document les images pourvues d’une alternative textuelle ;\n2. Pour chaque image, vérifier l’alternative textuelle est courte et concise ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.3' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"1.4.1":"1. Retrouver dans le document les images structurées au moyen d’un élément `<img>` pourvues d’une alternative textuelle et utilisées comme CAPTCHA ou comme image-test ;\n2. Pour chaque image, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.4.2":"1. Retrouver dans le document les éléments `<area>` pourvus d’une alternative textuelle et utilisés comme CAPTCHA ou comme image-test ;\n2. Pour chaque élément `<area>`, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.4.3":"1. Retrouver dans le document les éléments `<input>` pourvus de l’attribut `type=\"image\"` et d’une alternative textuelle, et utilisés comme CAPTCHA ou comme image-test ;\n2. Pour chaque élément `<input>` pourvu de l’attribut `type=\"image\"`, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.4.4":"1. Retrouver dans le document les éléments `<object>` pourvus de l’attribut `type=\"image/…\"` et d’une alternative textuelle, et utilisés comme CAPTCHA ou comme image-test ;\n2. Pour chaque élément `<object>` pourvu de l’attribut `type=\"image/…\"`, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.4.5":"1. Retrouver dans le document les éléments `<embed>` pourvus de l’attribut `type=\"image/…\"` et d’une alternative textuelle, et utilisés comme CAPTCHA ou comme image-test ;\n2. Pour chaque élément `<embed>` pourvu de l’attribut `type=\"image/…\"`, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.4.6":"1. Retrouver dans le document les éléments `<svg>` pourvus d’une alternative textuelle et utilisés comme CAPTCHA ou comme image-test ;\n2. Pour chaque élément `<svg>`, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.4.7":"1. Retrouver dans le document les éléments `<canvas>` pourvus d’une alternative textuelle et utilisés comme CAPTCHA ou comme image-test ;\n2. Pour chaque élément `<canvas>`, vérifier que l’alternative textuelle est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.4' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"1.5.1":"1. Retrouver dans le document les images (éléments `<img>`, `<area>`, `<object>`, `<embed>`, `<svg>`, `<canvas>` ou possédant un attribut WAI-ARIA `role=\"img\"`) utilisés comme CAPTCHA ou comme image-test ;\n2. Pour chaque image, vérifier qu’il existe :\n   - Soit une autre forme de CAPTCHA non graphique, au moins ;\n   - Soit une autre solution d’accès à la fonctionnalité qui est sécurisée par le CAPTCHA.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.5.2":"1. Retrouver dans le document les boutons associés à une image (éléments `<input>` avec l’attribut `type=\"image\"`) utilisés comme CAPTCHA ou comme image-test ;\n2. Pour chaque bouton associé à une image, vérifier qu’il existe :\n   - Soit une autre forme de CAPTCHA non graphique, au moins ;\n   - Soit une autre solution d’accès à la fonctionnalité qui est sécurisée par le CAPTCHA.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.5' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"1.6.1":"1. Retrouver dans le document les images structurées au moyen d’un élément `<img>` (ou d’un élément possédant l’attribut WAI-ARIA `role=\"img\"`) porteuses d’information qui nécessitent une description détaillée ;\n2. Pour chaque image, vérifier qu’il existe :\n   - Soit un attribut longdesc qui donne l’adresse (url) d’une page ou d’un emplacement dans la page contenant la description détaillée ;\n   - Soit une alternative textuelle contenant la référence à une description détaillée adjacente à l’image ;\n   - Soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.6.2":"1. Retrouver dans le document les éléments `<object>` pourvus de l’attribut `type=\"image/…\"`, porteurs d’information qui nécessitent une description détaillée ;\n2. Pour chaque élément `<object>` pourvu de l’attribut `type=\"image/…\"`, vérifier qu’il existe :\n   - Soit une alternative textuelle contenant la référence à une description détaillée adjacente à l’image ;\n   - Soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée.\n3. Si c’est le cas pour chaque élément `<object>` pourvu de l’attribut `type=\"image/…\"`, **le test est validé**.\n","1.6.3":"1. Retrouver dans le document les éléments `<embed>` pourvus de l’attribut `type=\"image/…\"`, porteurs d’information qui nécessitent une description détaillée ;\n2. Pour chaque élément `<embed>` pourvu de l’attribut `type=\"image/…\"`, vérifier qu’il existe :\n   - Soit une alternative textuelle contenant la référence à une description détaillée adjacente à l’image ;\n   - Soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée.\n3. Si c’est le cas pour chaque élément `<embed>` pourvu de l’attribut `type=\"image/…\"`, **le test est validé**.\n","1.6.4":"1. Retrouver dans le document les éléments `<input>` pourvus de l’attribut `type=\"image\"`, porteurs d’information qui nécessitent une description détaillée ;\n2. Pour chaque élément `<input>` pourvu de l’attribut `type=\"image\"`, vérifier qu’il existe :\n   - Soit une alternative textuelle contenant la référence à une description détaillée adjacente à l’image ;\n   - Soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée ;\n   - Soit un attribut WAI-ARIA aria-describedby associant un passage de texte faisant office de description détaillée.\n3. Si c’est le cas pour chaque élément `<input>` pourvu de l’attribut `type=\"image\"`, **le test est validé**.\n","1.6.5":"1. Retrouver dans le document les éléments `<svg>` porteurs d’information qui nécessitent une description détaillée ;\n2. Pour chaque élément `<svg>`, vérifier qu’il existe :\n   - Soit un attribut WAI-ARIA `aria-label` contenant l’alternative textuelle et une référence à une description détaillée adjacente ;\n   - Soit un attribut WAI-ARIA `aria-labelledby` associant un passage de texte faisant office d’alternative textuelle et un autre faisant office de description détaillée ;\n   - Soit un attribut WAI-ARIA `aria-describedby` associant un passage de texte faisant office de description détaillée ;\n   - Soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée.\n3. Si c’est le cas pour chaque élément `<svg>`, **le test est validé**.\n","1.6.6":"1. Retrouver dans le document les éléments `<svg>` porteurs d’information dont la description détaillée est fournie au moyen d’un attribut `aria-label`, `aria-labelledby` ou `aria-describedby` ;\n2. Pour chaque élément `<svg>`, vérifier que le contenu de la description détaillée est correctement restitué par les technologies d’assistance ;\n3. Si c’est le cas pour chaque élément `<svg>`, **le test est validé**.\n","1.6.7":"1. Retrouver dans le document les éléments `<canvas>` porteurs d’information qui nécessitent une description détaillée ;\n2. Pour chaque élément `<canvas>`, vérifier qu’il existe :\n   - Soit un attribut WAI-ARIA aria-label contenant l’alternative textuelle et une référence à une description détaillée adjacente ;\n   - Soit un attribut WAI-ARIA aria-labelledby associant un passage de texte faisant office d’alternative textuelle et un autre faisant office de description détaillée ;\n   - Soit un contenu textuel entre `<canvas>` et `</canvas>` faisant référence à une description détaillée adjacente à l’image bitmap ;\n   - Soit un contenu textuel entre `<canvas>` et `</canvas>` faisant office de description détaillée ;\n   - Soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée.\n3. Si c’est le cas pour chaque élément `<canvas>`, **le test est validé**.\n","1.6.8":"1. Retrouver dans le document les éléments `<canvas>` porteurs d’information dont la description détaillée est fournie au moyen d’un attribut `aria-label`, `aria-labelledby` ou `aria-describedby` ;\n2. Pour chaque élément `<canvas>`, vérifier que le contenu de la description détaillée est correctement restitué par les technologies d’assistance ;\n3. Si c’est le cas pour chaque élément `<canvas>`, **le test est validé**.\n","1.6.9":"1. Retrouver dans le document les images (éléments `<img>`, `<input>` avec l’attribut `type=\"image\"`, `<area>`, `<object>`, `<embed>`, `<svg>`, `<canvas>` ou possédant un attribut WAI-ARIA `role=\"img\"`) porteuses d’information dont la description détaillée utilise un attribut WAI-ARIA `aria-describedby` ;\n2. Pour chaque image, vérifier que le contenu de la description détaillée est correctement restitué par les technologies d’assistance ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.6.10":"1. Retrouver dans le document les éléments pourvus d’un attribut WAI-ARIA `role=\"img\"` porteurs d’information qui nécessitent une description détaillée ;\n2. Pour chaque élément `role=\"img\"`, vérifier qu’il existe :\n   - Soit un attribut WAI-ARIA `aria-label` contenant l’alternative textuelle et une référence à une description détaillée adjacente ;\n   - Soit un attribut WAI-ARIA `aria-labelledby` associant un passage de texte faisant office d’alternative textuelle et un autre faisant office de description détaillée ;\n   - Soit un attribut WAI-ARIA `aria-describedby` associant un passage de texte faisant office de description détaillée ;\n   - Soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée.\n3. Si c’est le cas pour chaque élément `role=\"img\"`, **le test est validé**.\n"}'::jsonb
where identifier = '1.6' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"1.7.1":"1. Retrouver dans le document les images structurées au moyen d’un élément `<img>` qui possèdent une description détaillée ;\n2. Pour chaque image, vérifier que la description détaillée est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.7.2":"1. Retrouver dans le document les éléments `<input>` pourvus de l’attribut `type=\"image\"` qui possèdent une description détaillée ;\n2. Pour chaque élément `<input>` pourvu de l’attribut `type=\"image\"`, vérifier que la description détaillée est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.7.3":"1. Retrouver dans le document les éléments `<object>` pourvus de l’attribut `type=\"image/…\"` qui possèdent une description détaillée ;\n2. Pour chaque élément `<object>` pourvu de l’attribut `type=\"image/…\"`, vérifier que la description détaillée est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.7.4":"1. Retrouver dans le document les éléments `<embed>` pourvus de l’attribut `type=\"image/…\"` qui possèdent une description détaillée ;\n2. Pour chaque élément `<embed>` pourvu de l’attribut `type=\"image/…\"`, vérifier que la description détaillée est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.7.5":"1. Retrouver dans le document les éléments `<svg>` qui possèdent une description détaillée ;\n2. Pour chaque élément `<svg>`, vérifier que la description détaillée est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.7.6":"1. Retrouver dans le document les éléments `<canvas>` qui possèdent une description détaillée ;\n2. Pour chaque élément `<canvas>`, vérifier que la description détaillée est pertinente ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.7' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"1.8.1":"1. Retrouver dans le document les images texte structurées au moyen d’un élément `<img>` (ou d’un élément possédant l’attribut WAI-ARIA `role=\"img\"`) ;\n2. Pour chaque image, vérifier que :\n   - Soit il existe un mécanisme de remplacement ;\n   - Soit l’image contient un texte qui fait appel à un effet graphique qui ne peut pas être reproduit en CSS.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.8.2":"1. Retrouver dans le document les boutons “images texte” (élément `<input>` avec l’attribut `type=\"image\"`) ;\n2. Pour chaque image, vérifier que :\n   - Soit il existe un mécanisme de remplacement ;\n   - Soit l’image contient un texte qui fait appel à un effet graphique qui ne peut pas être reproduit en CSS.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.8.3":"1. Retrouver dans le document les images texte objet (élément `<object>` avec l’attribut `type=\"image/…\"`) ;\n2. Pour chaque image, vérifier que :\n   - Soit il existe un mécanisme de remplacement ;\n   - Soit l’image contient un texte qui fait appel à un effet graphique qui ne peut pas être reproduit en CSS.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.8.4":"1. Retrouver dans le document les images texte embarquées (élément `<embed>` avec l’attribut `type=\"image/…\"`) ;\n2. Pour chaque image, vérifier que :\n   - Soit il existe un mécanisme de remplacement ;\n   - Soit l’image contient un texte qui fait appel à un effet graphique qui ne peut pas être reproduit en CSS.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.8.5":"1. Retrouver dans le document les images texte bitmap (élément `<canvas>`) ;\n2. Pour chaque image, vérifier que :\n   - Soit il existe un mécanisme de remplacement ;\n   - Soit l’image contient un texte qui fait appel à un effet graphique qui ne peut pas être reproduit en CSS.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.8.6":"1. Retrouver dans le document les images texte vectorielle (élément `<svg>`) porteuse d’information et dont le texte n’est pas complètement structuré au moyen d’éléments `<text>` ;\n2. Pour chaque image, vérifier que :\n   - Soit il existe un mécanisme de remplacement ;\n   - Soit l’image contient un texte qui fait appel à un effet graphique qui ne peut pas être reproduit en CSS.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.8' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"1.9.1":"1. Retrouver dans le document les images pourvues d’une légende structurées au moyen d’élément `<img>`, d’un élément `<input>` avec l’attribut `type=\"image\"` ou d’un élément possédant l’attribut WAI-ARIA `role=\"img\"` ;\n2. Pour chaque image, vérifier que :\n   - L’image et sa légende sont contenues dans une balise `<figure>` ;\n   - La balise `<figure>` possède une propriété WAI-ARIA `role=\"figure\"` ou `role=\"group\"` ;\n   - La balise `<figure>` possède un attribut WAI-ARIA `aria-label` dont le contenu est identique au contenu de la légende ;\n   - La légende est contenue dans une balise `<figcaption>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.9.2":"1. Retrouver dans le document les images objet pourvues d’une légende (élément `<object>` avec l’attribut `type=\"image/…\"`) ;\n2. Pour chaque image, vérifier que :\n   - L’image et sa légende sont contenues dans une balise `<figure>` ;\n   - La balise `<figure>` possède une propriété WAI-ARIA `role=\"figure`\" ou `role=\"group\"` ;\n   - La balise `<figure>` possède un attribut WAI-ARIA `aria-label` dont le contenu est identique au contenu de la légende ;\n   - La légende est contenue dans une balise `<figcaption>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.9.3":"1. Retrouver dans le document les images embarquées pourvues d’une légende (élément `<embed>` avec l’attribut `type=\"image/…\"`) ;\n2. Pour chaque image, vérifier que :\n   - L’image et sa légende sont contenues dans une balise `<figure>` ;\n   - La balise `<figure>` possède une propriété WAI-ARIA `role=\"figure\"` ou `role=\"group\"` ;\n   - La balise `<figure>` possède un attribut WAI-ARIA `aria-label` dont le contenu est identique au contenu de la légende ;\n   - La légende est contenue dans une balise `<figcaption>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.9.4":"1. Retrouver dans le document les images vectorielles pourvues d’une légende (élément `<svg>`) ;\n2. Pour chaque image, vérifier que :\n   - L’image et sa légende sont contenues dans une balise `<figure>` ;\n   - La balise `<figure>` possède une propriété WAI-ARIA `role=\"figure\"` ou `role=\"group\"` ;\n   - La balise `<figure>` possède un attribut WAI-ARIA `aria-label` dont le contenu est identique au contenu de la légende ;\n   - La légende est contenue dans une balise `<figcaption>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.9.5":"1. Retrouver dans le document les images bitmap (élément `<canvas>`) ;\n2. Pour chaque image, vérifier que :\n   - L’image et sa légende sont contenues dans une balise `<figure>` ;\n   - La balise `<figure>` possède une propriété WAI-ARIA `role=\"figure\"` ou `role=\"group\"` ;\n   - La balise `<figure>` possède un attribut WAI-ARIA `aria-label` dont le contenu est identique au contenu de la légende ;\n   - La légende est contenue dans une balise `<figcaption>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.9' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.1.1":"1. Vérifier l’absence des éléments de présentation `<basefont>`, `<big>`, `<blink>`, `<center>`, `<font>`, `<marquee>`, `<s>`, `<strike>`, `<tt>` ;\n2. Vérifier l’absence de l’élément `<u>` uniquement si le DOCTYPE du document ne correspond pas à HTML 5 ;\n3. Si c’est le cas, **le test est validé**.\n","10.1.2":"1. Vérifier l’absence des attributs de présentation : `align`, `alink`, `background`, `bgcolor`, `border`, `cellpadding`, `cellspacing`, `char`, `charoff`, `clear`, `color`, `compact`, `frameborder`, `hspace`, `link`, `marginheight`, `marginwidth`, `text`, `valign`, `vlink`, `vspace`, `size`(exception faite de l''élément `<select>`), `width` (exception faite des éléments `<img>`, `<object>`, `<embed>`, `<canvas>` et `<svg>`), `height` (exception faite des éléments `<img>`, `<object>`, `<embed>`, `<canvas>` et `<svg>`) ;\n2. Si c’est le cas, **le test est validé**.\n","10.1.3":"1. Désactiver les styles (CSS) du document ;\n2. Vérifier l’absence d’espaces utilisées :\n   - Entre les lettres d’un mot ;\n   - Pour créer des effets de marges ou d’alignement ;\n   - Pour simuler des tableaux ou des colonnes.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '10.1' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.10.1":"1. Retrouver dans le document les informations d’un texte données par la forme, la taille ou la position ;\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier que le moyen alternatif de récupérer cette information est pertinent, c’est-à-dire qu’il permet de transmettre l’information dans tous les contextes de consultation et pour tous les utilisateurs.\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","10.10.2":"1. Retrouver dans le document les informations d’une image données par la forme, la taille ou la position ;\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier que le moyen alternatif de récupérer cette information est pertinent, c’est-à-dire qu’il permet de transmettre l’information dans tous les contextes de consultation et pour tous les utilisateurs.\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","10.10.3":"1. Retrouver dans le document les informations d’un média temporel données par la forme, la taille ou la position ;\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier que le moyen alternatif de récupérer cette information est pertinent, c’est-à-dire qu’il permet de transmettre l’information dans tous les contextes de consultation et pour tous les utilisateurs.\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","10.10.4":"1. Retrouver dans le document les informations d’un média non temporel données par la forme, la taille ou la position ;\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier que le moyen alternatif de récupérer cette information est pertinent, c’est-à-dire qu’il permet de transmettre l’information dans tous les contextes de consultation et pour tous les utilisateurs.\n3. Si c’est le cas pour chaque information, **le test est validé**.\n"}'::jsonb
where identifier = '10.10' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.11.1":"1. Retrouver dans le document si son contenu est conçu pour défiler verticalement (le sens de lecture du texte est horizontal), les informations et fonctionnalités ;\n2. Réduire la fenêtre d’affichage à une largeur de 320 px et vérifier que les informations et les fonctionnalités restent disponibles sans aucun défilement horizontal ;\n3. Si c’est le cas, **le test est validé**.\n","10.11.2":"1. Retrouver dans le document si son contenu est conçu pour défiler horizontalement (le sens de lecture du texte est vertical), les informations et fonctionnalités ;\n2. Réduire la fenêtre d’affichage à une hauteur de 256 px et vérifier que les informations et les fonctionnalités restent disponibles sans aucun défilement vertical ;\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '10.11' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.12.1":"1. Modifier les styles du document en donnant :\n   - Une valeur de 1.5 à la propriété `line-height` de tous les éléments du document ;\n   - Une valeur de 2em à la propriété `margin-bottom` des éléments `<p>` ;\n   - Une valeur de 0.12em à la propriété `letter-spacing` de tous les éléments du document ;\n   - Une valeur de 0.16em à la propriété `word-spacing` de tous les éléments du document ;\n2. Pour chaque passage de texte, vérifier qu’il reste lisible, à l’exception :\n   - Des sous-titres directement intégrés à une vidéo ;\n   - Des images texte ;\n   - Des textes au sein d’une balise `<canvas>`.\n3. Si c’est le cas pour chaque passage de texte, **le test est validé**.\n\nNote : une implémentation de ces règles de modification est disponible dans les ressources du critère de succès WCAG 1.4.12 (https://github.com/alastc/adaptation-scripts/blob/master/scripts/text-adaptation.js).\n"}'::jsonb
where identifier = '10.12' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.13.1":"1. Retrouver dans le document les contenus additionnels devenant visible à la prise de focus ou au survol d’un composant d’interface, à l’exception :\n   - Des contenus additionnels contrôlés par l’agent utilisateur (par exemple, les infobulles associées à l’attribut `title` ou à la validation native d’un formulaire ;\n   - Des contenus additionnels devenant visibles par une activation de l’utilisateur (par exemple, une fenêtre de dialogue).\n2. Pour chaque contenu additionnel, vérifier que :\n   - Soit le contenu additionnel est positionné de façon à ce qu’il ne gêne pas la consultation des autres contenus informatifs sur lesquels il viendrait se superposer (y compris le composant d’interface qui a déclenché son apparition), quelles que soient les conditions de consultation (y compris lors de l’utilisation d’un mécanisme de zoom) ;\n   - Soit un mécanisme (au clavier) permet de faire disparaître le contenu additionnel (par exemple, la touche Echap).\n3. Si c’est le cas pour chaque contenu additionnel, **le test est validé**.\n","10.13.2":"1. Retrouver dans le document les contenus additionnels devenant visible au survol d’un composant d’interface, à l’exception :\n   - Des contenus additionnels contrôlés par l’agent utilisateur (par exemple, les infobulles associées à l’attribut title ou à la validation native d’un formulaire) ;\n   - Des contenus additionnels devenant visibles par une activation de l’utilisateur (par exemple, une fenêtre de dialogue).\n2. Pour chaque contenu additionnel, vérifier qu’il peut être survolé par le pointeur de la souris sans disparaître ;\n3. Si c’est le cas pour chaque contenu additionnel, **le test est validé**.\n","10.13.3":"1. Retrouver dans le document les contenus additionnels devenant visible à la prise de focus ou au survol d’un composant d’interface, à l’exception :\n   - Des contenus additionnels contrôlés par l’agent utilisateur (par exemple, les infobulles associées à l’attribut `title` ou à la validation native d’un formulaire) ;\n   - Des contenus additionnels devenant visibles par une activation de l’utilisateur (par exemple, une fenêtre de dialogue).\n2. Pour chaque contenu additionnel, vérifier qu’il reste visible :\n   - Jusqu’à ce que l’utilisateur retire le pointeur souris ou le focus du contenu additionnel ou du composant d’interface ayant déclenché son apparition ;\n   - Jusqu’à ce l’utilisateur déclenche le mécanisme prévu pour faire disparaître le contenu additionnel ;\n   - Jusqu’à ce que l’information proposée par le contenu additionnel ne soit plus valide (par exemple un contenu additionnel signalant l’état “occupé” du composant d’interface que l’utilisateur souhaite activer ou encore un message d’erreur signalé sous la forme d’un contenu additionnel tant que l’utilisateur n’a pas rectifié sa saisie).\n3. Si c’est le cas pour chaque contenu additionnel, **le test est validé**.\n"}'::jsonb
where identifier = '10.13' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.14.1":"1. Retrouver dans le document les contenus additionnels devenant visible au survol d’un composant d’interface au moyen d’un mécanisme CSS (`pseudo-classe :hover`) ;\n2. Pour chaque contenu additionnel, vérifier que les contenus additionnels apparaissent également :\n   - À l’activation du composant au moyen du clavier ou de tout autre dispositif de pointage ;\n   - À la prise de focus du composant ;\n   - À l’activation ou à la prise de focus d’un autre composant.\n3. Si c’est le cas pour chaque contenu additionnel, **le test est validé**.\n","10.14.2":"1. Retrouver dans le document les contenus additionnels devenant visible à la prise de focus d’un composant d’interface au moyen d’un mécanisme CSS (`pseudo-classe :focus`) ;\n2. Pour chaque contenu additionnel, vérifier que les contenus additionnels apparaissent également :\n\n- À l’activation du composant au moyen du clavier ou de tout autre dispositif de pointage ;\n- Au survol du composant ;\n- À l’activation ou du survol d’un autre composant.\n\n3. Si c’est le cas pour chaque contenu additionnel, **le test est validé**.\n"}'::jsonb
where identifier = '10.14' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.2.1":"1. Désactiver les styles (CSS) du document ;\n2. Comparer le document dépourvu de styles avec le document mis en forme ;\n3. Vérifier si dans le document dépourvu de styles, les contenus visibles porteurs d''information restent présents ;\n4. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '10.2' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.3.1":"1. Désactiver les styles (CSS) du document ;\n2. Vérifier que l’ordre dans lequel les contenus sont implémentés ne pose pas de problème de compréhension ;\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '10.3' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.4.1":"1. Vérifier dans le document si les textes restent présents et lisibles lorsque :\n   - Le zoom texte du navigateur est réglé à 200 % ;\n   - Le zoom graphique du navigateur est réglé à 200 % ;\n   - Les fonctionnalités de zoom personnalisées proposé par le document sont utilisés.\n2. Si c’est le cas, **le test est validé**.\n","10.4.2":"1. Vérifier dans le document si les textes sont effectivement agrandis lorsque :\n   - Le zoom texte du navigateur est réglé à 200 % ;\n   - Le zoom graphique du navigateur est réglé à 200 % ;\n   - Les fonctionnalités de zoom personnalisées proposé par le document sont utilisés.\n2. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '10.4' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.5.1":"1. Retrouver dans le document les textes mis en couleur, à l’exception des couleurs par défaut (par exemple les liens, etc.) ;\n2. Déterminer l’élément qui contient le texte et vérifier la présence d’une valeur calculée pour la propriété `background-color` de l’élément ;\n3. Si c’est le cas, **le test est validé**.\n","10.5.2":"1. Retrouver dans le document les textes mis en couleur, à l’exception des couleurs par défaut (par exemple les liens, etc.) ;\n2. Déterminer l’élément qui contient le texte et vérifier la présence d’une valeur calculée pour la propriété `color` de l’élément ;\n3. Si c’est le cas, **le test est validé**.\n","10.5.3":"1. Retrouver dans le document les textes dont l’arrière-plan est constitué d’une image (propriété background-image) ;\n2. Déterminer l’élément qui contient le texte et vérifier que si l’image d’arrière-plan est absente, le texte reste lisible ;\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '10.5' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.6.1":"1. Retrouver dans le document les éléments de type lien (élément `<a>` ou élément pourvu d’un attribut WAI-ARIA `role=\"link\"`) ;\n2. Pour chaque élément de type lien, s’il peut être confondu avec un texte normal lorsqu’il est signalé uniquement par la couleur, vérifier que le contraste entre la couleur de police du lien et la couleur de police du texte environnant est de 3:1, au moins ;\n3. Cette vérification doit être faite pour les différents états du lien s’ils sont présentés au moyen d’une couleur différente : l’état non visité, l’état visité, l’état activé, l’état au survol et l’état à la prise de focus ;\n4. Si c’est le cas pour chaque élément de type lien, **le test est validé**.\n"}'::jsonb
where identifier = '10.6' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.7.1":"1. Retrouver dans le document les éléments susceptibles de recevoir le focus (les éléments d’interface tels que les liens ou les contrôles de formulaire, ainsi que tout élément pourvu d’un attribut `tabindex` d’une valeur égale ou supérieure à 1) ;\n2. Pour chaque élément susceptible de recevoir le focus, vérifier que l’indication visuelle de la prise de focus est présente (en agissant sur le contour ou le fond ou les deux) et est suffisamment contrastée (ratio de contraste égal ou supérieur à 3:1) ;\n3. Si c’est le cas pour chaque élément susceptible de recevoir le focus, **le test est validé**.\n"}'::jsonb
where identifier = '10.7' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.8.1":"1. Retrouver les contenus cachés (éléments pourvus de l’attribut hidden ou de l’attribut WAI-ARIA aria-hidden, ou bien d’une classe ou d’un ensemble de styles CSS susceptibles de masquer le contenu).\n2. Pour chaque contenu caché, vérifier que :\n   - Soit le contenu caché a vocation à être ignoré par les technologies d’assistance (un élément statistique de visites par exemple) ;\n   - Soit le contenu caché n’a pas vocation à être ignoré par les technologies d’assistance, et dans ce cas il est rendu restituable par les technologies d’assistance au moyen :\n     - Soit d’une action de l’utilisateur réalisable au clavier ou par tout dispositif de pointage sur un élément précédent le contenu caché ;\n     - Soit d’une fonction de programmation qui repositionne le focus sur le contenu.\n3. Si c’est le cas pour chaque contenu caché, **le test est validé**.\n"}'::jsonb
where identifier = '10.8' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"10.9.1":"1. Retrouver dans le document les informations d’un texte données par la forme, la taille ou la position ;\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier qu’il existe un autre moyen de récupérer cette information ;\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","10.9.2":"1. Retrouver dans le document les informations d’une image données par la forme, la taille ou la position ;\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier qu’il existe un autre moyen de récupérer cette information ;\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","10.9.3":"1. Retrouver dans le document les informations d’un média temporel données par la forme, la taille ou la position ;\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier qu’il existe un autre moyen de récupérer cette information ;\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","10.9.4":"1. Retrouver dans le document les informations d’un média non temporel données par la forme, la taille ou la position ;\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier qu’il existe un autre moyen de récupérer cette information ;\n3. Si c’est le cas pour chaque information, **le test est validé**.\n"}'::jsonb
where identifier = '10.9' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"11.1.1":"1. Retrouver dans le document les champs de formulaire ;\n2. Pour chaque champ de formulaire, vérifier que le champ de formulaire :\n   - Possède un attribut WAI-ARIA `aria-labelledby` référençant un passage de texte identifié ;\n   - Possède un attribut WAI-ARIA `aria-label` ;\n   - Est associé à un élément `<label>` ayant un attribut `for` ;\n   - Possède un attribut `title` ;\n   - Un bouton adjacent au champ de formulaire lui fournit une étiquette visible et un élément `<label>` visuellement caché ou un attribut WAI-ARIA `aria-label`, `aria-labelledby` ou `title` lui fournit un nom accessible.\n3. Si c’est le cas pour champ de formulaire, **le test est validé**.\n","11.1.2":"1. Retrouver dans le document les champs de formulaire associé à un élément `<label>` ;\n2. Pour chaque champ de formulaire, vérifier que :\n   - Le champ de formulaire possède un attribut `id` ;\n   - La valeur de l’attribut `for` de l’élément `<label>` est égale à la valeur de l’attribut `id`.\n3. Si c’est le cas pour champ de formulaire, **le test est validé**.\n","11.1.3":"1. Retrouver dans le document les champs de formulaire dont l’étiquette n’est pas visible ou à proximité (masquée, utilisation de l’attribut aria-label) ou n’est pas accolée au champ (utilisation de l’attribut `aria-labelledby`) ;\n2. Pour chaque champ de formulaire, vérifier que le champ de formulaire :\n   - soit possède un attribut `title` dont le contenu permet de comprendre la nature de la saisie attendue ;\n   - est accompagné d’un passage de texte accolé au champ qui devient visible à la prise de focus permettant de comprendre la nature de la saisie attendue ;\n   - est accompagné d’un passage de texte visible accolé au champ permettant de comprendre la nature de la saisie attendue.\n"}'::jsonb
where identifier = '11.1' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"11.10.1":"1. Retrouver dans le document les champs de formulaire obligatoires ;\n2. Pour chaque champ de formulaire, vérifier que préalablement à la validation du formulaire :\n   - Soit une indication de champ obligatoire est visible et permet d’identifier nommément le champ concerné ;\n   - Soit le champ possède un attribut `aria-required=\"true\"` ou `required`.\n3. Si c’est le cas pour chaque champ de formulaire obligatoire, **le test est validé**.\n","11.10.2":"1. Retrouver dans le document les champs de formulaire obligatoires qui possèdent un attribut `aria-required=\"true\"` ou `required` ;\n2. Pour chaque champ de formulaire, vérifier que préalablement à la validation du formulaire :\n   - Soit une indication de champ obligatoire est visible et située dans l’étiquette associée au champ ;\n   - Soit une indication de champ obligatoire est visible et située dans le passage de texte associé au champ.\n3. Si c’est le cas pour chaque champ de formulaire obligatoire qui possèdent un attribut `aria-required=\"true\"` ou `required`, **le test est validé**.\n","11.10.3":"1. Retrouver dans le document les messages d’erreur indiquant l’absence de saisie d’un champ obligatoire ;\n2. Pour chaque message d’erreur, vérifier que :\n   - Soit le message d’erreur est visible et permet d’identifier nommément le champ concerné ;\n   - Soit le champ obligatoire associé au message d’erreur possède un attribut `aria-invalid=\"true\"`.\n3. Si c’est le cas pour chaque message d’erreur indiquant l’absence de saisie d’un champ obligatoire, **le test est validé**.\n","11.10.4":"1. Retrouver dans le document les champs de formulaire obligatoires qui possèdent un attribut `aria-invalid=\"true\"` ;\n2. Pour chaque champ de formulaire, vérifier que :\n   - Soit le message d’erreur indiquant le caractère invalide de la saisie est visible et situé dans l’étiquette associée au champ ;\n   - Soit le message d’erreur indiquant le caractère invalide de la saisie est visible et situé dans le passage de texte associé au champ.\n3. Si c’est le cas pour chaque champ de formulaire obligatoire qui possède un attribut `aria-invalid=\"true\"`, **le test est validé**.\n","11.10.5":"1. Retrouver dans le document les champs de formulaire obligatoires auxquels est associée une instruction ou une indication du type de données et/ou de format obligatoire ;\n2. Pour chaque champ de formulaire, vérifier que l’instruction ou l’indication du type de données et/ou de format obligatoire est préalablement à la validation du formulaire :\n   - Soit visible et permet d’identifier nommément le champ concerné ;\n   - Soit visible dans l’étiquette ou le passage de texte associé au champ.\n3. Si c’est le cas pour chaque champ de formulaire obligatoire auquel est associée une instruction ou une indication du type de données et/ou de format obligatoire, **le test est validé**.\n","11.10.6":"1. Retrouver dans le document les messages d’erreur fournissant une instruction ou une indication du type de données et/ou de format obligatoire d’un champ ;\n2. Pour chaque message d’erreur, vérifier que :\n   - Soit le message d’erreur est visible et permet d’identifier nommément le champ concerné ;\n   - Soit le champ associé au message d’erreur possède un attribut `aria-invalid=\"true\"`.\n3. Si c’est le cas pour chaque message d’erreur indiquant l’absence de saisie d’un champ obligatoire, **le test est validé**.\n","11.10.7":"1. Retrouver dans le document les champs de formulaire qui possèdent un attribut `aria-invalid=\"true\"` ;\n2. Pour chaque champ de formulaire, vérifier que :\n   - Soit une instruction ou une indication du type de données et/ou de format obligatoire est visible et située dans l’élément `<label>` associé au champ ;\n   - Soit une instruction ou une indication du type de données et/ou de format obligatoire est visible et située dans le passage de texte associé au champ.\n3. Si c’est le cas pour chaque champ de formulaire qui possède un attribut `aria-invalid=\"true\"`, **le test est validé**.\n"}'::jsonb
where identifier = '11.10' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"11.11.1":"1. Retrouver dans le document les messages d’erreur ;\n2. Pour chaque message d’erreur, vérifier que les types et les formats de données attendus sont suggérés ;\n3. Si c’est le cas pour chaque message d’erreur , **le test est validé**.\n","11.11.2":"1. Retrouver dans le document les messages d’erreur ;\n2. Pour chaque message d’erreur, vérifier que des exemples de valeurs attendues sont suggérés ;\n3. Si c’est le cas pour chaque message d’erreur , **le test est validé**.\n"}'::jsonb
where identifier = '11.11' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"11.12.1":"1. Retrouver dans le document les formulaires qui modifient ou suppriment des données, ou qui transmettent des réponses à un test ou un examen, ou dont la validation a des conséquences financières ou juridiques ;\n2. Pour chaque formulaire, vérifier que l’utilisateur peut :\n   - Soit modifier ou annuler les données et les actions effectuées sur ces données après la validation du formulaire ;\n   - Soit vérifier et corriger les données avant la validation d’un formulaire en plusieurs étapes ;\n   - Soit disposer d’un mécanisme de confirmation explicite (par exemple, une case à cocher ou une étape supplémentaire).\n3. Si c’est le cas pour chaque formulaire retrouvé, **le test est validé**.\n","11.12.2":"1. Retrouver dans le document les formulaires qui modifient ou suppriment des données à caractère financier, juridique ou personnel ;\n2. Pour chaque formulaire, vérifier que l’utilisateur dispose :\n   - Soit d’un mécanisme qui permet de récupérer les données supprimées ou modifiées ;\n   - Soit d’un mécanisme de demande de confirmation explicite de la suppression ou de la modification (par exemple, une case à cocher ou une étape supplémentaire).\n3. Si c’est le cas pour chaque formulaire retrouvé, **le test est validé**.\n"}'::jsonb
where identifier = '11.12' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"11.13.1":"1. Retrouver dans le document les champs de formulaire qui se rapportent à une information concernant l’utilisateur (nom, prénom, numéro de téléphone, etc.) ;\n2. Pour chaque champ de formulaire, vérifier que :\n   - Le champ de formulaire possède un attribut `autocomplete` ;\n   - L’attribut `autocomplete` est pourvu d’une valeur présente dans la <a rel=\"noreferrer noopener\" target=\"_blank\" title=\"liste des valeurs possibles - en anglais - nouvelle fenêtre\" href=\"https://www.w3.org/TR/html52/sec-forms.html#autofill-processing-model\">liste des valeurs possibles</a> ;\n   - La valeur indiquée pour l’attribut `autocomplete` est pertinente au regard du type d’information attendu.\n3. Si c’est le cas pour chaque champ de formulaire retrouvé, **le test est validé**.\n"}'::jsonb
where identifier = '11.13' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"11.2.1":"1. Retrouver dans le document les champs de formulaire dont l’étiquette est fournie par un élément `<label>` ;\n2. Pour chaque champ de formulaire, vérifier que le contenu de l’élément est pertinent ;\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.2.2":"1. Retrouver dans le document les champs de formulaire dont l’étiquette est fournie par un attribut `title` ;\n2. Pour chaque champ de formulaire, vérifier que le contenu de l’attribut est pertinent ;\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.2.3":"1. Retrouver dans le document les champs de formulaire dont l’étiquette est fournie par un attribut WAI-ARIA `aria-label` ;\n2. Pour chaque champ de formulaire, vérifier que le contenu de l’attribut est pertinent ;\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.2.4":"1. Retrouver dans le document les champs de formulaire dont l’étiquette est fournie par un attribut WAI-ARIA `aria-labelledby` ;\n2. Pour chaque champ de formulaire, vérifier que le contenu du passage de texte référencé est pertinent ;\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.2.5":"1. Retrouver dans le document les champs de formulaire dont l’étiquette est fournie à la fois par un intitulé visible et par le contenu soit d’un élément `<label>`, soit d’un attribut `title` ou d’un attribut `aria-label` ou d’un attribut `aria-labelledby` ;\n2. Pour chaque champ de formulaire, vérifier que le contenu de l’élément `<label>` ou de l’attribut `title` ou de l’attribut `aria-label` ou de l’attribut `aria-labelledby` contient l’intitulé visible ;\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.2.6":"1. Retrouver dans le document les champs de formulaire dont l’étiquette visible est fournie par un bouton adjacent ;\n2. Pour chaque champ de formulaire, vérifier que le contenu visible du bouton est pertinent ;\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n"}'::jsonb
where identifier = '11.2' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"11.3.1":"1. Retrouver dans le document les champs de formulaire ayant une même fonction (par exemple plusieurs champs d’adresse) ;\n2. Pour chaque champ de formulaire, vérifier que les étiquettes sont cohérentes (elles permettent de comprendre qu’il s’agit de saisies de natures identiques) ;\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.3.2":"1. Retrouver dans l’ensemble des pages considérées les champs de formulaire ayant une même fonction (par exemple le champ de saisie d’un moteur de recherche ou le champ de saisie d’inscription à une newsletter) ;\n2. Pour chaque champ de formulaire, vérifier que les étiquettes sont cohérentes (elles permettent de comprendre qu’il s’agit de saisies de natures identiques) ;\n3. Si c’est le cas pour chaque champ de formulaire de l’ensemble des pages considérées, **le test est validé**.\n"}'::jsonb
where identifier = '11.3' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"11.4.1":"1. Retrouver dans le document les champs de formulaire ;\n2. Pour chaque champ de formulaire, vérifier qu’il est accolé à son étiquette ;\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.4.2":"1. Retrouver dans le document les champs de formulaire qui ne sont pas des éléments `<input>` de type `checkbox` ou de type `radio` ou des éléments ayant un attribut WAI-ARIA `role=\"checkbox\"`, `role=\"radio\"` ou `role=\"switch`\";\n2. Pour chaque champ de formulaire, vérifier que l’étiquette est visuellement accolée :\n   - Immédiatement au-dessus ou à gauche du champ de formulaire lorsque le sens de lecture de la langue de l’étiquette est de gauche à droite ;\n   - Immédiatement au-dessus ou à droite du champ de formulaire lorsque le sens de lecture de la langue de l’étiquette est de droite à gauche.\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.4.3":"1. Retrouver dans le document les champs de formulaire qui sont `<input>` de type `checkbox` ou de type `radio` ou des éléments ayant un attribut WAI-ARIA `role=\"checkbox\"`, `role=\"radio\"` ou `role=\"switch`\";\n2. Pour chaque champ de formulaire, vérifier que l’étiquette est visuellement accolée :\n   - Immédiatement au-dessous ou à droite du champ de formulaire lorsque le sens de lecture de la langue de l’étiquette est de gauche à droite ;\n   - Immédiatement au-dessous ou à gauche du champ de formulaire lorsque le sens de lecture de la langue de l’étiquette est de droite à gauche.\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n"}'::jsonb
where identifier = '11.4' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"11.5.1":"1. Retrouver dans le document les champs de formulaire de même nature (par exemple un groupe de saisie d’informations d’identité, une série de cases à cocher, une saisie de date sur plusieurs champs successifs…) ;\n2. Pour chaque groupe de champs de formulaire de même nature, vérifier que ces champs de même nature sont regroupés :\n   - Soit dans un élément `<fieldset>` ;\n   - Soit dans un élément possédant un attribut WAI-ARIA `role=\"group\"` ;\n   - Soit dans un élément possédant un attribut WAI-ARIA `role=\"radiogroup\"` ou `\"group\"`, s’il s’agit d’éléments `<input>` de type `radio` ( ou d’éléments possédant un attribut WAI-ARIA `role=\"radio\"`).\n3. Si c’est le cas pour chaque groupe de champs de formulaire de même nature, **le test est validé**.\n"}'::jsonb
where identifier = '11.5' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"11.6.1":"1. Retrouver dans le document les groupes de champs de formulaire de même nature ;\n2. Pour chaque groupe de champs de formulaire de même nature, vérifier que :\n   - Si le regroupement utilise un élément `<fieldset>`, l’élément `<fieldset>` possède un élément `<legend>` ;\n   - Si l’élément de regroupement utilise un attribut WAI-ARIA `role=\"group\"` ou `\"radiogroup\"`, il possède un attribut WAI-ARIA `aria-label` ou `aria-labelledby`.\n3. Sinon, pour chacun des champs de même nature, vérifier la présence :\n   - Soit d’un attribut title permettant de déterminer l’appartenance du champ au groupement de champ ;\n   - Soit d’un attribut `aria-label` permettant de déterminer l’appartenance du champ au groupement de champ ;\n   - Soit d’un attribut `aria-labelledby` qui référence un passage de texte permettant de déterminer l’appartenance du champ au groupement de champ ;\n   - Soit d’un attribut `aria-describedby` qui référence un passage de texte permettant de déterminer l’appartenance du champ au groupement de champ.\n4. Si c’est le cas pour chaque groupe de champs de formulaire ou pour chacun des champs de même nature, **le test est validé**.\n"}'::jsonb
where identifier = '11.6' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"11.7.1":"1. Retrouver dans le document les groupes de champs de formulaire de même nature ;\n2. Pour chaque groupe de champs de formulaire de même nature ou pour chacun des champs de même nature qui dispose d’une légende, vérifier que le texte de cette légende est pertinent ;\n3. Si c’est le cas pour chaque groupe de champs de formulaire ou pour chacun des champs de même nature, **le test est validé**.\n"}'::jsonb
where identifier = '11.7' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"11.8.1":"1. Retrouver dans le document les listes de sélection (élément `<select>`) ;\n2. Pour chaque liste de sélection proposant des groupes d’items de même nature, vérifier que ces items sont regroupés au moyen d’éléments `<optgroup>` ;\n3. Si c’est le cas pour chaque liste de sélection proposant des groupes d’items de même nature, **le test est validé**.\n","11.8.2":"1. Retrouver dans le document les listes de sélection (élément `<select>`) qui possèdent des éléments `<optgroup>` ;\n2. Pour chaque élément `<optgroup>`, vérifier qu’il possède un attribut `label` ;\n3. Si c’est le cas pour chaque élément `<optgroup>`, **le test est validé**.\n","11.8.3":"1. Retrouver dans le document les listes de sélection (élément `<select>`) qui possèdent des éléments `<optgroup>` pourvus d’un attribut `label` ;\n2. Pour chaque attribut `label`, vérifier que son contenu est pertinent ;\n3. Si c’est le cas pour chaque attribut `label`, **le test est validé**.\n"}'::jsonb
where identifier = '11.8' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"11.9.1":"1. Retrouver dans le document les boutons présents au sein d’un formulaire ;\n2. Pour chaque bouton, vérifier que son intitulé visible et son nom accessible sont pertinents ;\n3. Si c’est le cas pour chaque bouton, **le test est validé**.\n","11.9.2":"1. Retrouver dans le document les boutons présents au sein d’un formulaire ;\n2. Pour chaque bouton, vérifier que son nom accessible contient au moins son intitulé visible ;\n3. Si c’est le cas pour chaque bouton, **le test est validé**.\n"}'::jsonb
where identifier = '11.9' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"12.1.1":"1. Pour chaque ensemble de pages du site, vérifier la présence :\n   - Soit d’un menu de navigation et d’un plan du site ;\n   - Soit d’un menu de navigation et d’un moteur de recherche ;\n   - Soit d’un moteur de recherche et d’un plan du site.\n2. Si c’est le cas pour chaque ensemble de pages du site, **le test est validé**.\n"}'::jsonb
where identifier = '12.1' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"12.10.1":"1. Retrouver dans le document l’ensemble des raccourcis clavier proposés à l’utilisateur ;\n2. Pour chaque raccourci clavier, vérifier que :\n   - Soit un mécanisme est disponible pour désactiver le raccourci clavier ;\n   - Soit un mécanisme est disponible pour configurer la touche de raccourci clavier au moyen des touches de modification (Ctrl, Alt, Maj, etc.) ;\n   - Soit, dans le cas d’un composant d’interface utilisateur, le raccourci clavier qui lui est associé ne peut être activé que si le focus clavier est sur ce composant.\n3. Si c’est le cas pour chaque raccourci clavier, **le test est validé**.\n"}'::jsonb
where identifier = '12.10' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"12.11.1":"1. Retrouver dans le document l’ensemble des contenus additionnels apparaissant au survol, à la prise de focus ou à l’activation d’un composant d’interface ;\n2. Pour chaque contenu additionnel, s’il contient des composants d’interface avec lesquels l’utilisateur peut interagir au clavier (par exemple, une infobulle personnalisée qui propose un lien dans son contenu), vérifier que ces composants d’interface sont atteignables au clavier ;\n3. Si c’est le cas pour chaque contenu additionnel, **le test est validé**.\n"}'::jsonb
where identifier = '12.11' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"12.2.1":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit ;\n2. Comparer visuellement les deux pages et vérifier que le menu ou les barres de navigation sont toujours à la même place dans la présentation ;\n3. Comparer le code source (généré côté client) des deux pages et vérifier que le menu ou les barres de navigation se présentent toujours dans le même ordre relatif dans la structure ;\n4. Si c’est le cas, **le test est validé**.\n\nNote : le critère est non applicable dans les situations où :\n\n- Les pages d''un ensemble de pages sont le résultat ou une partie d''un processus (un processus de paiement ou de prise de commande, par exemple) ;\n- La page est la page d''accueil ;\n- Le site web est constitué d''une seule page.\n"}'::jsonb
where identifier = '12.2' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"12.3.1":"1. Vérifier que le plan du site est représentatif de l’architecture générale du site (cf. note) ;\n2. Si c’est le cas, **le test est validé**.\n\nNote : Un plan du site trop complexe ou trop profond n''est pas recommandé pour aider à la navigation. Il n''est pas obligatoire que toutes les pages soient présentes dans le plan du site si elles peuvent être atteintes, par exemple, à partir de la page d''accueil d''une rubrique ou d''un catalogue.\n","12.3.2":"1. Pour tous les liens du plan du site, vérifier qu’ils sont fonctionnels ;\n2. Si c’est le cas, **le test est validé**.\n","12.3.3":"1. Pour tous les liens du plan du site, vérifier qu’ils sont à jour (ni obsolètes ni en erreur) et conduisent à la page indiquée par leur intitulé ;\n2. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '12.3' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"12.4.1":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit ;\n2. Comparer le code source (généré côté client) des deux pages et vérifier que le moyen d’accès au plan du site est toujours le même (un lien ou un bouton, par exemple) ;\n3. Si c’est le cas, **le test est validé**.\n","12.4.2":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit ;\n2. Comparer le code source (généré côté client) des deux pages et vérifier que le moyen d’accès au plan du site est toujours à la même place dans la structure (par rapport à l’ordre relatif des éléments de la page, par exemple il est toujours en haut de page) ;\n3. Si c’est le cas, **le test est validé**.\n","12.4.3":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit ;\n2. Comparer visuellement les deux pages et vérifier que le moyen d’accès au plan du site est toujours à la même place dans la présentation ;\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '12.4' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"12.5.1":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit ;\n2. Comparer le code source (généré côté client) des deux pages et vérifier que le moyen d’accès au moteur de recherche est toujours le même (un champ de formulaire, par exemple) ;\n3. Si c’est le cas, **le test est validé**.\n","12.5.2":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit ;\n2. Comparer visuellement les deux pages et vérifier que le moyen d’accès au moteur de recherche est toujours à la même place dans la présentation ;\n3. Si c’est le cas, **le test est validé**.\n","12.5.3":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit ;\n2. Comparer le code source (généré côté client) des deux pages et vérifier que le moyen d’accès au moteur de recherche est toujours à la même place dans la structure (par rapport à l’ordre relatif des éléments de la page, par exemple il est toujours en haut de page) ;\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '12.5' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"12.6.1":"1. Retrouver dans le document les zones de regroupement de contenus (zones d’en-tête, de navigation principale, de contenu principal, de pied de page et de moteur de recherche) ;\n2. Pour chaque zone, vérifier que la zone :\n   - Soit possède un rôle WAI-ARIA de type landmark correspondant à sa nature ;\n   - Soit possède un titre de hiérarchie dont le contenu permet de comprendre la nature du contenu de la zone ;\n   - Soit peut être masquée au moyen d’un bouton précédant directement la zone dans l’ordre du code source ;\n   - Soit peut être évitée au moyen d’un lien d’évitement précédant directement la zone dans l’ordre du code source ;\n   - Soit peut être atteinte au moyen d’un lien d’accès rapide soit visible par défaut, soit visible à la prise de focus lors d’une tabulation.\n3. Si c’est le cas pour chaque zone de regroupement de contenus, **le test est validé**.\n"}'::jsonb
where identifier = '12.6' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"12.7.1":"1. Retrouver dans le document la zone de contenu principal (indiquée par l’élément main visible) ;\n2. Vérifier que la zone :\n   - Soit peut être évitée au moyen d’un lien d’évitement précédant directement la zone dans l’ordre du code source ;\n   - Soit peut être atteinte au moyen d’un lien d’accès rapide visible à la prise de focus lors d’une tabulation.\n3. Si c’est le cas, **le test est validé**.\n","12.7.2":"1. Retrouver dans le document la zone de contenu principal (indiquée par l’élément main visible) ;\n2. Vérifier que le lien d’évitement ou d’accès rapide à la zone est :\n   - Situé à la même place dans la présentation ;\n   - Présent toujours dans le même ordre relatif dans le code source (généré côté client) ;\n   - Visible à la prise de focus lors d’une tabulation ;\n   - Fonctionnel.\n3. Si c’est le cas, **le test est validé**.\n\nNote : lorsque le site web est constitué d''une seule page, l''obligation de la présence d''un lien d''accès rapide est liée au contexte de la page (présence ou absence de navigation ou de contenus additionnels, par exemple). Le critère peut être considéré comme non applicable lorsqu''il est avéré qu''un lien d''accès rapide est inutile.\n"}'::jsonb
where identifier = '12.7' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"12.8.1":"1. Parcourir dans le document l’ensemble des contenus au moyen de la touche de tabulation vers l’avant (touche Tab) et vers l’arrière (touches Maj+Tab) ;\n2. Vérifier que l’ordre de déplacement du focus reste cohérent relativement au contenu considéré (par exemple, l’ordre de tabulation dans une fenêtre modale ne doit considérer que les éléments d’interface présents au sein de cette fenêtre) ;\n3. Si c’est le cas, **le test est validé**.\n\nNote : il n''est pas obligatoire que la tabulation suive l''ordre de lecture naturel (de gauche à droite et de haut en bas par exemple) tant que les éléments sont accessibles dans un ordre cohérent.\n","12.8.2":"1. Retrouver dans le document l’ensemble des contenus insérés au moyen d’un script (affichage d’éléments masqués, mise jour de contenu via AJAX par exemple) ;\n2. Positionner la tabulation sur l’élément déclencheur et l’activer ;\n3. Après l’affichage du contenu mis à jour, vérifier que la tabulation reste cohérente (repositionnement correct du focus) ;\n4. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '12.8' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"12.9.1":"1. Retrouver dans le document l’ensemble des éléments d’interface susceptibles de recevoir le focus (au moyen de la tabulation ou au moyen d’un script) ;\n2. Pour chaque élément d’interface, vérifier que l’utilisateur peut atteindre l’élément suivant ou précédent pouvant recevoir le focus :\n   - Soit au moyen de la touche de tabulation (Tab ou Maj+Tab) ;\n   - Soit au moyen d’une autre interaction clavier dont l’utilisateur est informé (par exemple, les flèches de direction).\n3. Si c’est le cas pour chaque élément d’interface, **le test est validé**.\n\nNote : certains éléments d''interface complexes, comme un groupe de boutons radio, une liste de sélection et tous les composants développés avec WAI-ARIA font appel à des navigations optimisées qui utilisent généralement les flèches de direction pour passer d''une partie du composant à l''autre. Par exemple, dans un groupe de boutons radio les options sont navigables avec les flèches de direction. De même dans un système d''onglets l''utilisateur active les onglets avec les flèches de direction. Le test sur le piège au clavier se limite alors à vérifier que le composant est atteint avec la tabulation et qu''il est possible de passer au composant suivant ou revenir au composant précédent.\n"}'::jsonb
where identifier = '12.9' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"13.1.1":"1. Retrouver dans le document les rafraîchissements initiés dans le contenu par un élément `<object>`, `<embed>`, `<svg>`, `<canvas>` ou par un élément `<meta http-equiv=\"refresh\" content=\"[compteur]\">` (dans l’élément `<head>` de la page) ;\n2. Pour chaque rafraîchissement, vérifier que :\n   - Soit la présence d’un mécanisme permet à l’utilisateur de stopper et de relancer le rafraîchissement ;\n   - Soit la présence d’un mécanisme permet à l’utilisateur d’augmenter la limite de temps entre deux rafraîchissements de dix fois, au moins ;\n   - Soit la présence d’un mécanisme qui avertit l’utilisateur de l’imminence du rafraîchissement, laisse 20 secondes, au moins, à l’utilisateur, pour augmenter la limite de temps avant le prochain rafraîchissement ;\n   - Soit la limite de temps entre deux rafraîchissements est de vingt heures, au moins.\n3. Si c’est le cas, **le test est validé**.\n","13.1.2":"1. Retrouver dans le document une redirection automatique initiée par un élément `<meta http-equiv=\"refresh\" content=\"0;URL=''[URL ciblée]''\" />` ;\n2. Vérifier que la redirection est immédiate ;\n3. Si c’est le cas, **le test est validé**.\n","13.1.3":"1. Retrouver dans le document les redirections automatiques initiées par un script (sous la forme d’un décompte par exemple) ;\n2. Pour chaque redirection automatique, vérifier que :\n   - Soit la présence d’un mécanisme permet à l’utilisateur de stopper et relancer la redirection ;\n   - Soit la présence d’un mécanisme permet à l’utilisateur d’augmenter la limite de temps avant le rafraîchissement de dix fois, au moins ;\n   - Soit la présence d’un mécanisme qui avertit l’utilisateur de l’imminence du rafraîchissement, laisse 20 secondes, au moins, à l’utilisateur, pour augmenter la limite de temps avant le prochain rafraîchissement ;\n   - Soit la limite de temps avant la redirection est de vingt heures, au moins.\n3. Si c’est le cas, **le test est validé**.\n","13.1.4":"1. Retrouver dans le document les procédés limitant le temps d’une session (par exemple, après une authentification) ;\n2. Pour chaque procédé, vérifier que :\n   - Soit la présence d’un mécanisme permet à l’utilisateur de supprimer la limite de temps ;\n   - Soit la présence d’un mécanisme permet à l’utilisateur d’augmenter la limite de temps ;\n   - Soit la limite de temps est de vingt heures, au moins.\n3. Si c’est le cas, **le test est validé**.\n\nNote : lorsque la limite de temps est essentielle, notamment lorsqu''elle ne pourrait pas être supprimée sans changer fondamentalement le contenu ou les fonctionnalités liées au contenu, le critère est non applicable. Par exemple, le rafraîchissement d''un flux RSS dans une page n''est pas une limite de temps essentielle ; le critère est applicable. En revanche, une redirection automatique qui amène vers la nouvelle version d''une page à partir d''une url obsolète est essentielle ; le critère est non applicable.\n"}'::jsonb
where identifier = '13.1' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"13.10.1":"1. Retrouver dans le document les fonctionnalités utilisables ou disponibles au moyen d’une interaction au toucher de type contact multipoint ;\n2. Pour chaque fonctionnalité, vérifier qu’elle reste disponible au moyen d’une interaction au toucher de type contact en un point unique de l’écran (par exemple, la possibilité de consulter les éléments d’une liste par un mouvement de balayage horizontal droit ou gauche doit aussi être disponible au moyen de boutons “précédent” et “suivant” ou encore un geste de pincer et zoomer qui peut être alternativement réalisé au moyen de boutons “plus” et “moins”) ;\n3. Si c’est le cas pour chaque fonctionnalité utilisable ou disponible au moyen d’une interaction au toucher de type contact multipoint, **le test est validé**.\n","13.10.2":"1. Retrouver dans le document les fonctionnalités utilisables ou disponibles au moyen d’une interaction au toucher qui implique le suivi d’une trajectoire sur l’écran ;\n2. Pour chaque fonctionnalité, vérifier qu’elle reste disponible au moyen d’une interaction au toucher de type contact en un point unique de l’écran (par exemple, la possibilité de composer son mot de passe en suivant une trajectoire sur un clavier virtuel doit aussi être disponible au moyen de pressions successives sur les touches du clavier) ;\n3. Si c’est le cas pour chaque fonctionnalité utilisable ou disponible au moyen d’une interaction au toucher qui implique le suivi d’une trajectoire sur l’écran, **le test est validé**.\n\nIl existe une gestion de cas particuliers dans deux types de situation :\n\n- Le critère ne s''applique qu''à des fonctionnalités mises en place par l''auteur du site. Il ne concerne donc pas les gestes requis par l''agent utilisateur ou le système d''exploitation.\n- Le critère ne s''applique pas aux fonctionnalités dont la réalisation d''un geste complexe est essentielle (exécuter le tracé d''une signature, par exemple).\n"}'::jsonb
where identifier = '13.10' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"13.11.1":"1. Retrouver dans le document les actions déclenchées au moyen d’un dispositif de pointage sur un point unique de l’écran ;\n2. Pour chaque action, vérifier que :\n   - Soit l’action est déclenchée au moment où le dispositif de pointage est relâché ou relevé ;\n   - Soit l’action est déclenchée au moment où le dispositif de pointage est pressé ou posé puis annulée lorsque le dispositif de pointage est relâché ou relevé ;\n   - Soit il existe un mécanisme pour abandonner (avant achèvement de l’action) ou annuler (après achèvement) l’exécution de l’action ; par exemple, lors d’une interaction de type glisser-déposer un relâchement du dispositif de pointage doit permettre d’abandonner l’interaction en cours et une fois la zone de dépôt atteinte, l’utilisateur doit rester en mesure d’annuler son opération de dépôt au moyen d’un dialogue de confirmation (choix de confirmer ou d’annuler le dépôt) ou par le fait de pouvoir replacer l’élément déposé à sa position initiale.\n3. Si c’est le cas pour chaque action déclenchée au moyen d’un dispositif de pointage sur un point unique de l’écran, **le test est validé**.\n"}'::jsonb
where identifier = '13.11' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"13.12.1":"1. Retrouver dans le document les fonctionnalités disponibles en bougeant l’appareil ;\n2. Pour chaque fonctionnalité, vérifier qu’elle peut être accomplie au moyen de composants d’interface utilisateur ;\n3. Si c’est le cas pour chaque fonctionnalité disponible en bougeant l’appareil, **le test est validé**.\n","13.12.2":"1. Retrouver dans le document les fonctionnalités disponibles en faisant un geste en direction de l’appareil ;\n2. Pour chaque fonctionnalité, vérifier qu’elle peut être accomplie au moyen de composants d’interface utilisateur ;\n3. Si c’est le cas pour chaque fonctionnalité disponible en faisant un geste en direction de l’appareil, **le test est validé**.\n","13.12.3":"1. Retrouver dans le document les fonctionnalités disponibles en mettant en mouvement l’appareil ;\n2. Vérifier si l’utilisateur à la possibilité de désactiver la détection du mouvement ;\n3. Si c’est le cas, pour chaque fonctionnalité, vérifier qu’elle ne peut pas être déclenchée ;\n4. Si c’est le cas pour chaque fonctionnalité disponible en mettant en mouvement l’appareil, **le test est validé**."}'::jsonb
where identifier = '13.12' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"13.2.1":"1. Vérifier qu’à l’ouverture du document, aucune nouvelle fenêtre (pop-up ou pop-under, par exemple) n’est ouverte.\n2. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '13.2' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"13.3.1":"1. Retrouver dans le document les liens et les contrôles de formulaire (un bouton de formulaire ou un formulaire de téléchargement par exemple) permettant de télécharger un fichier au format bureautique ;\n2. Pour chaque fichier au format bureautique, vérifier la présence d’une version alternative présentée comme accessible :\n   - Pour les documents au format .pdf, analyser le fichier avec l’outil PAC (PDF Accessibility Checker) et vérifier l’absence d’erreur d’accessibilité dans le document (cf. note) ;\n   - Pour les documents au format .doc ou .docx, analyser le fichier avec l’outil de vérification d’accessibilité de Microsoft Office (à partir de la version 2010) et vérifier l’absence d’erreur d’accessibilité (cf. note) ;\n   - Pour les documents au format .odt, analyser le document avec l’éditeur OpenOffice et vérifier que l’ensemble des contenus est conforme avec la liste des critères « Liste document bureautique en téléchargement » (cf. note pour une méthode alternative) ;\n   - Pour les documents au format EPUB/DAISY, analyser le document avec un éditeur EPUB/DAISY et vérifier que l’ensemble des contenus est conforme avec la liste des critères « Liste document bureautique en téléchargement ».\n   - Pour les documents eux-mêmes au format .html, analyser l’accessibilité du document.\n3. Si c’est le cas pour chaque fichier au format bureautique, **le test est validé**.\n\nNote au sujet de l''outil PAC : l''outil analyse le document PDF du point de vue de l''accessibilité mais également de critères de qualité (par exemple la norme PDF/UA). Seules les erreurs relatives à des critères présents dans la liste des critères « Liste document bureautique en téléchargement » rendent le critère « Non conforme ». Par ailleurs, cet outil ne fonctionne que sur la plateforme Windows. Sur Mac, le contrôle doit se faire manuellement.\n\nNote au sujet Microsoft Office : le logiciel offre un vérificateur d''accessibilité en standard, (accessible via le menu « Fichier > Informations > Vérifier la présence de problèmes > Vérifier l''accessibilité »). Ce vérificateur peut être considérablement amélioré via le plugin Word Accessibility Plug-in (voir dans la section Outils). Ce plugin ne fonctionne que sur Windows. Sur Mac, le contrôle doit se faire manuellement.\n\nNote au sujet des documents au format .odt : OpenOffice et LibreOffice ne possèdent pas de vérificateur d''accessibilité. Une méthode plus rapide qu''une analyse manuelle peut consister à enregistrer le document au format .docx et le vérifier via le vérificateur d''accessibilité de Microsoft Office 2010. Attention cependant : cette méthode rapide est à réserver aux documents très simples car certaines informations liées à l''accessibilité ne sont pas correctement transcodées. C''est le cas des indications de langue, de certaines alternatives d''images ou d''en-têtes fusionnées sur les tableaux par exemple.\n\nNote au sujet du format EPUB : l''utilitaire Ace by DAISY App permet d''effectuer le travail de validation d''un fichier EPUB 3 de manière efficace.\n\nNote au sujet des documents dérogés : le référentiel propose un statut de dérogation dans certains cas (cf. guide d''accompagnement). Dans ce cas, les tests ne sont pas à réaliser, la version accessible étant fournie sur demande de l''utilisateur.\n\nNote à l''attention des personnes de droit privé mentionnées aux 2° à 4° du I de l’article 47 de la loi du 11 février 2005 : si les fichiers bureautiques (ex : PDF, documents Microsoft ou LibreOffice, etc.) ont été publiés avant le 23 septembre 2018 (sauf si ce sont des documents nécessaires pour accomplir une démarche administrative relevant des tâches effectuées par l''organisme concerné), ils sont exemptés de l’obligation d’accessibilité.\n"}'::jsonb
where identifier = '13.3' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"13.4.1":"1. Retrouver dans le document les fichiers en téléchargement au format bureautique accompagné de leur version alternative accessible ;\n2. Pour chaque couple de fichiers, ouvrir les deux documents (le document d’origine et le document accessible) et vérifier que les deux documents apportent la même information ;\n3. Si c’est le cas pour chaque couple de fichiers, **le test est validé**.\n"}'::jsonb
where identifier = '13.4' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"13.5.1":"1. Retrouver dans le document les contenus cryptiques (art ASCII, émoticône, syntaxe cryptique) ;\n2. Pour chaque contenu cryptique, vérifier que :\n   - Soit une définition est disponible au moyen d’un attribut `title`, sur un lien, un contrôle de formulaire, une abréviation (élément `<abbr>`) par exemple ;\n   - Soit une définition est donnée dans le contexte adjacent (immédiatement avant ou après).\n3. Si c’est le cas pour chaque contenu cryptique, **le test est validé**.\n"}'::jsonb
where identifier = '13.5' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"13.6.1":"1. Retrouver dans le document les contenus cryptiques (art ASCII, émoticône, syntaxe cryptique) ;\n2. Pour chaque contenu cryptique, vérifier que la définition donnée est pertinente.\n3. Si c’est le cas pour chaque contenu cryptique, **le test est validé**.\n"}'::jsonb
where identifier = '13.6' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"13.7.1":"1. Retrouver dans le document les contenus clignotants ou qui provoquent des effets de flash de type image animée, vidéo (cf. note) ou animation (éléments `<img>`, `<svg>`, `<canvas>`, `<embed>`, `<object>` ou `<video>`) ;\n2. Pour chaque contenu clignotant ou provoquant des effets de flash, vérifier que :\n   - Soit la fréquence de l’effet est inférieur à 3 par seconde ;\n   - Soit la surface cumulée est inférieure à 21824 pixels.\n3. Si c’est le cas pour chaque contenu clignotant ou provoquant des effets de flash, **le test est validé**.\n\nNote : l''évaluation de ce critère peut être complexe. Lorsque l''effet est géré par un script ou au moyen de CSS, l''analyse du code est suffisante. L''outil PEAT permet d''analyser les vidéos au format .avi, par exemple. Un exemple de vidéo ayant provoqué des crises d''épilepsie peut être consulté ici : London 2012 Olympics Seizure (https://www.youtube.com/watch?v=vs0hfhSje9M).\n","13.7.2":"1. Retrouver dans le document les contenus clignotants ou qui provoquent des effets de flash obtenus au moyen d’un script ;\n2. Pour chaque contenu clignotant ou provoquant des effets de flash, vérifier que :\n   - Soit la fréquence de l’effet est inférieur à 3 par seconde ;\n   - Soit la surface cumulée est inférieure à 21824 pixels.\n3. Si c’est le cas pour chaque contenu clignotant ou provoquant des effets de flash, **le test est validé**.\n","13.7.3":"1. Retrouver dans le document les contenus clignotants ou qui provoquent des effets de flash obtenus au moyen d’une animation CSS ;\n2. Pour chaque contenu clignotant ou provoquant des effets de flash, vérifier que :\n   - Soit la fréquence de l’effet est inférieur à 3 par seconde ;\n   - Soit la surface cumulée est inférieure à 21824 pixels.\n3. Si c’est le cas pour chaque contenu clignotant ou provoquant des effets de flash, **le test est validé**.\n"}'::jsonb
where identifier = '13.7' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"13.8.1":"1. Retrouver dans le document les contenus en mouvement (obtenus au moyen d’une image, d’un script ou d’un effet CSS) déclenchés automatiquement au chargement de la page ou lors de l’affichage d’un contenu (cf. note) ;\n2. Pour chaque contenu, vérifier que :\n   - Soit la durée du mouvement est inférieure à 5 secondes ;\n   - Soit la présence d’un mécanisme (un bouton, par exemple) permet d’arrêter et de relancer le mouvement ;\n   - Soit la présence d’un mécanisme (un bouton, par exemple) permet de cacher et d’afficher à nouveau le contenu en mouvement ;\n   - Soit la présence d’un mécanisme (un bouton, par exemple) permet d’afficher la totalité du contenu sans mouvement.\n3. Si c’est le cas pour chaque contenu en mouvement, **le test est validé**.\n","13.8.2":"1. Retrouver dans le document les contenus clignotants (obtenus au moyen d’une image, d’un script ou d’un effet CSS) déclenchés automatiquement au chargement de la page ou lors de l’affichage d’un contenu (cf. note).\n2. Pour chaque contenu, vérifier que :\n   - Soit la durée du clignotement est inférieure à 5 secondes ;\n   - Soit la présence d’un mécanisme (un bouton, par exemple) permet d’arrêter et de relancer le clignotement ;\n   - Soit la présence d’un mécanisme (un bouton, par exemple) permet de cacher et d’afficher à nouveau le contenu clignotant ;\n   - Soit la présence d’un mécanisme (un bouton, par exemple) permet d’afficher la totalité du contenu clignotant.\n3. Si c’est le cas pour chaque contenu clignotant, **le test est validé**.\n\nNote : l''arrêt ou la mise en pause d''un contenu en mouvement ou clignotant au moyen de la prise de focus (par exemple, l''effet est suspendu uniquement pendant la prise de focus) n''est pas considéré comme un procédé conforme. Dans certains cas, le mouvement ne peut pas être arrêté, par exemple dans le cas d''une barre de progression, dans ce cas, le critère est non applicable.\n"}'::jsonb
where identifier = '13.8' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"13.9.1":"1. Consulter le document dans un mode d’orientation portrait puis dans un mode d’orientation paysage ;\n2. Vérifier que :\n   - La consultation est possible quel que soit le mode d’orientation de l’écran.\n   - Le contenu proposé reste le même quel que soit le mode d’orientation de l’écran utilisé même si sa présentation et le moyen d’y accéder peut différer.\n3. Si c’est le cas, **le test est validé**.\n\nNote : il existe des interfaces pour lesquelles l''orientation du périphérique est essentielle à leur utilisation. Dans ces situations, le critère est non applicable. Il peut s''agir d''interfaces de jeu, de piano, de dépôt de chèques bancaires, etc. Si l''interface est le seul moyen d''accéder au service proposé, une alternative devrait être mise en place pour pallier cette carence.\n"}'::jsonb
where identifier = '13.9' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"2.1.1":"1. Retrouver dans le document les cadres (élément `<iframe>` ou `<frame>`) ;\n2. Pour chaque cadre, vérifier qu’il possède un attribut `title `;\n3. Si c’est le cas pour chaque cadre, **le test est validé**.\n"}'::jsonb
where identifier = '2.1' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"2.2.1":"1. Retrouver dans le document les cadres (élément `<iframe>` ou `<frame>`) ;\n2. Pour chaque cadre pourvu d’un attribut `title`, vérifier que son contenu est pertinent ;\n3. Si c’est le cas pour chaque cadre, **le test est validé**.\n"}'::jsonb
where identifier = '2.2' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"3.1.1":"1. Retrouver dans le document les informations données par la couleur dans un mot ou un ensemble de mots ;\n2. Pour chacune de ces informations, vérifier qu’il existe un autre moyen de récupérer cette information (présence d’un attribut title, d’une icône ou d’un effet graphique de forme ou de position, un effet typographique…) ;\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","3.1.2":"1. Retrouver dans le document les informations données par la couleur dans un texte ;\n2. Pour chacune de ces informations, vérifier qu’il existe un autre moyen de récupérer cette information (présence d’un attribut title, d’une icône ou d’un effet graphique de forme ou de position, un effet typographique…) ;\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","3.1.3":"1. Retrouver dans le document les informations données par la couleur dans une image ;\n2. Pour chacune de ces informations, vérifier qu’il existe un autre moyen de récupérer cette information (présence d’un attribut title, d’une icône ou d’un effet graphique de forme ou de position, un effet typographique…) ;\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","3.1.4":"1. Retrouver dans le document les informations données par la couleur dans une propriété CSS ;\n2. Pour chacune de ces informations, vérifier qu’il existe un autre moyen de récupérer cette information (présence d’un attribut title, d’une icône ou d’un effet graphique de forme ou de position, un effet typographique…) ;\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","3.1.5":"1. Retrouver dans le document les informations données par la couleur dans un média temporel ;\n2. Pour chacune de ces informations, vérifier qu’il existe un autre moyen de récupérer cette information (présence d’un attribut title, d’une icône ou d’un effet graphique de forme ou de position, un effet typographique…) ;\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","3.1.6":"1. Retrouver dans le document les informations données par la couleur dans un média non temporel ;\n2. Pour chacune de ces informations, vérifier qu’il existe un autre moyen de récupérer cette information (présence d’un attribut title, d’une icône ou d’un effet graphique de forme ou de position, un effet typographique…) ;\n3. Si c’est le cas pour chaque information, **le test est validé**.\n"}'::jsonb
where identifier = '3.1' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"3.2.1":"1. Retrouver dans le document les textes et les textes en image sans effet de graisse d’une taille restituée inférieure à 24px qui pourraient poser des problèmes de contraste ;\n2. Pour chacun de ces textes, vérifier que :\n   - Soit le rapport de contraste entre le texte et son arrière-plan est de 4.5:1, au moins ;\n   - Soit un mécanisme permet à l’utilisateur d’afficher le texte avec un rapport de contraste de 4.5:1, au moins.\n3. Si c’est le cas pour chaque texte, **le test est validé**.\n","3.2.2":"1. Retrouver dans le document les textes et les textes en image en gras d’une taille restituée inférieure à 18,5px qui pourraient poser des problèmes de contraste ;\n2. Pour chacun de ces textes, vérifier que :\n   - Soit le rapport de contraste entre le texte et son arrière-plan est de 4.5:1, au moins ;\n   - Soit un mécanisme permet à l’utilisateur d’afficher le texte avec un rapport de contraste de 4.5:1, au moins.\n3. Si c’est le cas pour chaque texte, **le test est validé**.\n","3.2.3":"1. Retrouver dans le document les textes et les textes en image sans effet de graisse d’une taille restituée supérieure ou égale à 24px qui pourraient poser des problèmes de contraste ;\n2. Pour chacun de ces textes, vérifier que :\n   - Soit le rapport de contraste entre le texte et son arrière-plan est de 3:1, au moins ;\n   - Soit un mécanisme permet à l’utilisateur d’afficher le texte avec un rapport de contraste de 3:1, au moins.\n3. Si c’est le cas pour chaque texte, **le test est validé**.\n","3.2.4":"1. Retrouver dans le document les textes et les textes en image en gras d’une taille restituée supérieure ou égale à 18,5px qui pourraient poser des problèmes de contraste ;\n2. Pour chacun de ces textes, vérifier que :\n   - Soit le rapport de contraste entre le texte et son arrière-plan est de 3:1, au moins ;\n   - Soit un mécanisme permet à l’utilisateur d’afficher le texte avec un rapport de contraste de 3:1, au moins.\n3. Si c’est le cas pour chaque texte, **le test est validé**.\n","3.2.5":"1. Retrouver dans le document les mécanismes qui permettent d’afficher un rapport de contraste conforme ;\n2. Pour chacun de ces mécanismes, vérifier que le rapport de contraste entre le texte et la couleur d’arrière-plan est suffisamment élevé ;\n3. Si c’est le cas pour chaque mécanisme, **le test est validé**.\n"}'::jsonb
where identifier = '3.2' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"3.3.1":"1. Retrouver dans le document les composants d’interface qui pourraient poser des problèmes de contraste ;\n2. Pour chacun de ces composants, vérifier que :\n   - Soit le rapport de contraste entre les couleurs du composant dans ses différents états et la couleur d’arrière-plan contiguë est de 3:1, au moins ;\n   - Soit un mécanisme permet à l’utilisateur d’afficher le composant avec un rapport de contraste de 3:1, au moins.\n3. Si c’est le cas pour chaque composant, **le test est validé**.\n","3.3.2":"1. Retrouver dans le document les éléments graphiques qui pourraient poser des problèmes de contraste ;\n2. Pour chacun de ces éléments, vérifier que :\n   - Soit le rapport de contraste entre les couleurs de l’élément graphique nécessaires à sa compréhension et la couleur d’arrière-plan contiguë est de 3:1, au moins ;\n   - Soit un mécanisme permet à l’utilisateur d’afficher l’élément graphique avec un rapport de contraste de 3:1, au moins.\n3. Si c’est le cas pour chaque composant, **le test est validé**.\n","3.3.3":"1. Retrouver dans le document les éléments graphiques qui pourraient poser des problèmes de contraste ;\n2. Pour chacun de ces éléments, vérifier que :\n   - Soit le rapport de contraste des différentes couleurs contiguës de l’élément graphique entre elles, lorsqu’elles sont nécessaires à sa compréhension, est de 3:1, au moins ;\n   - Soit un mécanisme permet à l’utilisateur d’afficher l’élément graphique avec un rapport de contraste de 3:1, au moins.\n3. Si c’est le cas pour chaque élément graphique, **le test est validé**.\n","3.3.4":"1. Retrouver dans le document les mécanismes qui permettent d’afficher un rapport de contraste conforme ;\n2. Pour chacun de ces mécanismes, vérifier que le rapport de contraste entre les couleurs du composant ou des éléments graphiques porteurs d’informations qui le composent est suffisamment élevé ;\n3. Si c’est le cas pour chaque mécanisme, **le test est validé**.\n\nNote : le critère est non applicable dans ces situations :\n\n- Composant d''interface inactif (par exemple, un bouton avec un attribut `disabled`) sur lequel aucune action n''est possible ;\n- Composant d''interface pour lequel l''apparence est gérée par les styles natifs du navigateur sans aucune modification par l''auteur (par exemple, le style au focus natif dans Chrome ou Firefox) ;\n- Composant d''interface pour lequel la couleur n''est pas nécessaire pour identifier le composant ou son état (par exemple, un groupe de liens faisant office de navigation dont la position dans la page, la taille et la couleur du texte permettent de comprendre qu''il s''agit de liens même si la couleur du soulignement des liens avec le fond blanc n''a pas un ratio de 3:1 et que le texte lui a un ratio de 4.5:1) ;\n- Élément graphique ou parties d''élément graphique non porteur d''information ou ayant une alternative (description longue, informations identiques visibles dans la page) ;\n- Élément graphique ou parties d''élément graphique faisant partie d''un logo ou du nom de marque d''un organisme ou d''une société ;\n- Élément graphique ou parties d''élément graphique dont la présentation est essentielle à l''information véhiculée (exemple drapeaux, logotypes, photos de personnes ou de scènes, captures d''écran, diagrammes médicaux, carte de chaleurs) ;\n- Élément graphique ou parties d''élément graphique dynamiques dont le contraste au survol / focus est suffisant.\n"}'::jsonb
where identifier = '3.3' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"4.1.1":"1. Retrouver dans le document les médias temporels (éléments `<audio>`, `<video>` ou `<object>`) seulement audio qui nécessitent une transcription textuelle ;\n2. Pour chaque média temporel seulement audio, vérifier la présence d’une transcription textuelle :\n   - Soit accessible au moyen d’un bouton ou d’un lien adjacent (une URL ou une ancre) ;\n   - Soit adjacente clairement identifiable.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.1.2":"1. Retrouver dans le document les médias temporels (éléments `<video>` ou `<object>`) seulement vidéo qui nécessitent une transcription textuelle ;\n2. Pour chaque média temporel seulement vidéo, vérifier la présence :\n   - Soit d’une version alternative audio seulement accessible au moyen d’un lien ou bouton adjacent (une URL ou une ancre) ;\n   - Soit d’une version alternative audio seulement adjacente ;\n   - Soit d’une transcription textuelle accessible au moyen d’un bouton ou d’un lien adjacent (une URL ou une ancre) ;\n   - Soit d’une transcription textuelle adjacente clairement identifiable ;\n   - Soit d’une audiodescription synchronisée ;\n   - Soit d’une version alternative avec une audiodescription synchronisée accessible au moyen d’un bouton ou d''un lien adjacent (une URL ou une ancre).\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.1.3":"1. Retrouver dans le document les médias temporels (éléments `<video>` ou `<object>`) synchronisés qui nécessitent une transcription textuelle ;\n2. Pour chaque média temporel synchronisé, vérifier la présence :\n   - Soit d’une transcription textuelle accessible au moyen d’un lien ou bouton adjacent (une URL ou une ancre) ;\n   - Soit d’une transcription textuelle adjacente clairement identifiable ;\n   - Soit d’une audiodescription synchronisée ;\n   - Soit d’une version alternative avec une audiodescription synchronisée accessible au moyen d’un bouton ou d’un lien adjacent (une URL ou une ancre).\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n"}'::jsonb
where identifier = '4.1' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"4.10.1":"1. Au chargement du document, si un son se déclenche automatiquement, vérifier que :\n   - Soit la séquence sonore a une durée inférieure ou égale à 3 secondes ;\n   - Soit un dispositif (un bouton par exemple), sur l’élément ayant déclenché le son (voir note), ou dans la page, permet de le stopper ;\n   - Soit le volume de la séquence peut être contrôlé par l’utilisateur, indépendamment du contrôle de volume du système.\n2. Si c’est le cas, **le test est validé**.\n\nNote : les éléments suivants sont susceptibles de déclencher des sons au chargement de la page : éléments `<audio>`, `<video>`, `<object>`, `<embed>`, `<bgsound>` ou un code JavaScript (utilisation de la Web Audio API, par exemple).\n"}'::jsonb
where identifier = '4.10' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"4.11.1":"1. Retrouver dans le document les médias temporels ;\n2. Pour chaque média temporel, vérifier la présence des fonctionnalités obligatoires de contrôle de la consultation :\n   - Au minimum : lecture, pause ou stop ;\n   - Si le média a du son, il doit avoir une fonctionnalité d’activation / désactivation du son ;\n   - Si le média a des sous-titres, il doit avoir une fonctionnalité de contrôle de l’apparition/disparition des sous-titres ;\n   - Si le média a une audiodescription, il doit avoir une fonctionnalité de contrôle de l’apparition/disparition de l’audiodescription.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.11.2":"1. Retrouver dans le document les médias temporels pourvus de fonctionnalités de contrôle ;\n2. Pour chaque média temporel, vérifier que :\n   - Soit la fonctionnalité est accessible par le clavier et tout dispositif de pointage ;\n   - Soit une fonctionnalité accessible par le clavier et tout dispositif de pointage permettant de réaliser la même action est présente dans la page.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.11.3":"1. Retrouver dans le document les médias temporels pourvus de fonctionnalités de contrôle ;\n2. Pour chaque média temporel, vérifier que :\n   - Soit la fonctionnalité est activable par le clavier et tout dispositif de pointage ;\n   - Soit une fonctionnalité activable par le clavier et tout dispositif de pointage permettant de réaliser la même action est présente dans la page.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n"}'::jsonb
where identifier = '4.11' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"4.12.1":"1. Retrouver dans le document les médias non temporels pourvus de fonctionnalités de contrôle ;\n2. Pour chaque média non temporel, vérifier que :\n   - Soit la fonctionnalité est accessible par le clavier et tout dispositif de pointage ;\n   - Soit une fonctionnalité accessible par le clavier et tout dispositif de pointage permettant de réaliser la même action est présente dans la page.\n3. Si c’est le cas pour chaque média non temporel, **le test est validé**.\n","4.12.2":"1. Retrouver dans le document les médias non temporels pourvus de fonctionnalités de contrôle ;\n2. Pour chaque média non temporel, vérifier que :\n   - Soit la fonctionnalité est activable par le clavier et tout dispositif de pointage ;\n   - Soit une fonctionnalité activable par le clavier et tout dispositif de pointage permettant de réaliser la même action est présente dans la page.\n3. Si c’est le cas pour chaque média non temporel, **le test est validé**.\n"}'::jsonb
where identifier = '4.12' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"4.13.1":"1. Retrouver dans le document les médias temporels et non temporels ;\n2. Pour chaque média, vérifier que :\n   - Soit le nom, le rôle, la valeur, le paramétrage et les changements d’états des composants d’interfaces sont accessibles aux technologies d’assistance via une API d’accessibilité (par exemple, les zones mises à jour dynamiquement dans un lecteur vidéo sont correctement restituées) ;\n   - Soit une alternative compatible avec une API d’accessibilité permet d’accéder aux mêmes fonctionnalités.\n3. Si c’est le cas pour chaque média temporel ou non temporel, **le test est validé**.\n","4.13.2":"1. Retrouver dans le document les médias temporels et non temporels qui possèdent une alternative compatible avec les technologies d’assistance ;\n2. Pour chaque média, vérifier que :\n   - Soit l’alternative est adjacente au média temporel ou non temporel ;\n   - Soit l’alternative est accessible au moyen d’un lien ou d’un bouton adjacent ;\n   - Soit un mécanisme permet de remplacer le média temporel ou non temporel par son alternative.\n3. Si c’est le cas pour chaque média temporel ou non temporel, **le test est validé**.\n"}'::jsonb
where identifier = '4.13' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"4.2.1":"1. Retrouver dans le document les médias temporels pré-enregistrés seulement audio qui possèdent une transcription textuelle ;\n2. Pour chaque média temporel seulement audio, vérifier que transcription textuelle est pertinente ;\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.2.2":"1. Retrouver dans le document les médias temporels pré-enregistrés seulement vidéo qui possèdent une transcription textuelle ;\n2. Pour chaque média temporel seulement vidéo, vérifier la pertinence :\n   - Soit de la transcription textuelle ;\n   - Soit de l’audiodescription synchronisée ;\n   - Soit de l’audiodescription synchronisée de la version alternative ;\n   - Soit de la version alternative audio seulement.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.2.3":"1. Retrouver dans le document les médias temporels pré-enregistrés synchronisés ;\n2. Pour chaque média temporel synchronisé, vérifier la pertinence :\n   - Soit de la transcription textuelle ;\n   - Soit de l’audiodescription synchronisée ;\n   - Soit de l’audiodescription synchronisée de la version alternative.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n"}'::jsonb
where identifier = '4.2' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"4.3.1":"1. Retrouver dans le document les médias temporels pré-enregistrés synchronisés ;\n2. Pour chaque média temporel synchronisé, vérifier la présence :\n   - Soit de sous-titres synchronisés ;\n   - Soit d’une version alternative possédant des sous-titres synchronisés accessible au moyen d’un lien ou d’un bouton adjacent.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.3.2":"1. Retrouver dans le document les médias temporels synchronisés possédant des sous-titres synchronisés au moyen d’un élément `<track>` ;\n2. Pour chaque média temporel synchronisé, vérifier que la balise `<track>` possède un attribut `kind=\"caption\"` ;\n3. Si c’est le cas pour chaque média temporel synchronisé, **le test est validé**.\n"}'::jsonb
where identifier = '4.3' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"4.4.1":"1. Retrouver dans le document les médias temporels synchronisés possédant des sous-titres synchronisés ;\n2. Pour chaque média temporel synchronisé, vérifier que les sous-titres sont :\n   - Pertinents (toutes les informations sonores importantes sont présentes, les dialogues notamment) ;\n   - Et correctement synchronisés.\n3. Si c’est le cas pour chaque média temporel synchronisé, **le test est validé**.\n"}'::jsonb
where identifier = '4.4' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"4.5.1":"1. Retrouver dans le document les médias temporels pré-enregistrés seulement vidéo qui nécessitent une audiodescription ;\n2. Pour chaque média temporel seulement vidéo, vérifier la présence :\n   - Soit d’une audiodescription synchronisée ;\n   - Soit d’une version alternative avec une audiodescription synchronisée accessible au moyen d’un bouton ou d’un lien adjacent (une URL ou une ancre).\n3. Si c’est le cas pour chaque média temporel seulement vidéo, **le test est validé**.\n","4.5.2":"1. Retrouver dans le document les médias temporels pré-enregistrés synchronisés qui nécessitent une audiodescription ;\n2. Pour chaque média temporel synchronisé, vérifier la présence :\n   - Soit d’une audiodescription synchronisée ;\n   - Soit d’une version alternative avec une audiodescription synchronisée accessible au moyen d’un bouton ou d’un lien adjacent (une URL ou une ancre).\n3. Si c’est le cas pour chaque média temporel synchronisé, **le test est validé**.\n"}'::jsonb
where identifier = '4.5' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"4.6.1":"1. Retrouver dans le document les médias temporels seulement vidéo qui possèdent une audiodescription ;\n2. Pour chaque média temporel, vérifier que l’audiodescription synchronisée est pertinente (toutes les informations visuelles qu’il est possible de vocaliser dans les blancs de la bande son principale sont présentes, les textes incrustés notamment) ;\n3. Si c’est le cas pour chaque média temporel seulement vidéo, **le test est validé**.\n","4.6.2":"1. Retrouver dans le document les médias temporels synchronisés qui possèdent une audiodescription ;\n2. Pour chaque média temporel, vérifier que l’audiodescription synchronisée est pertinente (toutes les informations visuelles qu’il est possible de vocaliser dans les blancs de la bande son principale sont présentes, les textes incrustés notamment) ;\n3. Si c’est le cas pour chaque média temporel synchronisé, **le test est validé**.\n"}'::jsonb
where identifier = '4.6' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"4.7.1":"1. Retrouver dans le document les médias temporels pré-enregistrés seulement vidéo, audio ou synchronisés ;\n2. Pour chaque média temporel, vérifier que :\n   - Un passage de texte (un titre ou un paragraphe, par exemple) qui précède ou suit immédiatement le média temporel, permet de l’identifier ;\n   - Et le passage de texte est situé à l’extérieur du lecteur de contenu multimédia si ce dernier fait appel à la technologie Flash.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n"}'::jsonb
where identifier = '4.7' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"4.8.1":"1. Retrouver dans le document les médias non temporels ;\n2. Pour chaque média non temporel, vérifier qu’un lien ou un bouton adjacent, clairement identifiable :\n   - Soit contient l’adresse (url) d’une page contenant une alternative ;\n   - Soit permet d’accéder à une alternative dans la page.\n3. Si c’est le cas pour chaque média non temporel, **le test est validé**.\n","4.8.2":"1. Retrouver dans le document les médias non temporels associés à une alternative ;\n2. Pour chaque média non temporel, vérifier que :\n   - La page référencée par le lien ou le bouton adjacent est accessible ;\n   - L’alternative dans la page, référencée par le lien ou le bouton adjacent, est accessible.\n3. Si c’est le cas pour chaque média non temporel, **le test est validé**.\n\nNote : le critère est non applicable dans les situations où :\n\n- Le média non temporel est utilisé à des fins décoratives (c''est-à-dire qu''il n''apporte aucune information) ;\n- Le média non temporel est diffusé dans un environnement maîtrisé ;\n- Le média non temporel est inséré via JavaScript en vérifiant la présence et la version du plug-in, en remplacement d''un contenu alternatif déjà présent.\n"}'::jsonb
where identifier = '4.8' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"4.9.1":"1. Retrouver dans le document les médias non temporels associés à une alternative ;\n2. Pour chaque média non temporel, vérifier que l’alternative est pertinente (elle permet d’accéder au même contenu et à des fonctionnalités similaires) ;\n3. Si c’est le cas pour chaque média non temporel, **le test est validé**.\n"}'::jsonb
where identifier = '4.9' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"5.1.1":"1. Retrouver dans le document les tableaux de données complexes (tableau de données - élément `<table>` ou élément pourvu d’un attribut WAI-ARIA `role=\"table\"` - contenant des en-têtes qui ne sont pas répartis uniquement sur la première ligne et/ou la première colonne de la grille ou dont la portée n’est pas valable pour l’ensemble de la colonne ou de la ligne) ;\n2. Pour chaque tableau de données complexe, vérifier qu’un passage de texte permettant de comprendre la nature et la structure du tableau, est présent :\n   - Soit dans l’élément `<caption>` ;\n   - Soit dans l’attribut `summary` de l’élément `<table>` (dans les versions de HTML et de XHTML antérieures à HTML 5) ;\n   - Soit dans un passage de texte lié au tableau avec l’attribut `aria-describedby`.\n3. Si c’est le cas pour chaque tableau de données complexe, **le test est validé**.\n"}'::jsonb
where identifier = '5.1' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"5.2.1":"1. Retrouver dans le document les résumés de tableaux de données complexes (tels que déterminés par le test 5.1.1) ;\n2. Pour chaque résumé, vérifier que son contenu est pertinent ;\n3. Si c’est le cas pour chaque résumé de tableaux de données complexes, **le test est validé**.\n"}'::jsonb
where identifier = '5.2' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"5.3.1":"1. Retrouver dans le document les tableaux de mise en forme ;\n2. Pour chaque tableau de mise en forme, vérifier que :\n   - L’ordre d’accès aux cellules est cohérent avec le contenu ;\n   - L’élément `<table>` est pourvu d’un attribut WAI-ARIA `role=\"presentation\"`.\n3. Si c’est le cas pour chaque tableau de mise en forme, **le test est validé**.\n"}'::jsonb
where identifier = '5.3' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"5.4.1":"1. Retrouver dans le document les tableaux de données pourvus d’un titre ;\n2. Pour chaque titre, vérifier qu’il est fourni au moyen :\n   - Soit d’un élément `<caption>` ;\n   - Soit d’un attribut `title` ;\n   - Soit d’un attribut WAI-ARIA `aria-label` ;\n   - Soit d’un attribut WAI-ARIA `aria-labelledby` référençant un passage de texte.\n3. Si c’est le cas pour chaque titre de tableau de données, **le test est validé**.\n"}'::jsonb
where identifier = '5.4' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"5.5.1":"1. Retrouver dans le document les tableaux de données pourvus d’un titre ;\n2. Pour chaque titre, vérifier qu’il est pertinent ;\n3. Si c’est le cas pour chaque titre de tableau de données, **le test est validé**.\n"}'::jsonb
where identifier = '5.5' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"5.6.1":"1. Retrouver dans le document les tableaux de données ;\n2. Pour chaque en-tête de colonnes s’appliquant à la totalité de la colonne, vérifier que l’en-tête de colonne est structuré au moyen :\n   - Soit d’un élément `<th>` ;\n   - Soit d’un élément pourvu d’un attribut WAI-ARIA `role=\"columnheader\"`.\n3. Si c’est le cas pour chaque en-tête de colonne s’appliquant à la totalité de la colonne, **le test est validé**.\n","5.6.2":"1. Retrouver dans le document les tableaux de données ;\n2. Pour chaque en-tête de ligne s’appliquant à la totalité de la ligne, vérifier que l’en-tête de ligne est structuré au moyen :\n   - Soit d’un élément `<th>` ;\n   - Soit d’un élément pourvu d’un attribut WAI-ARIA `role=\"rowheader\"`.\n3. Si c’est le cas pour chaque en-tête de ligne s’appliquant à la totalité de la ligne, **le test est validé**.\n","5.6.3":"1. Retrouver dans le document les tableaux de données ;\n2. Pour chaque en-tête ne s’appliquant pas à la totalité de la ligne ou de la colonne, vérifier que l’en-tête de ligne est structuré au moyen d’un élément `<th>` ;\n3. Si c’est le cas pour chaque en-tête ne s’appliquant pas à la totalité de la ligne ou de la colonne, **le test est validé**.\n","5.6.4":"1. Retrouver dans le document les tableaux de données ;\n2. Pour chaque cellule associée à plusieurs en-têtes est-elle structurée au moyen d’une balise `<th>` ou `<td>` ;\n3. Si c’est le cas pour chaque en-tête ne s’appliquant pas à la totalité de la ligne ou de la colonne, **le test est validé**.\n"}'::jsonb
where identifier = '5.6' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"5.7.1":"1. Retrouver dans le document les tableaux de données ;\n2. Pour chaque en-tête (élément `<th>`) s’appliquant à la totalité de la ligne ou de la colonne, vérifier que l’élément `<th>` possède :\n   - Soit un attribut `id` unique ;\n   - Soit un attribut scope ;\n   - Soit un attribut WAI-ARIA `role=\"rowheader\"` ou `\"columnheader\"`.\n3. Si c’est le cas pour chaque en-tête s’appliquant à la totalité de la ligne ou de la colonne, **le test est validé**.\n","5.7.2":"1. Retrouver dans le document les tableaux de données ;\n2. Pour chaque en-tête (élément `<th>`) s’appliquant à la totalité de la ligne ou de la colonne et pourvu d’un attribut `scope`, vérifier que l’attribut `scope` possède :\n   - Soit une valeur `\"row\"` pour les en-têtes de ligne ;\n   - Soit une valeur `\"col\"` pour les en-têtes de colonne.\n3. Si c’est le cas pour chaque en-tête s’appliquant à la totalité de la ligne ou de la colonne et pourvu d’un attribut `scope`, **le test est validé**.\n","5.7.3":"1. Retrouver dans le document les tableaux de données ;\n2. Pour chaque en-tête (élément `<th>`) ne s’appliquant pas à la totalité de la ligne ou de la colonne, vérifier que l’élément `<th>` :\n   - Possède un attribut `id` unique ;\n   - Et ne possède pas d’attribut `scope `;\n   - Et ne possède pas d’attribut WAI-ARIA `role=\"rowheader\"` ou `\"columnheader\"`.\n3. Si c’est le cas pour chaque en-tête ne s’appliquant pas à la totalité de la ligne ou de la colonne, **le test est validé**.\n","5.7.4":"1. Retrouver dans le document les tableaux de données ;\n2. Pour chaque élément `<td>` ou `<th>` associé à un ou plusieurs en-têtes possédant un attribut `id`, vérifier que :\n   - L’élément `<td>` ou `<th>` possède un attribut `headers` ;\n   - Et l’attribut `headers` possède la liste des valeurs d’attribut `id` des en-têtes associés.\n3. Si c’est le cas pour chaque élément `<td>` ou `<th>` associé à un ou plusieurs en-têtes possédant un attribut `id`, **le test est validé**.\n","5.7.5":"1. Retrouver dans le document les tableaux de données ;\n2. Pour chaque en-tête s’appliquant à la totalité de la ligne ou de la colonne et pourvu d’un attribut WAI-ARIA `role=\"rowheader\"` ou `\"columnheader\"`, vérifier que l’élément possède :\n   - Soit un attribut WAI-ARIA `role=\"rowheader\"` pour les en-têtes de ligne ;\n   - Soit un attribut WAI-ARIA `role=\"columnheader\"` pour les en-têtes de colonne.\n3. Si c’est le cas pour chaque en-tête s’appliquant à la totalité de la ligne ou de la colonne et pourvu d’un attribut WAI-ARIA `role=\"rowheader\"` ou `\"columnheader\"`, **le test est validé**.\n"}'::jsonb
where identifier = '5.7' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"5.8.1":"1. Retrouver dans le document les tableaux de mise en forme ;\n2. Pour chaque tableau de mise en forme, vérifier que :\n   - L’élément `<table>` ne possède pas d''attribut `summary`, d’éléments enfant `<caption>`, `<thead>`, `<th>`, `<tfoot>` ou d’éléments pourvus d’un attribut WAI-ARIA `role=\"rowheader\"` ou `role=\"columnheader\"` ;\n   - Les éléments `<td>` ne possèdent pas d’attributs `scope`, `headers` et `axis`.\n3. Si c’est le cas pour chaque tableau de mise en forme, **le test est validé**.\n"}'::jsonb
where identifier = '5.8' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"6.1.1":"1. Retrouver dans le document les liens texte ;\n2. Pour chaque lien texte, vérifier que ce qui permet d’en comprendre la fonction et la destination est :\n   - Soit l’intitulé du lien seul ;\n   - Soit le contexte du lien.\n3. Si c’est le cas pour chaque lien texte, **le test est validé**.\n","6.1.2":"1. Retrouver dans le document les liens image (lien avec pour contenu un élément `<img>` ou un élément ayant l’attribut WAI-ARIA `role=\"img\"`, un élément `<area>` possédant un attribut `href`, un élément `<object>`, un élément `<canvas>` ou un élément `<svg>`) ;\n2. Pour chaque lien image, vérifier que ce qui permet d’en comprendre la fonction et la destination est :\n   - Soit l’intitulé du lien seul, fourni par l’alternative textuelle de l’image ;\n   - Soit le contexte du lien.\n3. Si c’est le cas pour chaque lien image, **le test est validé**.\n","6.1.3":"1. Retrouver dans le document les liens composites (lien composé à la fois de contenu texte et d’éléments de type image) ;\n2. Pour chaque lien composite, vérifier que ce qui permet d’en comprendre la fonction et la destination est :\n   - Soit l’intitulé du lien seul, fourni par la combinaison du contenu texte et de l’alternative textuelle de l’image ;\n   - Soit le contexte du lien.\n3. Si c’est le cas pour chaque lien composite, **le test est validé**.\n","6.1.4":"1. Retrouver dans le document les liens SVG (élément `<svg>` qui possède un élément `<a>` pourvu d’un attribut `xlink-href` (SVG 1.1) ou `href` (SVG 2)) ;\n2. Pour chaque lien SVG, vérifier que ce qui permet d’en comprendre la fonction et la destination est :\n   - Soit l’intitulé du lien seul, fourni par le nom accessible de l’élément `<svg>` (résolu généralement à partir du contenu d’un élément `<text>`) ;\n   - Soit le contexte du lien.\n3. Si c’est le cas pour chaque lien SVG, **le test est validé**.\n","6.1.5":"1. Retrouver dans le document les liens autres que SVG dont le contenu est fourni à la fois par un intitulé visible et par le contenu soit d’un attribut title ou d’un attribut `aria-label` ou d’un attribut `aria-labelledby` ;\n2. Pour chaque lien, vérifier que le contenu de l’attribut `title` ou de l’attribut `aria-label` ou de l’attribut `aria-labelledby` contient l’intitulé visible ;\n3. Si c’est le cas pour chaque lien, **le test est validé** pour les liens autres que SVG.\n4. Retrouver dans le document les liens SVG dont le contenu est fourni à la fois par un intitulé visible et par le contenu soit d’un attribut `aria-labelledby`, ou d’un attribut `aria-label` ou d’un élément title (enfant direct de l’élément `<svg>`) ou d’un attribut x-link:title (SVG 1.1) ou d’un ou plusieurs éléments `<text>`;\n5. Pour chaque lien SVG, vérifier que le contenu de l’attribut `aria-labelledby` ou de l’attribut `aria-label` ou de l’élément `<title>` ou de l’attribut `x-link:title` ou d’un ou plusieurs éléments `<text>` contient l’intitulé visible ;\n6. Si c’est le cas pour chaque lien SVG, **le test est validé** pour les liens SVG.\n7. Si le test est validé à la fois pour les liens non SVG et pour les liens SVG, le test est globalement validé.\n\nNote : considérant la détermination du nom accessible, il existe deux cas particuliers et une particularité liée aux expressions mathématiques :\n\n- La ponctuation et les lettres majuscules présentes dans le texte de l’intitulé visible peuvent être ignorées dans le nom accessible sans porter à conséquence.\n- Si le texte de l’intitulé visible sert de symbole, il ne doit pas être interprété littéralement au niveau du nom accessible. Le nom doit exprimer la fonction véhiculée par le symbole (par exemple, \"B\" au niveau d''un éditeur de texte aura pour nom accessible \"Mettre en gras\", le signe \">\" en fonction du contexte signifiera \"Suivant\" ou \"Lancer la vidéo\"). Le cas des symboles mathématiques fait cependant exception (voir le point ci-dessous).\n- Si l''étiquette visible représente une expression mathématique, les symboles mathématiques peuvent être repris littéralement pour servir d''étiquette au nom accessible (par exemple, \"A>B\"). Il est laissé à l''utilisateur le soin d''opérer la correspondance entre l''expression et ce qu''il doit épeler compte tenu de la connaissance qu''il a du fonctionnement de son logiciel de saisie vocale (\"A plus grand que B\" ou \"A supérieur à B\").\n"}'::jsonb
where identifier = '6.1' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"6.2.1":"1. Retrouver dans le document les liens quels qu’ils soient ;\n2. Pour chaque lien, vérifier que le contenu de l’élément `<a>` (ou d’un élément pourvu d’un attribut WAI-ARIA `role=link`) contient un intitulé (texte ou alternative) ;\n3. Si c’est le cas pour chaque lien, **le test est validé**.\n"}'::jsonb
where identifier = '6.2' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"7.1.1":"1. Retrouver dans le document tous les composants d’interface générés ou contrôlés au moyen de JavaScript ;\n2. Vérifier que :\n   - Le composant possède un rôle cohérent avec son usage (généralement un bouton ou un lien) ;\n   - Le composant possède un nom explicite ;\n   - Le nom du composant est cohérent avec l’état de la fonctionnalité ou des contenus contrôlés (par exemple pour une fonctionnalité permettant d’afficher ou de masquer une zone de contenu).\n3. Sinon, vérifier la présence d’un composant d’interface accessible permettant d’accéder aux mêmes fonctionnalités ;\n4. Sinon, vérifier la présence d’une alternative accessible permettant d’accéder aux mêmes fonctionnalités.\n5. Si c’est le cas, **le test est validé**.\n","7.1.2":"1. Pour chacun des composants d’interface ayant validé le test 7.1.1, vérifier que le composant d’interface est correctement restitué par les technologies d’assistance ;\n2. Sinon, vérifier qu’une alternative accessible au composant d’interface permet d’accéder aux mêmes fonctionnalités ;\n3. Si c’est le cas, **le test est validé**.\n","7.1.3":"1. Pour chacun des composants d’interface ayant validé le test 7.1.1, vérifier que le composant d’interface possède :\n   - Un nom pertinent (intitulé visible) ;\n   - Un rôle pertinent.\n2. Si le composant d’interface possède un nom accessible, vérifier que ce nom est pertinent et contient au moins l’intitulé visible.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '7.1' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"7.2.1":"1. Retrouver les alternatives aux fonctionnalités JavaScript :\n2. Chercher dans la page, les alternatives à un composant ou une fonctionnalité JavaScript mises à disposition.\n3. Désactiver JavaScript dans le document et retrouver les alternatives proposées.\n4. Pour chacune des alternatives proposées, vérifier qu’elle permet d’accéder aux mêmes contenus et à des fonctionnalités similaires.\n5. Si c’est le cas, **le test est validé**.\n","7.2.2":"1. Retrouver dans le document tous les éléments non textuels mis à jour par une fonctionnalité JavaScript.\n2. Si l''élément non textuel a une alternative, vérifier que :\n   - L''alternative est mise à jour lorsque le contenu non textuel est mis à jour ;\n   - L''alternative mise à jour est pertinente.\n3. Si c''est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '7.2' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"7.3.1":"1. Retrouver dans le document, tous les éléments sur lesquels est implémenté un gestionnaire d’événements JavaScript (par exemple click, focus, mouseover, blur, keydown, touch…).\n2. Vérifier que l’élément est accessible au moyen du clavier :\n   - Il est atteignable avec la touche de tabulation (tab) ;\n   - Si l’élément gère une action simple, il est activable au clavier avec la touche entrée (Entrée) ;\n   - Si l’élément gère une action complexe, il est utilisable avec le clavier (généralement avec les touches de direction).\n3. Sinon, vérifier qu’un élément accessible par le clavier permettant de réaliser la même action est présent dans la page.\n4. Vérifier que l’élément est accessible par tout dispositif de pointage (souris, toucher, stylet…).\n5. Sinon, vérifier qu’un élément accessible au moyen d’un dispositif de pointage et permettant de réaliser la même action est présent dans la page.\n6. Si c’est le cas, **le test est validé**.\n","7.3.2":"1. Activer, l’un après l’autre, tous les éléments capables de recevoir le focus.\n2. Vérifier que le focus n’est pas supprimé via une fonctionnalité JavaScript.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '7.3' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"7.4.1":"1. Retrouver dans le document tous les événements JavaScript qui initient un changement de contexte, par exemple :\n   - Une mise à jour dynamique de champs de formulaire ;\n   - L’ouverture d’une nouvelle page à l’activation d’une option d’une liste de sélection (élément `<select>`) ;\n   - La mise à jour, via un procédé AJAX d’une partie essentielle de la page ;\n   - Le lancement automatique d’un lecteur vidéo suite à la sélection d’une playlist ;\n   - La manipulation du focus ayant pour résultat de modifier la position courante de l’utilisateur dans la page.\n2. Vérifier que :\n   - L’utilisateur est averti par un message de l’action du script et du type de changement avant son déclenchement ;\n   - Ou bien le changement de contexte est initié par un bouton (input de type submit, button ou image ou la balise button) explicite ;\n   - Ou bien le changement de contexte est initié par un lien explicite.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '7.4' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"7.5.1":"1. Retrouver dans le document les messages qui valent pour message de statut.\n2. Pour chacun de ces messages, déterminer la nature de l’information dont est porteur le message :\n3. Si le message informe de la réussite, du résultat d’une action ou bien de l’état d’une application, vérifier que l’élément qui contient le message :\n   - Soit utilise l’attribut WAI-ARIA `role=”status”` ;\n   - Soit utilise les attributs WAI-ARIA `aria-live=”polite”` et `aria-atomic=”true”`.\n4. Si le message présente une suggestion, ou avertit de l’existence d’une erreur, vérifier que l’élément qui contient le message :\n   - Soit utilise l’attribut WAI-ARIA `role=”alert”` ;\n   - Soit utilise les attributs `aria-live=”assertive”` et `aria-atomic=”true”`.\n5. Si le message indique la progression d’un processus, vérifier que l’élément qui contient le message :\n   - Soit utilise l’un des attributs WAI-ARIA `role=”log”`, `role=”progressbar”` ou `role=”status”` ;\n   - Soit utilise l’attribut WAI-ARIA `aria-live=”polite”` si l’intention est de signaler l’équivalent d’un `rôle “log”` ;\n   - Soit utilise les attributs WAI-ARIA `aria-live=”polite”` et aria-atomic=”true si l’intention est de signaler l’équivalent d’un rôle “status”.\n6. Si c’est le cas, **le test est validé**.\n","7.5.2":"Tests identiques à 7.5.1\n","7.5.3":"Tests identiques à 7.5.1\n"}'::jsonb
where identifier = '7.5' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"8.1.1":"1. Retrouver dans le document la balise DOCTYPE (par exemple `<!DOCTYPE html>`) ;\n2. Vérifier que :\n   - La balise DOCTYPE est placée avant la balise `<html>` ;\n   - Le type de document est valide.\n3. Si c’est le cas, **le test est validé**.\n","8.1.2":"Tests identiques à 8.1.1\n","8.1.3":"Tests identiques à 8.1.1\n"}'::jsonb
where identifier = '8.1' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"8.10.1":"1. Retrouver dans le document les passages de textes qui utilisent une langue qui se lit dans le sens inverse de la langue du document (comme l’arabe ou l’hébreu pour le français par exemple).\n2. Pour chaque passage de texte, vérifier que le passage de texte est contenu dans une balise qui possède un attribut `dir`.\n3. Si c’est le cas pour chaque passage de texte, **le test est validé**.\n","8.10.2":"1. Pour chaque passage de texte validé au test 8.10.1, vérifier que :\n   - L’indication de sens de lecture est conforme (ltr, pour le sens « de gauche à droite » et rtl pour le sens « de droite à gauche ») ;\n   - L’indication de sens de lecture est pertinente.\n2. Si c’est le cas pour chaque passage de texte, **le test est validé**.\n"}'::jsonb
where identifier = '8.10' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"8.2.1":"1. Dans le menu « Check », activer l’option « W3C Nu markup checker (all frames) ».\n2. Dans la page de résultats, vérifier que :\n   - Les balises, attributs et valeurs d’attributs respectent les règles d’écriture ;\n   - L’imbrication des balises est conforme ;\n   - L’ouverture et la fermeture des balises sont conformes ;\n   - Les valeurs d’attribut id sont uniques dans la page ;\n   - Les attributs ne sont pas doublés sur un même élément.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '8.2' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"8.3.1":"1. Retrouver dans le document l’indication de langue par défaut ;\n2. Vérifier la présence d’une indication de langue :\n   - Soit au moyen de l’attribut lang sur la balise html si le code est du HTML5 ou du HTML4 ;\n   - Soit au moyen des attributs lang et xml:lang sur la balise html si le code est du XHTML 1.0 ;\n   - Soit au moyen de l’attribut xml:lang sur la balise html si le code est du XHTML 1.1 ;\n   - Sinon, vérifier la présence d’une indication de langue sur chaque élément de texte ou l’un de ses parents.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '8.3' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"8.4.1":"1. Retrouver dans le document l’indication de langue par défaut ;\n2. Vérifier la présence d’un code de langue :\n   - Valide (conforme à la norme ISO 639-1 ou ISO 639-2 et suivantes) ;\n   - Et pertinent (qui indique la langue principale du document).\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '8.4' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"8.5.1":"Test 8.5.1\n\n1. Retrouver dans le document le titre structuré au moyen d’un élément `<title>` ;\n2. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '8.5' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"8.6.1":"1. Retrouver dans le document le titre structuré au moyen d’un élément `<title>` ;\n2. Vérifier si le contenu de l’élément `<title>` est suffisamment pertinent (il permet de retrouver la page dans l’historique de navigation ou la liste des onglets).\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '8.6' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"8.7.1":"1. Retrouver les passages de texte en langue étrangère, à l’exception :\n   - Des noms propres ;\n   - Des mots d’origine étrangère, présents dans le dictionnaire de la langue du document ;\n   - Des mots d’origine étrangère et d’usage courant dont la prononciation ne provoque pas d’incompréhension.\n   - Vérifier que chaque passage de texte retenu possède une indication de langue (attribut `lang` et/ou `xml:lang` sur l’élément lui-même ou l’un de ses parents).\n2. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '8.7' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"8.8.1":"1. Pour chaque passage de texte validé au test 8.7.1, vérifier que :\n   - L’indication de langue est valide ;\n   - L’indication de langue est pertinente.\n2. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '8.8' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"8.9.1":"1. Retrouver dans le document l’ensemble des éléments sémantiques utilisés à des fins de présentation ;\n2. Pour chacun de ces éléments, vérifier que :\n   - L’élément est pourvu d’un attribut `role=\"presentation\"` ;\n   - L’utilisation de cet élément à des fins de présentation reste justifée.\n3. Si c’est le cas, **le test est validé**.\n\nNote : Quelques exemples, non exhaustifs de détournement de balisage : un élément `<div>` utilisé comme paragraphe, un titre utilisé comme légende, un élément `<blockquote>` ou des paragraphes vides ou encore des espaces utilisés pour créer des effets de marges.\nL''utilisation d''un `role=\"presentation\"` est formellement déconseillée, mais peut toutefois se justifier dans de rares cas. Cela peut être acceptable sur un élément `<blockquote>` ou un paragraphe vide, mais sera considéré comme non-conforme sur un titre.\n\nLe cas des tableaux : à noter que ce test aborde les tableaux de présentation qui ne devraient finalement pas apparaître au sein de la thématique Tableaux.\n"}'::jsonb
where identifier = '8.9' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"9.1.1":"1. Retrouver dans le document les titres (balise `<hx>` ou balise possédant un attribut WAI-ARIA `role=\"heading\"` associé à un attribut WAI-ARIA `aria-level`) ;\n2. Vérifier que la hiérarchie entre les titres est pertinente ;\n3. Si c’est le cas, **le test est validé**.\n","9.1.2":"1. Pour chaque titre identifié au test 9.1.1, vérifier que son contenu est pertinent ;\n2. Si c’est le cas pour chaque titre, **le test est validé**.\n","9.1.3":"1. Pour chaque titre identifié au test 9.1.1, vérifier que :\n   - Soit il est structuré au moyen d’une balise `<hx>` (“x” désignant une valeur numérique comprise entre 1 et 6);\n   - Soit il est structuré au moyen d’une balise possédant un attribut WAI-ARIA `role=\"heading\"` et un attribut WAI-ARIA `aria-level=x` (“x” désignant une valeur numérique).\n2. Si c’est le cas pour chaque titre, **le test est validé**.\n"}'::jsonb
where identifier = '9.1' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"9.2.1":"1. Vérifier que la zone d’en-tête est structurée au moyen d’un élément `<header>` ;\n2. Vérifier que les zones de navigation principales et secondaires sont structurées au moyen d’un élément `<nav>` ;\n3. Vérifier que l’élément `<nav>` n’est pas utilisé en dehors de la structuration des zones de navigation principales et secondaires ;\n4. Vérifier que la zone de contenu principal est structurée au moyen d’un élément `<main>` ;\n5. Si le document possède plusieurs éléments `<main>`, vérifier qu’un seul de ces éléments est visible (les autres occurrences de l’élément sont pourvues d’un attribut `hidden`) ;\n6. Vérifier que la zone de pied de page est structurée au moyen d’un élément `<footer>`.\n7. Si c’est le cas pour chaque zone de contenu, **le test est validé**.\n"}'::jsonb
where identifier = '9.2' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"9.3.1":"1. Retrouver dans le document les éléments regroupés visuellement sous la forme d’une liste non ordonnée ;\n2. Pour chaque liste, vérifier que la liste est structurée :\n   - Soit au moyen des éléments `<ul>` et `<li>` ;\n   - Soit au moyen d’éléments pourvus d’attributs WAI-ARIA `role=\"list\"` et `role=\"listitem\"`.\n3. Si c’est le cas pour chaque liste non ordonnée, **le test est validé**.\n","9.3.2":"1. Retrouver dans le document les éléments regroupés visuellement sous la forme d’une liste ordonnée ;\n2. Pour chaque liste, vérifier que la liste est structurée :\n   - Soit au moyen des éléments `<ol>` et `<li>` ;\n   - Soit au moyen d’éléments pourvus d’attributs WAI-ARIA `role=\"list\"` et `role=\"listitem\"`.\n3. Si c’est le cas pour chaque liste ordonnée, **le test est validé**.\n","9.3.3":"1. Retrouver dans le document les éléments regroupés visuellement sous la forme d’une liste de description ;\n2. Pour chaque liste, vérifier que la liste est structurée au moyen des éléments `<dl>`, `<dt>` et `<dd>` ;\n3. Si c’est le cas pour chaque liste de description, **le test est validé**.\n"}'::jsonb
where identifier = '9.3' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

update public.criteria set test_procedures = '{"9.4.1":"1. Retrouver dans le document les citations courtes (ou en ligne) ;\n2. Pour chaque citation, vérifier que la citation est structurée au moyen d’un élément `<q>` ;\n3. Si c’est le cas pour chaque citation courte, **le test est validé**.\n","9.4.2":"1. Retrouver dans le document les blocs de citation ;\n2. Pour chaque bloc de citation, vérifier que le bloc de citation est structuré au moyen d’un élément `<blockquote>` ;\n3. Si c’est le cas pour chaque bloc de citation, **le test est validé**.\n"}'::jsonb
where identifier = '9.4' and thematic_id in (select id from public.thematics where reference_id = '11111111-1111-1111-1111-111111111111');

-- ============================================================================
-- RAWeb 1.1
-- ============================================================================

update public.criteria set test_procedures = '{"1.1.1":"1. Retrouver dans le document les images structurées au moyen d’un élément `<img>` ou d’un élément possédant l’attribut WAI-ARIA `role=\"img\"`.\n2. Pour chaque image, déterminer si l’image est porteuse d’information.\n3. Dans le cas où il s’agit d’un élément `<img>`, vérifier que l’image est pourvue au moins d’une alternative textuelle parmi les suivantes :\n   - passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - contenu de l’attribut WAI-ARIA `aria-label` ;\n   - contenu de l’attribut `alt` ;\n   - contenu de l’attribut `title`.\n4. Dans le cas où il s’agit d’un élément possédant l’attribut WAI-ARIA `role=\"img\"`, vérifier que l’image est pourvue au moins d’une alternative textuelle parmi les suivantes :\n   - passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - contenu de l’attribut WAI-ARIA `aria-label`.\n5. Si au moins une alternative textuelle est trouvée, **le test est validé**.\n","1.1.2":"1. Retrouver dans le document les éléments `<area>`.\n2. Pour chaque élément `<area>`, déterminer si la zone réactive est porteuse d’information.\n3. Vérifier que la zone réactive est pourvue au moins d’une alternative textuelle parmi les suivantes :\n   - contenu de l’attribut WAI-ARIA `aria-label` ;\n   - contenu de l’attribut `alt` ;\n4. Si au moins une alternative textuelle est trouvée, **le test est validé**.\n","1.1.3":"1. Retrouver dans le document les éléments `<input>` pourvus de l’attribut `type=\"image\"`.\n2. Pour chaque élément `<input>` pourvu de l’attribut type=\"image\", déterminer si l’image utilisée est porteuse d’information.\n3. Vérifier que l’élément `<input>` est pourvu au moins d’une alternative textuelle parmi les suivantes :\n   - passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - contenu de l’attribut WAI-ARIA `aria-label` ;\n   - contenu de l’attribut `alt` ;\n   - contenu de l’attribut `title`.\n4. Si au moins une alternative textuelle est trouvée, **le test est validé**.\n","1.1.4":"1. Retrouver dans le document les éléments `<img>` pourvus de l’attribut `ismap`.\n2. Pour chaque élément `<img>` pourvu de l’attribut `ismap`, vérifier la présence d’un lien ou d’un ensemble de liens (ou bien d’un autre type de composant d’interface qui jouerait un rôle similaire comme une liste de sélection, par exemple) permettant d’accéder aux mêmes ressources que lorsque l’image fait l’objet d’un clic.\n3. Si c’est le cas, **le test est validé**.\n","1.1.5":"1. Retrouver dans le document les éléments `<svg>`.\n2. Pour chaque élément `<svg>`, déterminer si l’image est porteuse d’information.\n3. S’assurer que l’élément `<svg>` est pourvu d’un attribut WAI-ARIA `role=\"img\"`.\n4. Si ce n’est pas le cas, le test est invalidé.\n5. Le cas échéant, vérifier que l’élément `<svg>` est pourvu au moins d’une alternative textuelle parmi les suivantes :\n   - contenu de l’élément `<title>` ;\n   - passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - contenu de l’attribut WAI-ARIA `aria-label` ;\n6. Si au moins une alternative textuelle est trouvée, **le test est validé**.\n","1.1.6":"1. Retrouver dans le document les balises ouvrantes `<object>` pourvues de l’attribut `type=\"image/…\"`.\n2. Pour chaque balise ouvrante `<object>` pourvue de l’attribut `type=\"image/…\"`, déterminer si l’image utilisée est porteuse d’information.\n3. Vérifier que l’élément `<object>` est pourvu d’un attribut WAI-ARIA `role=\"img\"`.\n4. Vérifier que l’élément `<object>` est pourvu au moins d’une alternative textuelle parmi les suivantes :\n   - passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - contenu de l’attribut WAI-ARIA `aria-label` ;\n   - contenu de l’attribut `title`.\n5. Si au moins une alternative textuelle est trouvée, **le test est validé**.\n6. Sinon, vérifier que :\n   - soit l’élément `<object>` est immédiatement suivi d’un lien ou bouton adjacent permettant d’accéder à un contenu alternatif ;\n   - soit un mécanisme permet à l’utilisateur de remplacer l’élément `<object>` par un contenu alternatif.\n7. Si c’est le cas, **le test est validé**.\n","1.1.7":"1. Pour chaque élément `<embed>` pourvu de l’attribut `type=\"image/…\"`, déterminer si l’image utilisée est porteuse d’information.\n2. Vérifier que l’élément `<embed>` est pourvu d’un attribut WAI-ARIA `role=\"img\"`.\n3. Vérifier que l’élément `<embed>` est pourvu au moins d’une alternative textuelle parmi les suivantes :\n   - passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - contenu de l’attribut WAI-ARIA `aria-label` ;\n   - contenu de l’attribut `title`.\n4. Si au moins une alternative textuelle est trouvée, **le test est validé**.\n6. Sinon, vérifier que :\n   - soit l’élément `<object>` est immédiatement suivi d’un lien ou bouton adjacent permettant d’accéder à un contenu alternatif ;\n   - soit un mécanisme permet à l’utilisateur de remplacer l’élément `<object>` par un contenu alternatif.\n6. Si c’est le cas, **le test est validé**.\n","1.1.8":"1. Retrouver dans le document les éléments `<canvas>`.\n2. Pour chaque élément `<canvas>`, déterminer si l’image utilisée est porteuse d’information.\n3. Vérifier que l’élément `<canvas>` est pourvu d’un attribut WAI-ARIA `role=\"img\"`.\n4. Vérifier que la balise ouvrante `<canvas>` est pourvue au moins d’une alternative textuelle parmi les suivantes :\n   - passage de texte associé via l’attribut WAI-ARIA `aria-labelledby` ;\n   - contenu de l’attribut WAI-ARIA `aria-label`.\n5. Si au moins une alternative textuelle est trouvée, **le test est validé**.\n6. Si les étapes 3 et 4 ne sont pas satisfaites, vérifier que :\n   - l’élément `<canvas>` est pourvu d’un contenu alternatif présent entre les balises `<canvas>` et `</canvas>` ;\n   - ou que l’élément `<canvas>` est immédiatement suivi d’un lien ou bouton adjacent permettant d’accéder à un contenu alternatif ;\n   - ou qu’un mécanisme permet à l’utilisateur de remplacer l’élément `<canvas>` par un contenu alternatif.\n7. Si c’est le cas, **le test est validé**.\n\nNote : si l’élément `<canvas>` dispose d’un rôle `img`, son alternative ne peut  être fournie que par les techniques listées à l’étape 4.\n"}'::jsonb
where identifier = '1.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"1.2.1":"1. Retrouver dans le document les images décoratives dépourvues de légende structurées au moyen d’un élément `<img>`.\n2. Pour chaque image, vérifier que l’image possède un attribut `aria-hidden=\"true\"`.\n3. Sinon, vérifier que l’image possède un attribut `role=\"presentation\"` ou un `role=\"none\"` et qu’elle est dépourvue des attributs `aria-labelledby`, `aria-label` et `title`.\n4. Sinon, vérifier que l’image possède un `alt` vide (`alt=\"\"`) et qu’elle est dépourvue des attributs `aria-labelledby`, `aria-label` et `title`.\n5. Si c’est le cas pour chaque image, le test est validé.","1.2.2":"1. Retrouver dans le document les images décoratives dépourvues de légende structurées au moyen d’un élément `<area>` (sans attribut `href`).\n2. Pour chaque image, vérifier que l’élément `<area>` possède un attribut `aria-hidden=\"true\"`.\n3. Sinon, vérifier que l’élément `<area>` possède un attribut `role=\"presentation\"` ou un `role=\"none\"` et qu’elle est dépourvue des attributs `aria-labelledby`, `aria-label` et `title`.\n4. Sinon, vérifier que l’élément `<area>` possède un `alt` vide (`alt=\"\"`) et qu’elle est dépourvue des attributs `aria-labelledby`, `aria-label` et `title`.\n5. Si c’est le cas pour chaque image, le test est validé.","1.2.3":"1. Retrouver dans le document les images décoratives structurées dépourvues de légende au moyen d’un élément `<object>` (avec un attribut `type=\"image/…\"`).\n2. Pour chaque image, vérifier que la balise ouvrante `<object>` ne possède pas d’attributs `aria-labelledby`, `aria-label` ou `title` et qu’elle :\n   - possède un attribut WAI-ARIA `aria-hidden=\"true\"` ;\n   - et est dépourvue d’alternative textuelle ;\n   - et est dépourvue d’un contenu alternatif présent entre les balises `<object>` et `</object>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.2.4":"1. Retrouver dans le document les images décoratives dépourvues de légende structurées au moyen d’un élément `<svg>`.\n2. Pour chaque image, vérifier que l’élément `<svg>` possède un attribut WAI-ARIA `aria-hidden=\"true\"`.\n3. Si c’est le cas pour chaque image, **le test est validé**.","1.2.5":"1. Retrouver dans le document les images décoratives dépourvues de légende structurées au moyen d’un élément `<canvas>`.\n2. Pour chaque image, vérifier que l’élément `<canvas>` ne possède pas d’attributs `aria-labelledby`, `aria-label` ou `title` et qu’il :\n   - possède un attribut WAI-ARIA `aria-hidden=\"true\"` ;\n   - et est dépourvu d’alternative textuelle ;\n   - et est dépourvu d’un contenu alternatif présent entre les balises `<canvas>` et `</canvas>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.2.6":"1. Retrouver dans le document les images décoratives dépourvues de légende structurées au moyen d’un élément `<embed>` (avec un attribut `type=\"image/…\"`).\n2. Pour chaque image, vérifier que l’élément `<embed>` ne possède pas d’attributs `aria-labelledby`, `aria-label` ou `title` et qu’il :\n   - possède un attribut WAI-ARIA `aria-hidden=\"true\"` ;\n   - et est dépourvu d’alternative textuelle ;\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"1.3.1":"1. Retrouver dans le document les images structurées au moyen d’un élément `<img>` (ou d’un élément possédant l’attribut WAI-ARIA `role=\"img\"`) pourvues d’une alternative textuelle.\n2. Pour chaque image, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.2":"1. Retrouver dans le document les éléments `<area>` pourvus d’une alternative textuelle.\n2. Pour chaque élément `<area>`, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.3":"1. Retrouver dans le document les éléments `<input>` pourvus de l’attribut `type=\"image\"` et d’une alternative textuelle.\n2. Pour chaque élément `<input>` pourvu de l’attribut `type=\"image\"`, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.4":"1. Retrouver dans le document les éléments `<object>` pourvus de l’attribut `type=\"image/…\"` et d’une alternative textuelle.\n2. Pour chaque élément `<object>` pourvu de l’attribut `type=\"image/…\"`, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.5":"1. Retrouver dans le document les éléments `<embed>` pourvus de l’attribut `type=\"image/…\"` et d’une alternative textuelle.\n2. Pour chaque élément `<embed>` pourvu de l’attribut `type=\"image/…\"`, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.6":"1. Retrouver dans le document les éléments `<svg>` pourvus d’une alternative textuelle.\n2. Pour chaque élément `<svg>`, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.7":"1. Retrouver dans le document les éléments `<canvas>` pourvus d’une alternative textuelle.\n2. Pour chaque élément `<canvas>`, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.8":"1. Retrouver dans le document les éléments `<canvas>` pourvus d’un contenu alternatif entre les balises `<canvas>` et `</canvas>`.\n2. Pour chaque élément `<canvas>`, vérifier que le contenu alternatif est correctement restitué par les technologies d’assistance.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.3.9":"1. Retrouver dans le document les images pourvues d’une alternative textuelle.\n2. Pour chaque image, vérifier l’alternative textuelle est courte et concise.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"1.4.1":"1. Retrouver dans le document les images structurées au moyen d’un élément `<img>` pourvues d’une alternative textuelle et utilisées comme CAPTCHA ou comme image-test.\n2. Pour chaque image, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.4.2":"1. Retrouver dans le document les éléments `<area>` pourvus d’une alternative textuelle et utilisés comme CAPTCHA ou comme image-test.\n2. Pour chaque élément `<area>`, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.4.3":"1. Retrouver dans le document les éléments `<input>` pourvus de l’attribut `type=\"image\"` et d’une alternative textuelle, et utilisés comme CAPTCHA ou comme image-test.\n2. Pour chaque élément `<input>` pourvu de l’attribut `type=\"image\"`, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.4.4":"1. Retrouver dans le document les éléments `<object>` pourvus de l’attribut `type=\"image/…\"` et d’une alternative textuelle, et utilisés comme CAPTCHA ou comme image-test.\n2. Pour chaque élément `<object>` pourvu de l’attribut `type=\"image/…\"`, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.4.5":"1. Retrouver dans le document les éléments `<embed>` pourvus de l’attribut `type=\"image/…\"` et d’une alternative textuelle, et utilisés comme CAPTCHA ou comme image-test.\n2. Pour chaque élément `<embed>` pourvu de l’attribut `type=\"image/…\"`, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.4.6":"1. Retrouver dans le document les éléments `<svg>` pourvus d’une alternative textuelle et utilisés comme CAPTCHA ou comme image-test.\n2. Pour chaque élément `<svg>`, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.4.7":"1. Retrouver dans le document les éléments `<canvas>` pourvus d’une alternative textuelle et utilisés comme CAPTCHA ou comme image-test.\n2. Pour chaque élément `<canvas>`, vérifier que l’alternative textuelle est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.4' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"1.5.1":"1. Retrouver dans le document les images (éléments `<img>`, `<area>`, `<object>`, `<embed>`, `<svg>`, `<canvas>` ou possédant un attribut WAI-ARIA `role=\"img\"`) utilisés comme CAPTCHA ou comme image-test.\n2. Pour chaque image, vérifier qu’il existe :\n   - soit une autre forme de CAPTCHA non graphique, au moins ;\n   - soit une autre solution d’accès à la fonctionnalité qui est sécurisée par le CAPTCHA.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.5.2":"1. Retrouver dans le document les boutons associés à une image (éléments `<input>` avec l’attribut `type=\"image\"`) utilisés comme CAPTCHA ou comme image-test.\n2. Pour chaque bouton associé à une image, vérifier qu’il existe :\n   - soit une autre forme de CAPTCHA non graphique, au moins ;\n   - soit une autre solution d’accès à la fonctionnalité qui est sécurisée par le CAPTCHA.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.5' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"1.6.1":"1. Retrouver dans le document les images structurées au moyen d’un élément `<img>` (ou d’un élément possédant l’attribut WAI-ARIA `role=\"img\"`) porteuses d’information qui nécessitent une description détaillée.\n2. Pour chaque image, vérifier qu’il existe :\n   - Soit une alternative textuelle contenant la référence à une description détaillée adjacente à l’image ;\n   - Soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée.\n3. Si c’est le cas pour chaque image, **le test est validé**.","1.6.2":"1. Retrouver dans le document les éléments `<object>` pourvus de l’attribut `type=\"image/…\"`, porteurs d’information qui nécessitent une description détaillée.\n2. Pour chaque élément `<object>` pourvu de l’attribut `type=\"image/…\"`, vérifier qu’il existe :\n   - soit une alternative textuelle contenant la référence à une description détaillée adjacente à l’image ;\n   - soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée.\n3. Si c’est le cas pour chaque élément `<object>` pourvu de l’attribut `type=\"image/…\"`, **le test est validé**.\n","1.6.3":"1. Retrouver dans le document les éléments `<embed>` pourvus de l’attribut `type=\"image/…\"`, porteurs d’information qui nécessitent une description détaillée.\n2. Pour chaque élément `<embed>` pourvu de l’attribut `type=\"image/…\"`, vérifier qu’il existe :\n   - soit une alternative textuelle contenant la référence à une description détaillée adjacente à l’image ;\n   - soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée.\n3. Si c’est le cas pour chaque élément `<embed>` pourvu de l’attribut `type=\"image/…\"`, **le test est validé**.\n","1.6.4":"1. Retrouver dans le document les éléments `<input>` pourvus de l’attribut `type=\"image\"`, porteurs d’information qui nécessitent une description détaillée.\n2. Pour chaque élément `<input>` pourvu de l’attribut `type=\"image\"`, vérifier qu’il existe :\n   - soit une alternative textuelle contenant la référence à une description détaillée adjacente à l’image ;\n   - soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée ;\n   - soit un attribut WAI-ARIA aria-describedby associant un passage de texte faisant office de description détaillée.\n3. Si c’est le cas pour chaque élément `<input>` pourvu de l’attribut `type=\"image\"`, **le test est validé**.\n","1.6.5":"1. Retrouver dans le document les éléments `<svg>` porteurs d’information qui nécessitent une description détaillée.\n2. Pour chaque élément `<svg>`, vérifier qu’il existe :\n   - soit un attribut WAI-ARIA `aria-label` contenant l’alternative textuelle et une référence à une description détaillée adjacente ;\n   - soit un attribut WAI-ARIA `aria-labelledby` associant un passage de texte faisant office d’alternative textuelle et un autre faisant office de description détaillée ;\n   - soit un attribut WAI-ARIA `aria-describedby` associant un passage de texte faisant office de description détaillée ;\n   - soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée.\n3. Si c’est le cas pour chaque élément `<svg>`, **le test est validé**.\n","1.6.6":"1. Retrouver dans le document les éléments `<svg>` porteurs d’information dont la description détaillée est fournie au moyen d’un attribut `aria-label`, `aria-labelledby` ou `aria-describedby`.\n2. Pour chaque élément `<svg>`, vérifier que le contenu de la description détaillée est correctement restitué par les technologies d’assistance.\n3. Si c’est le cas pour chaque élément `<svg>`, **le test est validé**.\n","1.6.7":"1. Retrouver dans le document les éléments `<canvas>` porteurs d’information qui nécessitent une description détaillée.\n2. Pour chaque élément `<canvas>`, vérifier qu’il existe :\n   - soit un attribut WAI-ARIA aria-label contenant l’alternative textuelle et une référence à une description détaillée adjacente ;\n   - soit un attribut WAI-ARIA aria-labelledby associant un passage de texte faisant office d’alternative textuelle et un autre faisant office de description détaillée ;\n   - soit un contenu textuel entre `<canvas>` et `</canvas>` faisant référence à une description détaillée adjacente à l’image bitmap ;\n   - soit un contenu textuel entre `<canvas>` et `</canvas>` faisant office de description détaillée ;\n   - soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée.\n3. Si c’est le cas pour chaque élément `<canvas>`, **le test est validé**.\n","1.6.8":"1. Retrouver dans le document les éléments `<canvas>` porteurs d’information dont la description détaillée est fournie au moyen d’un attribut `aria-label`, `aria-labelledby` ou `aria-describedby`.\n2. Pour chaque élément `<canvas>`, vérifier que le contenu de la description détaillée est correctement restitué par les technologies d’assistance.\n3. Si c’est le cas pour chaque élément `<canvas>`, **le test est validé**.\n","1.6.9":"1. Retrouver dans le document les images (éléments `<img>`, `<input>` avec l’attribut `type=\"image\"`, `<area>`, `<object>`, `<embed>`, `<svg>`, `<canvas>` ou possédant un attribut WAI-ARIA `role=\"img\"`) porteuses d’information dont la description détaillée utilise un attribut WAI-ARIA `aria-describedby`.\n2. Pour chaque image, vérifier que le contenu de la description détaillée est correctement restitué par les technologies d’assistance.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.6.10":"1. Retrouver dans le document les éléments pourvus d’un attribut WAI-ARIA `role=\"img\"` porteurs d’information qui nécessitent une description détaillée.\n2. Pour chaque élément `role=\"img\"`, vérifier qu’il existe :\n   - soit un attribut WAI-ARIA `aria-label` contenant l’alternative textuelle et une référence à une description détaillée adjacente ;\n   - soit un attribut WAI-ARIA `aria-labelledby` associant un passage de texte faisant office d’alternative textuelle et un autre faisant office de description détaillée ;\n   - soit un attribut WAI-ARIA `aria-describedby` associant un passage de texte faisant office de description détaillée ;\n   - soit un lien ou un bouton adjacent permettant d’accéder à la description détaillée.\n3. Si c’est le cas pour chaque élément `role=\"img\"`, **le test est validé**.\n"}'::jsonb
where identifier = '1.6' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"1.7.1":"1. Retrouver dans le document les images structurées au moyen d’un élément `<img>` qui possèdent une description détaillée.\n2. Pour chaque image, vérifier que la description détaillée est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.7.2":"1. Retrouver dans le document les éléments `<input>` pourvus de l’attribut `type=\"image\"` qui possèdent une description détaillée.\n2. Pour chaque élément `<input>` pourvu de l’attribut `type=\"image\"`, vérifier que la description détaillée est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.7.3":"1. Retrouver dans le document les éléments `<object>` pourvus de l’attribut `type=\"image/…\"` qui possèdent une description détaillée.\n2. Pour chaque élément `<object>` pourvu de l’attribut `type=\"image/…\"`, vérifier que la description détaillée est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.7.4":"1. Retrouver dans le document les éléments `<embed>` pourvus de l’attribut `type=\"image/…\"` qui possèdent une description détaillée.\n2. Pour chaque élément `<embed>` pourvu de l’attribut `type=\"image/…\"`, vérifier que la description détaillée est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.7.5":"1. Retrouver dans le document les éléments `<svg>` qui possèdent une description détaillée.\n2. Pour chaque élément `<svg>`, vérifier que la description détaillée est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.7.6":"1. Retrouver dans le document les éléments `<canvas>` qui possèdent une description détaillée.\n2. Pour chaque élément `<canvas>`, vérifier que la description détaillée est pertinente.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.7' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"1.8.1":"1. Retrouver dans le document les images texte structurées au moyen d’un élément `<img>` (ou d’un élément possédant l’attribut WAI-ARIA `role=\"img\"`).\n2. Pour chaque image, vérifier que :\n   - soit il existe un mécanisme de remplacement ;\n   - soit l’image contient un texte qui fait appel à un effet graphique qui ne peut pas être reproduit en CSS.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.8.2":"1. Retrouver dans le document les boutons “images texte” (élément `<input>` avec l’attribut `type=\"image\"`).\n2. Pour chaque image, vérifier que :\n   - soit il existe un mécanisme de remplacement ;\n   - soit l’image contient un texte qui fait appel à un effet graphique qui ne peut pas être reproduit en CSS.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.8.3":"1. Retrouver dans le document les images texte objet (élément `<object>` avec l’attribut `type=\"image/…\"`).\n2. Pour chaque image, vérifier que :\n   - soit il existe un mécanisme de remplacement ;\n   - soit l’image contient un texte qui fait appel à un effet graphique qui ne peut pas être reproduit en CSS.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.8.4":"1. Retrouver dans le document les images texte embarquées (élément `<embed>` avec l’attribut `type=\"image/…\"`).\n2. Pour chaque image, vérifier que :\n   - Soit il existe un mécanisme de remplacement ;\n   - Soit l’image contient un texte qui fait appel à un effet graphique qui ne peut pas être reproduit en CSS.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.8.5":"1. Retrouver dans le document les images texte bitmap (élément `<canvas>`).\n2. Pour chaque image, vérifier que :\n   - soit il existe un mécanisme de remplacement ;\n   - soit l’image contient un texte qui fait appel à un effet graphique qui ne peut pas être reproduit en CSS.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.8.6":"1. Retrouver dans le document les images texte vectorielle (élément `<svg>`) porteuse d’information et dont le texte n’est pas complètement structuré au moyen d’éléments `<text>`.\n2. Pour chaque image, vérifier que :\n   - soit il existe un mécanisme de remplacement ;\n   - soit l’image contient un texte qui fait appel à un effet graphique qui ne peut pas être reproduit en CSS.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.8' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"1.9.1":"1. Retrouver dans le document les images pourvues d’une légende structurées au moyen d’élément `<img>`, d’un élément `<input>` avec l’attribut `type=\"image\"` ou d’un élément possédant l’attribut WAI-ARIA `role=\"img\"`.\n2. Pour chaque image, vérifier que :\n   - l’image et sa légende sont contenues dans une balise `<figure>` ;\n   - la légende est contenue dans une balise `<figcaption>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.9.2":"1. Retrouver dans le document les images objet pourvues d’une légende (élément `<object>` avec l’attribut `type=\"image/…\"`).\n2. Pour chaque image, vérifier que :\n   - l’image et sa légende sont contenues dans une balise `<figure>` ;\n   - la légende est contenue dans une balise `<figcaption>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.9.3":"1. Retrouver dans le document les images embarquées pourvues d’une légende (élément `<embed>` avec l’attribut `type=\"image/…\"`).\n2. Pour chaque image, vérifier que :\n   - l’image et sa légende sont contenues dans une balise `<figure>` ;\n   - la légende est contenue dans une balise `<figcaption>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.9.4":"1. Retrouver dans le document les images vectorielles pourvues d’une légende (élément `<svg>`).\n2. Pour chaque image, vérifier que :\n   - l’image et sa légende sont contenues dans une balise `<figure>` ;\n   - la légende est contenue dans une balise `<figcaption>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n","1.9.5":"1. Retrouver dans le document les images bitmap (élément `<canvas>`).\n2. Pour chaque image, vérifier que :\n   - l’image et sa légende sont contenues dans une balise `<figure>` ;\n   - la légende est contenue dans une balise `<figcaption>`.\n3. Si c’est le cas pour chaque image, **le test est validé**.\n"}'::jsonb
where identifier = '1.9' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.1.1":"1. Vérifier l’absence des éléments de présentation `<basefont>`, `<big>`, `<blink>`, `<center>`, `<font>`, `<marquee>`, `<s>`, `<strike>`, `<tt>`.\n2. Vérifier l’absence de l’élément `<u>` uniquement si le DOCTYPE du document ne correspond pas à HTML 5.\n3. Si c’est le cas, **le test est validé**.\n","10.1.2":"1. Vérifier l’absence des attributs de présentation : `align`, `alink`, `background`, `bgcolor`, `border`, `cellpadding`, `cellspacing`, `char`, `charoff`, `clear`, `color`, `compact`, `frameborder`, `hspace`, `link`, `marginheight`, `marginwidth`, `text`, `valign`, `vlink`, `vspace`, `size` (exception faite de l’élément `<select>`).\n2. Vérifier que les attributs `width` ou `height`, s’ils sont utilisés, sont uniquement présents sur les éléments  `<canvas>`, `<embed>`, `<iframe>`, `<img>`, `<object>`, `<source>`, `<svg>` (ou l’un de ses enfants).\n3. Si c’est le cas, **le test est validé**.\n\n","10.1.3":"1. Désactiver les styles (CSS) du document.\n2. Vérifier l’absence d’espaces utilisées :\n   - Entre les lettres d’un mot.\n   - Pour créer des effets de marges ou d’alignement.\n   - Pour simuler des tableaux ou des colonnes.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '10.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.10.1":"1. Retrouver dans le document les informations d’un texte données par la forme, la taille ou la position.\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier que le moyen alternatif de récupérer cette information est pertinent, c’est-à-dire qu’il permet de transmettre l’information dans tous les contextes de consultation et pour tous les utilisateurs.\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","10.10.2":"1. Retrouver dans le document les informations d’une image données par la forme, la taille ou la position.\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier que le moyen alternatif de récupérer cette information est pertinent, c’est-à-dire qu’il permet de transmettre l’information dans tous les contextes de consultation et pour tous les utilisateurs.\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","10.10.3":"1. Retrouver dans le document les informations d’un média temporel données par la forme, la taille ou la position.\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier que le moyen alternatif de récupérer cette information est pertinent, c’est-à-dire qu’il permet de transmettre l’information dans tous les contextes de consultation et pour tous les utilisateurs.\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","10.10.4":"1. Retrouver dans le document les informations d’un média non temporel données par la forme, la taille ou la position.\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier que le moyen alternatif de récupérer cette information est pertinent, c’est-à-dire qu’il permet de transmettre l’information dans tous les contextes de consultation et pour tous les utilisateurs.\n3. Si c’est le cas pour chaque information, **le test est validé**.\n"}'::jsonb
where identifier = '10.10' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.11.1":"1. Retrouver dans le document si son contenu est conçu pour défiler verticalement (le sens de lecture du texte est horizontal), les informations et fonctionnalités.\n2. Réduire la fenêtre d’affichage à une largeur de 320 px et vérifier que les informations et les fonctionnalités restent disponibles sans aucun défilement horizontal.\n3. Si c’est le cas, **le test est validé**.\n","10.11.2":"1. Retrouver dans le document si son contenu est conçu pour défiler horizontalement (le sens de lecture du texte est vertical), les informations et fonctionnalités.\n2. Réduire la fenêtre d’affichage à une hauteur de 256 px et vérifier que les informations et les fonctionnalités restent disponibles sans aucun défilement vertical.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '10.11' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.12.1":"1. Modifier les styles du document en donnant :\n   - une valeur de 1.5 à la propriété `line-height` de tous les éléments du document ;\n   - une valeur de 2em à la propriété `margin-bottom` des éléments `<p>` ;\n   - une valeur de 0.12em à la propriété `letter-spacing` de tous les éléments du document ;\n   - une valeur de 0.16em à la propriété `word-spacing` de tous les éléments du document.\n2. Pour chaque passage de texte, vérifier qu’il reste lisible, à l’exception :\n   - des sous-titres directement intégrés à une vidéo ;\n   - des images texte ;\n   - des textes au sein d’une balise `<canvas>`.\n3. Si c’est le cas pour chaque passage de texte, **le test est validé**.\n\nNote : une implémentation de ces règles de modification est disponible dans les ressources du critère de succès WCAG 1.4.12 (https://github.com/alastc/adaptation-scripts/blob/master/scripts/text-adaptation.js).\n"}'::jsonb
where identifier = '10.12' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.13.1":"1. Retrouver dans le document les contenus additionnels devenant visibles à la prise de focus ou au survol d’un composant d’interface, à l’exception :\n   - Des contenus additionnels contrôlés par l’agent utilisateur (par exemple, les infobulles associées à l’attribut `title` ou à la validation native d’un formulaire.\n   - Des contenus additionnels devenant visibles par une activation de l’utilisateur (par exemple, une fenêtre de dialogue).\n2. Pour chaque contenu additionnel, vérifier que :\n   - Soit le contenu additionnel est positionné de façon à ce qu’il ne gêne pas la consultation des autres contenus informatifs sur lesquels il viendrait se superposer (y compris le composant d’interface qui a déclenché son apparition), quelles que soient les conditions de consultation (y compris lors de l’utilisation d’un mécanisme de zoom).\n   - Soit un mécanisme (au clavier) permet de faire disparaître le contenu additionnel (par exemple, la touche Echap).\n3. Si c’est le cas pour chaque contenu additionnel, **le test est validé**.\n","10.13.2":"1. Retrouver dans le document les contenus additionnels devenant visibles au survol d’un composant d’interface, à l’exception :\n   - des contenus additionnels contrôlés par l’agent utilisateur (par exemple, les infobulles associées à l’attribut `title` ou à la validation native d’un formulaire) ;\n   - des contenus additionnels devenant visibles par une activation de l’utilisateur (par exemple, une fenêtre de dialogue).\n2. Pour chaque contenu additionnel, vérifier qu’il peut être survolé par le pointeur de la souris sans disparaître.\n3. Si c’est le cas pour chaque contenu additionnel, **le test est validé**.\n","10.13.3":"1. Retrouver dans le document les contenus additionnels devenant visibles à la prise de focus ou au survol d’un composant d’interface, à l’exception :\n   - des contenus additionnels contrôlés par l’agent utilisateur (par exemple, les infobulles associées à l’attribut `title` ou à la validation native d’un formulaire) ;\n   - des contenus additionnels devenant visibles par une activation de l’utilisateur (par exemple, une fenêtre de dialogue).\n2. Pour chaque contenu additionnel, vérifier qu’il reste visible :\n   - jusqu’à ce que l’utilisateur retire le pointeur souris ou le focus du contenu additionnel ou du composant d’interface ayant déclenché son apparition ;\n   - jusqu’à ce l’utilisateur déclenche le mécanisme prévu pour faire disparaître le contenu additionnel ;\n   - jusqu’à ce que l’information proposée par le contenu additionnel ne soit plus valide (par exemple un contenu additionnel signalant l’état “occupé” du composant d’interface que l’utilisateur souhaite activer ou encore un message d’erreur signalé sous la forme d’un contenu additionnel tant que l’utilisateur n’a pas rectifié sa saisie).\n3. Si c’est le cas pour chaque contenu additionnel, **le test est validé**.\n"}'::jsonb
where identifier = '10.13' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.14.1":"1. Retrouver dans le document les contenus additionnels devenant visibles au survol d’un composant d’interface au moyen d’un mécanisme CSS (`pseudo-classe :hover`).\n2. Pour chaque contenu additionnel, vérifier que les contenus additionnels apparaissent également :\n   - À l’activation du composant au moyen du clavier ou de tout autre dispositif de pointage.\n   - À la prise de focus du composant.\n   - À l’activation ou à la prise de focus d’un autre composant.\n3. Si c’est le cas pour chaque contenu additionnel, **le test est validé**.\n","10.14.2":"1. Retrouver dans le document les contenus additionnels devenant visibles à la prise de focus d’un composant d’interface au moyen d’un mécanisme CSS (`pseudo-classe :focus`).\n2. Pour chaque contenu additionnel, vérifier que les contenus additionnels apparaissent également :\n   - À l’activation du composant au moyen du clavier ou de tout autre dispositif de pointage.\n   - Au survol du composant.\n   - À l’activation ou du survol d’un autre composant.\n3. Si c’est le cas pour chaque contenu additionnel, **le test est validé**.\n"}'::jsonb
where identifier = '10.14' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.2.1":"1. Identifier les éléments porteurs d’informations qui pourraient ne pas être atteignables par les technologies d’assistance, par exemple, des images de fond insérées par CSS.\n2. Vérifier qu’il existe dans la page, une alternative accessible aux technologies d’assistance (par exemple, un texte visuellement caché qui apporte la même information).\n4. Si c’est le cas, **le test est validé**."}'::jsonb
where identifier = '10.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.3.1":"1. Désactiver les styles (CSS) du document.\n2. Vérifier que l’ordre dans lequel les contenus sont implémentés ne pose pas de problème de compréhension.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '10.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.4.1":"1. Vérifier dans le document si les textes restent présents et lisibles :\n   - Soit lorsque le zoom texte du navigateur est réglé à 200 %.\n   - Soit lorsque le zoom graphique du navigateur est réglé à 200 %.\n   - Soit lorsque les fonctionnalités de zoom personnalisé proposées par le document sont utilisées.\n2. Si c’est le cas, **le test est validé**.\n","10.4.2":"1. Vérifier dans le document si les textes sont effectivement agrandis :\n   - Soit lorsque le zoom texte du navigateur est réglé à 200 %.\n   - Soit lorsque le zoom graphique du navigateur est réglé à 200 %.\n   - Soit lorsque les fonctionnalités de zoom personnalisé proposées par le document sont utilisées.\n2. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '10.4' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.5.1":"1. Retrouver dans le document les textes mis en couleur, à l’exception des couleurs par défaut (par exemple les liens, etc.).\n2. Déterminer l’élément qui contient le texte et vérifier la présence d’une valeur calculée pour la propriété `background-color` de l’élément.\n3. Si c’est le cas, **le test est validé**.\n","10.5.2":"1. Retrouver dans le document les textes mis en couleur, à l’exception des couleurs par défaut (par exemple les liens, etc.).\n2. Déterminer l’élément qui contient le texte et vérifier la présence d’une valeur calculée pour la propriété `color` de l’élément.\n3. Si c’est le cas, **le test est validé**.\n","10.5.3":"1. Retrouver dans le document les textes dont l’arrière-plan est constitué d’une image (propriété `background-image`).\n2. Déterminer l’élément qui contient le texte et vérifier que si l’image d’arrière-plan est absente, le texte reste lisible.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '10.5' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.6.1":"1. Retrouver dans le document les éléments de type lien (élément `<a>` ou élément pourvu d’un attribut WAI-ARIA `role=\"link\"`).\n2. Pour chaque élément de type lien, s’il peut être confondu avec un texte normal lorsqu’il est signalé uniquement par la couleur, vérifier que le contraste entre la couleur de police du lien et la couleur de police du texte environnant est de 3:1, au moins.\n3. Cette vérification doit être faite pour les différents états du lien s’ils sont présentés au moyen d’une couleur différente : l’état non visité, l’état visité, l’état activé, l’état au survol et l’état à la prise de focus.\n4. Si c’est le cas pour chaque élément de type lien, **le test est validé**.\n"}'::jsonb
where identifier = '10.6' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.7.1":"1. Retrouver dans le document les éléments susceptibles de recevoir le focus du clavier (les éléments d’interface tels que les liens ou les contrôles de formulaire, ainsi que tout élément pourvu d’un attribut `tabindex` d’une valeur égale ou supérieure à 1).\n2. Pour chaque élément susceptible de recevoir le focus du clavier, vérifier que l’indication visuelle de la prise de focus est présente (en agissant sur le contour ou le fond ou les deux) et est suffisamment contrastée (ratio de contraste égal ou supérieur à 3:1).\n3. Si c’est le cas pour chaque élément susceptible de recevoir le focus, **le test est validé**.\n"}'::jsonb
where identifier = '10.7' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.8.1":"1. Retrouver les contenus cachés (éléments pourvus de l’attribut `hidden` ou de l’attribut WAI-ARIA `aria-hidden`, ou bien d’une classe ou d’un ensemble de styles CSS susceptibles de masquer le contenu).\n2. Pour chaque contenu caché, vérifier que :\n   - Soit le contenu caché a vocation à être ignoré par les technologies d’assistance (un élément statistique de visites par exemple).\n   - Soit le contenu caché n’a pas vocation à être ignoré par les technologies d’assistance, et dans ce cas il est rendu restituable par les technologies d’assistance au moyen :\n     - Soit d’une action de l’utilisateur réalisable au clavier ou par tout dispositif de pointage sur un élément précédent le contenu caché.\n     - Soit d’une fonction de programmation qui repositionne le focus sur le contenu.\n3. Si c’est le cas pour chaque contenu caché, **le test est validé**.\n"}'::jsonb
where identifier = '10.8' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"10.9.1":"1. Retrouver dans le document les informations d’un texte données par la forme, la taille ou la position.\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier qu’il existe un autre moyen de récupérer cette information.\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","10.9.2":"1. Retrouver dans le document les informations d’une image données par la forme, la taille ou la position.\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier qu’il existe un autre moyen de récupérer cette information.\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","10.9.3":"1. Retrouver dans le document les informations d’un média temporel données par la forme, la taille ou la position.\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier qu’il existe un autre moyen de récupérer cette information.\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","10.9.4":"1. Retrouver dans le document les informations d’un média non temporel données par la forme, la taille ou la position.\n2. Pour chaque information donnée par la forme, la taille ou la position, vérifier qu’il existe un autre moyen de récupérer cette information.\n3. Si c’est le cas pour chaque information, **le test est validé**.\n"}'::jsonb
where identifier = '10.9' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"11.1.1":"1. Retrouver dans le document les champs de formulaire.\n2. Pour chaque champ de formulaire, vérifier que le champ de formulaire :\n   - possède un attribut WAI-ARIA `aria-labelledby` référençant un passage de texte identifié ;\n   - possède un attribut WAI-ARIA `aria-label` ;\n   - est associé à un élément `<label>` ayant un attribut `for` ;\n   - possède un attribut `title` ;\n   - un bouton adjacent au champ de formulaire lui fournit une étiquette visible et un élément `<label>` visuellement caché ou un attribut WAI-ARIA `aria-label`, `aria-labelledby` ou `title` lui fournit un nom accessible.\n3. Si c’est le cas pour champ de formulaire, **le test est validé**.\n","11.1.2":"1. Retrouver dans le document les champs de formulaire associé à un élément `<label>`.\n2. Pour chaque champ de formulaire, vérifier que :\n   - Le champ de formulaire possède un attribut `id`.\n   - La valeur de l’attribut `for` de l’élément `<label>` est égale à la valeur de l’attribut `id`.\n3. Si c’est le cas pour champ de formulaire, **le test est validé**.\n","11.1.3":"1. Retrouver dans le document les champs de formulaire dont l’étiquette n’est pas visible ou à proximité (masquée, utilisation de l’attribut aria-label) ou n’est pas accolée au champ (utilisation de l’attribut `aria-labelledby`).\n2. Pour chaque champ de formulaire, vérifier que le champ de formulaire :\n   - soit possède un attribut `title` dont le contenu permet de comprendre la nature de la saisie attendue ;\n   - est accompagné d’un passage de texte accolé au champ qui devient visible à la prise de focus permettant de comprendre la nature de la saisie attendue ;\n   - est accompagné d’un passage de texte visible accolé au champ permettant de comprendre la nature de la saisie attendue.\n"}'::jsonb
where identifier = '11.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"11.10.1":"1. Retrouver dans le document les champs de formulaire obligatoires.\n2. Pour chaque champ de formulaire, vérifier qu’avant sa saisie :\n   - soit une indication de champ obligatoire est visible et permet d’identifier nommément le champ concerné ;\n   - soit une indication de champ obligatoire  est donnée par la présence de l’attribut `aria-required=\"true\"` ou `required` sur le champ avant sa saisie ;\n   - soit une indication de champ facultatif est visible et permet d’identifier nommément le champ concerné.\n3. Si c’est le cas, **le test est validé**.","11.10.2":"1. Retrouver dans le document les champs de formulaire obligatoires qui possèdent un attribut `aria-required=\"true\"` ou `required`.\n2. Pour chaque champ de formulaire, vérifier qu’avant sa saisie :\n   - soit une indication de champ obligatoire est visible et permet d’identifier nommément le champ concerné ;\n   - soit une indication de champ obligatoire est visible et située dans l’étiquette associée au champ ;\n   - soit une indication de champ obligatoire est visible et située dans le passage de texte associé au champ ;\n   - soit une indication de champ obligatoire est visible et située dans la légende associée au groupe de champs.\n3. Si c’est le cas, **le test est validé**.\n","11.10.3":"1. Retrouver dans le document les messages d’erreur indiquant l’absence de saisie d’un champ obligatoire.\n2. Pour chaque message d’erreur, vérifier que :\n   - soit le message d’erreur est visible et permet d’identifier nommément le champ concerné ;\n   - soit le champ obligatoire associé au message d’erreur possède un attribut `aria-invalid=\"true\"`.\n3. Si c’est le cas pour chaque message d’erreur indiquant l’absence de saisie d’un champ obligatoire, **le test est validé**.\n","11.10.4":"1. Retrouver dans le document les champs de formulaire qui possèdent un attribut `aria-invalid=\"true\"`.\n2. Pour chaque champ de formulaire, vérifier que :\n   - soit le message d’erreur indiquant le caractère invalide de la saisie est visible et situé dans l’étiquette associée au champ ;\n   - soit le message d’erreur indiquant le caractère invalide de la saisie est visible et situé dans le passage de texte associé au champ.\n3. Si c’est le cas pour chaque champ de formulaire qui possède un attribut `aria-invalid=\"true\"`, **le test est validé**.\n","11.10.5":"1. Remplir les champs de formulaire avec des valeurs susceptibles de provoquer des erreurs de saisies (entrer une adresse <em lang=\"en\">e-mail</em> mal formée par exemple).\n2. Valider le formulaire.\n3. Pour chaque champ de formulaire qui possède un contrôle du format, vérifier que l’instruction ou l’indication du type de données et/ou de format obligatoire  : \n    - est indiquée avant sa saisie ;\n    - est indiquée de manière visible ; \n    - permet d’identifier nommément le champ concerné ou est incluse dans l’étiquette ou le passage de texte associé au champ. \n4. Si c’est le cas pour chaque champ de formulaire auquel est associée une instruction ou une indication du type de données et/ou de format obligatoire, **le test est validé**.","11.10.6":"1. Retrouver dans le document les messages d’erreur fournissant une instruction ou une indication du type de données et/ou de format obligatoire d’un champ.\n2. Pour chaque message d’erreur, vérifier que :\n   - soit le message d’erreur est visible et permet d’identifier nommément le champ concerné ;\n   - soit le champ associé au message d’erreur possède un attribut `aria-invalid=\"true\"`.\n3. Si c’est le cas pour chaque message d’erreur indiquant l’absence de saisie d’un champ obligatoire, **le test est validé**.\n","11.10.7":"1. Retrouver dans le document les champs de formulaire qui possèdent un attribut `aria-invalid=\"true\"`.\n2. Pour chaque champ de formulaire, vérifier que :\n   - soit une instruction ou une indication du type de données et/ou de format obligatoire est visible et située dans l’élément `<label>` associé au champ ;\n   - soit une instruction ou une indication du type de données et/ou de format obligatoire est visible et située dans le passage de texte associé au champ.\n3. Si c’est le cas pour chaque champ de formulaire qui possède un attribut `aria-invalid=\"true\"`, **le test est validé**.\n"}'::jsonb
where identifier = '11.10' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"11.11.1":"1. Retrouver dans le document les messages d’erreur.\n2. Pour chaque message d’erreur, vérifier que les types et les formats de données attendus sont suggérés.\n3. Si c’est le cas pour chaque message d’erreur, **le test est validé**.\n","11.11.2":"1. Retrouver dans le document les messages d’erreur.\n2. Pour chaque message d’erreur, vérifier que des exemples de valeurs attendues sont suggérés.\n3. Si c’est le cas pour chaque message d’erreur, **le test est validé**.\n"}'::jsonb
where identifier = '11.11' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"11.12.1":"1. Retrouver dans le document les formulaires qui modifient ou suppriment des données, ou qui transmettent des réponses à un test ou un examen, ou dont la validation a des conséquences financières ou juridiques.\n2. Pour chaque formulaire, vérifier que l’utilisateur peut :\n   - soit modifier ou annuler les données et les actions effectuées sur ces données après la validation du formulaire ;\n   - soit vérifier et corriger les données avant la validation d’un formulaire en plusieurs étapes ;\n   - soit disposer d’un mécanisme de confirmation explicite (par exemple, une case à cocher ou une étape supplémentaire).\n3. Si c’est le cas pour chaque formulaire retrouvé, **le test est validé**.\n","11.12.2":"1. Retrouver dans le document les formulaires qui modifient ou suppriment des données à caractère financier, juridique ou personnel.\n2. Pour chaque formulaire, vérifier que l’utilisateur dispose :\n   - soit d’un mécanisme qui permet de récupérer les données supprimées ou modifiées ;\n   - soit d’un mécanisme de demande de confirmation explicite de la suppression ou de la modification (par exemple, une case à cocher ou une étape supplémentaire).\n3. Si c’est le cas pour chaque formulaire retrouvé, **le test est validé**.\n"}'::jsonb
where identifier = '11.12' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"11.13.1":"1. Retrouver dans le document les champs de formulaire qui se rapportent à une information concernant l’utilisateur (nom, prénom, numéro de téléphone, etc.).\n2. Pour chaque champ de formulaire, vérifier que :\n   - Le champ de formulaire possède un attribut `autocomplete`.\n   - L’attribut `autocomplete` est pourvu d’une valeur présente dans la <a rel=\"noreferrer noopener\" target=\"_blank\" title=\"liste des valeurs possibles - en anglais - nouvelle fenêtre\" href=\"https://www.w3.org/TR/html52/sec-forms.html#autofill-processing-model\">liste des valeurs possibles</a>.\n   - La valeur indiquée pour l’attribut `autocomplete` est pertinente au regard du type d’information attendu.\n3. Si c’est le cas pour chaque champ de formulaire retrouvé, **le test est validé**.\n"}'::jsonb
where identifier = '11.13' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"11.2.1":"1. Retrouver dans le document les champs de formulaire dont l’étiquette est fournie par un élément `<label>`.\n2. Pour chaque champ de formulaire, vérifier que le contenu de l’élément est pertinent.\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.2.2":"1. Retrouver dans le document les champs de formulaire dont l’étiquette est fournie par un attribut `title`.\n2. Pour chaque champ de formulaire, vérifier que le contenu de l’attribut est pertinent.\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.2.3":"1. Retrouver dans le document les champs de formulaire dont l’étiquette est fournie par un attribut WAI-ARIA `aria-label`.\n2. Pour chaque champ de formulaire, vérifier que le contenu de l’attribut est pertinent.\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.2.4":"1. Retrouver dans le document les champs de formulaire dont l’étiquette est fournie par un attribut WAI-ARIA `aria-labelledby`.\n2. Pour chaque champ de formulaire, vérifier que le contenu du passage de texte référencé est pertinent.\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.2.5":"1. Retrouver dans le document les champs de formulaire dont l’étiquette est fournie à la fois par un intitulé visible et par le contenu soit d’un élément `<label>`, soit d’un attribut `title` ou d’un attribut `aria-label` ou d’un attribut `aria-labelledby`.\n2. Pour chaque champ de formulaire, vérifier que le contenu de l’élément `<label>` ou de l’attribut `title` ou de l’attribut `aria-label` ou de l’attribut `aria-labelledby` contient l’intitulé visible.\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.2.6":"1. Retrouver dans le document les champs de formulaire dont l’étiquette visible est fournie par un bouton adjacent.\n2. Pour chaque champ de formulaire, vérifier que le contenu visible du bouton est pertinent.\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n"}'::jsonb
where identifier = '11.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"11.3.1":"1. Retrouver dans le document les champs de formulaire ayant une même fonction (par exemple plusieurs champs d’adresse).\n2. Pour chaque champ de formulaire, vérifier que les étiquettes sont cohérentes (elles permettent de comprendre qu’il s’agit de saisies de natures identiques).\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.3.2":"1. Retrouver dans l’ensemble des pages considérées les champs de formulaire ayant une même fonction (par exemple le champ de saisie d’un moteur de recherche ou le champ de saisie d’inscription à une newsletter).\n2. Pour chaque champ de formulaire, vérifier que les étiquettes sont cohérentes (elles permettent de comprendre qu’il s’agit de saisies de natures identiques).\n3. Si c’est le cas pour chaque champ de formulaire de l’ensemble des pages considérées, **le test est validé**.\n"}'::jsonb
where identifier = '11.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"11.4.1":"1. Retrouver dans le document les champs de formulaire.\n2. Pour chaque champ de formulaire, vérifier qu’il est accolé à son étiquette.\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.4.2":"1. Retrouver dans le document les champs de formulaire qui ne sont pas des éléments `<input>` de type `checkbox` ou de type `radio` ou des éléments ayant un attribut WAI-ARIA `role=\"checkbox\"`, `role=\"radio\"` ou `role=\"switch\"`.\n2. Pour chaque champ de formulaire, vérifier que l’étiquette est visuellement accolée :\n   - Immédiatement au-dessus ou à gauche du champ de formulaire lorsque le sens de lecture de la langue de l’étiquette est de gauche à droite.\n   - Immédiatement au-dessus ou à droite du champ de formulaire lorsque le sens de lecture de la langue de l’étiquette est de droite à gauche.\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n","11.4.3":"1. Retrouver dans le document les champs de formulaire qui sont `<input>` de type `checkbox` ou de type `radio` ou des éléments ayant un attribut WAI-ARIA `role=\"checkbox\"`, `role=\"radio\"` ou `role=\"switch\"`.\n2. Pour chaque champ de formulaire, vérifier que l’étiquette est visuellement accolée :\n   - Immédiatement au-dessous ou à droite du champ de formulaire lorsque le sens de lecture de la langue de l’étiquette est de gauche à droite.\n   - Immédiatement au-dessous ou à gauche du champ de formulaire lorsque le sens de lecture de la langue de l’étiquette est de droite à gauche.\n3. Si c’est le cas pour chaque champ de formulaire, **le test est validé**.\n"}'::jsonb
where identifier = '11.4' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"11.5.1":"1. Retrouver dans le document les champs de formulaire de même nature (par exemple un groupe de saisie d’informations d’identité, une série de cases à cocher, une saisie de date sur plusieurs champs successifs…).\n2. Pour chaque groupe de champs de formulaire de même nature, vérifier que ces champs de même nature sont regroupés :\n   - soit dans un élément `<fieldset>` ;\n   - soit dans un élément possédant un attribut WAI-ARIA `role=\"group\"` ;\n   - soit dans un élément possédant un attribut WAI-ARIA `role=\"radiogroup\"` ou `\"group\"`, s’il s’agit d’éléments `<input>` de type `radio` ( ou d’éléments possédant un attribut WAI-ARIA `role=\"radio\"`).\n3. Si c’est le cas pour chaque groupe de champs de formulaire de même nature, **le test est validé**.\n"}'::jsonb
where identifier = '11.5' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"11.6.1":"1. Retrouver dans le document les groupes de champs de formulaire de même nature.\n2. Pour chaque groupe de champs de formulaire de même nature, vérifier que :\n   - Si le regroupement utilise un élément `<fieldset>`, l’élément `<fieldset>` possède un élément `<legend>`.\n   - Si l’élément de regroupement utilise un attribut WAI-ARIA `role=\"group\"` ou `\"radiogroup\"`, il possède un attribut WAI-ARIA `aria-label` ou `aria-labelledby`.\n3. Sinon, pour chacun des champs de même nature, vérifier la présence :\n   - soit d’un attribut title permettant de déterminer l’appartenance du champ au groupement de champ ;\n   - soit d’un attribut `aria-label` permettant de déterminer l’appartenance du champ au groupement de champ ;\n   - soit d’un attribut `aria-labelledby` qui référence un passage de texte permettant de déterminer l’appartenance du champ au groupement de champ ;\n   - soit d’un attribut `aria-describedby` qui référence un passage de texte permettant de déterminer l’appartenance du champ au groupement de champ ;\n4. Si c’est le cas pour chaque groupe de champs de formulaire ou pour chacun des champs de même nature, **le test est validé**.\n"}'::jsonb
where identifier = '11.6' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"11.7.1":"1. Retrouver dans le document les groupes de champs de formulaire de même nature.\n2. Pour chaque groupe de champs de formulaire de même nature ou pour chacun des champs de même nature qui dispose d’une légende, vérifier que le texte de cette légende est pertinent.\n3. Si c’est le cas pour chaque groupe de champs de formulaire ou pour chacun des champs de même nature, **le test est validé**.\n"}'::jsonb
where identifier = '11.7' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"11.8.1":"1. Retrouver dans le document les listes de sélection (élément `<select>`).\n2. Pour chaque liste de sélection proposant des groupes d’items de même nature, vérifier que ces items sont regroupés au moyen d’éléments `<optgroup>`.\n3. Si c’est le cas pour chaque liste de sélection proposant des groupes d’items de même nature, **le test est validé**.\n","11.8.2":"1. Retrouver dans le document les listes de sélection (élément `<select>`) qui possèdent des éléments `<optgroup>`.\n2. Pour chaque élément `<optgroup>`, vérifier qu’il possède un attribut `label`.\n3. Si c’est le cas pour chaque élément `<optgroup>`, **le test est validé**.\n","11.8.3":"1. Retrouver dans le document les listes de sélection (élément `<select>`) qui possèdent des éléments `<optgroup>` pourvus d’un attribut `label`.\n2. Pour chaque attribut `label`, vérifier que son contenu est pertinent.\n3. Si c’est le cas pour chaque attribut `label`, **le test est validé**.\n"}'::jsonb
where identifier = '11.8' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"11.9.1":"1. Retrouver dans le document les boutons présents au sein d’un formulaire.\n2. Pour chaque bouton, vérifier que son intitulé visible et son nom accessible sont pertinents.\n3. Si c’est le cas pour chaque bouton, **le test est validé**.\n","11.9.2":"1. Retrouver dans le document les boutons présents au sein d’un formulaire.\n2. Pour chaque bouton, vérifier que son nom accessible contient au moins son intitulé visible.\n3. Si c’est le cas pour chaque bouton, **le test est validé**.\n"}'::jsonb
where identifier = '11.9' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"12.1.1":"1. Pour chaque ensemble de pages du site, vérifier la présence :\n   - Soit d’un menu de navigation et d’un plan du site.\n   - Soit d’un menu de navigation et d’un moteur de recherche.\n   - Soit d’un moteur de recherche et d’un plan du site.\n2. Si c’est le cas pour chaque ensemble de pages du site, **le test est validé**.\n"}'::jsonb
where identifier = '12.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"12.10.1":"1. Retrouver dans le document l’ensemble des raccourcis clavier proposés à l’utilisateur\n2. Pour chaque raccourci clavier, vérifier que :\n   - soit un mécanisme est disponible pour désactiver le raccourci clavier ;\n   - soit un mécanisme est disponible pour configurer la touche de raccourci clavier au moyen des touches de modification (Ctrl, Alt, Maj, etc.) ;\n   - soit, dans le cas d’un composant d’interface utilisateur, le raccourci clavier qui lui est associé ne peut être activé que si le focus clavier est sur ce composant.\n3. Si c’est le cas pour chaque raccourci clavier, **le test est validé**.\n"}'::jsonb
where identifier = '12.10' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"12.11.1":"1. Retrouver dans le document l’ensemble des contenus additionnels apparaissant au survol, à la prise de focus ou à l’activation d’un composant d’interface\n2. Pour chaque contenu additionnel, s’il contient des composants d’interface avec lesquels l’utilisateur peut interagir au clavier (par exemple, une infobulle personnalisée qui propose un lien dans son contenu), vérifier que ces composants d’interface sont atteignables au clavier\n3. Si c’est le cas pour chaque contenu additionnel, **le test est validé**.\n"}'::jsonb
where identifier = '12.11' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"12.2.1":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit.\n2. Comparer visuellement les deux pages et vérifier que le menu ou les barres de navigation sont toujours à la même place dans la présentation.\n3. Comparer le code source (généré côté client) des deux pages et vérifier que le menu ou les barres de navigation se présentent toujours dans le même ordre relatif dans la structure.\n4. Si c’est le cas, **le test est validé**."}'::jsonb
where identifier = '12.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"12.3.1":"1. Vérifier que le plan du site est représentatif de l’architecture générale du site (cf. note).\n2. Si c’est le cas, **le test est validé**.\n\nNote : Un plan du site trop complexe ou trop profond n’est pas recommandé pour aider à la navigation. Il n’est pas obligatoire que toutes les pages soient présentes dans le plan du site si elles peuvent être atteintes, par exemple, à partir de la page d’accueil d’une rubrique ou d’un catalogue.\n","12.3.2":"1. Pour tous les liens du plan du site, vérifier qu’ils sont fonctionnels.\n2. Si c’est le cas, **le test est validé**.\n","12.3.3":"1. Pour tous les liens du plan du site, vérifier qu’ils sont à jour (ni obsolètes ni en erreur) et conduisent à la page indiquée par leur intitulé.\n2. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '12.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"12.4.1":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit.\n2. Comparer le code source (généré côté client) des deux pages et vérifier que le moyen d’accès au plan du site est toujours le même (un lien ou un bouton, par exemple).\n3. Si c’est le cas, **le test est validé**.\n","12.4.2":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit.\n2. Comparer visuellement les deux pages et vérifier que le moyen d’accès au plan du site est toujours à la même place dans la présentation.\n3. Si c’est le cas, **le test est validé**.\n","12.4.3":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit.\n2. Comparer le code source (généré côté client) des deux pages et vérifier que le moyen d’accès au plan du site est toujours à la même place dans la structure (par rapport à l’ordre relatif des éléments de la page, par exemple il est toujours en haut de page).\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '12.4' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"12.5.1":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit.\n2. Comparer le code source (généré côté client) des deux pages et vérifier que le moyen d’accès au moteur de recherche est toujours le même (un champ de formulaire, par exemple).\n3. Si c’est le cas, **le test est validé**.\n","12.5.2":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit.\n2. Comparer visuellement les deux pages et vérifier que le moyen d’accès au moteur de recherche est toujours à la même place dans la présentation.\n3. Si c’est le cas, **le test est validé**.\n","12.5.3":"1. Choisir une page de l’échantillon appartenant au même ensemble que la page en cours d’audit.\n2. Comparer le code source (généré côté client) des deux pages et vérifier que le moyen d’accès au moteur de recherche est toujours à la même place dans la structure (par rapport à l’ordre relatif des éléments de la page, par exemple il est toujours en haut de page).\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '12.5' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"12.6.1":"1. Retrouver dans le document les zones de regroupement de contenus présentes dans plusieurs pages web (à l’exception des zones principales constituant la structure du document).\n2. Pour chaque zone, vérifier que la zone :\n   - soit possède un rôle WAI-ARIA de type landmark correspondant à sa nature ;\n   - soit possède un titre de hiérarchie dont le contenu permet de comprendre la nature du contenu de la zone ;\n   - soit peut être masquée au moyen d’un bouton précédant directement la zone dans l’ordre du code source ;\n   - soit peut être évitée au moyen d’un lien d’évitement précédant directement la zone dans l’ordre du code source ;\n   - soit peut être atteinte au moyen d’un lien d’accès rapide soit visible par défaut, soit visible à la prise de focus lors d’une tabulation.\n3. Si c’est le cas pour chaque zone de regroupement de contenus, **le test est validé**.\n"}'::jsonb
where identifier = '12.6' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"12.7.1":"1. Retrouver dans le document la zone de contenu principal (indiquée par l’élément main visible).\n2. Vérifier que la zone :\n   - soit peut être évitée au moyen d’un lien d’évitement précédant directement la zone dans l’ordre du code source ;\n   - soit peut être atteinte au moyen d’un lien d’accès rapide visible à la prise de focus lors d’une tabulation.\n3. Si c’est le cas, **le test est validé**.\n","12.7.2":"1. Retrouver dans le document la zone de contenu principal (indiquée par l’élément main visible).\n2. Vérifier que le lien d’évitement ou d’accès rapide à la zone est :\n   - situé à la même place dans la présentation ;\n   - présent toujours dans le même ordre relatif dans le code source (généré côté client) ;\n   - visible à la prise de focus lors d’une tabulation ;\n   - fonctionnel.\n3. Si c’est le cas, **le test est validé**."}'::jsonb
where identifier = '12.7' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"12.8.1":"1. Parcourir dans le document l’ensemble des contenus au moyen de la touche de tabulation vers l’avant (touche Tab) et vers l’arrière (touches Maj+Tab).\n2. Vérifier que l’ordre de déplacement du focus reste cohérent relativement au contenu considéré (par exemple, l’ordre de tabulation dans une fenêtre modale ne doit considérer que les éléments d’interface présents au sein de cette fenêtre).\n3. Si c’est le cas, **le test est validé**.\n\nNote : il n’est pas obligatoire que la tabulation suive l’ordre de lecture naturel (de gauche à droite et de haut en bas par exemple) tant que les éléments sont accessibles dans un ordre cohérent.\n","12.8.2":"1. Retrouver dans le document l’ensemble des contenus insérés au moyen d’un script (affichage d’éléments masqués, mise à jour de contenu via AJAX par exemple).\n2. Positionner la tabulation sur l’élément déclencheur et l’activer.\n3. Après l’affichage du contenu mis à jour, vérifier que la tabulation reste cohérente (repositionnement correct du focus).\n4. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '12.8' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"12.9.1":"1. Retrouver dans le document l’ensemble des éléments d’interface susceptibles de recevoir le focus (au moyen de la tabulation ou au moyen d’un script).\n2. Pour chaque élément d’interface, vérifier que l’utilisateur peut atteindre l’élément suivant ou précédent pouvant recevoir le focus :\n   - soit au moyen de la touche de tabulation (<kbd>Tab</kbd> ou <kbd>Maj+Tab</kbd>) ;\n   - soit au moyen d’une autre interaction clavier dont l’utilisateur est informé (par exemple, les flèches de direction).\n3. Si c’est le cas pour chaque élément d’interface, **le test est validé**.\n\nNote : certains éléments d’interface complexes, comme un groupe de boutons radio, une liste de sélection et tous les composants développés avec WAI-ARIA font appel à des navigations optimisées qui utilisent généralement les flèches de direction pour passer d’une partie du composant à l’autre. Par exemple, dans un groupe de boutons radio les options sont navigables avec les flèches de direction. De même dans un système d’onglets l’utilisateur active les onglets avec les flèches de direction. Le test sur le piège au clavier se limite alors à vérifier que le composant est atteint avec la tabulation et qu’il est possible de passer au composant suivant ou revenir au composant précédent.\n"}'::jsonb
where identifier = '12.9' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.1.1":"1. Retrouver dans le document les rafraîchissements initiés dans le contenu par un élément `<object>`, `<embed>`, `<svg>`, `<canvas>` ou par un élément `<meta http-equiv=\"refresh\" content=\"[compteur]\">` (dans l’élément `<head>` de la page).\n2. Pour chaque rafraîchissement, vérifier que :\n   - soit la présence d’un mécanisme permet à l’utilisateur de stopper et de relancer le rafraîchissement ;\n   - soit la présence d’un mécanisme permet à l’utilisateur d’augmenter la limite de temps entre deux rafraîchissements de dix fois, au moins ;\n   - soit la présence d’un mécanisme qui avertit l’utilisateur de l’imminence du rafraîchissement, laisse 20 secondes, au moins, à l’utilisateur, pour augmenter la limite de temps avant le prochain rafraîchissement ;\n   - soit la limite de temps entre deux rafraîchissements est de vingt heures, au moins.\n3. Si c’est le cas, **le test est validé**.\n","13.1.2":"1. Retrouver dans le document une redirection automatique initiée par un élément `<meta http-equiv=\"refresh\" />`.\n2. Si un procédé de redirection existe, vérifier :\n    - soit que la redirection est immédiate (la propriété `content` doit avoir la valeur `0`, par exemple `content=\"0; URL=''https://url.com''\"`)\n    - soit que la limite de temps avant la redirection est de vingt heures, au moins (la propriété `content` a alors une valeur supérieure ou égale à `72000`, par exemple `content=\"80000; URL=''https://url.com''\"`).\n3. Si c’est le cas, **le test est validé**.","13.1.3":"1. Retrouver dans le document les redirections automatiques initiées par un script (sous la forme d’un décompte par exemple).\n2. Pour chaque redirection automatique, vérifier que :\n   - Soit la présence d’un mécanisme permet à l’utilisateur de stopper et relancer la redirection.\n   - Soit la présence d’un mécanisme permet à l’utilisateur d’augmenter la limite de temps avant le rafraîchissement de dix fois, au moins.\n   - Soit la présence d’un mécanisme qui avertit l’utilisateur de l’imminence du rafraîchissement, laisse 20 secondes, au moins, à l’utilisateur, pour augmenter la limite de temps avant le prochain rafraîchissement.\n   - Soit la limite de temps avant la redirection est de vingt heures, au moins.\n3. Si c’est le cas, **le test est validé**.\n","13.1.4":"1. Retrouver dans le document les procédés limitant le temps d’une session (par exemple, après une authentification).\n2. Pour chaque procédé, vérifier que :\n   - soit la présence d’un mécanisme permet à l’utilisateur de supprimer la limite de temps ;\n   - soit la présence d’un mécanisme permet à l’utilisateur d’augmenter la limite de temps ;\n   - soit la limite de temps est de vingt heures, au moins.\n3. Si c’est le cas, **le test est validé**."}'::jsonb
where identifier = '13.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.10.1":"1. Retrouver dans le document les fonctionnalités utilisables ou disponibles au moyen d’une interaction au toucher de type contact multipoint.\n2. Pour chaque fonctionnalité, vérifier qu’elle reste disponible au moyen d’une interaction au toucher de type contact en un point unique de l’écran (par exemple, la possibilité de consulter les éléments d’une liste par un mouvement de balayage horizontal droit ou gauche doit aussi être disponible au moyen de boutons “précédent” et “suivant” ou encore un geste de pincer et zoomer qui peut être alternativement réalisé au moyen de boutons “plus” et “moins”).\n3. Si c’est le cas pour chaque fonctionnalité utilisable ou disponible au moyen d’une interaction au toucher de type contact multipoint, **le test est validé**.\n","13.10.2":"1. Retrouver dans le document les fonctionnalités utilisables ou disponibles au moyen d’une interaction au toucher qui implique le suivi d’une trajectoire sur l’écran.\n2. Pour chaque fonctionnalité, vérifier qu’elle reste disponible au moyen d’une interaction au toucher de type contact en un point unique de l’écran (par exemple, la possibilité de composer son mot de passe en suivant une trajectoire sur un clavier virtuel doit aussi être disponible au moyen de pressions successives sur les touches du clavier).\n3. Si c’est le cas pour chaque fonctionnalité utilisable ou disponible au moyen d’une interaction au toucher qui implique le suivi d’une trajectoire sur l’écran, **le test est validé**."}'::jsonb
where identifier = '13.10' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.11.1":"1. Retrouver dans le document les actions déclenchées au moyen d’un dispositif de pointage sur un point unique de l’écran.\n2. Pour chaque action, vérifier que :\n   - soit l’action est déclenchée au moment où le dispositif de pointage est relâché ou relevé ;\n   - soit l’action est déclenchée au moment où le dispositif de pointage est pressé ou posé puis annulée lorsque le dispositif de pointage est relâché ou relevé ;\n   - soit il existe un mécanisme pour abandonner (avant achèvement de l’action) ou annuler (après achèvement) l’exécution de l’action. Par exemple, lors d’une interaction de type glisser-déposer, un relâchement du dispositif de pointage doit permettre d’abandonner l’interaction en cours et une fois la zone de dépôt atteinte, l’utilisateur doit rester en mesure d’annuler son opération de dépôt au moyen d’un dialogue de confirmation (choix de confirmer ou d’annuler le dépôt) ou par le fait de pouvoir replacer l’élément déposé à sa position initiale.\n3. Si c’est le cas pour chaque action déclenchée au moyen d’un dispositif de pointage sur un point unique de l’écran, **le test est validé**.\n"}'::jsonb
where identifier = '13.11' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.12.1":"1. Retrouver dans le document les fonctionnalités disponibles en bougeant l’appareil.\n2. Pour chaque fonctionnalité, vérifier qu’elle peut être accomplie au moyen de composants d’interface utilisateur.\n3. Si c’est le cas pour chaque fonctionnalité disponible en bougeant l’appareil, **le test est validé**.\n","13.12.2":"1. Retrouver dans le document les fonctionnalités disponibles en faisant un geste en direction de l’appareil.\n2. Pour chaque fonctionnalité, vérifier qu’elle peut être accomplie au moyen de composants d’interface utilisateur.\n3. Si c’est le cas pour chaque fonctionnalité disponible en faisant un geste en direction de l’appareil, **le test est validé**.\n","13.12.3":"1. Retrouver dans le document les fonctionnalités disponibles en mettant en mouvement l’appareil.\n2. Vérifier si l’utilisateur à la possibilité de désactiver la détection du mouvement.\n3. Si c’est le cas, pour chaque fonctionnalité, vérifier qu’elle ne peut pas être déclenchée.\n4. Si c’est le cas pour chaque fonctionnalité disponible en mettant en mouvement l’appareil, **le test est validé**."}'::jsonb
where identifier = '13.12' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.13.1":"Sont concernés tous les formats numériques tels que le texte, l’audio et la vidéo.\n\n1. Repérer dans la page les fonctionnalités de conversion de document (exportation en PDF, en .odt, HTML, etc.).\n2. Repérer dans le contenu original les informations d’accessibilité présentes (alternative d’un élément graphique, niveaux de titres, table des matières, etc.).\n3. Vérifier dans le document résultant de la conversion que les informations d’accessibilité sont toujours présentes (sauf si le format de conversion choisi ne possède pas de support pour les informations d’accessibilité du document source).\n4. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '13.13' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.14.1":"1. Repérer dans la page les fonctionnalités d’identification (authentification) et de contrôle qui utilisent des caractéristiques biologiques (reconnaissance vocale, empreinte digitale, reconnaissance faciale, …).\n2. Vérifier qu’il existe une méthode alternative pour réaliser l’action : \n\t- Pour une fonctionnalité d’authentification qui utilise une reconnaissance d’empreinte digitale, un bouton est disponible sur la page de connexion pour accéder à la saisie d’un mot de passe.\n\t- Pour une fonctionnalité d’authentification qui utilise une reconnaissance vocale, le site web propose également une reconnaissance d’empreinte digitale.\n3. Si c’est le cas, le test est validé.\n\nSi la méthode alternative repose également sur une caractéristique biologique, il est indispensable qu’elle n’utilise pas une caractéristique biologique similaire. Par exemple, si la méthode initiale repose sur la voix, la méthode alternative ne doit pas utiliser la voix."}'::jsonb
where identifier = '13.14' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.2.1":"1. Pendant la consultation d’une page, vérifier qu’aucune nouvelle fenêtre (fenêtre de navigateur ou nouvel onglet) n’est ouverte sans action de l’utilisateur.\n2. Si c’est le cas, **le test est validé**."}'::jsonb
where identifier = '13.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.3.1":"1. Retrouver dans le document les liens et les contrôles de formulaire (un bouton de formulaire ou un formulaire de téléchargement par exemple) permettant de télécharger un fichier au format bureautique.\n2. Pour chaque fichier au format bureautique, vérifier la présence d’une version alternative présentée comme accessible :\n   - Pour les documents au format .pdf, vérifier la conformité au [référentiel d’évaluation de l’accessibilité des documents au format PDF (RAPDF)](../rapdf1.1/index.html).\n   - Pour les documents au format .doc ou .docx, analyser le fichier avec l’outil de vérification d’accessibilité de Microsoft Office (à partir de la version 2010) et vérifier l’absence d’erreur d’accessibilité (cf. note).\n   - Pour les documents au format .odt, analyser le document avec l’outil de vérification d’accessibilité de LibreOffice (à partir de la version 7.0).\n   - Pour les documents au format EPUB/DAISY, analyser le document avec un éditeur EPUB/DAISY.\n   - Pour les documents eux-mêmes au format .html, analyser l’accessibilité du document.\n3. Si c’est le cas pour chaque fichier au format bureautique, **le test est validé**.\n\nNote au sujet Microsoft Office : le logiciel offre un vérificateur d’accessibilité en standard, (accessible via le menu « Fichier > Informations > Vérifier la présence de problèmes > Vérifier l’accessibilité »). Ce vérificateur peut être considérablement amélioré via le <span lang=\"en\">plugin Word Accessibility Plug-in</span> (voir dans la section Outils). Ce plugin ne fonctionne que sur Windows. Sur Mac, le contrôle doit se faire manuellement.\n\nNote au sujet LibreOffice : le logiciel offre un vérificateur d’accessibilité en standard, accessible via le menu « <span lang=\"en\">Tools > Accessibility Check</span> ». \n\nNote au sujet du format EPUB : l’utilitaire <span lang=\"en\">Ace by DAISY App</span> permet d’effectuer le travail de validation d’un fichier EPUB 3 de manière efficace.\n"}'::jsonb
where identifier = '13.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.4.1":"1. Retrouver dans le document les fichiers en téléchargement au format bureautique accompagné de leur version alternative accessible.\n2. Pour chaque couple de fichiers, ouvrir les deux documents (le document d’origine et le document accessible) et vérifier que les deux documents apportent la même information.\n3. Si c’est le cas pour chaque couple de fichiers, **le test est validé**.\n"}'::jsonb
where identifier = '13.4' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.5.1":"1. Retrouver dans le document les contenus cryptiques porteurs d’information.\n2. Pour chaque contenu cryptique, vérifier que :\n   - Soit sa signification est donnée dans le contexte adjacent (immédiatement avant ou après).\n   - Soit sa signification est mise à disposition par une méthode compatible avec l’accessibilité, par exemple le contenu cryptique est inclus dans un lien dont le nom accessible est défini par la propriété `aria-label` qui contient la signification du contenu cryptique.\n3. Si c’est le cas pour chaque contenu cryptique, **le test est validé**.","13.5.2":"1. Retrouver dans le document les contenus cryptiques.\n2. Pour chaque contenu cryptique, vérifier :\n   - Soit que le contenu cryptique est intégré dans une balise qui possède un attribut WAI-ARIA `aria-hidden=\"true\"`.\n   - Soit qu’une balise parente du contenu cryptique possède un attribut WAI-ARIA `aria-hidden=\"true\"`.\n3. Si c’est le cas pour chaque contenu cryptique, **le test est validé**.\n"}'::jsonb
where identifier = '13.5' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.6.1":"1. Retrouver dans le document les contenus cryptiques porteurs d’information.\n2. Pour chaque contenu cryptique, vérifier que la signification donnée est pertinente.\n3. Si c’est le cas pour chaque contenu cryptique, **le test est validé**.\n"}'::jsonb
where identifier = '13.6' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.7.1":"1. Retrouver dans le document les contenus clignotants ou qui provoquent des effets de flash de type image animée, vidéo (cf. note) ou animation (éléments `<img>`, `<svg>`, `<canvas>`, `<embed>`, `<object>` ou `<video>`).\n2. Pour chaque contenu clignotant ou provoquant des effets de flash, vérifier que :\n   - soit la fréquence de l’effet est inférieure ou égale à 3 par seconde ;\n   - soit la surface cumulée est inférieure à ou égale 21824 pixels.\n3. Si c’est le cas pour chaque contenu clignotant ou provoquant des effets de flash, **le test est validé**.\n\nNote : l’évaluation de ce critère peut être complexe. Lorsque l’effet est géré par un script ou au moyen de CSS, l’analyse du code est suffisante. L’outil PEAT permet d’analyser les vidéos au format .avi, par exemple. Un exemple de vidéo ayant provoqué des crises d’épilepsie peut être consulté ici : <span lang=\"en\">[London 2012 Olympics Seizure](https://www.youtube.com/watch?v=vs0hfhSje9M)</span>.\n","13.7.2":"1. Retrouver dans le document les contenus clignotants ou qui provoquent des effets de flash obtenus au moyen d’un script.\n2. Pour chaque contenu clignotant ou provoquant des effets de flash, vérifier que :\n   - soit la fréquence de l’effet est inférieure ou égale à 3 par seconde ;\n   - soit la surface cumulée est inférieure ou égale à 21824 pixels.\n3. Si c’est le cas pour chaque contenu clignotant ou provoquant des effets de flash, **le test est validé**.\n","13.7.3":"1. Retrouver dans le document les contenus clignotants ou qui provoquent des effets de flash obtenus au moyen d’une animation CSS.\n2. Pour chaque contenu clignotant ou provoquant des effets de flash, vérifier que :\n   - soit la fréquence de l’effet est inférieure ou égale à 3 par seconde ;\n   - soit la surface cumulée est inférieure ou égale à 21824 pixels.\n3. Si c’est le cas pour chaque contenu clignotant ou provoquant des effets de flash, **le test est validé**.\n"}'::jsonb
where identifier = '13.7' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.8.1":"1. Retrouver dans le document les contenus en mouvement (obtenus au moyen d’une image, d’un script ou d’un effet CSS) déclenchés automatiquement au chargement de la page ou lors de l’affichage d’un contenu (cf. note).\n2. Pour chaque contenu, vérifier que :\n   - soit la durée du mouvement est inférieure à 5 secondes ;\n   - soit la présence d’un mécanisme (un bouton, par exemple) permet d’arrêter et de relancer le mouvement ;\n   - soit la présence d’un mécanisme (un bouton, par exemple) permet de cacher et d’afficher à nouveau le contenu en mouvement ;\n   - soit la présence d’un mécanisme (un bouton, par exemple) permet d’afficher la totalité du contenu sans mouvement.\n3. Si c’est le cas pour chaque contenu en mouvement, **le test est validé**.\n","13.8.2":"1. Retrouver dans le document les contenus clignotants (obtenus au moyen d’une image, d’un script ou d’un effet CSS) déclenchés automatiquement au chargement de la page ou lors de l’affichage d’un contenu (cf. note).\n2. Pour chaque contenu, vérifier que :\n   - soit la durée du clignotement est inférieure à 5 secondes ;\n   - soit la présence d’un mécanisme (un bouton, par exemple) permet d’arrêter et de relancer le clignotement ;\n   - soit la présence d’un mécanisme (un bouton, par exemple) permet de cacher et d’afficher à nouveau le contenu clignotant ;\n   - soit la présence d’un mécanisme (un bouton, par exemple) permet d’afficher la totalité du contenu clignotant.\n3. Si c’est le cas pour chaque contenu clignotant, **le test est validé**.\n\nNote : l’arrêt ou la mise en pause d’un contenu en mouvement ou clignotant au moyen de la prise de focus (par exemple, l’effet est suspendu uniquement pendant la prise de focus) n’est pas considéré comme un procédé conforme. Dans certains cas, le mouvement ne peut pas être arrêté, par exemple dans le cas d’une barre de progression, dans ce cas, le critère est non applicable.\n"}'::jsonb
where identifier = '13.8' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"13.9.1":"1. Consulter le document dans un mode d’orientation portrait puis dans un mode d’orientation paysage.\n2. Vérifier que :\n   - La consultation est possible, quel que soit le mode d’orientation de l’écran.\n   - Le contenu proposé reste le même, quel que soit le mode d’orientation de l’écran utilisé même si sa présentation et le moyen d’y accéder peuvent différer.\n3. Si c’est le cas, **le test est validé**."}'::jsonb
where identifier = '13.9' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"14.1.1":"1. Repérer la présence d’une documentation.\n2. Repérer la présence de fonctionnalités d’accessibilité.\n3. Vérifier la présence dans la documentation : \n\t- de la description des fonctionnalités d’accessibilité proposées par le site web ;\n\t- d’explications sur les modalités d’utilisation de ces fonctionnalités (leur localisation, les méthodes pour les activer) ;\n\t- de la description des composants complexes pour lesquels il est mis en place une gestion particulière selon les technologies d’assistance ;\n\t- de la liste des non-conformités ou de la description des éléments non conformes, et de la présence d’alternatives le cas échéant ;\n\t- de la description des composants qui présentent des défauts de compatibilité avec les technologies d’assistance.\n4.\tSi c’est le cas, le test est validé."}'::jsonb
where identifier = '14.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"14.2.1":"1. Repérer les fonctionnalités d’accessibilité décrites dans la documentation. Par exemple : \n\t- accéder à une version du contenu en langage simplifié ;\n\t- agrandir la taille du texte.\n2. Vérifier que les utilisateurs concernés par chaque fonctionnalité d’accessibilité sont en mesure d’y accéder. Par exemple :\n\t- Version alternative en langage simplifié : le mécanisme ou l’ensemble des mécanismes qui permettent d’activer la fonctionnalité doit être compréhensible et identifiable par une personne qui bénéficie du langage simplifié (par exemple, l’emploi du <a href=\"https://www.inclusion-europe.eu/easy-to-read/\" hreflang=\"en\">logo &laquo;&nbsp;Facile à lire&nbsp;&raquo;</a> pour identifier le mécanisme est une solution conforme).\n\t- Agrandissement de la taille des caractères : si le mécanisme contient du texte, alors le texte doit être affiché par défaut avec une taille de police équivalent à 200% de la taille de police initiale.\n3. Vérifier qu’il est possible d’activer cette fonctionnalité.\n4. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '14.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"14.3.1":"1. Repérer la présence d’une documentation au format web (HTML, CSS).\n2. Vérifier pour chaque élément de documentation qu’il est conforme au [RAWeb](../raweb1/criteres.html).\n3. Si c’est le cas, le test est validé.","14.3.2":"1. Repérer la présence d’une documentation au format PDF.\n2. Vérifier pour chaque élément de documentation qu’il est conforme au [RAPDF](../rapdf1.1/index.html).\n3. Si c’est le cas, le test est validé.","14.3.3":"1. Repérer la présence d’une documentation au format non web (hors PDF).\n2. Vérifier pour chaque élément de documentation qu’il est conforme aux critères de la [section 10 <span lang=\"en\">Non-web documents</span>](https://www.etsi.org/deliver/etsi_en/301500_301599/301549/03.02.01_60/en_301549v030201p.pdf#page=52) de la norme européenne EN 301 549 v3.2.1.\n3. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '14.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"15.1.1":"1. Repérer dans l’outil les fonctionnalités d’édition (par exemple, un éditeur de texte, mais cela peut être une médiathèque ou toute autre interface qui permet de saisir du texte ou définir des propriétés) qui permettent de créer du contenu au format web (HTML, CSS).\n2. Vérifier qu’il est possible de définir les informations d’accessibilité nécessaires pour rendre le contenu conforme au [RAWeb](../raweb1/index.html). Par exemple : \n\t- définir l’alternative textuelle d’une image depuis l’éditeur de texte ou une médiathèque ;\n\t- définir un intitulé de lien ;\n\t- etc.\n3. Si c’est le cas, le test est validé.","15.1.2":"1. Repérer dans l’outil les fonctionnalités d’édition (par exemple, un éditeur de texte, mais cela peut être une médiathèque ou toute autre interface qui permet de saisir du texte ou définir des propriétés) qui permettent de créer du contenu au format PDF.\n2. Vérifier qu’il est possible de définir les informations d’accessibilité nécessaires pour rendre le contenu conforme au [RAPDF](../rapdf1.1/index.html). Par exemple : \n\t- définir l’alternative textuelle d’une image depuis l’éditeur de texte ou une médiathèque ;\n\t- définir un intitulé de lien ;\n\t- etc.\n3. Si c’est le cas, le test est validé.","15.1.3":"1. Repérer dans l’outil les fonctionnalités d’édition (par exemple, un éditeur de texte, mais cela peut être une médiathèque ou toute autre interface qui permet de saisir du texte ou définir des propriétés) qui permettent de créer du contenu au format non web (hors PDF).\n2. Vérifier qu’il est possible de définir les informations d’accessibilité nécessaires pour rendre le contenu conforme aux critères de la [section 10 <span lang=\"en\">Non-web documents</span>](https://www.etsi.org/deliver/etsi_en/301500_301599/301549/03.02.01_60/en_301549v030201p.pdf#page=52) de la norme européenne EN 301 549 v3.2.1. Par exemple : \n\t- définir l’alternative textuelle d’une image depuis l’éditeur de texte ou une médiathèque ;\n\t- définir un intitulé de lien ;\n\t- etc.\n3. Si c’est le cas, le test est validé.","15.1.4":"1. Repérer dans l’outil les fonctionnalités d’édition (par exemple, un éditeur de texte, mais cela peut être une médiathèque ou toute autre interface qui permet de saisir du texte ou définir des propriétés) qui permettent de créer du contenu diffusé dans une application mobile.\n2. Vérifier qu’il est possible de définir les informations d’accessibilité nécessaires pour rendre le contenu conforme aux critères du [RAAM](../raam1.1/index.html) Par exemple : \n\t- définir l’alternative textuelle d’une image depuis l’éditeur de texte ou une médiathèque ;\n\t- définir un intitulé de lien ;\n\t- etc.\n3. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '15.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"15.2.1":"1. Repérer dans l’outil la présence d’aides à la création de contenus accessibles. Cela peut être : \n\t- des tests automatiques ou semi-automatiques disponibles depuis les fonctionnalités d’édition ;\n\t- d’autres outils automatiques (un <i lang=\"en\">chatbot</i> par exemple) ;\n\t- une documentation qui explique comment définir les propriétés d’accessibilité pour chaque élément de contenu ;\n\t- des tests manuels disponibles depuis les fonctionnalités d’édition pour guider les auteurs dans la détection d’erreurs.\n2. Vérifier que les aides à la création de contenus accessibles sont pertinentes, c’est-à-dire que les résultats ou les indications qu’elles donnent permettent de créer un contenu accessible.\n3. Si c’est le cas, le test est validé.\n"}'::jsonb
where identifier = '15.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"15.3.1":"1. Depuis les fonctionnalités d’édition (un éditeur de texte, mais cela peut être une médiathèque et toute autre interface qui permet de saisir du texte ou définir des propriétés), saisir les typologies de contenus proposées par l’éditeur (titre, liste, tableau, image, etc.). Utiliser également les différents paramètres permettant de définir des informations d’accessibilité (renseigner l’alternative textuelle d’une image, ajouter une description sur un lien, etc.)\n2. Enregistrer les saisies.\n3. Consulter le contenu généré : \n\t- dans la fonctionnalité d’édition (par exemple, dans l’éditeur de texte) ;\n\t- et dans l’interface de publication des contenus (par exemple, la page web de publication).\n4. Pour chaque contenu au format web (HTML, CSS), vérifier : \n\t- que les informations nécessaires pour qu’il soit conforme au [RAWeb](../raweb1/index.html) (par exemple, l’alternative d’une image, les niveaux de titres) sont préservées dans le contenu généré.\n\t- que l’information, si elle est restructurée, reste compatible avec les technologies d’assistance (par exemple, si l’auteur saisit un tableau HTML et qu’après l’enregistrement, l’outil linéarise le tableau, l’information ainsi restructurée doit être compréhensible pour les utilisateurs de technologies d’assistance, comme elle l’aurait été dans sa forme initiale).\n5. Pour chaque contenu au format PDF, vérifier : \n\t- que les informations nécessaires pour qu’il soit conforme au [RAPDF](../rapdf1.1/index.html) (par exemple, l’alternative d’une image, les niveaux de titres) sont préservées dans le contenu généré.\n\t- que l’information, si elle est restructurée, reste compatible avec les technologies d’assistance (par exemple, si l’auteur saisit un tableau et qu’après l’enregistrement, l’outil linéarise le tableau, l’information ainsi restructurée doit être compréhensible pour les utilisateurs de technologies d’assistance, comme elle l’aurait été dans sa forme initiale).\n6. Pour chaque contenu au format non web qui n’est pas du PDF, vérifier : \n\t- que les informations nécessaires pour qu’il soit conforme à la [section 10 <span lang=\"en\">Non-web documents</span>](https://www.etsi.org/deliver/etsi_en/301500_301599/301549/03.02.01_60/en_301549v030201p.pdf#page=52) de la norme européenne EN 301 549 v3.2.1 sont préservées dans le contenu généré.\n\t- que l’information, si elle est restructurée, reste compatible avec les technologies d’assistance (par exemple, si l’auteur saisit un tableau et qu’après l’enregistrement, l’outil linéarise le tableau, l’information ainsi restructurée doit être compréhensible pour les utilisateurs de technologies d’assistance, comme elle l’aurait été dans sa forme initiale).\n7. Pour chaque contenu diffusé dans une application mobile, vérifier : \n\t- que les informations nécessaires pour qu’il soit conforme au [RAAM](../raam1.1/index.html) (par exemple, l’alternative d’une image, les niveaux de titres) sont préservées dans le contenu généré.\n\t- que l’information, si elle est restructurée, reste compatible avec les technologies d’assistance (par exemple, si l’auteur saisit un tableau et qu’après l’enregistrement, l’outil linéarise le tableau, l’information ainsi restructurée doit être compréhensible pour les utilisateurs de technologies d’assistance, comme elle l’aurait été dans sa forme initiale).\n8. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '15.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"15.4.1":"1. Repérer dans l’outil la présence de fonctionnalités de tests automatiques ou semi-automatiques.\n2. Générer du contenu (web et non-web) avec l’outil d’édition avec des erreurs d’accessibilité.\n3. Activer les fonctionnalités de tests.\n4. Vérifier : \n\t- que l’outil répare automatiquement l’erreur (test automatique) ;\n\t- ou que l’outil met à disposition de l’auteur des suggestions de réparations (test semi-automatique).\n5.\tDans le cas d’un test semi-automatique, vérifier : \n\t- que l’outil met à disposition une aide à la décision et des suggestions de réparations ;\n\t- ou que l’outil met à disposition de l’auteur des explications pour effectuer la réparation.\n6.\tSi c’est le cas, le test est validé."}'::jsonb
where identifier = '15.4' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"15.5.1":"1. Repérer la présence de gabarits au format web (HTML, CSS) mis à disposition par l’outil d’édition.\n2. Vérifier qu’au moins un gabarit permet de respecter l’ensemble des critères du [RAWeb](../raweb1/index.html).\n5. Si c’est le cas, le test est validé.","15.5.2":"1. Repérer la présence de gabarits au format PDF mis à disposition par l’outil d’édition.\n2. Vérifier qu’au moins un gabarit permet de respecter l’ensemble des critères du [RAPDF](../rapdf1.1/index.html).\n5. Si c’est le cas, le test est validé.","15.5.3":"1. Repérer la présence de gabarits au format non-web (hors PDF) mis à disposition par l’outil d’édition.\n2. Vérifier qu’au moins un gabarit permet de respecter l’ensemble des critères de la [section 10 <span lang=\"en\">Non-web documents</span>](https://www.etsi.org/deliver/etsi_en/301500_301599/301549/03.02.01_60/en_301549v030201p.pdf#page=52) de la norme européenne EN 301 549 v3.2.1.\n5. Si c’est le cas, le test est validé.","15.5.4":"1. Repérer la présence de gabarits pour la diffusion dans une application mobile mis à disposition par l’outil d’édition.\n2. Vérifier qu’au moins un gabarit permet de respecter l’ensemble des critères [RAAM](../raam1.1/index.html).\n5. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '15.5' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"15.6.1":"1. Repérer la présence de gabarits totalement conformes aux règles d’accessibilité numérique mis à disposition par l’outil d’édition.\n2. Vérifier la présence d’une mention explicite permettant de les identifier. Par exemple, depuis la liste des gabarits, les gabarits conformes possèdent une étiquette « gabarit accessible ».\n3. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '15.6' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"16.1.1":"1. Repérer la mise à disposition d’un service d’assistance depuis le site web.\n2. Si c’est le cas, repérer dans le site web la présence d’une documentation.\n3. Repérer la présence dans la documentation : \n\t- de la description des fonctionnalités d’accessibilité proposées par le site web ;\n\t- de la description des composants complexes pour lesquels il est mis en place une gestion particulière selon les technologies d’assistance ;\n\t- d’explications sur les modalités d’utilisation de ces fonctionnalités (leur localisation, les méthodes pour les activer) ;\n\t- de la description des éléments non conformes ou non compatibles avec certaines technologies d’assistance, et de la présence d’alternatives le cas échéant.\n4. Vérifier que le service d’assistance propose des informations concernant ces fonctionnalités.\n5. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '16.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"16.2.1":"1. Retrouver dans le document les services d’assistance.\n2. Pour chaque service, vérifier qu’il peut être utilisé par toutes les personnes en situation de handicap. Il peut être utile de rechercher dans la documentation du site web pour trouver ces informations. Par exemple, si le service d’assistance est disponible depuis un numéro de téléphone, vérifier qu’il existe des moyens alternatifs pour les utilisateurs qui n’accèdent pas ou peu au langage oral (personnes sourdes ou malentendantes) ou qui ne peuvent pas utiliser le langage verbal (personnes aphasiques). Par exemple : \n\t- une adresse mail ou un formulaire en ligne ;\n\t- une messagerie instantanée ;\n\t- la mise à disposition d’une traduction écrite simultanée ou visuelle des informations orales ou sonores, ou la mise à disposition d’un interprète en langue des signes (utilisation d’un service de relais).\n3. Si c’est le cas, le test est validé.\n"}'::jsonb
where identifier = '16.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"16.3.1":"1. Repérer la présence d’une documentation fournie par le service d’assistance.\n2. Vérifier pour chaque élément de documentation : \n\t- s’il s’agit d’une page web (HTML, CSS), qu’il respecte le [RAWeb](../raweb1/criteres.html) ;\n\t- s’il s’agit d’un document bureautique au format PDF, qu’il respecte le [référentiel d’évaluation de l’accessibilité des documents au format PDF (RAPDF)](../rapdf1.1/index.html) ;\n\t- s’il s’agit d’un document non web qui n’est pas au format PDF, qu’il respecte les critères de la [section 10 <span lang=\"en\">Non-web documents</span>](https://www.etsi.org/deliver/etsi_en/301500_301599/301549/03.02.01_60/en_301549v030201p.pdf#page=52) de la norme européenne EN 301 549 v3.2.1.\n3.\tSi c’est le cas, le test est validé."}'::jsonb
where identifier = '16.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"17.1.1":"1. Activer l’application web et lancer un appel entre les deux terminaux.\n2. Vérifier que la qualité de l’activité orale avec l’application web est au moins équivalente à la qualité de l’activité orale lors d’un appel avec un téléphone fixe.\n3. Si le test n’est pas satisfaisant (par exemple, mauvaise compréhension de certains mots énoncés par l’interlocuteur, présence de bruits parasites, etc.), vérifier dans la documentation de l’application : \n   1. la présence d’une référence à l’implémentation de la [recommandation UIT-T G.722](https://www.itu.int/rec/T-REC-G.722/fr) ; \n   2. ou la présence d’une référence à l’utilisation du [codec opus de l’API WebRTC](https://developer.mozilla.org/en-US/docs/Web/Media/Formats/WebRTC_codecs) ; \n   3. ou la présence d’une référence à l’utilisation d’un encodage et décodage dont la fréquence est supérieure ou égale à 7 000 Hz.\n4. Sinon, il est recommandé de demander à l’éditeur de l’application de fournir ces détails techniques, notamment en demandant si l’application web implémente par exemple la [recommandation UIT-T G.722](https://www.itu.int/rec/T-REC-G.722/fr) ou utilise le [codec opus de l’API WebRTC](https://developer.mozilla.org/en-US/docs/Web/Media/Formats/WebRTC_codecs).\n5. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '17.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"17.10.1":"1.\tRepérer dans l’application web les fonctionnalités disponibles (en dehors de la fonctionnalité de communication orale) qui se basent sur l’écoute d’information ou l’énonciation de commande, par exemple : \n\t- une messagerie vocale ;\n\t- un standard téléphonique automatique (par exemple, qui demande d’énoncer un chiffre entre 1 et 4 pour être redirigé vers un service) ;\n\t- ou tout autre serveur vocal interactif.\n2.\tVérifier : \n\t- que l’information est disponible sans devoir écouter ou parler (par exemple grâce à une transcription textuelle ou un système de chat) ;\n\t- que les actions peuvent être réalisées sans devoir écouter ou parler ou qu’il existe une alternative à la fonctionnalité qui peut être utilisée sans devoir écouter ou parler.\n3.\tSi c’est le cas, le test est validé."}'::jsonb
where identifier = '17.10' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"17.11.1":"Pour les conditions concernant la résolution et la fréquence des images, la façon la plus sûre d’évaluer ce critère est de faire une recherche soit dans l’interface soit dans la documentation de l’application pour obtenir ces informations. Il est également recommandé de demander à l’éditeur de l’application de fournir ces détails techniques.\n\nPour la dernière condition concernant le décalage entre la vidéo et l’audio, le test peut s’établir sur une simple observation :\n1. Activer l’application web sur deux terminaux.\n2. Établir une connexion d’appel vidéo entre les deux terminaux.\n3. Vérifier la synchronisation entre les paroles et la vidéo (synchronisation labiale, mouvement des lèvres).\n4. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '17.11' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"17.2.1":"1. Vérifier que l’application web permet la communication orale bidirectionnelle.\n2. Si c’est le cas, vérifier la présence d’une fonctionnalité de communication écrite en temps réel (il peut être parfois nécessaire d’activer un paramètre dédié dans l’application pour permettre la communication écrite en temps réel).\n3. Sinon, vérifier si l’application web peut se connecter à un terminal intégrant une fonctionnalité de communication écrite en temps réel. Cette évaluation peut être complexe à mener sans la mise à disposition d’un terminal de communication en temps réel ou si le réseau utilisé par le terminal ne supporte pas les protocoles de texte en temps réel. Une première étape peut être de rechercher dans la documentation ou de questionner directement l’éditeur de l’application.\n4. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '17.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"17.3.1":"1. Vérifier que l’application web permet la communication orale bidirectionnelle.\n2. Si c’est le cas, vérifier la présence d’une fonctionnalité de communication écrite en temps réel.\n3. Si c’est le cas, vérifier qu’il est possible d’utiliser les deux modes de communications en même temps, c’est-à-dire qu’il est possible pour un même utilisateur de parler et d’utiliser simultanément le système de communication écrite en temps réel.\n4. Si c’est le cas, le test est validé.\n"}'::jsonb
where identifier = '17.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"17.4.1":"1. Activer l’application web et la fonctionnalité de communication écrite en temps réel de l’application sur deux terminaux et les connecter à une même session.\n2. Envoyer un message écrit depuis les deux terminaux pour obtenir des messages avec des statuts différents (envoyé et reçu).\n3. Vérifier : \n\t- que les messages envoyés et reçus sont visuellement séparés (par exemple, les messages envoyés sont dans une fenêtre et les messages reçus dans une autre, ou il y a un saut de ligne entre chaque message reçu et envoyé s’ils sont présentés dans une même fenêtre) ;\n\t- qu’il est possible visuellement de distinguer les messages envoyés et les messages reçus. Par exemple, par une mise en forme ou une couleur qui les différencie ou par une annotation textuelle visible (repérer la mention « Envoyé » à proximité d’un message envoyé ou « Reçu » à proximité d’un message reçu) ;\n\t- que l’information de la nature du message (reçu ou envoyé) est accessible aux technologies d’assistance (une information textuelle est disponible pour apporter cette information).\n4. Si c’est le cas, le test est validé.","17.4.2":"1. Activer l’application web et la fonctionnalité de communication écrite en temps réel de l’application sur deux terminaux et les connecter à une même session.\n2. Envoyer un message écrit depuis les deux terminaux pour obtenir des messages avec des auteurs différents.\n3. Vérifier que les auteurs des messages écrits sont identifiés (par exemple, la présence d’un nom ou un identifiant précédant le message).\n4. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '17.4' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"17.5.1":"1. Vérifier que l’application web permet la communication orale bidirectionnelle et la communication écrite en temps réel.\n2. Si c’est le cas, activer l’application web sur deux terminaux et les connecter à une même session.\n3. Faire parler un utilisateur depuis un des terminaux.\n4. Vérifier sur l’interface l’apparition d’un indicateur visuel permettant d’identifier qu’une personne est en train de parler. Il n’est pas nécessaire pour ce critère d’identifier qui parle, mais simplement d’identifier qu’il y a une personne qui est en train de parler. Par exemple, un halo autour ou une icône à proximité de l’avatar de la personne qui parle.\n5. Si c’est le cas, le test est validé.","17.5.2":"1. Vérifier que l’application web permet la communication orale bidirectionnelle et la diffusion de la vidéo en temps réel.\n2. Si c’est le cas, activer l’application sur deux terminaux et les connecter à une même session.\n3. Faire parler un utilisateur depuis un des terminaux.\n4. Vérifier sur l’interface l’apparition d’un indicateur visuel permettant d’identifier qu’une personne est en train de parler. Il n’est pas nécessaire pour ce critère d’identifier qui parle, mais simplement d’identifier qu’il y a une personne qui est en train de parler. Par exemple, un halo autour ou une icône à proximité de l’avatar de la personne qui parle.\n5. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '17.5' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"17.6.1":"Ce critère est très complexe à évaluer et demande une certaine maîtrise de l’ensemble des concepts et normes d’interopérabilité. \n\nIl est recommandé de demander à l’éditeur de l’application de vérifier que l’ensemble des exigences décrites dans le critère 6.2.3 <span lang=\"en\">Interoperability</span> de la norme EN 301 549 sont respectées."}'::jsonb
where identifier = '17.6' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"17.7.1":"1. Vérifier que l’application web permet la communication écrite en temps réel.\n2. Si c’est le cas, activer l’application web et la fonctionnalité de communication écrite sur deux terminaux distincts et les connecter à une même session.\n3. Saisir du texte sur le premier terminal et observer son apparition sur le second terminal. L’apparition sur le second terminal doit être instantanée (inférieure à une demi-seconde). Selon le paramétrage de la fonctionnalité, chaque caractère n’est pas envoyé individuellement. En effet, si la fonctionnalité de communication écrite en temps réel implémente une prédiction de mots, c’est lorsque le mot désiré sera sélectionné qu’il sera envoyé, et non pas lors de la saisie des premiers caractères servant à déclencher l’affichage de suggestion. Un test par observation simple peut être suffisant pour constater l’apparition instantanée sur le terminal qui reçoit le message écrit.\n4. Si c’est le cas, le test est validé.\n"}'::jsonb
where identifier = '17.7' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"17.8.1":"1. Activer l’application web depuis un terminal.\n2. Depuis un second terminal, lancer un appel vers le premier terminal.\n3. Lorsque l’appel entrant apparaît, vérifier : \n\t- que l’identification de l’interlocuteur est disponible visuellement sous la forme d’un texte dont la nature est compréhensible (par exemple, un nom ou un numéro de téléphone) ;\n\t- que cette identification est compatible avec les technologies d’assistance : par exemple, par l’utilisation d’un message de statut pertinent.\n4. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '17.8' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"17.9.1":"1. Activer l’application web et lancer un appel vidéo entre les deux terminaux.\n2. Initier une activité orale, et vérifier la présence sur le second terminal d’une information permettant d’identifier cette activité (par exemple, la présence d’un halo de couleur autour de la vignette de l’interlocuteur en activité). \n3. Si c’est le cas : \n\t- repérer la présence d’un mécanisme manuel (par exemple, un bouton) qui permettrait à l’interlocuteur signant d’indiquer qu’il est en train de signer&nbsp;;\n\t- sinon, réaliser des gestes devant la caméra (voir note) et vérifier l’affichage automatique d’une information permettant d’identifier cette activité visuelle.\n4. Si c’est le cas, le test est validé.\n\n\n**Note :** dans les applications de communication, l’identification d’une activité orale ne repose pas sur l’identification d’un message verbal intelligible (mot ou phrase par exemple) mais uniquement sur l’identification d’un son (un bruit par exemple). Ainsi, une activité visuelle, même si elle ne correspond pas à un élément compréhensible en langue des signes, pourrait être détectée automatiquement par cette application et servirait donc comme mécanisme pour identifier l’activité d’une personne signante. Il est donc possible de tester en réalisant des gestes même s’ils ne correspondent pas à un élément de sens en langue des signes."}'::jsonb
where identifier = '17.9' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"2.1.1":"1. Retrouver dans le document les cadres (élément `<iframe>` ou `<frame>`).\n2. Pour chaque cadre, vérifier qu’il possède un attribut `title `.\n3. Si c’est le cas pour chaque cadre, **le test est validé**.\n"}'::jsonb
where identifier = '2.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"2.2.1":"1. Retrouver dans le document les cadres (élément `<iframe>` ou `<frame>`).\n2. Pour chaque cadre pourvu d’un attribut `title`, vérifier que son contenu est pertinent.\n3. Si c’est le cas pour chaque cadre, **le test est validé**.\n"}'::jsonb
where identifier = '2.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"3.1.1":"1. Retrouver dans le document les informations données par la couleur dans un mot ou un ensemble de mots.\n2. Pour chacune de ces informations, vérifier la présence : \n    - d’un complément au niveau du code (`title`, `aria-label`, texte visuellement masqué, `aria-current`, etc.) ;\n    - et d’une information visuelle complémentaire à la couleur (icône, effet graphique de forme ou de position, un effet typographique…).\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","3.1.2":"1. Retrouver dans le document les informations données par la couleur dans un texte.\n2. Pour chacune de ces informations, vérifier la présence : \n    - d’un complément au niveau du code (`title`, `aria-label`, texte visuellement masqué, `aria-current`, etc.) ;\n    - et d’une information visuelle complémentaire à la couleur (icône, effet graphique de forme ou de position, un effet typographique…).\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","3.1.3":"1. Retrouver dans le document les informations données par la couleur dans une image.\n2. Pour chacune de ces informations, vérifier la présence : \n    - d’un complément au niveau du code (`title`, `aria-label`, texte visuellement masqué, `aria-current`, etc.) ;\n    - et d’une information visuelle complémentaire à la couleur (icône, effet graphique de forme ou de position, un effet typographique…).\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","3.1.4":"1. Retrouver dans le document les informations données par la couleur dans une propriété CSS.\n2. Pour chacune de ces informations, vérifier la présence : \n    - d’un complément au niveau du code (`title`, `aria-label`, texte visuellement masqué, `aria-current`, etc.) ;\n    - et d’une information visuelle complémentaire à la couleur (icône, effet graphique de forme ou de position, un effet typographique…).\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","3.1.5":"1. Retrouver dans le document les informations données par la couleur dans un média temporel.\n2. Pour chacune de ces informations, vérifier la présence : \n    - d’un complément au niveau du code (`title`, `aria-label`, texte visuellement masqué, `aria-current`, etc.) ;\n    - et d’une information visuelle complémentaire à la couleur (icône, effet graphique de forme ou de position, un effet typographique…).\n3. Si c’est le cas pour chaque information, **le test est validé**.\n","3.1.6":"1. Retrouver dans le document les informations données par la couleur dans un média non temporel.\n2. Pour chacune de ces informations, vérifier la présence : \n    - d’un complément au niveau du code (`title`, `aria-label`, texte visuellement masqué, `aria-current`, etc.) ;\n    - et d’une information visuelle complémentaire à la couleur (icône, effet graphique de forme ou de position, un effet typographique…).\n3. Si c’est le cas pour chaque information, **le test est validé**.\n"}'::jsonb
where identifier = '3.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"3.2.1":"1. Retrouver dans le document les textes et les textes en image sans effet de graisse d’une taille restituée inférieure à 24px qui pourraient poser des problèmes de contraste.\n2. Pour chacun de ces textes, vérifier que :\n   - soit le rapport de contraste entre le texte et son arrière-plan est de 4.5:1, au moins ;\n   - soit un mécanisme permet à l’utilisateur d’afficher le texte avec un rapport de contraste de 4.5:1, au moins.\n3. Si c’est le cas pour chaque texte, **le test est validé**.\n","3.2.2":"1. Retrouver dans le document les textes et les textes en image en gras d’une taille restituée inférieure à 18,5px qui pourraient poser des problèmes de contraste.\n2. Pour chacun de ces textes, vérifier que :\n   - soit le rapport de contraste entre le texte et son arrière-plan est de 4.5:1, au moins ;\n   - soit un mécanisme permet à l’utilisateur d’afficher le texte avec un rapport de contraste de 4.5:1, au moins.\n3. Si c’est le cas pour chaque texte, **le test est validé**.\n","3.2.3":"1. Retrouver dans le document les textes et les textes en image sans effet de graisse d’une taille restituée supérieure ou égale à 24px qui pourraient poser des problèmes de contraste.\n2. Pour chacun de ces textes, vérifier que :\n   - soit le rapport de contraste entre le texte et son arrière-plan est de 3:1, au moins ;\n   - soit un mécanisme permet à l’utilisateur d’afficher le texte avec un rapport de contraste de 3:1, au moins.\n3. Si c’est le cas pour chaque texte, **le test est validé**.\n","3.2.4":"1. Retrouver dans le document les textes et les textes en image en gras d’une taille restituée supérieure ou égale à 18,5px qui pourraient poser des problèmes de contraste.\n2. Pour chacun de ces textes, vérifier que :\n   - soit le rapport de contraste entre le texte et son arrière-plan est de 3:1, au moins ;\n   - soit un mécanisme permet à l’utilisateur d’afficher le texte avec un rapport de contraste de 3:1, au moins.\n3. Si c’est le cas pour chaque texte, **le test est validé**.\n","3.2.5":"1. Retrouver dans le document les mécanismes qui permettent d’afficher un rapport de contraste conforme.\n2. Pour chacun de ces mécanismes, vérifier que le rapport de contraste entre le texte et la couleur d’arrière-plan est suffisamment élevé.\n3. Si c’est le cas pour chaque mécanisme, **le test est validé**.\n"}'::jsonb
where identifier = '3.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"3.3.1":"1. Retrouver dans le document les composants d’interface qui pourraient poser des problèmes de contraste.\n2. Pour chacun de ces composants, vérifier que :\n   - soit le rapport de contraste entre les couleurs du composant dans ses différents états et la couleur d’arrière-plan contiguë est de 3:1, au moins ;\n   - soit un mécanisme permet à l’utilisateur d’afficher le composant avec un rapport de contraste de 3:1, au moins.\n3. Si c’est le cas pour chaque composant, **le test est validé**.\n","3.3.2":"1. Retrouver dans le document les éléments graphiques qui pourraient poser des problèmes de contraste.\n2. Pour chacun de ces éléments, vérifier que :\n   - soit le rapport de contraste entre les couleurs de l’élément graphique nécessaires à sa compréhension et la couleur d’arrière-plan contiguë est de 3:1, au moins ;\n   - soit un mécanisme permet à l’utilisateur d’afficher l’élément graphique avec un rapport de contraste de 3:1, au moins.\n3. Si c’est le cas pour chaque composant, **le test est validé**.\n","3.3.3":"1. Retrouver dans le document les éléments graphiques qui pourraient poser des problèmes de contraste.\n2. Pour chacun de ces éléments, vérifier que :\n   - soit le rapport de contraste des différentes couleurs contiguës de l’élément graphique entre elles, lorsqu’elles sont nécessaires à sa compréhension, est de 3:1, au moins ;\n   - soit un mécanisme permet à l’utilisateur d’afficher l’élément graphique avec un rapport de contraste de 3:1, au moins.\n3. Si c’est le cas pour chaque élément graphique, **le test est validé**.\n","3.3.4":"1. Retrouver dans le document les mécanismes qui permettent d’afficher un rapport de contraste conforme.\n2. Pour chacun de ces mécanismes, vérifier que le rapport de contraste entre les couleurs du composant ou des éléments graphiques porteurs d’informations qui le composent est suffisamment élevé.\n3. Si c’est le cas pour chaque mécanisme, **le test est validé**."}'::jsonb
where identifier = '3.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.1.1":"1. Retrouver dans le document les médias temporels (éléments `<audio>`, `<video>` ou `<object>`) seulement audio qui nécessitent une transcription textuelle.\n2. Pour chaque média temporel seulement audio, vérifier la présence d’une transcription textuelle :\n   - soit accessible au moyen d’un bouton ou d’un lien adjacent (une URL ou une ancre) ;\n   - soit adjacente clairement identifiable.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.1.2":"1. Retrouver dans le document les médias temporels (éléments `<video>` ou `<object>`) seulement vidéo qui nécessitent une transcription textuelle.\n2. Pour chaque média temporel seulement vidéo, vérifier la présence :\n   - soit d’une version alternative audio seulement accessible au moyen d’un lien ou bouton adjacent (une URL ou une ancre) ;\n   - soit d’une version alternative audio seulement adjacente ;\n   - soit d’une transcription textuelle accessible au moyen d’un bouton ou d’un lien adjacent (une URL ou une ancre) ;\n   - soit d’une transcription textuelle adjacente clairement identifiable ;\n   - soit d’une audiodescription synchronisée ;\n   - soit d’une version alternative avec une audiodescription synchronisée accessible au moyen d’un bouton ou d’un lien adjacent (une URL ou une ancre).\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.1.3":"1. Retrouver dans le document les médias temporels (éléments `<video>` ou `<object>`) synchronisés qui nécessitent une transcription textuelle.\n2. Pour chaque média temporel synchronisé, vérifier la présence :\n   - soit d’une transcription textuelle accessible au moyen d’un lien ou bouton adjacent (une URL ou une ancre) ;\n   - soit d’une transcription textuelle adjacente clairement identifiable ;\n   - soit d’une audiodescription synchronisée ;\n   - soit d’une version alternative avec une audiodescription synchronisée accessible au moyen d’un bouton ou d’un lien adjacent (une URL ou une ancre) ;\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n"}'::jsonb
where identifier = '4.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.10.1":"1. Au chargement du document, si un son se déclenche automatiquement, vérifier que :\n   - soit la séquence sonore a une durée inférieure ou égale à 3 secondes ;\n   - soit un dispositif (un bouton par exemple), sur l’élément ayant déclenché le son (voir note), ou dans la page, permet de le stopper ;\n   - soit le volume de la séquence peut être contrôlé par l’utilisateur, indépendamment du contrôle de volume du système.\n2. Si c’est le cas, **le test est validé**.\n\nNote : les éléments suivants sont susceptibles de déclencher des sons au chargement de la page : éléments `<audio>`, `<video>`, `<object>`, `<embed>`, `<bgsound>` ou un code JavaScript (utilisation de la Web Audio API, par exemple)."}'::jsonb
where identifier = '4.10' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.11.1":"1. Retrouver dans le document les médias temporels.\n2. Pour chaque média temporel, vérifier la présence des fonctionnalités obligatoires de contrôle de la consultation :\n   - au minimum : lecture, pause ou stop ;\n   - si le média a du son, il doit avoir une fonctionnalité d’activation / désactivation du son ;\n   - si le média a des sous-titres, il doit avoir une fonctionnalité de contrôle de l’apparition/disparition des sous-titres ;\n   - si le média a une audiodescription, il doit avoir une fonctionnalité de contrôle de l’apparition/disparition de l’audiodescription.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.11.2":"1. Retrouver dans le document les médias temporels pourvus de fonctionnalités de contrôle.\n2. Pour chaque média temporel, vérifier que :\n   - soit la fonctionnalité est accessible par le clavier et tout dispositif de pointage ;\n   - soit une fonctionnalité accessible par le clavier et tout dispositif de pointage permettant de réaliser la même action est présente dans la page.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.11.3":"1. Retrouver dans le document les médias temporels pourvus de fonctionnalités de contrôle.\n2. Pour chaque média temporel, vérifier que :\n   - soit la fonctionnalité est activable par le clavier et tout dispositif de pointage ;\n   - soit une fonctionnalité activable par le clavier et tout dispositif de pointage permettant de réaliser la même action est présente dans la page.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n"}'::jsonb
where identifier = '4.11' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.12.1":"1. Retrouver dans le document les médias non temporels pourvus de fonctionnalités de contrôle.\n2. Pour chaque média non temporel, vérifier que :\n   - soit la fonctionnalité est accessible par le clavier et tout dispositif de pointage ;\n   - soit une fonctionnalité accessible par le clavier et tout dispositif de pointage permettant de réaliser la même action est présente dans la page.\n3. Si c’est le cas pour chaque média non temporel, **le test est validé**.\n","4.12.2":"1. Retrouver dans le document les médias non temporels pourvus de fonctionnalités de contrôle.\n2. Pour chaque média non temporel, vérifier que :\n   - soit la fonctionnalité est activable par le clavier et tout dispositif de pointage ;\n   - soit une fonctionnalité activable par le clavier et tout dispositif de pointage permettant de réaliser la même action est présente dans la page.\n3. Si c’est le cas pour chaque média non temporel, **le test est validé**.\n"}'::jsonb
where identifier = '4.12' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.13.1":"1. Retrouver dans le document les médias temporels et non temporels.\n2. Pour chaque média, vérifier que :\n   - soit le nom, le rôle, la valeur, le paramétrage et les changements d’états des composants d’interfaces sont accessibles aux technologies d’assistance via une API d’accessibilité (par exemple, les zones mises à jour dynamiquement dans un lecteur vidéo sont correctement restituées) ;\n   - soit une alternative compatible avec une API d’accessibilité permet d’accéder aux mêmes fonctionnalités.\n3. Si c’est le cas pour chaque média temporel ou non temporel, **le test est validé**.\n","4.13.2":"1. Retrouver dans le document les médias temporels et non temporels qui possèdent une alternative compatible avec les technologies d’assistance.\n2. Pour chaque média, vérifier que :\n   - soit l’alternative est adjacente au média temporel ou non temporel ;\n   - soit l’alternative est accessible au moyen d’un lien ou d’un bouton adjacent ;\n   - soit un mécanisme permet de remplacer le média temporel ou non temporel par son alternative.\n3. Si c’est le cas pour chaque média temporel ou non temporel, **le test est validé**."}'::jsonb
where identifier = '4.13' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.14.1":"1. Repérer les médias temporels pré-enregistrés avec une piste de sous-titres synchronisés ou une audiodescription.\n2. Vérifier qu’il est possible d’activer et désactiver les sous-titres ou l’audiodescription sans étape supplémentaire par rapport aux fonctionnalités principales (lecture, pause…).\n3. Si c’est le cas, le test est validé.\n\n<i>Exemple :</i> Si le bouton de lecture peut être activé depuis l’interface par un simple clic souris (sans la nécessité d’activer un premier composant pour afficher un menu déroulant par exemple), la fonction de sous-titres doit être disponible de manière équivalente, avec un simple clic. À l’inverse, si la fonction des sous-titres est disponible depuis un menu déroulant qui doit être activé au préalable (par un clic souris par exemple), elle ne sera pas considérée comme étant au même niveau puisqu’il y aura une étape supplémentaire à réaliser."}'::jsonb
where identifier = '4.14' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.15.1":"1. Repérer les fonctionnalités qui permettent de transmettre (envoyer un contenu vers un autre terminal ou envoyer une vidéo par e-mail par exemple), convertir (convertir une vidéo au format .avi dans un format .mpg par exemple) ou enregistrer un média temporel synchronisé pré-enregistré (enregistrer une vidéo depuis une plateforme de diffusion sur son ordinateur personnel par exemple). \n2. Exécuter chacune des fonctionnalités (transmettre, convertir et enregistrer).\n3. Pour chaque fonctionnalité, vérifier si les sous-titres&nbsp;:\n   - sont toujours présents ;\n   - peuvent être affichés ;\n   - sont correctement synchronisés ;\n   - conservent leurs caractéristiques essentielles (par exemple, si les sous-titres étaient colorés en fonction du locuteur, les couleurs doivent être reprises).\n4. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '4.15' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.16.1":"1. Repérer les fonctionnalités qui permettent de transmettre, convertir ou enregistrer un média temporel. Par exemple&nbsp;: envoyer un contenu vers un autre terminal ou par mail, convertir une vidéo au format .avi dans un format .mpg, enregistrer une vidéo depuis une plateforme de diffusion sur son ordinateur personnel.\n2. Exécuter chacune des fonctionnalités (transmettre, convertir et enregistrer).\n3. Pour chaque fonctionnalité, vérifier si l’audiodescription&nbsp;:\n   - est présente ;\n   - peut être activée ;\n   - est correctement synchronisée :\n      - les sons et paroles de l’audiodescription ne chevauchent pas ceux de la bande-son originale et ne provoquent pas de problèmes de perception et de compréhension ;\n      - les informations véhiculées dans l’audiodescription sont données au moment où apparaissent les informations visuelles équivalentes.\n4. Si c’est le cas, le test est validé.\n"}'::jsonb
where identifier = '4.16' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.17.1":"1. Repérer les médias temporels pré-enregistrés qui possèdent des sous-titres.\n2. Définir un ou plusieurs paramètres de présentation des sous-titres depuis les options de personnalisation mises à disposition par le système d’exploitation, par exemple : la taille des sous-titres, la couleur, le style de bordure des sous-titres, la couleur d’arrière-plan, l’opacité de l’arrière-plan, etc. (Note&nbsp;: la norme ne donne pas la liste précise des paramètres qu’il est obligatoire de pouvoir définir, aussi, la possibilité de modifier une seule caractéristique des sous-titres est suffisante pour rendre le critère conforme).\n3. Vérifier que les paramètres définis sont appliqués aux sous-titres.\n4. Sinon, repérer dans la page la présence d’une fonctionnalité permettant de modifier les paramètres de présentation des sous-titres (dans la page ou directement depuis le lecteur multimédia). \n5. Vérifier que les paramètres définis sont appliqués aux sous-titres.\n6. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '4.17' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.18.1":"1. Repérer les médias temporels synchronisés pré-enregistrés avec des sous-titres de traduction.\n2. Vérifier la présence d’une piste sonore qui serait la version vocalisée des sous-titres de traduction&nbsp;:\n\t1. activer la piste sonore&nbsp;;\n\t2. vérifier que les sous-titres vocalisés correspondent aux sous-titres affichés.\n3. Sinon, vérifier la présence d’une fonctionnalité qui permet de vocaliser des sous-titres&nbsp;:\n\t1. <span lang=\"en\">Text-to-speech</span>. Certains lecteurs multimédia (par exemple <a href=\"https://ableplayer.github.io/ableplayer/\" lang=\"en\">AblePlayer</a> ou <a href=\"https://videojs.com\">VideoJS</a>), offrent la possibilité d’ajouter une piste de description sous forme d’un fichier texte (d’une construction similaire à un fichier de sous-titres avec un [horodatage](#horodatage-time-stamp)) qui peut être synthétisée grâce à l’API <span lang=\"en\">Web Speech</span> des navigateurs (on parle alors de <span lang=\"en\">text-to-speech</span>, ou TTS). En activant cette fonctionnalité, c’est le navigateur qui va lire la description. Cette fonctionnalité peut être utilisée pour fournir une version vocalisée des sous-titres, et serait donc considérée comme une implémentation conforme si elle est correctement documentée pour l’utilisateur. Pour la tester&nbsp;: \n\t\t1. activer la fonctionnalité&nbsp;;\n\t\t2. lancer la lecture du contenu multimédia&nbsp;;\n\t\t3. vérifier que les textes affichés par ce moyen sont vocalisés.\n\t2. Pistes de description. Certains lecteurs multimédias (par exemple, <a href=\"https://ableplayer.github.io/ableplayer/\" lang=\"en\">AblePlayer</a> ou <a href=\"https://player.support.brightcove.com/playback/using-screen-reader-brightcove-player.html\">BrightCove</a>) offrent la possibilité d’intégrer des pistes de description sous forme d’un fichier texte (d’une construction similaire à un fichier de sous-titres avec un [horodatage](#horodatage-time-stamp)) et qui est déclarée dans le code grâce à la balise <code>&lt;track&gt;</code> pourvue de l’attribut <code>kind=\"descriptions\"</code> et dont l’implémentation finale est pourvue des propriétés suffisantes pour permettre leur restitution par les lecteurs d’écran (présence de la propriété <code>aria-live</code> par exemple). Cette fonctionnalité peut être utilisée pour fournir une version des sous-titres qui pourra être vocalisée par les lecteurs d’écran, et serait donc considérée comme une implémentation conforme si elle est correctement documentée pour l’utilisateur. Pour la tester&nbsp;: \n\t\t1. activer la fonctionnalité&nbsp;;\n\t\t2. activer le lecteur d’écran&nbsp;;\n\t\t3. vérifier que les textes affichés par ce moyen sont vocalisés.\n4. Sinon&nbsp;: \n\t1. activer les sous-titres de traduction&nbsp;;\n\t2. activer le lecteur d’écran&nbsp;;\n\t3. vérifier que les sous-titres vocalisés correspondent aux sous-titres affichés.\n5. Sinon&nbsp;:\n\t1. rechercher la présence d’un média alternatif dont la bande son contient les sous-titres de traduction vocalisés&nbsp;;\n\t2. vérifier que les sous-titres vocalisés correspondent aux sous-titres affichés.\n6. Si c’est le cas, le test est validé."}'::jsonb
where identifier = '4.18' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.2.1":"1. Retrouver dans le document les médias temporels pré-enregistrés seulement audio qui possèdent une transcription textuelle.\n2. Pour chaque média temporel seulement audio, vérifier que transcription textuelle est pertinente.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.2.2":"1. Retrouver dans le document les médias temporels pré-enregistrés seulement vidéo qui possèdent une transcription textuelle.\n2. Pour chaque média temporel seulement vidéo, vérifier la pertinence :\n   - soit de la transcription textuelle ;\n   - soit de l’audiodescription synchronisée ;\n   - soit de l’audiodescription synchronisée de la version alternative ;\n   - soit de la version alternative audio seulement.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.2.3":"1. Retrouver dans le document les médias temporels pré-enregistrés synchronisés.\n2. Pour chaque média temporel synchronisé, vérifier la pertinence :\n   - soit de la transcription textuelle ;\n   - soit de l’audiodescription synchronisée ;\n   - soit de l’audiodescription synchronisée de la version alternative.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n"}'::jsonb
where identifier = '4.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.3.1":"1. Retrouver dans le document les médias temporels pré-enregistrés synchronisés.\n2. Pour chaque média temporel synchronisé, vérifier la présence :\n   - soit de sous-titres synchronisés ;\n   - soit d’une version alternative possédant des sous-titres synchronisés accessible au moyen d’un lien ou d’un bouton adjacent.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n","4.3.2":"1. Retrouver dans le document les médias temporels synchronisés pré-enregistrés possédant des sous-titres synchronisés au moyen d’un élément `<track>`.\n2. Pour chaque média temporel synchronisé, vérifier que la balise `<track>` possède un attribut `kind=\"captions\"`.\n3. Si c’est le cas pour chaque média temporel synchronisé pré-enregistré, **le test est validé**.\n","4.3.3":"1. Retrouver dans le document les médias temporels en direct synchronisés.\n2. Pour chaque média temporel synchronisé, vérifier la présence :\n   - soit de sous-titres synchronisés ;\n   - soit d’une version alternative possédant des sous-titres synchronisés accessible au moyen d’un lien ou d’un bouton adjacent.\n3. Si c’est le cas pour chaque média temporel en direct synchronisé, **le test est validé**.\n"}'::jsonb
where identifier = '4.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.4.1":"1. Retrouver dans le document les médias temporels synchronisés pré-enregistrés possédant des sous-titres synchronisés.\n2. Pour chaque média temporel synchronisé pré-enregistrés, vérifier que les sous-titres sont :\n\t- dans la langue de la vidéo (si le contenu oralisé est en anglais, les sous-titres doivent être en anglais) ; \n\t- pertinents (toutes les informations sonores importantes sont présentes, les dialogues notamment) ;\n\t- correctement synchronisés. Si vous n’observez pas de décalage entre le discours oralisé et l’apparition des sous-titres, les sous-titres sont correctement synchronisés. La norme de référence spécifie que les sous-titres doivent apparaître dans les 100&nbsp;ms suivant l’[horodatage du sous-titre](#horodatage-time-stamp).\n3. Si c’est le cas pour chaque média temporel synchronisé, **le test est validé**.\n","4.4.2":"1. Retrouver dans le document les médias temporels synchronisés en direct possédant des sous-titres synchronisés.\n2. Pour chaque média temporel synchronisé en direct, vérifier que les sous-titres sont :\n\t- dans la langue de la vidéo (si le contenu oralisé est en anglais, les sous-titres doivent être en anglais) ; \n\t- pertinents (toutes les informations sonores importantes sont présentes, les dialogues notamment) ;\n\t- correctement synchronisés. Si vous n’observez pas de décalage entre le discours oralisé et l’apparition des sous-titres, les sous-titres sont correctement synchronisés. La norme de référence spécifie que les sous-titres doivent apparaître dans les 100&nbsp;ms suivant l’[horodatage du sous-titre](#horodatage-time-stamp).\n3. Si c’est le cas pour chaque média temporel synchronisé, **le test est validé**."}'::jsonb
where identifier = '4.4' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.5.1":"1. Retrouver dans le document les médias temporels pré-enregistrés seulement vidéo qui nécessitent une audiodescription.\n2. Pour chaque média temporel seulement vidéo, vérifier la présence :\n   - soit d’une audiodescription synchronisée ;\n   - soit d’une version alternative avec une audiodescription synchronisée accessible au moyen d’un bouton ou d’un lien adjacent (une URL ou une ancre).\n3. Si c’est le cas pour chaque média temporel seulement vidéo, **le test est validé**.\n","4.5.2":"1. Retrouver dans le document les médias temporels pré-enregistrés synchronisés qui nécessitent une audiodescription.\n2. Pour chaque média temporel synchronisé, vérifier la présence :\n   - soit d’une audiodescription synchronisée ;\n   - Soit d’une version alternative avec une audiodescription synchronisée accessible au moyen d’un bouton ou d’un lien adjacent (une URL ou une ancre).\n3. Si c’est le cas pour chaque média temporel synchronisé, **le test est validé**.\n"}'::jsonb
where identifier = '4.5' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.6.1":"1. Retrouver dans le document les médias temporels seulement vidéo qui possèdent une audiodescription.\n2. Pour chaque média temporel, vérifier que l’audiodescription synchronisée est pertinente (toutes les informations visuelles qu’il est possible de vocaliser dans les blancs de la bande son principale sont présentes, les textes incrustés notamment).\n3. Si c’est le cas pour chaque média temporel seulement vidéo, **le test est validé**.","4.6.2":"1. Retrouver dans le document les médias temporels synchronisés qui possèdent une audiodescription.\n2. Pour chaque média temporel, vérifier que l’audiodescription synchronisée est pertinente (toutes les informations visuelles qu’il est possible de vocaliser dans les blancs de la bande son principale sont présentes, les textes incrustés notamment).\n3. Si c’est le cas pour chaque média temporel synchronisé, **le test est validé**.\n"}'::jsonb
where identifier = '4.6' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.7.1":"1. Retrouver dans le document les médias temporels pré-enregistrés seulement vidéo, audio ou synchronisés.\n2. Pour chaque média temporel, vérifier qu’un passage de texte (un titre ou un paragraphe, par exemple) qui précède ou suit immédiatement le média temporel permet de l’identifier.\n3. Si c’est le cas pour chaque média temporel, **le test est validé**.\n"}'::jsonb
where identifier = '4.7' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.8.1":"1. Retrouver dans le document les médias non temporels.\n2. Pour chaque média non temporel, vérifier qu’un lien ou un bouton adjacent, clairement identifiable :\n   - soit contient l’adresse (url) d’une page contenant une alternative ;\n   - soit permet d’accéder à une alternative dans la page.\n3. Si c’est le cas pour chaque média non temporel, **le test est validé**.\n","4.8.2":"1. Retrouver dans le document les médias non temporels associés à une alternative.\n2. Pour chaque média non temporel, vérifier que :\n   - la page référencée par le lien ou le bouton adjacent est accessible ;\n   - l’alternative dans la page, référencée par le lien ou le bouton adjacent, est accessible.\n3. Si c’est le cas pour chaque média non temporel, **le test est validé**."}'::jsonb
where identifier = '4.8' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"4.9.1":"1. Retrouver dans le document les médias non temporels associés à une alternative.\n2. Pour chaque média non temporel, vérifier que l’alternative est pertinente (elle permet d’accéder au même contenu et à des fonctionnalités similaires).\n3. Si c’est le cas pour chaque média non temporel, **le test est validé**.\n"}'::jsonb
where identifier = '4.9' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"5.1.1":"1. Retrouver dans le document les tableaux de données complexes (tableau de données - élément `<table>` ou élément pourvu d’un attribut WAI-ARIA `role=\"table\"` - contenant des en-têtes qui ne sont pas répartis uniquement sur la première ligne et/ou la première colonne de la grille ou dont la portée n’est pas valable pour l’ensemble de la colonne ou de la ligne).\n2. Pour chaque tableau de données complexe, vérifier qu’un passage de texte permettant de comprendre la nature et la structure du tableau, est présent :\n   - soit dans l’élément `<caption>` ;\n   - soit dans un passage de texte lié au tableau avec l’attribut `aria-describedby`.\n3. Si c’est le cas pour chaque tableau de données complexe, **le test est validé**.\n"}'::jsonb
where identifier = '5.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"5.2.1":"1. Retrouver dans le document les résumés de tableaux de données complexes (tels que déterminés par le test 5.1.1).\n2. Pour chaque résumé, vérifier que son contenu est pertinent.\n3. Si c’est le cas pour chaque résumé de tableaux de données complexes, **le test est validé**.\n"}'::jsonb
where identifier = '5.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"5.3.1":"1. Retrouver dans le document les tableaux de mise en forme.\n2. Pour chaque tableau de mise en forme, vérifier que :\n   - L’ordre d’accès aux cellules est cohérent avec le contenu.\n   - L’élément `<table>` est pourvu d’un attribut WAI-ARIA `role=\"presentation\"`.\n3. Si c’est le cas pour chaque tableau de mise en forme, **le test est validé**.\n"}'::jsonb
where identifier = '5.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"5.4.1":"1. Retrouver dans le document les tableaux de données pourvus d’un titre.\n2. Pour chaque titre, vérifier qu’il est fourni au moyen :\n   - soit d’un élément `<caption>` ;\n   - soit d’un attribut `title` ;\n   - soit d’un attribut WAI-ARIA `aria-label` ;\n   - soit d’un attribut WAI-ARIA `aria-labelledby` référençant un passage de texte.\n3. Si c’est le cas pour chaque titre de tableau de données, **le test est validé**.\n"}'::jsonb
where identifier = '5.4' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"5.5.1":"1. Retrouver dans le document les tableaux de données pourvus d’un titre.\n2. Pour chaque titre, vérifier qu’il est pertinent.\n3. Si c’est le cas pour chaque titre de tableau de données, **le test est validé**.\n"}'::jsonb
where identifier = '5.5' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"5.6.1":"1. Retrouver dans le document les tableaux de données.\n2. Pour chaque en-tête de colonnes s’appliquant à la totalité de la colonne, vérifier que l’en-tête de colonne est structuré au moyen :\n   - soit d’un élément `<th>` ;\n   - soit d’un élément pourvu d’un attribut WAI-ARIA `role=\"columnheader\"`.\n3. Si c’est le cas pour chaque en-tête de colonne s’appliquant à la totalité de la colonne, **le test est validé**.\n","5.6.2":"1. Retrouver dans le document les tableaux de données.\n2. Pour chaque en-tête de ligne s’appliquant à la totalité de la ligne, vérifier que l’en-tête de ligne est structuré au moyen :\n   - soit d’un élément `<th>` ;\n   - soit d’un élément pourvu d’un attribut WAI-ARIA `role=\"rowheader\"`.\n3. Si c’est le cas pour chaque en-tête de ligne s’appliquant à la totalité de la ligne, **le test est validé**.\n","5.6.3":"1. Retrouver dans le document les tableaux de données.\n2. Pour chaque en-tête ne s’appliquant pas à la totalité de la ligne ou de la colonne, vérifier que l’en-tête de ligne est structuré au moyen d’un élément `<th>`.\n3. Si c’est le cas pour chaque en-tête ne s’appliquant pas à la totalité de la ligne ou de la colonne, **le test est validé**.\n","5.6.4":"1. Retrouver dans le document les tableaux de données.\n2. Pour chaque cellule associée à plusieurs en-têtes est-elle structurée au moyen d’une balise `<th>` ou `<td>`.\n3. Si c’est le cas pour chaque en-tête ne s’appliquant pas à la totalité de la ligne ou de la colonne, **le test est validé**.\n"}'::jsonb
where identifier = '5.6' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"5.7.1":"1. Retrouver dans le document les tableaux de données.\n2. Pour chaque en-tête (élément `<th>`) s’appliquant à la totalité de la ligne ou de la colonne, vérifier que l’élément `<th>` possède :\n   - soit un attribut `id` unique ;\n   - soit un attribut scope ;\n   - soit un attribut WAI-ARIA `role=\"rowheader\"` ou `role=\"columnheader\"`.\n3. Si c’est le cas pour chaque en-tête s’appliquant à la totalité de la ligne ou de la colonne, **le test est validé**.\n","5.7.2":"1. Retrouver dans le document les tableaux de données.\n2. Pour chaque en-tête (élément `<th>`) s’appliquant à la totalité de la ligne ou de la colonne et pourvu d’un attribut `scope`, vérifier que l’attribut `scope` possède :\n   - soit une valeur `row` pour les en-têtes de ligne ;\n   - soit une valeur `col` pour les en-têtes de colonne.\n3. Si c’est le cas pour chaque en-tête s’appliquant à la totalité de la ligne ou de la colonne et pourvu d’un attribut `scope`, **le test est validé**.\n","5.7.3":"1. Retrouver dans le document les tableaux de données.\n2. Pour chaque en-tête (élément `<th>`) ne s’appliquant pas à la totalité de la ligne ou de la colonne, vérifier que l’élément `<th>` :\n   - possède un attribut `id` unique ;\n   - ne possède pas d’attribut `scope ` ;\n   - ne possède pas d’attribut WAI-ARIA `role=\"rowheader\"` ou  `role=\"columnheader\"`.\n3. Si c’est le cas pour chaque en-tête ne s’appliquant pas à la totalité de la ligne ou de la colonne, **le test est validé**.\n","5.7.4":"1. Retrouver dans le document les tableaux de données.\n2. Pour chaque élément `<td>` ou `<th>` associé à un ou plusieurs en-têtes possédant un attribut `id`, vérifier que :\n   - l’élément `<td>` ou `<th>` possède un attribut `headers` ;\n   - l’attribut `headers` possède la liste des valeurs d’attribut `id` des en-têtes associés.\n3. Si c’est le cas pour chaque élément `<td>` ou `<th>` associé à un ou plusieurs en-têtes possédant un attribut `id`, **le test est validé**.\n","5.7.5":"1. Retrouver dans le document les tableaux de données.\n2. Pour chaque en-tête s’appliquant à la totalité de la ligne ou de la colonne et pourvu d’un attribut WAI-ARIA `role=\"rowheader\"` ou `columnheader`, vérifier que l’élément possède :\n   - soit un attribut WAI-ARIA `role=\"rowheader\"` pour les en-têtes de ligne ;\n   - soit un attribut WAI-ARIA `role=\"columnheader\"` pour les en-têtes de colonne.\n3. Si c’est le cas pour chaque en-tête s’appliquant à la totalité de la ligne ou de la colonne et pourvu d’un attribut WAI-ARIA `role=\"rowheader\"` ou  `role=\"columnheader\"`., **le test est validé**.\n","5.7.6":"1. Retrouver dans le document les tableaux de données.\n2. Pour chaque en-tête (élément `<th>`) s’appliquant à un groupe de lignes ou à un groupe de colonnes et pourvu d’un attribut `scope`, vérifier que l’attribut `scope` possède :\n    - soit une valeur `rowgroup` pour les groupes d’en-têtes de ligne ;\n    - soit une valeur `colgroup` pour les groupes d’en-têtes de colonne.\n3. Si c’est le cas pour chaque en-tête s’appliquant à un groupe de lignes ou à un groupe de colonnes et pourvu d’un attribut `scope`, **le test est validé**.\n"}'::jsonb
where identifier = '5.7' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"5.8.1":"1. Retrouver dans le document les tableaux de mise en forme.\n2. Pour chaque tableau de mise en forme, vérifier que :\n   - L’élément `<table>` ne possède pas d’attribut `summary`, d’éléments enfant `<caption>`, `<thead>`, `<th>`, `<tfoot>` ou d’éléments pourvus d’un attribut WAI-ARIA `role=\"rowheader\"` ou `role=\"columnheader\"`.\n   - Les éléments `<td>` ne possèdent pas d’attributs `scope`, `headers` et `axis`.\n3. Si c’est le cas pour chaque tableau de mise en forme, **le test est validé**.\n"}'::jsonb
where identifier = '5.8' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"6.1.1":"1. Retrouver dans le document les liens texte.\n2. Pour chaque lien texte, vérifier que ce qui permet d’en comprendre la fonction et la destination est :\n   - soit l’intitulé du lien seul ;\n   - soit le contexte du lien.\n3. Si c’est le cas pour chaque lien texte, **le test est validé**.","6.1.2":"1. Retrouver dans le document les liens image (lien avec pour contenu un élément `<img>` ou un élément ayant l’attribut WAI-ARIA `role=\"img\"`, un élément `<area>` possédant un attribut `href`, un élément `<object>`, un élément `<canvas>` ou un élément `<svg>`).\n2. Pour chaque lien image, vérifier que ce qui permet d’en comprendre la fonction et la destination est :\n   - soit l’intitulé du lien seul, fourni par l’alternative textuelle de l’image ;\n   - soit le contexte du lien.\n3. Si c’est le cas pour chaque lien image, **le test est validé**.\n","6.1.3":"1. Retrouver dans le document les liens composites (lien composé à la fois de contenu texte et d’éléments de type image).\n2. Pour chaque lien composite, vérifier que ce qui permet d’en comprendre la fonction et la destination est :\n   - soit l’intitulé du lien seul, fourni par la combinaison du contenu texte et de l’alternative textuelle de l’image ;\n   - soit le contexte du lien.\n3. Si c’est le cas pour chaque lien composite, **le test est validé**.\n","6.1.4":"1. Retrouver dans le document les liens SVG (élément `<svg>` qui possède un élément `<a>` pourvu d’un attribut `xlink-href` (SVG 1.1) ou `href` (SVG 2)).\n2. Pour chaque lien SVG, vérifier que ce qui permet d’en comprendre la fonction et la destination est :\n   - soit l’intitulé du lien seul, fourni par le nom accessible de l’élément `<svg>` (résolu généralement à partir du contenu d’un élément `<text>`) ;\n   - soit le contexte du lien.\n3. Si c’est le cas pour chaque lien SVG, **le test est validé**.\n","6.1.5":"1. Retrouver dans le document les liens autres que SVG dont le contenu est fourni à la fois par un intitulé visible et par le contenu soit d’un attribut title ou d’un attribut `aria-label` ou d’un attribut `aria-labelledby`.\n2. Pour chaque lien, vérifier que le contenu de l’attribut `title` ou de l’attribut `aria-label` ou de l’attribut `aria-labelledby` contient l’intitulé visible.\n3. Si c’est le cas pour chaque lien, **le test est validé** pour les liens autres que SVG.\n4. Retrouver dans le document les liens SVG dont le contenu est fourni à la fois par un intitulé visible et par le contenu soit d’un attribut `aria-labelledby`, ou d’un attribut `aria-label` ou d’un élément title (enfant direct de l’élément `<svg>`) ou d’un attribut x-link:title (SVG 1.1) ou d’un ou plusieurs éléments `<text>`.\n5. Pour chaque lien SVG, vérifier que le contenu de l’attribut `aria-labelledby` ou de l’attribut `aria-label` ou de l’élément `<title>` ou de l’attribut `x-link:title` ou d’un ou plusieurs éléments `<text>` contient l’intitulé visible.\n6. Si c’est le cas pour chaque lien SVG, **le test est validé** pour les liens SVG.\n7. Si le test est validé à la fois pour les liens non SVG et pour les liens SVG, le test est globalement validé.","6.1.6":"1. Retrouver dans le document les liens qui ont un intitulé identique.\n2. Pour les liens identiques, vérifier qu’ils mènent tous vers la même destination ou vers un contenu similaire.\n3. Sinon, vérifier que le contexte de chacun des liens permet de les distinguer.\n4. Si c’est le cas, **le test est validé**."}'::jsonb
where identifier = '6.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"6.2.1":"1. Retrouver dans le document les liens, quels qu’ils soient.\n2. Pour chaque lien, vérifier la présence d’un intitulé de lien.\n3. Si c’est le cas pour chaque lien, **le test est validé**."}'::jsonb
where identifier = '6.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"7.1.1":"1. Retrouver dans le document tous les composants d’interface générés ou contrôlés au moyen de JavaScript.\n2. Vérifier que :\n   - Le composant possède un rôle cohérent avec son usage (généralement un bouton ou un lien).\n   - Le composant possède un nom explicite.\n   - Le nom du composant est cohérent avec l’état de la fonctionnalité ou des contenus contrôlés (par exemple pour une fonctionnalité permettant d’afficher ou de masquer une zone de contenu).\n3. Sinon, vérifier la présence d’un composant d’interface accessible permettant d’accéder aux mêmes fonctionnalités.\n4. Sinon, vérifier la présence d’une alternative accessible permettant d’accéder aux mêmes fonctionnalités.\n5. Si c’est le cas, **le test est validé**.\n","7.1.2":"1. Pour chacun des composants d’interface ayant validé le test 7.1.1, vérifier que le composant d’interface est correctement restitué par les technologies d’assistance.\n2. Sinon, vérifier qu’une alternative accessible au composant d’interface permet d’accéder aux mêmes fonctionnalités.\n3. Si c’est le cas, **le test est validé**.\n","7.1.3":"1. Pour chacun des composants d’interface ayant validé le test 7.1.1, vérifier que le composant d’interface possède :\n   - un nom pertinent ;\n   - un rôle pertinent.\n2. Si le composant d’interface possède un nom accessible, vérifier que ce nom est pertinent et contient au moins l’intitulé visible.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '7.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"7.2.1":"1. Retrouver les alternatives aux fonctionnalités JavaScript :\n2. Chercher dans la page, les alternatives à un composant ou une fonctionnalité JavaScript mises à disposition.\n3. Désactiver JavaScript dans le document et retrouver les alternatives proposées.\n4. Pour chacune des alternatives proposées, vérifier qu’elle permet d’accéder aux mêmes contenus et à des fonctionnalités similaires.\n5. Si c’est le cas, **le test est validé**.\n","7.2.2":"1. Retrouver dans le document tous les éléments non textuels mis à jour par une fonctionnalité JavaScript.\n2. Si l’élément non textuel a une alternative, vérifier que :\n   - l’alternative est mise à jour lorsque le contenu non textuel est mis à jour ;\n   - l’alternative mise à jour est pertinente.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '7.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"7.3.1":"1. Retrouver dans le document, tous les éléments sur lesquels est implémenté un gestionnaire d’événements JavaScript (par exemple click, focus, mouseover, blur, keydown, touch…).\n2. Vérifier que l’élément est accessible au moyen du clavier :\n   - Il est atteignable avec la touche de tabulation (<kbd>tab</kbd>).\n   - Si l’élément gère une action simple, il est activable au clavier avec la ou les touches prévues par défaut dans les agents utilisateurs (par exemple <kbd>Entrée</kbd>, <kbd>Espace</kbd>).\n   - Si l’élément gère une action complexe, il est utilisable avec le clavier (généralement avec les touches de direction).\n3. Sinon, vérifier qu’un élément accessible par le clavier permettant de réaliser la même action est présent dans la page.\n4. Vérifier que l’élément est accessible par tout dispositif de pointage (souris, toucher, stylet…).\n5. Sinon, vérifier qu’un élément accessible au moyen d’un dispositif de pointage et permettant de réaliser la même action est présent dans la page.\n6. Si c’est le cas, **le test est validé**.\n","7.3.2":"1. Activer, l’un après l’autre, tous les éléments capables de recevoir le focus.\n2. Vérifier que le focus n’est pas supprimé via une fonctionnalité JavaScript.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '7.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"7.4.1":"1. Retrouver dans le document tous les événements JavaScript qui initient un changement de contexte, par exemple :\n   - une mise à jour dynamique de champs de formulaire ;\n   - l’ouverture d’une nouvelle page à l’activation d’une option d’une liste de sélection (élément `<select>`) ;\n   - la mise à jour, via un procédé AJAX d’une partie essentielle de la page ;\n   - le lancement automatique d’un lecteur vidéo suite à la sélection d’une playlist ;\n   - la manipulation du focus ayant pour résultat de modifier la position courante de l’utilisateur dans la page.\n2. Vérifier que :\n   - l’utilisateur est averti par un message de l’action du script et du type de changement avant son déclenchement ;\n   - ou bien le changement de contexte est initié par un bouton (input de type submit, button ou image ou la balise button) explicite ;\n   - ou bien le changement de contexte est initié par un lien explicite.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '7.4' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"7.5.1":"1. Retrouver dans le document les messages qui valent pour message de statut.\n2. Pour chacun de ces messages, déterminer la nature de l’information dont est porteur le message :\n3. Si le message informe de la réussite, du résultat d’une action ou bien de l’état d’une application, vérifier que l’élément qui contient le message :\n   - soit utilise l’attribut WAI-ARIA `role=\"status\"` ;\n   - soit utilise les attributs WAI-ARIA `aria-live=\"polite\"` et `aria-atomic=\"true\"`.\n4. Si le message présente une suggestion, ou avertit de l’existence d’une erreur, vérifier que l’élément qui contient le message :\n   - soit utilise l’attribut WAI-ARIA `role=\"alert\"` ;\n   - soit utilise les attributs `aria-live=\"assertive\"` et `aria-atomic=\"true\"`.\n5. Si le message indique la progression d’un processus, vérifier que l’élément qui contient le message :\n   - soit utilise l’un des attributs WAI-ARIA `role=\"log\"`, `role=\"progressbar\"` ou `role=\"status\"` ;\n   - soit utilise l’attribut WAI-ARIA `aria-live=\"polite\"` si l’intention est de signaler l’équivalent d’un `rôle \"log\"` ;\n   - soit utilise les attributs WAI-ARIA `aria-live=\"polite\"` et `aria-atomic=\"true\"` si l’intention est de signaler l’équivalent d’un rôle `\"status\"`.\n6. Si c’est le cas, **le test est validé**.\n","7.5.2":"Tests identiques à 7.5.1\n","7.5.3":"Tests identiques à 7.5.1\n"}'::jsonb
where identifier = '7.5' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"8.1.1":""}'::jsonb
where identifier = '8.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"8.10.1":"1. Retrouver dans le document les passages de textes qui utilisent une langue qui se lit dans le sens inverse de la langue du document (comme l’arabe ou l’hébreu pour le français par exemple).\n2. Pour chaque passage de texte, vérifier que le passage de texte est contenu dans une balise qui possède un attribut `dir`.\n3. Si c’est le cas pour chaque passage de texte, **le test est validé**.\n","8.10.2":"1. Pour chaque passage de texte validé au test 8.10.1, vérifier que :\n   - L’indication de sens de lecture est conforme (ltr, pour le sens « de gauche à droite » et rtl pour le sens « de droite à gauche »)\n   - L’indication de sens de lecture est pertinente.\n2. Si c’est le cas pour chaque passage de texte, **le test est validé**.\n"}'::jsonb
where identifier = '8.10' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"8.2.1":""}'::jsonb
where identifier = '8.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"8.3.1":"1. Retrouver dans le document l’indication de langue par défaut.\n2. Vérifier la présence d’une indication de langue :\n   - soit au moyen de l’attribut lang sur la balise html si le code est du HTML5 ou du HTML4 ;\n   - soit au moyen des attributs lang et xml:lang sur la balise html si le code est du XHTML 1.0 ;\n   - soit au moyen de l’attribut xml:lang sur la balise html si le code est du XHTML 1.1 ;\n   - Sinon, vérifier la présence d’une indication de langue sur chaque élément de texte ou l’un de ses parents.\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '8.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"8.4.1":"1. Retrouver dans le document l’indication de langue par défaut.\n2. Vérifier la présence d’un code de langue :\n   - valide (conforme à la norme ISO 639-1 ou ISO 639-2 et suivantes) ;\n   - pertinent (qui indique la langue principale du document).\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '8.4' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"8.5.1":"1. Retrouver dans le document le titre structuré au moyen d’un élément `<title>`.\n2. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '8.5' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"8.6.1":"1. Retrouver dans le document le titre structuré au moyen d’un élément `<title>`.\n2. Vérifier si le contenu de l’élément `<title>` est suffisamment pertinent (il permet de retrouver la page dans l’historique de navigation ou la liste des onglets).\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '8.6' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"8.7.1":"1. Retrouver les passages de texte en langue étrangère, à l’exception :\n   - des noms propres ;\n   - des mots d’origine étrangère, présents dans le dictionnaire de la langue du document ;\n   - des mots d’origine étrangère et d’usage courant dont la prononciation ne provoque pas d’incompréhension.\n2. Vérifier que chaque passage de texte retenu possède une indication de langue (attribut `lang` et/ou `xml:lang` sur l’élément lui-même ou l’un de ses parents).\n3. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '8.7' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"8.8.1":"1. Pour chaque passage de texte validé au test 8.7.1, vérifier que :\n   - L’indication de langue est valide.\n   - L’indication de langue est pertinente.\n2. Si c’est le cas, **le test est validé**.\n"}'::jsonb
where identifier = '8.8' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"8.9.1":"1. Retrouver dans le document l’ensemble des éléments sémantiques utilisés à des fins de présentation\n2. Pour chacun de ces éléments, vérifier que :\n   - L’élément est pourvu d’un attribut `role=\"presentation\"`.\n   - L’utilisation de cet élément à des fins de présentation reste justifiée.\n3. Si c’est le cas, **le test est validé**.\n\nNote : Quelques exemples, non exhaustifs de détournement de balisage : un élément `<div>` utilisé comme paragraphe, un titre utilisé comme légende, un élément `<blockquote>` ou des paragraphes vides ou encore des espaces utilisés pour créer des effets de marges.\nL’utilisation d’un `role=\"presentation\"` est formellement déconseillée, mais peut toutefois se justifier dans de rares cas. Cela peut être acceptable sur un élément `<blockquote>` ou un paragraphe vide, mais sera considéré comme non-conforme sur un titre.\n\nLe cas des tableaux : à noter que ce test aborde les tableaux de présentation qui ne devraient finalement pas apparaître au sein de la thématique Tableaux.\n"}'::jsonb
where identifier = '8.9' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"9.1.1":"1. Retrouver dans le document les titres (balise `<hx>` ou balise possédant un attribut WAI-ARIA `role=\"heading\"` associé à un attribut WAI-ARIA `aria-level`).\n2. Vérifier que la hiérarchie entre les titres est pertinente.\n3. Si c’est le cas, **le test est validé**.\n","9.1.2":"1. Pour chaque titre identifié au test 9.1.1, vérifier que son contenu est pertinent.\n2. Si c’est le cas pour chaque titre, **le test est validé**.\n","9.1.3":"1. Pour chaque passage de texte constituant un titre, vérifier que :\n   - soit il est structuré au moyen d’une balise `<hx>` (“x” désignant une valeur numérique comprise entre 1 et 6) ;\n   - soit il est structuré au moyen d’une balise possédant un attribut WAI-ARIA `role=\"heading\"` et un attribut WAI-ARIA `aria-level=x` (“x” désignant une valeur numérique).\n2. Si c’est le cas pour chaque titre, **le test est validé**.\n"}'::jsonb
where identifier = '9.1' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"9.2.1":"1. Vérifier que la zone d’en-tête est structurée au moyen d’un élément `<header>` ou qu’elle est pourvue d’un attribut WAI-ARIA `role=\"banner\"`.\n2. Vérifier que les zones de navigation principales et secondaires sont structurées au moyen d’un élément `<nav>` ou qu’elles sont pourvues d’un attribut WAI-ARIA `role=\"navigation\"`.\n3. Vérifier que la zone de moteur de recherche est structurée au moyen d’un élément `<search>` ou qu’elle est pourvue d’un attribut WAI-ARIA `role=\"search\"`.\n4. Vérifier que la zone de contenu principal est structurée au moyen d’un élément `<main>` ou qu’elle est pourvue d’un attribut WAI-ARIA `role=\"main\"`.\n5. Vérifier que la zone de pied de page est structurée au moyen d’un élément `<footer>` ou qu’elle est pourvue d’un attribut WAI-ARIA `role=\"contentinfo\"`.\n6. Si c’est le cas pour chaque zone de contenu, **le test est validé**.\n","9.2.2":"1. Vérifier que les éléments qui ont un rôle calculé de `navigation` ne sont pas utilisés pour structurer des zones qui ont une fonction différente que navigation principale ou secondaire.\n2. Si le document possède plusieurs éléments qui ont le rôle calculé de `main`, vérifier qu’un seul de ces éléments est visible (les autres occurrences sont pourvues d’un attribut `hidden` par exemple).\n3. Si le document possède plusieurs éléments qui ont le rôle calculé de `banner`, vérifier qu’un seul de ces éléments est visible (les autres occurrences sont pourvues d’un attribut `hidden` par exemple).\n4. Si le document possède plusieurs éléments qui ont le rôle calculé de `contentinfo`, vérifier qu’un seul de ces éléments est visible (les autres occurrences sont pourvues d’un attribut `hidden` par exemple).\n5. Si c’est le cas, **le test est validé**.\n","9.2.3":"1. Vérifier que l’élément `<header>` dépourvu de l’attribut WAI-ARIA `role`, utilisé pour structurer la zone d’en-tête de la page, est imbriqué dans un élément ayant un rôle calculé différent de : \n    * `article`\n    * `complementary`\n    * `main`\n    * `navigation`\n    * `section`\n2. Si c’est le cas, **le test est validé**.\n","9.2.4":"1. Vérifier que l’élément `<footer>` dépourvu de l’attribut WAI-ARIA `role`, utilisé pour structurer la zone de pied de la page, est imbriqué dans un élément ayant un rôle calculé différent de : \n    * `article`\n    * `complementary`\n    * `main`\n    * `navigation`\n    * `section`\n2. Si c’est le cas, **le test est validé**."}'::jsonb
where identifier = '9.2' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"9.3.1":"1. Retrouver dans le document les éléments regroupés visuellement sous la forme d’une liste non ordonnée.\n2. Pour chaque liste, vérifier que la liste est structurée :\n   - soit au moyen des éléments `<ul>` et `<li>` ;\n   - soit au moyen d’éléments pourvus d’attributs WAI-ARIA `role=\"list\"` et `role=\"listitem\"`.\n3. Si c’est le cas pour chaque liste non ordonnée, **le test est validé**.\n","9.3.2":"1. Retrouver dans le document les éléments regroupés visuellement sous la forme d’une liste ordonnée.\n2. Pour chaque liste, vérifier que la liste est structurée :\n   - soit au moyen des éléments `<ol>` et `<li>` ;\n   - soit au moyen d’éléments pourvus d’attributs WAI-ARIA `role=\"list\"` et `role=\"listitem\"`.\n3. Si c’est le cas pour chaque liste ordonnée, **le test est validé**.\n","9.3.3":"1. Retrouver dans le document les éléments regroupés visuellement sous la forme d’une liste de description.\n2. Pour chaque liste, vérifier que la liste est structurée au moyen des éléments `<dl>`, `<dt>` et `<dd>`.\n3. Si c’est le cas pour chaque liste de description, **le test est validé**.\n"}'::jsonb
where identifier = '9.3' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

update public.criteria set test_procedures = '{"9.4.1":"1. Retrouver dans le document les citations courtes (ou en ligne).\n2. Pour chaque citation, vérifier que la citation est structurée au moyen d’un élément `<q>`.\n3. Si c’est le cas pour chaque citation courte, **le test est validé**.\n","9.4.2":"1. Retrouver dans le document les blocs de citation.\n2. Pour chaque bloc de citation, vérifier que le bloc de citation est structuré au moyen d’un élément `<blockquote>`.\n3. Si c’est le cas pour chaque bloc de citation, **le test est validé**.\n"}'::jsonb
where identifier = '9.4' and thematic_id in (select id from public.thematics where reference_id = '44444444-4444-4444-4444-444444444444');

-- ============================================================================
-- RAAM 1.1
-- ============================================================================

update public.criteria set test_procedures = '{"1.1":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Repérer dans l’écran les éléments graphiques décoratifs ([voir la note de glossaire concernant les particularités de restitution](glossaire.md#element-graphique)).\n3.  Vérifier :\n    *   qu’ils ne peuvent pas être atteints avec le lecteur d’écran ;\n    *   que leur contenu n’est pas restitué par ailleurs depuis un autre élément dans l’écran.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '1.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"1.2":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Repérer dans l’écran les éléments graphiques porteurs d’informations ([voir la note de glossaire concernant les particularités de restitution](glossaire.md#element-graphique)), par exemple, une image ou une icône.\n3.  Vérifier :\n    *   qu’ils peuvent être atteints avec le lecteur d’écran ;\n    *   ou que l’information qu’ils véhiculent est restituée depuis un autre élément dans l’écran.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '1.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"1.3":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Repérer dans l’écran les éléments graphiques porteurs d’information ([voir la note de glossaire concernant les particularités de restitution](glossaire.md#element-graphique)).\n3.  Vérifier :\n    *   que l’alternative restituée par le lecteur d’écran est pertinente ;\n    *   ou que l’information restituée depuis un autre élément dans l’écran est pertinente.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '1.3' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"1.4":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Repérer dans l’écran les éléments graphiques utilisés comme CAPTCHA ([voir la note de glossaire concernant les particularités de restitution](glossaire.md#element-graphique)).\n3.  Vérifier que l’alternative restituée par le lecteur d’écran permet de comprendre la fonction de l’élément graphique (par exemple « Code secret à saisir », « Code de sécurité »).\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '1.4' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"1.5":"###### iOS et Android\n1.  Repérer dans l’écran les éléments graphiques utilisés comme CAPTCHA ([voir la note de glossaire concernant les particularités de restitution](glossaire.md#element-graphique)).\n2.  Vérifier :\n    *   la présence d’une alternative non graphique (CAPTCHA sonore ou logique) ;\n    *   ou la présence d’une autre solution d’accès à la fonctionnalité sécurisée par le CAPTCHA (envoi d’un code sms, envoi d’un e-mail de confirmation, etc.).\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '1.5' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"1.6":"###### iOS et Android\n1.  Repérer dans l’écran les éléments graphiques porteurs d’information qui nécessitent une description détaillée ([voir la note de glossaire concernant les particularités de restitution](glossaire.md#element-graphique)). Par exemple :\n    *   éléments graphiques pour lesquels l’alternative à fournir est trop longue (plus d’une phrase par exemple) ou nécessite une structuration (titres, listes ou tableau) ;\n    *   éléments graphiques qui cumulent plusieurs problématiques (information par la couleur, élément graphique texte, contrastes, etc.) comme les graphiques ou les cartes.\n2.  Vérifier :\n    *   la présence d’une description détaillée clairement identifiable adjacente à l’élément graphique ;\n    *   ou la présence d’une fonctionnalité (un bouton, un lien) permettant d’accéder à une description détaillée.\n3.  Sinon, activer le **lecteur d’écran** et naviguer jusqu’à l’élément graphique.\n4.  Vérifier que le lecteur d’écran restitue une description détaillée.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '1.6' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"1.7":"###### iOS et Android\n1.  Repérer dans l’écran les éléments graphiques qui possèdent une description détaillée.\n2.  Vérifier que chaque description détaillée est pertinente. On doit y trouver toutes les informations présentes dans l’élément graphique et nécessaires à la compréhension du contenu.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '1.7' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"1.8":"###### iOS et Android\n1.  Repérer dans l’écran les éléments graphiques texte porteurs d’information ([voir la note de glossaire concernant les particularités de restitution](glossaire.md#element-graphique)) :\n    *   Activer le **lecteur d’écran**, parcourir le contenu et repérer si les éléments restitués « élément graphique » ou « image » contiennent du texte porteur d’information.\n2.  Vérifier :\n    *   qu’il existe un mécanisme de remplacement des éléments graphiques texte par du texte modifiable selon les préférences d’affichage de l’utilisateur (taille, couleur, graisse…) ;\n    *   ou que les styles et effets ne peuvent pas être reproduits via du [texte stylé](glossaire.md#texte-style).\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '1.8' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"1.9":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Naviguer jusqu’aux éléments graphiques légendés.\n3.  Vérifier que la légende de l’élément graphique est restituée lorsque le focus atteint l’élément graphique (l’élément graphique et la légende sont contenus dans un seul élément atteignable par le lecteur d’écran).\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '1.9' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"10.1":"###### iOS et Android\n1.  Connecter un **clavier externe** (et [paramétrer la navigation au clavier](methodologie.md#clavier-externe)).\n2.  Naviguer sur l’ensemble des éléments de l’écran et vérifier que l’ordre de tabulation reste cohérent. Il n’est pas obligatoire que la tabulation suive l’ordre de lecture naturel (de gauche à droite et de haut en bas par exemple) tant que les éléments sont accessibles dans un ordre cohérent.\n3.  Repérer dans l’écran les composants (bouton par exemple) qui mettent à jour un contenu (affichage d’élément masqué, mise à jour dynamique de contenus par exemple) :\n    1.  activer le composant ;\n    2.  après l’affichage du contenu mis à jour, vérifier que la tabulation reste cohérente.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '10.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"10.2":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Naviguer sur l’ensemble des éléments de l’écran avec les gestes du lecteur d’écran et vérifier que l’ordre d’accès aux éléments de l’écran (composants interactifs et textes) reste cohérent. Il n’est pas obligatoire que l’ordre suive l’ordre de lecture naturel (de gauche à droite et de haut en bas par exemple) tant que les éléments sont accessibles dans un ordre cohérent qui ne pose pas de problèmes de compréhension.\n3.  Repérer dans l’écran les composants (bouton par exemple) qui mettent à jour un contenu (affichage d’élément masqué, mise à jour dynamique de contenus par exemple) :\n    1.  activer le composant ;\n    2.  après l’affichage du contenu mis à jour, vérifier que le parcours du lecteur d’écran reste cohérent.\n4.  Si c’est le cas, le critère est validé.\n**Exemple de contenu dont l’implémentation pose un problème de compréhension :** une heure d’arrivée et une heure de départ sont affichées à l’écran sous forme de deux blocs d’informations visuelles (heure d’arrivée 17h00 ; heure de départ 18h00). Le lecteur d’écran atteint séquentiellement « heure d’arrivée » puis « heure de départ » puis « 17h00 » et enfin « 18h00 ». L’ordre de lecture ne correspond pas à l’ordre visuel, et l’ordre de lecture est problématique puisqu’il ne permet pas de lier les informations entre elles."}'::jsonb
where identifier = '10.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"10.3":"###### iOS\n1.  Connecter un **clavier externe** (et [paramétrer la navigation au clavier](methodologie.md#clavier-externe)).\n2.  Naviguer sur l’ensemble des éléments de l’écran en utilisant les touches du clavier dédiées (par défaut dans iOS, ce sont les touches Tab et les flèches de direction qui sont utilisées pour naviguer dans les contenus).\n3.  Vérifier que :\n    *   à partir de la position courante, l’élément focusable suivant ou précédent est atteignable avec les touches de navigation du clavier ;\n    *   l’élément possédant actuellement le focus propose une méthode utilisable au clavier (par exemple, un raccourci clavier) permettant d’atteindre l’élément suivant ou précédent.\n4.  Si c’est le cas, le critère est validé.\n**Note :** Certains éléments complexes, souvent gérés par la plateforme, peuvent faire appel à des navigations optimisées qui utilisent généralement les flèches de direction pour passer d’une partie du composant à l’autre. Le test sur le piège au clavier se limite alors à vérifier que le composant peut être atteint et qu’il est possible de passer au composant suivant ou revenir au composant précédent. On ne vérifie pas l’utilisation même du composant dans ce critère.\n###### Android\n1.  Connecter un **clavier externe** (et [paramétrer la navigation au clavier](methodologie.md#clavier-externe)).\n2.  Naviguer sur l’ensemble des éléments de l’écran en utilisant les touches du clavier (les touches ou la combinaison de touches qui aura été associée dans _Switch Access_{lang=en} pour les paramètres « Passer à l’option suivante » et « Passer à l’option précédente »).\n3.  Vérifier que :\n    *   à partir de la position courante, l’élément focusable suivant ou précédent est atteignable avec la touche de navigation du clavier ;\n    *   l’élément possédant actuellement le focus propose une méthode utilisable au clavier (par exemple, un raccourci clavier) permettant d’atteindre l’élément suivant ou précédent.\n4.  Si c’est le cas, le critère est validé.\n**Note :** Certains éléments complexes, souvent gérés par la plateforme, peuvent faire appel à des navigations optimisées qui utilisent généralement les flèches de direction pour passer d’une partie du composant à l’autre. Le test sur le piège au clavier se limite alors à vérifier que le composant peut être atteint et qu’il est possible de passer au composant suivant ou revenir au composant précédent. On ne vérifie pas l’utilisation même du composant dans ce critère."}'::jsonb
where identifier = '10.3' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"10.4":"###### iOS et Android\n1.  Connecter un **clavier externe** (et [paramétrer la navigation au clavier](methodologie.md#clavier-externe)).\n2.  Depuis l’application, appuyer successivement sur chacune des touches de caractère imprimable (les lettres minuscules a-z, les majuscules A-Z, les chiffres 0-9, tous les symboles comme $, \\*, %, ! etc. à partir du moment où ils peuvent être inscrits à l’écran).\n3.  Si le raccourci clavier est associé à un seul composant isolé de l’écran, vérifier qu’il ne peut être activé que si le focus clavier est à l’intérieur de ce composant.\n4.  Sinon, si une action est déclenchée, vérifier la présence dans l’application d’un élément de configuration permettant :\n    *   de désactiver ces raccourcis clavier à touche unique ;\n    *   de configurer ces raccourcis clavier en leur ajoutant une touche de modification Ctrl, Alt, Maj, etc.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '10.4' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.1":"###### iOS et Android\n1.  Repérer les procédés limitant le temps d’une session (par exemple après une authentification).\n2.  Vérifier :\n    *   la présence d’un mécanisme permettant à l’utilisateur de supprimer la limite de temps (par exemple, un bouton à bascule permettant à l’utilisateur d’activer ou désactiver la limite de temps de la session) ;\n    *   ou la présence d’un mécanisme permettant à l’utilisateur d’augmenter la limite de temps (par exemple, une liste déroulante avec des valeurs de temps de connexion disponibles) ;\n    *   ou la présence d’un mécanisme qui avertit l’utilisateur de l’imminence de la limite de temps et laisse 20 secondes, au moins, à l’utilisateur pour augmenter la limite de temps (par exemple, l’ouverture d’une modale avec un bouton permettant d’augmenter la limite de temps) ;\n    *   ou que la limite de temps est de vingt heures, au moins.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '11.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.10":"###### iOS et Android\n1.  Repérer dans l’écran les fonctionnalités qui nécessitent de réaliser des gestes complexes (repérer la présence de consignes dans l’interface ou dans une documentation associée à l’application), par exemple :\n    *   l’utilisation simultanée de deux doigts ou plus ;\n    *   la réalisation d’un tracé de trajectoire (comme le geste _swipe_{lang=en}).\n2.  Vérifier qu’il existe une méthode alternative pour réaliser l’action associée avec un geste simple, par exemple l’appui sur une seule touche du clavier ou un bouton.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '11.10' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.11":"###### iOS et Android\n1.  Repérer dans l’écran les fonctionnalités qui nécessitent la réalisation de deux actions simultanées, par exemple :\n    *   l’utilisation simultanée de deux touches d’un clavier ou plus ;\n    *   devoir énoncer une commande vocale et toucher l’écran en même temps pour réaliser une action.\n2.  Vérifier qu’il existe dans l’écran ou l’application une méthode alternative pour réaliser l’action associée avec une action unique, par exemple l’appui sur un bouton.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '11.11' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.12":"###### iOS et Android\n1.  Repérer dans l’écran les composants interactifs (par exemple, bouton ou lien).\n2.  Pour chaque composant interactif, effectuer un appui simple dessus et conserver la pression.\n3.  Déplacer le doigt en dehors de la zone interactive et constater que l’action associée n’est pas déclenchée.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '11.12' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.13":"###### iOS et Android\n1.  Repérer dans l’écran les fonctionnalités qui se déclenchent au moyen d’un mouvement de l’appareil ou d’un geste vers l’appareil (repérer par exemple la présence de consignes dans l’interface ou dans une documentation associée à l’application qui décrive ce type de déclenchement).\n2.  Vérifier :\n    *   que la fonctionnalité peut être déclenchée sans mouvement, par exemple par l’activation d’un bouton ou d’un lien ;\n    *   et que l’application propose une méthode pour désactiver la détection du mouvement (par exemple, un paramètre dans l’application).\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '11.13' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.14":"###### iOS et Android\n1.  Repérer dans l’écran les fonctionnalités de conversion de document (par exemple exportation en PDF, en .odt, HTML etc.)\n2.  Repérer dans le contenu original les informations d’accessibilité présentes (par exemple, une alternative d’un élément graphique, des niveaux de titres, une table des matières).\n3.  Vérifier que dans le document résultant de la conversion, les informations d’accessibilité sont toujours présentes (sauf si le format de conversion choisi ne possède pas de support pour les informations d’accessibilité du document source).\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '11.14' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.15":"###### iOS et Android\n1.  Repérer dans l’écran les fonctionnalités d’identification (authentification) et de contrôle qui reposent sur l’utilisation de caractéristiques biologiques (par exemple reconnaissance vocale, empreinte digitale, reconnaissance faciale).\n2.  Vérifier qu’il existe une méthode alternative pour réaliser l’action :\n    *   Pour une fonctionnalité d’authentification qui passe par une reconnaissance d’empreinte digitale, un bouton est disponible sur l’écran de connexion pour accéder à la saisie d’un mot de passe.\n    *   Pour une fonctionnalité d’authentification qui passe par une reconnaissance vocale, l’application propose également une reconnaissance d’empreinte digitale.\n3.  Si c’est le cas, le critère est validé.\nSi la méthode alternative repose également sur une caractéristique biologique, il est indispensable qu’elle n’implique pas une caractéristique biologique similaire. Par exemple, si la méthode initiale implique la voix, la méthode alternative ne doit pas utiliser la voix."}'::jsonb
where identifier = '11.15' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.16":"###### iOS et Android\n1.  Repérer dans l’application la présence d’une fonctionnalité de répétition de touches (repérer par exemple la présence de consignes dans l’interface ou dans une documentation associée à l’application).\n2.  Vérifier que le délai de déclenchement de la fonction de répétition (le délai entre la toute première pression de touche à répéter et la mise en œuvre de la fonction de répétition) :\n    *   est de 2 secondes au moins ;\n    *   ou qu’il existe une méthode permettant de le paramétrer à 2 secondes au moins (par exemple, un champ de saisie dans les paramètres utilisateurs de l’application).\n3.  Vérifier que le délai entre deux répétitions :\n    *   est de 2 secondes au moins ;\n    *   ou qu’il existe une méthode permettant de le paramétrer à 2 secondes au moins (par exemple, un champ de saisie dans les paramètres utilisateurs de l’application).\n4.  Si c’est le cas, le test est validé."}'::jsonb
where identifier = '11.16' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.2":"###### iOS et Android\n1.  Repérer les limites de temps de session (par exemple, la déconnexion d’un compte client).\n2.  Vérifier :\n    *   la présence d’un mécanisme permettant à l’utilisateur de supprimer la limite de temps (par exemple, un bouton avec un intitulé explicite) ;\n    *   ou la présence d’un mécanisme permettant à l’utilisateur d’augmenter la limite de temps (par exemple, un paramètre disponible dans l’application pour gérer les temps de sessions) ;\n    *   ou que la durée de la session est de vingt heures, au moins.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '11.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.3":"###### iOS et Android\n1.  Repérer dans l’écran les composants (un lien, un bouton de formulaire ou un formulaire de téléchargement par exemple) permettant de télécharger un fichier au format bureautique (.doc, .docx, .pdf par exemple).\n2.  Pour chaque fichier proposé au téléchargement, dans un format bureautique, vérifier la présence d’une version alternative présentée comme accessible.\n3.  Si l’alternative est proposée dans un format bureautique (pdf, odt, doc, docx, EPUB/DAISY) :\n    *   télécharger le fichier de l’alternative proposée ;\n    *   si ce fichier est au format PDF, vérifier qu’il est conforme au [référentiel d’évaluation de l’accessibilité des documents au format PDF (RAPDF 1)](../rapdf1/index.html).\n    *   si ce fichier est dans un autre format, vérifier qu’il est conforme aux critères de la [section 10 Non-web documents](https://www.etsi.org/deliver/etsi_en/301500_301599/301549/03.02.01_60/en_301549v030201p.pdf#page=52) de la norme européenne EN 301 549 v3.2.1.\n4.  Si l’alternative est proposée dans l’application, vérifier que le contenu est conforme au présent référentiel.\n5.  Sinon, pour les documents au format bureautique (pdf, odt, doc, docx, EPUB/DAISY) :\n    *   télécharger le fichier ;\n    *   si ce fichier est au format PDF, vérifier qu’il est conforme au [référentiel d’évaluation de l’accessibilité des documents au format PDF (RAPDF 1)](../rapdf1/index.html).\n    *   si ce fichier est dans un autre format, vérifier qu’il est conforme aux critères de la [section 10 Non-web documents](https://www.etsi.org/deliver/etsi_en/301500_301599/301549/03.02.01_60/en_301549v030201p.pdf#page=52) de la norme européenne EN 301 549 v3.2.1.\n6.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '11.3' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.4":"###### iOS et Android\n1.  Pour chaque fichier proposé au téléchargement dans un format bureautique qui possède une version alternative présentée comme accessible, vérifier que les deux documents (le document d’origine et la version accessible dans un format bureautique ou dans l’application) offrent la même information.\n2.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '11.4' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.5":"###### iOS et Android\n1.  Repérer dans l’écran les contenus cryptiques (art ascii, émoticône, syntaxe cryptique).\n2.  Vérifier qu’une définition est disponible dans le contexte adjacent (immédiatement avant ou après le contenu cryptique, dans le texte adjacent ou via l’activation d’un composant d’interface).\n3.  Sinon, activer le **lecteur d’écran**.\n4.  Naviguer jusqu’au contenu cryptique et vérifier qu’une alternative est restituée.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '11.5' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.6":"###### iOS et Android\n1.  Pour chaque contenu cryptique qui possède une alternative, vérifier que l’alternative donnée est pertinente (elle permet de comprendre le contenu ou la fonction).\n2.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '11.6' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.7":"###### iOS et Android\n1.  Repérer dans l’écran les contenus clignotants ou qui provoquent des effets de flash : élément graphique animé, vidéo ou animation, effet de mise en forme.\n2.  Vérifier :\n    *   que la fréquence de l’effet est inférieure ou égale à 3 flashs par seconde ;\n    *   ou que la surface cumulée est inférieure à 21824 pixels.\n3.  Si c’est le cas, le critère est validé.\nNote : L’outil [PEAT](https://trace.umd.edu/peat/) permet d’analyser les vidéos au format .avi."}'::jsonb
where identifier = '11.7' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.8":"###### iOS et Android\n1.  Repérer dans l’écran les contenus en mouvement ou clignotants (un élément graphique, un effet de mise en forme, un carrousel par exemple) déclenchés automatiquement au chargement de l’écran ou lors de l’affichage d’un contenu (cf. note).\n2.  Vérifier :\n    *   que la durée totale du mouvement ou du clignotement est inférieure à 5 secondes ;\n    *   ou la présence d’un mécanisme (un bouton par exemple) qui permet d’arrêter et de relancer le mouvement ou le clignotement ;\n    *   ou la présence d’un mécanisme (un bouton par exemple) qui permet de cacher et d’afficher à nouveau le contenu en mouvement ou clignotant ;\n    *   ou la présence d’un mécanisme (un bouton par exemple) qui permet d’afficher le contenu sans mouvement ou clignotement.\n3.  Si c’est le cas, le critère est validé.\n**Note :**\n*   L’arrêt ou la mise en pause d’un contenu en mouvement ou clignotant via la prise de focus (l’effet est suspendu uniquement pendant la prise de focus mais reprend une fois la prise de focus perdue) ou au toucher sur le contenu en mouvement (l’effet est suspendu uniquement pendant qu’une pression est effectuée sur le contenu, mais reprend une fois la pression relâchée) ne sont pas considérés comme des procédés conformes.\n*   Dans certains cas, le mouvement ne peut pas être arrêté, par exemple, une barre de progression, dans ce cas, le critère est non applicable."}'::jsonb
where identifier = '11.8' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"11.9":"###### iOS\n1.  Ouvrir le **Centre de contrôle**.\n2.  Vérifier que l’orientation de l’écran n’est pas verrouillée dans les paramètres de la plateforme ([voir la documentation officielle](https://support.apple.com/fr-fr/guide/iphone/iph3badf94ec/ios)).\n3.  Afficher l’application et basculer le terminal alternativement en mode paysage et portrait.\n4.  Vérifier :\n    *   que l’application est utilisable dans les deux orientations, c’est-à-dire que les éléments de l’application sont repositionnés pour être lisibles ;\n    *   que les contenus disponibles dans une orientation sont toujours disponibles dans l’autre orientation (directement ou par l’activation d’un composant supplémentaire par exemple).\n5.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Ouvrir le panneau de **configuration rapide**.\n2.  Vérifier que le paramètre « Rotation automatique » est activé ([voir la documentation officielle](https://support.google.com/android/answer/9083864?hl=fr)).\n3.  Afficher l’application et basculer le terminal alternativement en mode paysage et portrait.\n4.  Vérifier :\n    *   que l’application est utilisable dans les deux orientations, c’est-à-dire que les éléments de l’application sont repositionnés pour être lisibles ;\n    *   que les contenus disponibles dans une orientation sont toujours disponibles dans l’autre orientation (directement ou par l’activation d’un composant supplémentaire par exemple).\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '11.9' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"12.1":"###### iOS et Android\n1.  Repérer dans l’application la présence d’une documentation.\n2.  Repérer dans l’application la présence de fonctionnalités d’accessibilité.\n3.  Vérifier la présence dans la documentation :\n    *   de la description des fonctionnalités d’accessibilité de l’application ;\n    *   d’explications sur les modalités d’utilisation de ces fonctionnalités (leur localisation, les méthodes pour les activer) ;\n    *   de la description des composants complexes pour lesquels il est mis en place une gestion particulière selon les technologies d’assistance ;\n    *   de la description des éléments non conformes ou non compatibles avec certaines technologies d’assistance, et de la présence d’alternatives le cas échéant.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '12.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"12.2":"###### iOS et Android\n1.  Repérer les fonctionnalités d’accessibilité décrites dans la documentation. Par exemple :\n    *   accéder à une version du contenu en langage simplifié ;\n    *   agrandir la taille du texte.\n2.  Vérifier que les utilisateurs concernés par chaque fonctionnalité d’accessibilité sont en mesure d’y accéder. Par exemple :\n    *   Version alternative en langage simplifié : le mécanisme ou l’ensemble des mécanismes qui permettent d’activer la fonctionnalité doit être compréhensible et identifiable par une personne qui bénéficie du langage simplifié (par exemple, l’emploi du [logo « Facile à lire »](https://www.inclusion-europe.eu/easy-to-read/) pour identifier le mécanisme est une solution conforme).\n    *   Agrandissement de la taille des caractères : si le mécanisme contient du texte, alors le texte doit être affiché par défaut avec une taille de police équivalent à 200% de la taille de police initiale.\n3.  Vérifier qu’il est possible d’activer cette fonctionnalité.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '12.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"12.3":"###### iOS\n1.  Identifier dans la [documentation](glossaire.md#documentation) de la plateforme les fonctionnalités d’accessibilité mises à disposition des utilisateurs (voir la [documentation concernant les fonctionnalités d’accessibilité fournie par iOS](https://www.apple.com/fr/accessibility/)).\n2.  Vérifier que l’application n’empêche pas leur utilisation, par exemple :\n    *   si l’application implémente des interactions qui déclenchent des fonctionnalités, ces interactions n’empêchent pas le bon fonctionnement des fonctionnalités d’accessibilité de la plateforme comme le lecteur d’écran ou les autres fonctionnalités basées sur le toucher ;\n    *   si l’application embarque une reconnaissance vocale, alors l’utilisation de la commande vocale intégrée à la plateforme n’est pas perturbée ;\n    *   si l’application implémente des raccourcis clavier, ceux-ci n’utilisent pas des combinaisons de touches déjà employées par la plateforme pour des fonctionnalités d’accessibilité ([VoiceOver peut être utilisé avec un clavier](https://support.apple.com/fr-fr/guide/iphone/iph6c494dc6/ios) par exemple, les raccourcis proposés ne doivent pas interférer) ;\n    *   ou toute autre fonctionnalité de l’application.\n3.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Identifier dans la [documentation](glossaire.md#documentation) de la plateforme les fonctionnalités d’accessibilité mises à disposition des utilisateurs (voir la [documentation concernant les fonctionnalités d’accessibilité fournie par Android](https://support.google.com/accessibility/android/answer/6006564?hl=fr)).\n2.  Vérifier que l’application n’empêche pas leur utilisation, par exemple :\n    *   si l’application implémente des interactions qui déclenchent des fonctionnalités, ces interactions n’empêchent pas le bon fonctionnement des fonctionnalités d’accessibilité de la plateforme comme le lecteur d’écran ou les autres fonctionnalités basées sur le toucher ;\n    *   si l’application embarque une reconnaissance vocale, alors l’utilisation de la commande vocale intégrée à la plateforme n’est pas perturbée ;\n    *   si l’application implémente des raccourcis clavier, ceux-ci n’utilisent pas des combinaisons de touches déjà employées par la plateforme pour des fonctionnalités d’accessibilité ([TalkBack peut être utilisé avec un clavier](https://support.google.com/accessibility/android/answer/6110948?hl=fr&ref_topic=10602074) par exemple, les raccourcis proposés ne doivent pas interférer) ;\n    *   ou toute autre fonctionnalité de l’application.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '12.3' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"12.4":"###### iOS et Android\n1.  Repérer la présence d’une documentation dans l’application ou accessible depuis l’application.\n2.  Pour une documentation au format web (HTML, CSS), vérifier qu’elle respecte les critères du [RAWeb](../raweb1/criteres.html).\n3.  Pour une documentation au format PDF, vérifier qu’elle respecte les critères du [RAPDF](../rapdf1/index.html).\n4.  Pour une documentation au format non web (hors PDF), vérifier qu’elle respecte les critères de la [section 10 Non-web documents](https://www.etsi.org/deliver/etsi_en/301500_301599/301549/03.02.01_60/en_301549v030201p.pdf#page=52) de la norme européenne EN 301 549 v3.2.1 ;\n5.  Pour une documentation fournie dans une application mobile, vérifier qu’elle respecte les critères du RAAM.\n6.  Si c’est le cas, le critère est validé.\nNote : la documentation sera considérée non conforme dès qu’une erreur sera identifiée au regard des critères cibles, et ce, même si l’erreur fait partie des éléments de gabarits (menu, pied de page) et non pas uniquement du contenu de la documentation isolée."}'::jsonb
where identifier = '12.4' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"13.1":"###### iOS et Android\n1.  Repérer dans l’outil les fonctionnalités d’édition (par exemple, un éditeur de texte, mais cela peut être une médiathèque ou toute autre interface qui permet de saisir du texte ou définir des propriétés).\n2.  Pour les fonctionnalités qui permettent de créer du contenu au format web (HTML, CSS), vérifier qu’il est possible de définir les informations d’accessibilité nécessaires pour rendre le contenu conforme au [RAWeb](../raweb1/index.html). Par exemple :\n    *   définir l’alternative textuelle d’une image depuis l’éditeur de texte ou une médiathèque ;\n    *   définir un intitulé de lien ;\n    *   etc.\n3.  Pour les fonctionnalités qui permettent de créer du contenu au format PDF, vérifier qu’il est possible de définir les informations d’accessibilité nécessaires pour rendre le contenu conforme au [RAPDF](../rapdf1/index.html). Par exemple :\n    *   définir l’alternative textuelle d’une image depuis l’éditeur de texte ou une médiathèque ;\n    *   définir un intitulé de lien ;\n    *   etc.\n4.  Pour les fonctionnalités qui permettent de créer du contenu au format non web (hors PDF), vérifier qu’il est possible de définir les informations d’accessibilité nécessaires pour rendre le contenu conforme aux critères de la [section 10 Non-web documents](https://www.etsi.org/deliver/etsi_en/301500_301599/301549/03.02.01_60/en_301549v030201p.pdf#page=52) de la norme européenne EN 301 549 v3.2.1. Par exemple :\n    *   définir l’alternative textuelle d’une image depuis l’éditeur de texte ou une médiathèque ;\n    *   définir un intitulé de lien ;\n    *   etc.\n5.  Pour les fonctionnalités qui permettent de créer du contenu diffusé dans une application mobile, vérifier qu’il est possible de définir les informations d’accessibilité nécessaires pour rendre le contenu conforme aux critères du RAAM. Par exemple :\n    *   définir l’alternative textuelle d’une image depuis l’éditeur de texte ou une médiathèque ;\n    *   définir un intitulé de lien ;\n    *   etc.\n6.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '13.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"13.2":"###### iOS et Android\n1.  Repérer dans l’outil la présence d’aides à la création de contenus accessibles. Cela peut être :\n    *   des tests automatiques ou semi-automatiques disponibles depuis les fonctionnalités d’édition ;\n    *   d’autres outils automatiques (un _chatbot_ par exemple) ;\n    *   une documentation qui explique comment définir les propriétés d’accessibilité pour chaque élément de contenu ;\n    *   des tests manuels disponibles depuis les fonctionnalités d’édition pour guider les auteurs dans la détection d’erreurs.\n2.  Vérifier que les aides à la création de contenus accessibles sont pertinentes, c’est-à-dire que les résultats ou les indications qu’elles donnent permettent de créer un contenu conforme aux règles d’accessibilité numérique.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '13.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"13.3":"###### iOS et Android\n1.  Depuis les fonctionnalités d’édition (un éditeur de texte, mais cela peut être une médiathèque et toute autre interface qui permet de saisir du texte ou définir des propriétés), saisir les typologies de contenus proposées par l’éditeur (titre, liste, tableau, image, etc.). Utiliser également les différents paramètres permettant de définir des informations d’accessibilité (renseigner l’alternative textuelle d’une image, ajouter une description sur un lien, etc.)\n2.  Enregistrer les saisies.\n3.  Consulter le contenu généré :\n    *   dans la fonctionnalité d’édition (par exemple, dans l’éditeur de texte) ;\n    *   et dans l’interface de publication des contenus (par exemple, la page web de publication).\n4.  Pour chaque contenu au format web (HTML, CSS), vérifier :\n    *   que les informations nécessaires pour qu’il soit conforme au [RAWeb](../raweb1/index.html) (par exemple l’alternative d’une image, les niveaux de titres) sont préservées dans le contenu généré ;\n    *   que l’information, si elle est restructurée, reste compatible avec les technologies d’assistance (par exemple, si l’auteur saisit un tableau HTML et qu’après l’enregistrement, l’outil linéarise le tableau, l’information ainsi restructurée doit être compréhensible pour les utilisateurs de technologies d’assistance comme elle l’aurait été dans sa forme initiale).\n5.  Pour chaque contenu au format PDF, vérifier :\n    *   que les informations nécessaires pour qu’il soit conforme au [RAPDF](../rapdf1/index.html) (par exemple l’alternative d’une image, les niveaux de titres) sont préservées dans le contenu généré ;\n    *   que l’information, si elle est restructurée, reste compatible avec les technologies d’assistance (par exemple, si l’auteur saisit un tableau et qu’après l’enregistrement, l’outil linéarise le tableau, l’information ainsi restructurée doit être compréhensible pour les utilisateurs de technologies d’assistance comme elle l’aurait été dans sa forme initiale).\n6.  Pour chaque contenu au format non web qui n’est pas du PDF, vérifier :\n    *   que les informations nécessaires pour qu’il soit conforme à la [section 10 Non-web documents](https://www.etsi.org/deliver/etsi_en/301500_301599/301549/03.02.01_60/en_301549v030201p.pdf#page=52) de la norme européenne EN 301 549 v3.2.1 sont préservées dans le contenu généré ;\n    *   que l’information, si elle est restructurée, reste compatible avec les technologies d’assistance (par exemple, si l’auteur saisit un tableau et qu’après l’enregistrement, l’outil linéarise le tableau, l’information ainsi restructurée doit être compréhensible pour les utilisateurs de technologies d’assistance comme elle l’aurait été dans sa forme initiale).\n7.  Pour chaque contenu diffusé dans une application mobile, vérifier :\n    *   que les informations nécessaires pour qu’il soit conforme au RAAM (par exemple l’alternative d’une image, l’identification des titres) sont préservées dans le contenu généré ;\n    *   que l’information, si elle est restructurée, reste compatible avec les technologies d’assistance (par exemple, si l’auteur saisit un tableau HTML et qu’après l’enregistrement, l’outil linéarise le tableau, l’information ainsi restructurée doit être compréhensible pour les utilisateurs de technologies d’assistance comme elle l’aurait été dans sa forme initiale).\n8.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '13.3' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"13.4":"###### iOS et Android\n1.  Repérer dans l’outil la présence de fonctionnalités de tests automatiques ou semi-automatiques.\n2.  Générer du contenu (web et non-web) avec l’outil d’édition avec des erreurs d’accessibilité.\n3.  Activer les fonctionnalités de tests.\n4.  Vérifier :\n    *   que l’outil répare automatiquement l’erreur (test automatique) ;\n    *   ou que l’outil met à disposition de l’auteur des suggestions de réparations (test semi-automatique).\n5.  Dans le cas d’un test semi-automatique, vérifier :\n    *   que l’outil met à disposition une aide à la décision et des suggestions de réparations ;\n    *   ou que l’outil met à disposition de l’auteur des explications pour effectuer la réparation.\n6.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '13.4' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"13.5":"###### iOS et Android\n1.  Repérer la présence de gabarits mis à disposition par l’outil d’édition.\n2.  Pour les gabarits au format web (HTML, CSS), vérifier qu’au moins un gabarit permet de respecter l’ensemble des critères du [RAWeb](../raweb1/index.html).\n3.  Pour les gabarits au format PDF, vérifier qu’au moins un gabarit permet de respecter l’ensemble des critères du [RAPDF](../rapdf1/index.html).\n4.  Pour les gabarits au format non-web (hors PDF), vérifier qu’au moins un gabarit permet de respecter l’ensemble des critères de la [section 10 Non-web documents](https://www.etsi.org/deliver/etsi_en/301500_301599/301549/03.02.01_60/en_301549v030201p.pdf#page=52) de la norme européenne EN 301 549 v3.2.1.\n5.  Pour les gabarits permettant de diffuser des contenus dans une application mobile, vérifier qu’au moins un gabarit permet de respecter l’ensemble des critères du RAAM.\n6.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '13.5' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"13.6":"###### iOS et Android\n1.  Repérer la présence de gabarits totalement conformes aux règles d’accessibilité numérique mis à disposition par l’outil d’édition.\n2.  Vérifier la présence d’une mention explicite permettant de les identifier. Par exemple, depuis la liste des gabarits, les gabarits conformes possèdent une étiquette « gabarit accessible ».\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '13.6' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"14.1":"###### iOS et Android\n1.  Repérer la mise à disposition d’un service d’assistance depuis l’application.\n2.  Si c’est le cas, repérer dans l’application la présence d’une documentation.\n3.  Repérer la présence dans la documentation :\n    *   de la description des fonctionnalités d’accessibilité proposées par l’application ;\n    *   de la description des composants complexes pour lesquels il est mis en place une gestion particulière selon les technologies d’assistance ;\n    *   d’explications sur les modalités d’utilisation de ces fonctionnalités (leur localisation, les méthodes pour les activer) ;\n    *   de la description des éléments non conformes ou non compatibles avec certaines technologies d’assistance, et de la présence d’alternatives le cas échéant.\n4.  Vérifier que le service d’assistance propose des informations concernant ces fonctionnalités.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '14.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"14.2":"###### iOS et Android\n1.  Repérer la présence dans l’application d’un service d’assistance.\n2.  Si c’est le cas, vérifier que le service d’assistance peut être utilisé par toutes les personnes en situation de handicap. Il peut être utile de rechercher dans la [documentation](glossaire.md#documentation) de l’application pour trouver ces informations. Par exemple, si le service d’assistance est disponible depuis un numéro de téléphone, vérifier qu’il existe des moyens alternatifs pour les utilisateurs qui n’accèdent pas ou peu au langage oral (personnes sourdes ou malentendantes) ou qui ne peuvent pas utiliser le langage verbal (personnes aphasiques). Par exemple :\n    *   une adresse mail ou un formulaire en ligne ;\n    *   une messagerie instantanée ;\n    *   la mise à disposition d’une traduction écrite simultanée ou visuelle des informations orales ou sonores, ou la mise à disposition d’un interprète en langue des signes (utilisation d’un service de relais).\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '14.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"14.3":"###### iOS et Android\n1.  Repérer la présence d’une documentation fournie par le service d’assistance.\n2.  Pour une documentation au format web (HTML, CSS), vérifier qu’elle respecte les critères du [RAWeb](../raweb1/criteres.html).\n3.  Pour une documentation au format PDF, vérifier qu’elle respecte les critères du [RAPDF](../rapdf1/index.html).\n4.  Pour une documentation au format non web (hors PDF), vérifier qu’elle respecte les critères la [section 10 Non-web documents](https://www.etsi.org/deliver/etsi_en/301500_301599/301549/03.02.01_60/en_301549v030201p.pdf#page=52) de la norme européenne EN 301 549 v3.2.1 ;\n5.  Pour une documentation fournie dans une application mobile, vérifier qu’elle respecte les critères du RAAM.\n6.  Si c’est le cas, le critère est validé.\nNote : la documentation sera considérée non conforme dès qu’une erreur sera identifiée au regard des critères cibles, et ce, même si l’erreur fait partie des éléments de gabarits (menu, pied de page) et non pas uniquement du contenu de la documentation isolée."}'::jsonb
where identifier = '14.3' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"15.1":"###### iOS et Android\n1.  Activer l’application et lancer un appel entre les deux terminaux.\n2.  Vérifier que la qualité de l’activité orale avec l’application web est au moins équivalente à la qualité de l’activité orale lors d’un appel avec un téléphone fixe.\n3.  Si le test n’est pas satisfaisant (par exemple, mauvaise compréhension de certains mots énoncés par l’interlocuteur, présence de bruits parasites, etc.), vérifier dans la documentation de l’application :\n    *   la présence d’une référence à l’implémentation de la [recommandation UIT-T G.722](https://www.itu.int/rec/T-REC-G.722/fr) ;\n    *   ou la présence d’une référence à l’utilisation du [codec opus de l’API WebRTC](https://developer.mozilla.org/en-US/docs/Web/Media/Formats/WebRTC_codecs) ;\n    *   ou la présence d’une référence à l’utilisation d’un encodage et décodage dont la fréquence est supérieure ou égale à 7 000 Hz.\n4.  Sinon, il est recommandé de demander à l’éditeur de l’application de fournir ces détails techniques, notamment en demandant si l’application web implémente par exemple la recommandation UIT-T G.722 ou utilise le codec opus de l’API WebRTC.\n5.  Si c’est le cas, le critère est validé.\nSi l’information ne peut être trouvée dans l’interface ou sa documentation, et que l’éditeur de l’application n’est pas en mesure de répondre sur cette caractéristique technique, le critère sera considéré non conforme."}'::jsonb
where identifier = '15.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"15.10":"###### iOS et Android\n1.  Repérer dans l’application les fonctionnalités disponibles (en dehors de la fonctionnalité de communication orale) qui se basent sur l’écoute d’information ou l’énonciation de commande, par exemple :\n    *   une messagerie vocale ;\n    *   un standard téléphonique automatique (par exemple, qui demande d’énoncer un chiffre entre 1 et 4 pour être redirigé vers un service) ;\n    *   ou tout autre serveur vocal interactif.\n2.  Vérifier :\n    *   que l’information est disponible sans devoir écouter ou parler (par exemple grâce à une transcription textuelle ou un système de chat) ;\n    *   que les actions peuvent être réalisées sans devoir écouter ou parler ou qu’il existe une alternative à la fonctionnalité qui peut être utilisée sans devoir écouter ou parler.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '15.10' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"15.11":"###### iOS et Android\nPour les conditions concernant la résolution et la fréquence des images, la façon la plus sûre d’évaluer ce critère est de faire une recherche soit dans l’interface soit dans la documentation de l’application pour obtenir ces informations. Il est également recommandé de demander à l’éditeur de l’application de fournir ces détails techniques.\nSi l’information ne peut être trouvée dans l’interface ou sa documentation, et que l’éditeur de l’application n’est pas en mesure de répondre sur cette caractéristique technique, ces conditions ne pouvant être validées, le critère sera considéré non conforme.\nPour la dernière condition concernant le décalage entre la vidéo et l’audio, le test peut s’établir sur une simple observation :\n1.  Activer l’application sur deux terminaux.\n2.  Établir une connexion d’appel vidéo entre les deux terminaux.\n3.  Vérifier la synchronisation entre les paroles et la vidéo (synchronisation labiale, mouvement des lèvres).\n4.  Si c’est le cas, le test est validé."}'::jsonb
where identifier = '15.11' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"15.2":"###### iOS et Android\n1.  Vérifier que l’application permet la communication orale bidirectionnelle.\n2.  Si c’est le cas, vérifier la présence d’une fonctionnalité de communication écrite en temps réel (il peut être parfois nécessaire d’activer un paramètre dédié dans l’application pour permettre la communication écrite en temps réel).\n3.  Si c’est le cas, le critère est validé.\nSi l’information ne peut être trouvée dans l’interface ou sa documentation, et que l’éditeur de l’application n’est pas en mesure de répondre sur cette caractéristique technique, le critère sera considéré non conforme."}'::jsonb
where identifier = '15.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"15.3":"###### iOS et Android\n1.  Vérifier que l’application permet la communication orale bidirectionnelle.\n2.  Si c’est le cas, vérifier la présence d’une fonctionnalité de communication écrite en temps réel.\n3.  Si c’est le cas, vérifier qu’il est possible d’utiliser les deux modes de communications en même temps, c’est-à-dire qu’il est possible pour un même utilisateur de parler et d’utiliser simultanément le système de communication écrite en temps réel.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '15.3' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"15.4":"###### iOS et Android\n1.  Activer l’application et la fonctionnalité de communication écrite en temps réel de l’application sur deux terminaux et les connecter à une même session.\n2.  Envoyer un message écrit depuis les deux terminaux pour obtenir des messages avec des statuts différents (envoyé et reçu) et avec des auteurs différents.\n3.  Vérifier :\n    *   que les messages envoyés et reçus sont visuellement séparés (par exemple, les messages envoyés sont dans une fenêtre et les messages reçus dans une autre, ou il y a un saut de ligne entre chaque message reçu et envoyé s’ils sont présentés dans une même fenêtre) ;\n    *   qu’il est possible visuellement de distinguer les messages envoyés et les messages reçus. Par exemple, par une mise en forme ou une couleur qui les différencie ou par une annotation textuelle visible (repérer la mention « Envoyé » à proximité d’un message envoyé ou « Reçu » à proximité d’un message reçu) ;\n    *   que l’information de la nature du message (reçu ou envoyé) est accessible aux technologies d’assistance (une information textuelle est disponible pour apporter cette information) ;\n    *   que les auteurs des messages écrits sont identifiés (par exemple, la présence d’un nom ou un identifiant précédant le message).\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '15.4' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"15.5":"###### iOS et Android\n1.  Vérifier que l’application permet la communication orale bidirectionnelle et la communication écrite en temps réel ou la diffusion de la vidéo en temps réel.\n2.  Si c’est le cas, activer l’application sur deux terminaux et les connecter à une même session.\n3.  Faire parler un utilisateur depuis un des terminaux.\n4.  Vérifier sur l’interface l’apparition d’un indicateur visuel permettant d’identifier qu’une personne est en train de parler. Il n’est pas nécessaire pour ce critère d’identifier qui parle, mais simplement d’identifier qu’il y a une personne qui est en train de parler. Par exemple, un halo autour ou une icône à proximité de l’avatar de la personne qui parle.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '15.5' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"15.6":"###### iOS et Android\nCe critère est très complexe à évaluer et demande une certaine maîtrise de l’ensemble des concepts et normes d’interopérabilité.\nIl est recommandé de demander à l’éditeur de l’application de vérifier que l’ensemble des exigences décrites dans le critère _6.2.3 Interoperability_{lang=en} de la norme EN 301 549 sont respectées.\nIl est également conseillé de rechercher dans la documentation ou de questionner directement l’éditeur de l’application.\nSi l’information ne peut être trouvée dans l’interface ou sa documentation, et que l’éditeur de l’application n’est pas en mesure de répondre sur cette caractéristique technique, le critère sera considéré non conforme."}'::jsonb
where identifier = '15.6' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"15.7":"###### iOS et Android\n1.  Vérifier que l’application permet la communication écrite en temps réel.\n2.  Si c’est le cas, activer l’application et la fonctionnalité de communication écrite sur deux terminaux distincts et les connecter à une même session.\n3.  Saisir du texte sur le premier terminal et observer son apparition sur le second terminal. L’apparition sur le second terminal doit être instantanée (inférieure à une demi-seconde). Selon le paramétrage de la fonctionnalité, chaque caractère n’est pas envoyé individuellement. En effet, si la fonctionnalité de communication écrite en temps réel implémente une prédiction de mots, c’est lorsque le mot désiré sera sélectionné qu’il sera envoyé, et non pas lors de la saisie des premiers caractères servant à déclencher l’affichage de suggestion. Un test par observation simple peut être suffisant pour constater l’apparition instantanée sur le terminal qui reçoit le message écrit.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '15.7' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"15.8":"###### iOS et Android\n1.  Activer l’application et le **lecteur d’écran** depuis un terminal.\n2.  Depuis un second terminal, lancer un appel vers le premier terminal.\n3.  Lorsque l’appel entrant apparaît, vérifier :\n    *   que l’identification de l’interlocuteur est disponible visuellement sous la forme d’un texte dont la nature est compréhensible (par exemple, un nom ou un numéro de téléphone) ;\n    *   que cette identification est correctement restituée par **le lecteur d’écran**.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '15.8' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"15.9":"###### iOS et Android\n1.  Activer l’application et lancer un appel vidéo entre les deux terminaux.\n2.  Initier une activité orale, et vérifier la présence sur le second terminal d’une information permettant d’identifier cette activité (par exemple, la présence d’un halo de couleur autour de la vignette de l’interlocuteur en activité).\n3.  Si c’est le cas :\n    *   repérer la présence d’un mécanisme manuel (par exemple, un bouton) qui permettrait à l’interlocuteur signant d’indiquer qu’il est en train de signer ;\n    *   sinon, réaliser des gestes devant la caméra (voir note) et vérifier l’affichage automatique d’une information permettant d’identifier cette activité visuelle.\n4.  Si c’est le cas, le critère est validé.\nNote : dans les applications de communication, l’identification d’une activité orale ne repose pas sur l’identification d’un message verbal intelligible (mot ou phrase par exemple), mais uniquement sur l’identification d’un son (un bruit par exemple). Ainsi, une activité visuelle, même si elle ne correspond pas à un élément compréhensible en langue des signes, pourrait être détectée automatiquement par cette application et servirait donc comme mécanisme pour identifier l’activité d’une personne signante. Il est donc possible de tester en réalisant des gestes même s’ils ne correspondent pas à un élément de sens en langue des signes."}'::jsonb
where identifier = '15.9' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"2.1":"###### iOS\n1.  Activer l’option **Différencier sans couleur** (_Réglages > Accessibilité > Affichage et taille du texte > Différencier sans couleur_).\n2.  Repérer dans l’écran les mots ou ensembles de mots, les textes, les éléments graphiques porteurs d’information et les médias temporels dont la mise en couleur est porteuse d’information.\n3.  Vérifier qu’il existe un autre moyen visuel de récupérer cette information : présence d’une icône ou d’un effet graphique de forme ou de position, un effet typographique, etc.\n4.  Avec le **lecteur d’écran**, accéder à l’information donnée par la couleur.\n5.  Vérifier qu’une information équivalente est restituée par le lecteur d’écran (par exemple l’état « sélectionné » d’un bouton vert).\n6.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Repérer dans l’écran les mots ou ensembles de mots, les textes, les éléments graphiques porteurs d’information et les médias temporels dont la mise en couleur est porteuse d’information.\n2.  Vérifier qu’il existe un autre moyen visuel de récupérer cette information : présence d’une icône ou d’un effet graphique de forme ou de position, un effet typographique, etc.\n3.  Avec le **lecteur d’écran**, accéder à l’information donnée par la couleur.\n4.  Vérifier qu’une information équivalente est restituée par le lecteur d’écran (par exemple l’état « sélectionné » d’un bouton vert).\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '2.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"2.2":"###### iOS\n1.  Activer l’option **Augmenter le contraste** (_Réglages > Accessibilité > Affichage et taille du texte > Augmenter le contraste_) ou s’il est présent dans l’application, activer le [mécanisme de remplacement permettant d’afficher l’application avec un rapport de contraste suffisant](glossaire.md#mecanisme-qui-permet-d-afficher-un-rapport-de-contraste-conforme).\n2.  Repérer dans l’écran les textes, les textes contenus dans des éléments graphiques et les textes incrustés dans les vidéos qui pourraient poser des problèmes de contraste.\n3.  Pour les textes dont [la taille (normale ou agrandie)](glossaire.md#contraste-taille-des-textes) ne peut être appréciée à l’œil nu, vous devrez la mesurer ([voir la section dédiée dans la méthodologie](methodologie.md#evaluer-la-taille-d-un-texte)).\n4.  Activer le logiciel **Colour Contrast Analyser**{lang=en} sur l’ordinateur et capturer les couleurs d’avant-plan et d’arrière-plan :\n    *   en [diffusant l’écran du terminal mobile](methodologie.md#diffuser-l-ecran-du-terminal-mobile) sur l’ordinateur ;\n    *   ou en [réalisant des captures d’écran](methodologie.md#realiser-des-captures-d-ecran) des éléments à évaluer (et en les [important sur l’ordinateur](methodologie.md#importer-des-captures-d-ecrans-sur-l-ordinateur)).\n5.  Pour les textes problématiques identifiés précédemment, vérifier :\n    *   Pour les textes dont la taille est de moins de 24 px sans effet de graisse, ou de moins de 18,5 px avec effet de graisse, que la valeur de contraste est de 4.5:1, au moins ;\n    *   Pour les textes dont la taille est de 24 px ou plus sans effet de graisse, ou de 18,5 px ou plus avec effet de graisse, que la valeur de contraste est de 3:1 au moins.\n6.  Si c’est le cas, le critère est validé.\nNote : Il est possible d’utiliser l’application **[Accessibility Inspector](methodologie.md#applications-de-tests)**{lang=en} disponible sur macOS pour réaliser une évaluation rapide des contrastes des écrans. Le logiciel dispose d’une fonctionnalité « Audit » qui permet de faire des tests automatiques de certains éléments textes et graphiques des écrans. Cette fonctionnalité ne détecte pas l’ensemble des défauts de contraste, des tests complémentaires suivant la méthodologie décrite ci-avant seront nécessaires.\n###### Android\n1.  S’il existe dans l’application, activer le [mécanisme de remplacement permettant d’afficher l’application avec un rapport de contraste suffisant](glossaire.md#mecanisme-qui-permet-d-afficher-un-rapport-de-contraste-conforme).\n2.  Repérer dans l’écran les textes, les textes contenus dans des éléments graphiques et les textes incrustés dans les vidéos qui pourraient poser des problèmes de contraste.\n3.  Pour les textes dont [la taille (normale ou agrandie)](glossaire.md#contraste-taille-des-textes) ne peut être appréciée à l’œil nu, vous devrez la mesurer ([voir la section dédiée dans la méthodologie](methodologie.md#evaluer-la-taille-d-un-texte)).\n4.  Activer le logiciel **Colour Contrast Analyser**{lang=en} sur l’ordinateur et capturer les couleurs d’avant-plan et d’arrière-plan :\n    *   en [diffusant l’écran du terminal mobile](methodologie.md#diffuser-l-ecran-du-terminal-mobile) sur l’ordinateur ;\n    *   ou en [réalisant des captures d’écran](methodologie.md#realiser-des-captures-d-ecran) des éléments à évaluer (et en les [important sur l’ordinateur](methodologie.md#importer-des-captures-d-ecrans-sur-l-ordinateur)).\n5.  Pour les textes problématiques identifiés précédemment, vérifier :\n    *   Pour les textes dont la taille est de moins de 24 px sans effet de graisse, ou de moins de 18,5 px avec effet de graisse, que la valeur de contraste est de 4.5:1, au moins ;\n    *   Pour les textes dont la taille est de 24 px ou plus sans effet de graisse, ou de 18,5 px ou plus avec effet de graisse, que la valeur de contraste est de 3:1 au moins.\n6.  Si c’est le cas, le critère est validé.\nNote : Il est possible d’utiliser l’application **[Accessibility Scanner](methodologie.md#applications-de-tests)** pour réaliser une évaluation rapide des contrastes des écrans. L’application ne détecte pas l’ensemble des défauts de contrastes, des tests complémentaires suivant la méthodologie décrite ci-avant seront nécessaires."}'::jsonb
where identifier = '2.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"2.3":"###### iOS\n1.  Activer l’option **Augmenter le contraste** (_Réglages > Accessibilité > Affichage et taille du texte > Augmenter le contraste_) ou s’il est présent dans l’application, activer le [mécanisme de remplacement permettant d’afficher les éléments graphiques avec un rapport de contraste suffisant](glossaire.md#mecanisme-qui-permet-d-afficher-un-rapport-de-contraste-conforme).\n2.  Repérer dans l’écran les éléments graphiques porteurs d’information et pour chacun :\n    *   Identifier quelle(s) couleur(s) du composant sont nécessaires à l’identification de la localisation et/ou de l’information véhiculée (cela peut être la bordure, la couleur d’une icône, la couleur de fond) ;\n    *   Identifier les couleurs adjacentes qui ont un impact sur la visibilité de la ou les couleurs du composant.\n3.  Repérer dans l’écran les composants interactifs qui peuvent avoir plusieurs états (survolés, focus, activé, coché) et pour chacun :\n    *   Identifier quelle(s) couleur(s) du composant sont nécessaires à l’identification de la localisation et/ou de l’information véhiculée et de l’état (cela peut être la bordure, la couleur d’une icône, la couleur de fond) pour chacun des états ;\n    *   Identifier les couleurs adjacentes qui ont un impact sur la visibilité de la ou les couleurs du composant.\n4.  Activer le logiciel **Colour Contrast Analyser**{lang=en} sur l’ordinateur et capturer les couleurs d’avant-plan et d’arrière-plan sur le terminal mobile soit :\n    *   En [diffusant l’écran du terminal mobile sur l’ordinateur](methodologie.md#diffuser-l-ecran-du-terminal-mobile) ;\n    *   En réalisant des [captures d’écran](methodologie.md#realiser-des-captures-d-ecran) des éléments à évaluer (et en les important sur l’ordinateur).\n5.  Vérifier que le rapport de contraste entre les couleurs identifiées est de 3:1 au moins.\n6.  Si c’est le cas, le critère est validé.\nNote : Il est possible d’utiliser l’application **[Accessibility Inspector](methodologie.md#applications-de-tests)**{lang=en} disponible sur macOS pour réaliser une évaluation rapide des contrastes des écrans. Le logiciel dispose d’une fonctionnalité « Audit » qui permet de faire des tests automatiques de certains éléments textes et graphiques des écrans. Cette fonctionnalité ne détecte pas l’ensemble des défauts de contraste, des tests complémentaires suivant la méthodologie décrite ci-avant seront nécessaires.\n###### Android\n1.  S’il existe dans l’application, activer le [mécanisme de remplacement permettant d’afficher les éléments graphiques avec un rapport de contraste suffisant](glossaire.md#mecanisme-qui-permet-d-afficher-un-rapport-de-contraste-conforme).\n2.  Repérer dans l’écran les éléments graphiques porteurs d’information et pour chacun :\n    *   Identifier quelle(s) couleur(s) du composant sont nécessaires à l’identification de la localisation et/ou de l’information véhiculée (cela peut être la bordure, la couleur d’une icône, la couleur de fond) ;\n    *   Identifier les couleurs adjacentes qui ont un impact sur la visibilité de la ou les couleurs du composant.\n3.  Repérer dans l’écran les composants interactifs qui peuvent avoir plusieurs états (survolés, focus, activé, coché) et pour chacun :\n    *   Identifier quelle(s) couleur(s) du composant sont nécessaires à l’identification de la localisation et/ou de l’information véhiculée et de l’état (cela peut être la bordure, la couleur d’une icône, la couleur de fond) pour chacun des états ;\n    *   Identifier les couleurs adjacentes qui ont un impact sur la visibilité de la ou les couleurs du composant.\n4.  Activer le logiciel **Colour Contrast Analyser**{lang=en} sur l’ordinateur et capturer les couleurs d’avant-plan et d’arrière-plan sur le terminal mobile soit :\n    *   En [diffusant l’écran du terminal mobile sur l’ordinateur](methodologie.md#diffuser-l-ecran-du-terminal-mobile) ;\n    *   En réalisant des [captures d’écran](methodologie.md#realiser-des-captures-d-ecran) des éléments à évaluer (et en les important sur l’ordinateur).\n5.  Vérifier que le rapport de contraste entre les couleurs identifiées est de 3:1 au moins.\n6.  Si c’est le cas, le critère est validé.\nNote : Il est possible d’utiliser l’application **[Accessibility Scanner](methodologie.md#applications-de-tests)** pour réaliser une évaluation rapide des contrastes des écrans. L’application ne détecte pas l’ensemble des défauts de contrastes, des tests complémentaires suivant la méthodologie décrite ci-avant seront nécessaires."}'::jsonb
where identifier = '2.3' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"2.4":"###### iOS\n1.  Vérifier que l’option **Augmenter le contraste** (_Réglages > Accessibilité > Affichage et taille du texte > Augmenter le contraste_) est désactivée.\n2.  Repérer la présence d’un [mécanisme de remplacement permettant d’afficher l’application avec un rapport de contraste suffisant](glossaire.md#mecanisme-qui-permet-d-afficher-un-rapport-de-contraste-conforme).\n3.  Vérifier qu’il n’est pas activé (c’est-à-dire que l’écran est diffusé avec les contrastes par défaut).\n4.  Activer le logiciel **Colour Contrast Analyser**{lang=en} sur l’ordinateur et capturer les couleurs d’avant-plan et d’arrière-plan sur le terminal mobile soit :\n    *   En [diffusant l’écran du terminal mobile sur l’ordinateur](methodologie.md#diffuser-l-ecran-du-terminal-mobile) ;\n    *   En réalisant des [captures d’écran](methodologie.md#realiser-des-captures-d-ecran) des éléments à évaluer (et en les important sur l’ordinateur).\n5.  Si le mécanisme de remplacement est identifié par un texte, capturer les couleurs d’avant-plan et d’arrière-plan et vérifier :\n    *   Pour les textes en taille normale, que la valeur de contraste est de 4.5:1, au moins ;\n    *   Pour les textes en taille agrandie, que la valeur de contraste est de 3:1 au moins.\n6.  Si le mécanisme de remplacement est identifié par un élément non textuel uniquement (une icône par exemple) :\n    1.  Identifier quelle(s) couleur(s) du composant sont nécessaires à l’identification de la localisation et/ou de l’information (cela peut être la bordure, la couleur d’une icône, la couleur de fond) ;\n    2.  Identifier les couleurs adjacentes qui ont un impact sur la visibilité de la couleur ;\n    3.  Vérifier que le rapport de contraste entre les couleurs identifiées est de 3:1 au moins.\n7.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Repérer la présence d’un [mécanisme de remplacement permettant d’afficher l’application avec un rapport de contraste suffisant](glossaire.md#mecanisme-qui-permet-d-afficher-un-rapport-de-contraste-conforme).\n2.  Vérifier qu’il n’est pas activé (c’est-à-dire que l’écran est diffusé avec les contrastes par défaut).\n3.  Activer le logiciel **Colour Contrast Analyser**{lang=en} sur l’ordinateur et capturer les couleurs d’avant-plan et d’arrière-plan sur le terminal mobile soit :\n    *   En [diffusant l’écran du terminal mobile sur l’ordinateur](methodologie.md#diffuser-l-ecran-du-terminal-mobile) ;\n    *   En réalisant des [captures d’écran](methodologie.md#realiser-des-captures-d-ecran) des éléments à évaluer (et en les important sur l’ordinateur).\n4.  Si le mécanisme de remplacement est identifié par un texte, capturer les couleurs d’avant-plan et d’arrière-plan et vérifier :\n    *   Pour les textes en taille normale, que la valeur de contraste est de 4.5:1, au moins ;\n    *   Pour les textes en taille agrandie, que la valeur de contraste est de 3:1 au moins.\n5.  Si le mécanisme de remplacement est identifié par un élément non textuel uniquement (une icône par exemple) :\n    1.  Identifier quelle(s) couleur(s) du composant sont nécessaires à l’identification de la localisation et/ou de l’information (cela peut être la bordure, la couleur d’une icône, la couleur de fond) ;\n    2.  Identifier les couleurs adjacentes qui ont un impact sur la visibilité de la couleur ;\n    3.  Vérifier que le rapport de contraste entre les couleurs identifiées est de 3:1 au moins.\n6.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '2.4' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.1":"###### iOS et Android\n1.  Repérer dans l’écran les médias temporels seulement audio qui nécessitent une transcription textuelle.\n2.  Vérifier :\n    *   La présence d’une transcription textuelle accessible via un composant adjacent (un bouton ou un lien) ;\n    *   Ou la présence d’une transcription textuelle adjacente clairement identifiable.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.10":"###### iOS et Android\n1.  Repérer dans l’écran les médias temporels seulement vidéo ou synchronisé avec une audiodescription.\n2.  Vérifier que l’audiodescription est :\n    *   pertinente (toutes les informations visuelles importantes sont présentes) ;\n    *   correctement synchronisée :\n        *   les sons et paroles de l’audiodescription ne chevauchent pas ceux de la bande-son originale pour provoquer des problèmes de perception et de compréhension ;\n        *   les informations véhiculées dans l’audiodescription sont données au moment où apparaissent les informations visuelles équivalentes.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.10' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.11":"###### iOS et Android\n1.  Repérer dans l’écran les médias temporels seulement vidéo, audio ou synchronisés pré-enregistrés.\n2.  Vérifier :\n    *   qu’un passage de texte (un titre ou un paragraphe par exemple), permettant d’identifier le média temporel, le précède ou le suit immédiatement ;\n    *   que le passage de texte est situé à l’extérieur du lecteur de contenu multimédia.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.11' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.12":"###### iOS et Android\n1.  Au chargement de l’écran, si un son se déclenche automatiquement, vérifier :\n    *   que la séquence sonore a une durée inférieure ou égale à 3 secondes ;\n    *   ou qu’un dispositif (un bouton par exemple), sur l’élément ayant déclenché le son, ou dans l’écran, permet de le stopper ;\n    *   ou que le volume de la séquence peut être contrôlé par l’utilisateur, indépendamment du contrôle de volume du système.\n2.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.12' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.13":"###### iOS et Android\n1.  Repérer dans l’écran les médias temporels pré-enregistrés.\n2.  Vérifier que les fonctionnalités suivantes au moins sont présentes :\n    *   une fonctionnalité de lecture ;\n    *   une fonctionnalité de mise en pause ou d’arrêt ;\n    *   si le média possède une piste sonore, une fonctionnalité qui permet d’activer et désactiver le son ;\n3.  Si le média possède une audiodescription, vérifier qu’il existe une fonctionnalité qui permet d’activer et désactiver l’audiodescription.\n4.  Si le média possède des sous-titres synchronisés :\n    *   s’il s’agit de sous-titres incrustés (_open captions_{lang=en}) en tant qu’image, vérifier qu’ils sont affichés au lancement de la lecture de la vidéo ;\n    *   s’il s’agit de sous-titres non incrustés (_closed captions_{lang=en}) , vérifier qu’il existe une fonctionnalité qui permet d’activer et désactiver ces sous-titres.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.13' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.14":"###### iOS et Android\n1.  Repérer dans l’écran les médias temporels synchronisés pré-enregistrés avec une piste de sous-titres synchronisés ou une audiodescription.\n2.  Vérifier qu’il est possible d’activer et désactiver les sous-titres ou l’audiodescription sans étape supplémentaire par rapport aux fonctionnalités principales (lecture, pause…).\n3.  Si c’est le cas, le critère est validé.\n_Exemple_ : Si le bouton de lecture peut être activé depuis l’interface par un simple tap (sans la nécessité d’activer un premier composant pour afficher un menu déroulant par exemple), la fonction de sous-titres doit être disponible de manière équivalente, avec un simple tap. À l’inverse, si la fonction des sous-titres est disponible depuis un menu déroulant qui doit être activé au préalable (par un tap par exemple), elle ne sera pas considérée comme étant au même niveau puisqu’il y aura une étape supplémentaire à réaliser.\nNote : Bien que les contrôles de volume et de lecture puissent être des composants physiques des terminaux (boutons de volume d’un smartphone par exemple), il n’est pas requis que ces terminaux possèdent des contrôles physiques dédiés à l’activation des sous-titres et de l’audiodescription ou que ces contrôles, s’ils existent, soient situés au même niveau."}'::jsonb
where identifier = '3.14' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.15":"###### iOS et Android\n1.  Repérer les fonctionnalités qui permettent de transmettre (envoyer un contenu vers un autre terminal ou envoyer une vidéo par e-mail par exemple), convertir (convertir une vidéo au format .avi dans un format .mpg par exemple) ou enregistrer un média temporel synchronisé pré-enregistré (enregistrer une vidéo depuis une plateforme de diffusion sur son ordinateur personnel par exemple).\n2.  Exécuter chacune des fonctionnalités (transmettre, convertir et enregistrer).\n3.  Pour chaque fonctionnalité, vérifier si les sous-titres :\n    *   sont toujours présents ;\n    *   peuvent être affichés ;\n    *   sont correctement synchronisés ;\n    *   conservent leurs caractéristiques essentielles (par exemple, si les sous-titres étaient colorés en fonction du locuteur, les couleurs doivent être reprises).\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.15' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.16":"###### iOS et Android\n1.  Repérer les fonctionnalités qui permettent de transmettre, convertir ou enregistrer un média temporel synchronisé. Par exemple : envoyer un contenu vers un autre terminal ou par mail, convertir une vidéo au format .avi dans un format .mpg, enregistrer une vidéo depuis une plateforme de diffusion sur son ordinateur personnel.\n2.  Exécuter chacune des fonctionnalités (transmettre, convertir et enregistrer).\n3.  Pour chaque fonctionnalité, vérifier si l’audiodescription :\n    *   est présente ;\n    *   peut être activée ;\n    *   est correctement synchronisée :\n        *   les sons et paroles de l’audiodescription ne chevauchent pas ceux de la bande-son originale et ne provoquent pas de problèmes de perception et de compréhension ;\n        *   les informations véhiculées dans l’audiodescription sont données au moment où apparaissent les informations visuelles équivalentes.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.16' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.17":"###### iOS\n1.  Repérer dans l’écran les médias temporels pré-enregistrés qui possèdent des sous-titres.\n2.  Modifier les paramètres de présentation des sous-titres depuis la plateforme :\n    *   Aller dans _Réglages > Accessibilité > Sous-titres codés et SM > Style_ ;\n    *   Sélectionner **Créer un style** pour définir un style de sous-titres personnalisé et reconnaissable.\n    *   Vérifier que le paramètre **Ignorer les réglages personnalisés** en bas d’écran est désactivé.\n    *   Définir un ou plusieurs paramètres de présentation des sous-titres depuis les options de personnalisation mises à disposition par la plateforme, par exemple : la taille des sous-titres, la couleur, le style de bordure des sous-titres, la couleur d’arrière-plan, l’opacité de l’arrière-plan, etc. (Note : la norme ne donne pas la liste précise des paramètres qu’il est obligatoire de pouvoir définir, aussi, la possibilité de modifier une seule caractéristique des sous-titres est suffisante pour rendre le critère conforme).\n3.  Vérifier que les paramètres définis au niveau de la plateforme sont appliqués aux sous-titres.\n4.  Sinon, repérer dans l’écran la présence d’une fonctionnalité permettant de modifier les paramètres de présentation des sous-titres (dans l’écran ou directement depuis le lecteur multimédia).\n5.  Vérifier que les paramètres définis sont appliqués aux sous-titres.\n6.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Repérer dans l’écran les médias temporels pré-enregistrés qui possèdent des sous-titres.\n2.  Modifier les paramètres de présentation des sous-titres depuis la plateforme :\n    *   Aller dans _Paramètres > Accessibilité > Préférence pour les sous-titres > Style et taille des sous-titres_ ;\n    *   Définir un ou plusieurs paramètres de présentation des sous-titres depuis les options de personnalisation mises à disposition par la plateforme, par exemple : la taille des sous-titres, la couleur, le style de bordure des sous-titres, la couleur d’arrière-plan, l’opacité de l’arrière-plan, etc. (Note : la norme ne donne pas la liste précise des paramètres qu’il est obligatoire de pouvoir définir, aussi, la possibilité de modifier une seule caractéristique des sous-titres est suffisante pour rendre le critère conforme).\n3.  Vérifier que les paramètres définis au niveau de la plateforme sont appliqués aux sous-titres.\n4.  Sinon, repérer dans l’écran la présence d’une fonctionnalité permettant de modifier les paramètres de présentation des sous-titres (dans l’écran ou directement depuis le lecteur multimédia).\n5.  Vérifier que les paramètres définis sont appliqués aux sous-titres.\n6.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.17' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.18":"###### iOS et Android\n1.  Repérer dans l’écran les médias temporels synchronisés pré-enregistrés avec des sous-titres de traduction.\n2.  Vérifier la présence d’une piste sonore qui serait la version vocalisée des sous-titres de traduction :\n    *   activer la piste sonore ;\n    *   vérifier que les sous-titres vocalisés correspondent aux sous-titres affichés.\n3.  Sinon :\n    *   vérifier la présence d’une fonctionnalité qui permet de vocaliser des sous-titres ;\n    *   activer la fonctionnalité ;\n    *   lancer la lecture du contenu multimédia ;\n    *   vérifier que les textes affichés par ce moyen sont vocalisés.\n4.  Sinon :\n    *   activer le **lecteur d’écran** et naviguer jusqu’au lecteur multimédia ;\n    *   activer les sous-titres de traduction ;\n    *   vérifier que les sous-titres vocalisés correspondent aux sous-titres affichés.\n5.  Sinon :\n    *   activer le **lecteur d’écran** et naviguer jusqu’au lecteur multimédia ;\n    *   activer les sous-titres de traduction dans le lecteur multimédia et lancer la vidéo ;\n    *   vérifier que les sous-titres affichés sont restitués par le lecteur d’écran.\n6.  Sinon :\n    *   rechercher la présence d’un média alternatif dont la bande son contient les sous-titres de traduction vocalisés ;\n    *   vérifier que les sous-titres affichés sont restitués par le lecteur d’écran.\n7.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.18' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.2":"###### iOS et Android\n1.  Repérer dans l’écran les transcriptions textuelles des médias temporels seulement audio.\n2.  Vérifier que chaque transcription textuelle est pertinente (toutes les informations sonores importantes sont présentes, les dialogues notamment).\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.3":"###### iOS et Android\n1.  Repérer dans l’écran les médias temporels seulement vidéo qui nécessitent une transcription textuelle.\n2.  Vérifier :\n    *   la présence d’une version alternative audio seulement accessible via un composant adjacent (un bouton ou un lien) ;\n    *   ou la présence d’une version alternative audio seulement adjacente ;\n    *   ou la présence d’une transcription textuelle adjacente (un bouton ou un lien) ;\n    *   ou la présence d’une transcription textuelle adjacente clairement identifiable ;\n    *   ou la présence d’une audiodescription synchronisée ;\n    *   ou la présence d’une version alternative avec une audiodescription synchronisée accessible via un composant adjacent (un bouton ou un lien).\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.3' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.4":"###### iOS et Android\n1.  Repérer dans l’écran les médias temporels seulement vidéo avec une alternative (transcription textuelle ou une version audio seulement).\n2.  Si la transcription textuelle est présente, vérifier :\n    *   que celle-ci est pertinente (toutes les informations sonores ou visuelles importantes sont présentes, les dialogues et les textes incrustés notamment).\n3.  Si une audiodescription est présente, vérifier :\n    *   que celle-ci est pertinente (toutes les informations visuelles importantes sont présentes) ;\n    *   et que celle-ci est correctement synchronisée (la bande-son de l’audiodescription coïncide correctement avec la bande vidéo).\n4.  Si une version « audio seulement » est présente, vérifier :\n    *   que celle-ci est pertinente (toutes les informations sonores ou visuelles importantes sont présentes, les dialogues et les textes incrustés notamment).\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.4' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.5":"###### iOS et Android\n1.  Repérer dans l’écran les médias temporels synchronisés qui nécessitent une transcription textuelle.\n2.  Vérifier :\n    *   la présence d’une transcription textuelle adjacente clairement identifiable ;\n    *   ou la présence d’une transcription textuelle accessible via un composant adjacent (un bouton ou un lien) ;\n    *   ou la présence d’une audiodescription synchronisée ;\n    *   ou la présence d’une version alternative avec une audiodescription synchronisée accessible via un composant adjacent (un bouton ou un lien).\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.5' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.6":"###### iOS et Android\n1.  Repérer dans l’écran les médias temporels synchronisés avec une audiodescription ou une transcription textuelle.\n2.  Si une audiodescription est présente, vérifier :\n    *   que celle-ci est pertinente (toutes les informations visuelles importantes sont présentes) ;\n    *   et que celle-ci est correctement synchronisée (la bande-son de l’audiodescription coïncide correctement avec la bande vidéo).\n3.  Si une transcription textuelle est présente, vérifier :\n    *   que celle-ci est pertinente (toutes les informations sonores ou visuelles importantes sont présentes, les dialogues et les textes incrustés notamment).\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.6' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.7":"###### iOS et Android\n1.  Repérer dans l’écran les médias temporels synchronisés pré-enregistrés et les médias temporels synchronisés en direct qui nécessitent des sous-titres (c’est-à-dire dont la bande son apporte de l’information, comme le discours d’une personne).\n2.  Vérifier :\n    *   qu’il existe des sous-titres synchronisés ;\n    *   ou qu’il existe une version alternative possédant des sous-titres synchronisés accessible via un composant adjacent (un bouton ou un lien).\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.7' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.8":"###### iOS et Android\n1.  Repérer dans l’écran les médias temporels synchronisés pré-enregistrés et les médias temporels synchronisés en direct possédant des sous-titres.\n2.  Vérifier que les sous-titres sont :\n    *   pertinents (toutes les informations sonores importantes sont présentes, les dialogues notamment) ;\n    *   dans la langue de la vidéo ;\n    *   et correctement synchronisés. Si vous n’observez pas de décalage entre le discours oralisé et l’apparition des sous-titres, les sous-titres sont correctement synchronisés. La norme de référence spécifie que les sous-titres doivent apparaître dans les 100 ms suivant l’[horodatage du sous-titre](glossaire.md#horodatage-time-stamp).\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.8' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"3.9":"###### iOS et Android\n1.  Repérer dans l’écran les médias temporels pré-enregistrés seulement vidéo et synchronisés qui nécessitent une audiodescription.\n2.  Vérifier :\n    *   la présence d’une audiodescription synchronisée ;\n    *   ou la présence d’une version alternative avec une audiodescription synchronisée adjacente ou accessible via un composant adjacent (un bouton ou un lien).\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '3.9' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"4.1":"###### iOS et Android\n1.  Repérer dans l’écran les tableaux de données complexes.\n2.  Activer le **lecteur d’écran**.\n3.  Vérifier :\n    *   qu’un résumé est restitué lorsque le lecteur d’écran atteint le tableau ;\n    *   ou qu’un résumé est disponible avant le tableau, sous la forme d’un texte précédant le tableau.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '4.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"4.2":"###### iOS et Android\n1.  Vérifier que chaque résumé de tableau est pertinent, c’est-à-dire qu’il permet de comprendre la nature des données et la construction du tableau.\n2.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '4.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"4.3":"###### iOS et Android\n1.  Repérer dans l’écran les tableaux de données.\n2.  Activer le **lecteur d’écran**.\n3.  Vérifier qu’un titre est restitué lorsque le lecteur d’écran atteint le tableau.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '4.3' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"4.4":"###### iOS et Android\n1.  Vérifier que chaque titre de tableau de données est pertinent, c’est-à-dire qu’il permet d’identifier la nature des données présentées dans le tableau.\n2.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '4.4' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"4.5":"###### iOS et Android\n1.  Repérer dans l’écran les tableaux de données.\n2.  Activer le **lecteur d’écran** et parcourir les cellules de données.\n3.  Vérifier que les entêtes sont correctement restitués.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '4.5' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"5.1":"Le test le plus complet est un test de restitution avec un lecteur d’écran. En effet, tous les éléments à évaluer, s’ils sont présents, sont restitués par les lecteurs d’écran. D’autres tests avec d’autres technologies d’assistance peuvent être nécessaires pour s’assurer de la compatibilité. Plusieurs méthodes d’évaluation plus ou moins complètes vous sont décrites.\nPlusieurs méthodes sont disponibles avec iOS, mais seul le test avec VoiceOver est le test qui permet d’évaluer l’ensemble des éléments demandé par le critère.\nDe plus, il n’existe pas comme pour le web de documentation technique permettant de décrire le fonctionnement et les implémentations attendues (par exemple pour les fenêtres modales ou les potentiomètres). En l’absence d’une telle documentation, afin d’évaluer au plus juste ce type de composant il est conseillé tout de même de se rapprocher :\n*   de ce que décrit [la spécification ARIA pour les modèles de conception](https://www.w3.org/TR/wai-aria-practices-1.1/) ;\n*   des [documentations des éditeurs de plateformes dédiées aux développeurs](methodologie.md#ressources-des-editeurs).\n###### iOS avec VoiceOver\n1.  Activer le **lecteur d’écran**.\n2.  Repérer dans l’écran les composants interactifs (par exemple, bouton, lien).\n3.  Accéder à chaque composant interactif en utilisant les gestes du lecteur d’écran.\n4.  Vérifier :\n    *   qu’un rôle est restitué (par exemple, bouton, zone de modification, lien) ;\n    *   que le rôle restitué est pertinent au regard de la fonctionnalité associée (par exemple, un composant qui déclenche l’ouverture d’une fenêtre modale et qui est restitué « zone de modification » a un rôle non pertinent, il devrait être identifié comme un bouton) ;\n    *   qu’un nom est restitué et que ce nom est pertinent, c’est-à-dire qu’il permet de comprendre la fonction de l’élément (pour les champs de formulaire, on se reportera à la thématique « Formulaires » pour les évaluer) ;\n    *   que si le composant possède un nom visible (un texte visible), l’intitulé est restitué ;\n    *   que si le composant a un état perceptible (activé, désactivé, sélectionné), cet état est restitué ;\n    *   que si le composant peut changer d’état (par exemple bouton à bascule, potentiomètre), réaliser les actions nécessaires pour tester les différents états et vérifier que chaque changement d’état est correctement restitué (le passage à l’état sélectionné, l’augmentation du potentiomètre) ;\n    *   que si le composant a une valeur perceptible (valeur d’un potentiomètre), cette valeur est restituée.\n5.  Si c’est le cas, le critère est validé.\n###### iOS Avec **Accessibility Inspector**{lang=en}\n1.  Connecter le terminal mobile iOS à l’ordinateur avec macOS.\n2.  Activer le logiciel **Accessibility Inspector**{lang=en}.\n3.  Choisir le terminal mobile comme source et rester sur l’onglet « Inspection » (boutons en haut à droite).\n4.  Avec les flèches de _Accessibility Inspector_{lang=en}, accéder à chaque élément de l’interface.\n5.  Vérifier :\n    *   qu’un rôle est disponible dans le paramètre « _Traits_{lang=en} » (par exemple, _Bouton, Tab, Text Field_{lang=en}) ;\n    *   que le rôle est pertinent au regard de la fonctionnalité associée (par exemple, un composant qui déclenche l’ouverture d’une fenêtre modale et qui est présenté comme _Static text_{lang=en} a un rôle non pertinent, il devrait être identifié comme un bouton) ;\n    *   qu’un nom est disponible dans le paramètre « Label » et que ce nom est pertinent, c’est-à-dire qu’il permet de comprendre la fonction de l’élément (pour les champs de formulaire, on se reportera à la thématique « Formulaires » pour les évaluer) ;\n    *   que si le composant possède un nom visible (un texte visible), l’intitulé défini dans le paramètre « Label » contient au moins cet intitulé.\n6.  Si le composant a un état perceptible (activé, désactivé, sélectionné), vérifier que cet état :\n    *   est disponible dans le paramètre « _Traits_{lang=en} » ;\n    *   ou est indiqué dans le paramètre « Label ».\n7.  Si le composant peut changer d’état (par exemple bouton à bascule, potentiomètre), réaliser les actions nécessaires pour tester les différents états et vérifier que chaque changement d’état (le passage à l’état sélectionné, l’augmentation du potentiomètre) :\n    *   est disponible dans le paramètre « _Traits_{lang=en} » ;\n    *   ou est indiqué dans le paramètre « Label ».\n8.  Si c’est le cas, le critère est validé.\n###### iOS Avec le contrôle vocal\nL’application de contrôle vocal permet aux utilisateurs de naviguer à la voix.\nLe critère 5.1 dans sa globalité ne peut pas être évalué avec le contrôle vocal, mais une fonctionnalité du contrôle vocal (l’affichage des libellés) permet d’avoir une vue d’ensemble rapide de l’état des composants interactifs.\nLe contrôle vocal va permettre de déceler les composants utilisables au toucher qui ne sont pas des composants interactifs détectables par les technologies d’assistance, la présence d’un intitulé et sa pertinence, et la présence du nom visible dans le nom accessible.\n1.  Activer le contrôle vocal : _Réglages > Accessibilité > Contrôle vocal_.\n2.  Afficher les libellés des composants interactifs : depuis l’écran de paramètres du contrôle vocal, atteindre le bouton « Superposition » et l’activer, puis choisir « Noms des éléments ».\n3.  Dorénavant, lorsque le contrôle vocal sera activé, des infobulles grises apparaîtront au-dessus des éléments interactifs qui ont des labels. À noter que si l’écran possède un très grand nombre de contrôles interactifs, les labels s’afficheront par groupes successifs (un groupe de label disparaît et un autre apparaît).\nCe qu’il faut savoir : seuls les éléments qui ont des rôles interactifs reconnus par l’API d’accessibilité posséderont un label. Ceci va permettre de repérer rapidement quels éléments utilisables au toucher ne sont pas reconnus par le contrôle vocal et ne sont donc pas des éléments interactifs (ce qui constitue une non-conformité).\nProcédure :\n1.  Repérer dans l’écran tous les contrôles interactifs (activables au toucher).\n2.  Activer le contrôle vocal et vérifier que tous les contrôles interactifs identifiés possèdent un label associé (infobulle grise).\n3.  Si c’est le cas, vérifier que :\n    *   le label associé est pertinent ;\n    *   et que le nom visible (s’il en possède un) est compris dans ce label.\n4.  Si c’est le cas, les conditions sur la pertinence de l’intitulé et la présence du nom visible dans le nom accessible sont remplies.\n###### Android\n1.  Activer le **lecteur d’écran**.\n2.  Repérer dans l’écran les composants interactifs (par exemple, bouton, lien).\n3.  Accéder à chaque composant interactif avec les gestes du lecteur d’écran.\n4.  Vérifier :\n    *   qu’un rôle est restitué (par exemple, bouton, zone de modification, lien) ;\n    *   que le rôle restitué est pertinent au regard de la fonctionnalité associée (par exemple, un composant qui déclenche l’ouverture d’une fenêtre modale et qui est restitué « zone de modification » a un rôle non pertinent, il devrait être identifié comme un bouton) ;\n    *   qu’un nom est restitué et que ce nom est pertinent, c’est-à-dire qu’il permet de comprendre la fonction de l’élément (pour les champs de formulaire, on se reportera à la thématique [« Formulaires »](#topic-9) pour les évaluer) ;\n    *   que si le composant possède un nom visible (un texte visible), l’intitulé est restitué ;\n    *   que si le composant a un état perceptible (activé, désactivé, sélectionné), cet état est restitué ;\n    *   que si le composant peut changer d’état (par exemple bouton à bascule, potentiomètre), réaliser les actions nécessaires pour tester les différents états et vérifier que chaque changement d’état est correctement restitué (le passage à l’état sélectionné, l’augmentation du potentiomètre) ;\n    *   que si le composant a une valeur perceptible (valeur d’un potentiomètre), cette valeur est restituée.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '5.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"5.2":"Il s’agit ici de s’assurer que le composant peut être utilisé par le lecteur d’écran, le contrôle vocal, un clavier externe ou tout autre commutateur externe. On peut limiter les tests à quelques dispositifs de pointage puisque les caractéristiques nécessaires (sur les composants interactifs) sont semblables.\nIl est néanmoins nécessaire de tester au moins avec le lecteur d’écran et un clavier externe.\nPour le clavier externe, [certains paramétrages sont nécessaires pour que le périphérique soit pleinement fonctionnel](methodologie.md#clavier-externe).\n###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Parcourir l’ensemble des composants interactifs.\n3.  Vérifier :\n    *   qu’il peut être atteint avec le lecteur d’écran ;\n    *   qu’il peut être activé avec le lecteur d’écran.\n4.  Si c’est un composant modifiable (champ de saisie, case à cocher, potentiomètre), vérifier qu’il peut être modifié avec le lecteur d’écran.\n5.  Connecter un **clavier externe** (et [paramétrer la navigation au clavier](methodologie.md#clavier-externe)).\n6.  Parcourir l’ensemble des composants interactifs.\n7.  Vérifier :\n    *   qu’il peut être atteint avec les touches du clavier ;\n    *   qu’il peut être activé avec la touche dédiée du clavier.\n8.  Si c’est un composant modifiable (champ de saisie, case à cocher, potentiomètre), vérifier qu’il peut être modifié avec les touches du clavier.\n9.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '5.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"5.3":"###### iOS et Android\n1.  Repérer dans l’écran tous les événements qui initient un changement de contexte, par exemple :\n    *   une mise à jour dynamique de champs de formulaire ;\n    *   l’ouverture d’une nouvelle page sur la sélection d’une entrée de liste ;\n    *   la mise à jour d’une partie essentielle de l’écran sans action de l’utilisateur ;\n    *   le lancement automatique d’un lecteur vidéo sur la sélection d’une playlist ;\n    *   la manipulation du focus ayant pour résultat de modifier la position courante de l’utilisateur dans l’écran.\n2.  Vérifier :\n    *   que l’utilisateur est averti par un texte du type de changement avant son déclenchement ;\n    *   ou que le changement de contexte est initié par un bouton ou un lien explicite.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '5.3' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"5.4":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Réaliser les actions nécessaires à l’apparition d’un message de statut par exemple :\n    *   remplir correctement un formulaire et le valider pour faire apparaître un message indiquant l’envoi avec succès ;\n    *   soumettre un formulaire avec des champs obligatoires sans saisie pour faire apparaître un message indiquant la présence d’erreurs ;\n    *   afficher un écran qui nécessite un certain temps de chargement pour faire apparaître un message de progression ou un indicateur de progression de chargement.\n3.  Vérifier que lorsque le statut apparaît, le lecteur d’écran restitue l’information et que cette information est compréhensible.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '5.4' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"5.5":"###### iOS et Android\n1.  Repérer dans l’écran les contrôles à bascule (boutons avec un ou plusieurs états, par exemple, cases à cocher, bouton radio, _switch_{lang=en}).\n2.  Vérifier qu’il est possible de déterminer l’état du contrôle sur la base de sa présentation dans l’interface (par exemple, un changement de forme lorsque le contrôle passe d’un état à l’autre).\n3.  Activer le **lecteur d’écran** et naviguer jusqu’au contrôle.\n4.  Vérifier que l’état du contrôle est restitué par le lecteur d’écran sans avoir à interagir avec le contrôle.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '5.5' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"6.1":"###### iOS\n1.  Aller dans _Réglages > Accessibilité > VoiceOver > Parole_ et activer le paramètre « Détecter les langues ».\n2.  Activer le **lecteur d’écran** et parcourir l’ensemble des éléments de l’écran.\n3.  Vérifier que le texte est restitué dans la langue principale de l’écran.\n4.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Aller dans _Paramètres > Accessibilité > TalkBack > Paramètres > Synthèse vocale_ (selon la version de la plateforme, le chemin d’accès peut être différent) :\n    *   Vérifier que le paramètre « Moteur préféré » est « Synthèse vocale Google » ;\n    *   Activer les paramètres de la synthèse (bouton à droite de « Moteur préféré ») et vérifier que le paramètre « Détection de la langue » est sur « Forcée ».\n2.  Activer le **lecteur d’écran** et parcourir l’ensemble des éléments de l’écran.\n3.  Vérifier que les textes sont restitués dans la langue principale de l’écran.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '6.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"6.2":"Dans ce critère, on ne contrôle que les éléments qui ne doivent pas être interactifs (les éléments texte, les tableaux par exemple).\n###### iOS avec VoiceOver\n1.  Activer le **lecteur d’écran** et parcourir l’ensemble des éléments de l’écran.\n2.  Vérifier que le rôle restitué par le lecteur d’écran correspond à la nature de l’élément (par exemple, lorsque le lecteur d’écran atteint ce qui apparaît comme un paragraphe et qu’il restitue « Bouton », il s’agit d’une erreur, aucun rôle n’est restitué sur les paragraphes).\n3.  Si c’est le cas, le critère est validé.\n###### iOS Avec _Accessibility Inspector_{lang=en}\n1.  Connecter le terminal mobile iOS à l’ordinateur avec macOS.\n2.  Activer le logiciel **Accessibility Inspector**{lang=en}.\n3.  Choisir le terminal mobile comme source et rester sur l’onglet « Inspection » (boutons en haut à droite).\n4.  Avec les flèches de _Accessibility Inspector_{lang=en}, accéder à chaque élément de l’interface.\n5.  Vérifier que le rôle disponible dans le paramètre « _Traits_{lang=en} » est pertinent au regard de la nature de l’élément associé (par exemple, un simple texte qui aurait un rôle de bouton serait considéré non conforme, il devrait être identifié comme un texte statique).\n6.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Activer le **lecteur d’écran** et parcourir l’ensemble des éléments de l’écran.\n2.  Vérifier que le rôle restitué par le lecteur d’écran correspond à la nature de l’élément (par exemple, lorsque le lecteur d’écran atteint ce qui apparaît comme un paragraphe et qu’il restitue « Bouton », il s’agit d’une erreur, aucun rôle n’est restitué sur les paragraphes).\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '6.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"7.1":"###### iOS avec VoiceOver\n1.  Activer le **lecteur d’écran**.\n2.  Utiliser le rotor et sélectionner « En-têtes ».\n3.  Parcourir les entêtes en glissant un doigt vers le haut ou vers le bas.\n4.  Vérifier :\n    *   que chaque texte qui structure l’écran peut être atteint ;\n    *   que chaque entête atteint est pertinent, c’est-à-dire :\n        *   que le titre est utile à la structuration de l’écran ;\n        *   que le texte contenu dans le titre permet de comprendre le contenu de la section titrée.\n5.  Si c’est le cas, le critère est validé.\n###### iOS avec _Accessibility Inspector_{lang=en}\n1.  Connecter le terminal mobile iOS à l’ordinateur avec macOS.\n2.  Activer le logiciel **Accessibility Inspector**{lang=en}.\n3.  Choisir le terminal mobile comme source et rester sur l’onglet « Inspection » (boutons en haut à droite).\n4.  Avec les flèches de _Accessibility Inspector_{lang=en}, accéder à chaque élément de l’interface.\n5.  Vérifier :\n    *   que pour chaque texte qui structure l’écran, le paramètre « _Traits_{lang=en} » contient la valeur « En-têtes » ;\n    *   que chaque texte dont le paramètre « _Traits_{lang=en} » contient la valeur « En-têtes » est pertinent, c’est-à-dire :\n        *   que le titre ainsi déclaré est utile à la structuration de l’écran ;\n        *   que le texte contenu dans le titre permet de comprendre le contenu de la section ainsi titrée.\n6.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Activer le **lecteur d’écran**.\n2.  Utiliser le menu des commandes de lecture et sélectionner « Titres ».\n3.  Parcourir les titres en glissant un doigt vers le haut ou vers le bas.\n4.  Vérifier :\n    *   que chaque texte qui structure l’écran est atteint de cette manière et est restitué comme titre ;\n    *   que chaque titre atteint est pertinent, c’est-à-dire :\n        *   que le titre est utile à la structuration de l’écran ;\n        *   que le texte contenu dans le titre permet de comprendre le contenu de la section ainsi titrée.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '7.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"7.2":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Repérer dans l’écran les éléments [regroupés visuellement sous forme de liste](glossaire.html#listes).\n3.  Vérifier que le lecteur d’écran restitue « Liste » lorsqu’il atteint le groupe d’éléments.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '7.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"8.1":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Parcourir l’ensemble des éléments en utilisant les gestes du lecteur d’écran.\n3.  Vérifier que l’ensemble des informations visibles à l’écran sont restituées par le lecteur d’écran.\n4.  Si c’est le cas, le critère est validé.\nNote : Dans les applications, il est possible de réaliser des regroupements d’éléments. Par exemple, dans un catalogue de produits, chaque item possède un titre, un prix et une description. Au lieu de prendre le focus avec le lecteur d’écran sur chacun des 3 items, l’application peut être conçue pour que le lecteur d’écran accède seulement à l’item dans sa globalité, ainsi le lecteur d’écran restitue l’ensemble des informations sans que l’utilisateur ait à réaliser plusieurs gestes pour atteindre les 3 items. Ceci est conforme (voire encouragé puisque cela limite les actions à réaliser pour parcourir le contenu), il faut s’assurer que tous les textes contenus sont bien restitués par le lecteur d’écran."}'::jsonb
where identifier = '8.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"8.2":"###### iOS\n1.  Accéder aux paramètres de réglages des tailles de caractères de la plateforme : _Réglages > Accessibilité > Affichage et taille du texte > Police plus grande_.\n2.  Activer le bouton « Taille de police plus grande ».\n3.  Ouvrir le centre de contrôle et activer le [paramètre « Taille du texte » (bouton « aA »)](methodologie.md#modifier-la-taille-de-police-sur-ios) pour afficher la jauge des tailles de police. Augmenter la valeur pour atteindre le palier 190%.\n4.  Si nécessaire, redémarrer l’application pour s’assurer que le paramètre est pris en compte par l’application.\n5.  Vérifier :\n    *   que tous les textes de l’interface ont été agrandis ;\n    *   que tous les textes de l’interface restent lisibles et les fonctionnalités utilisables ;\n    *   que des contenus ne disparaissent pas ;\n    *   si des textes ne sont pas agrandis ou ont disparu, qu’il existe une méthode dans l’écran pour afficher les textes à la demande (par exemple avec l’appui prolongé sur une icône).\n6.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Accéder aux paramètres de réglages des tailles de caractères de la plateforme : _Paramètres > Accessibilité > Taille de la police_ (selon la version de la plateforme, le chemin d’accès peut être différent) ;\n2.  Augmenter la valeur de la taille de la police (potentiomètre en bas de l’écran) au maximum (voir note technique).\n3.  Si nécessaire, redémarrer l’application pour s’assurer que le paramètre est pris en compte par l’application.\n4.  Vérifier :\n    *   que tous les textes de l’interface ont été agrandis ;\n    *   que tous les textes de l’interface restent lisibles et les fonctionnalités utilisables ;\n    *   que des contenus ne disparaissent pas ;\n    *   si des textes ne sont pas agrandis ou ont disparu, qu’il existe une méthode dans l’écran pour afficher les textes à la demande (par exemple avec l’appui prolongé sur une icône).\n5.  Si c’est le cas, le critère est validé.\n**Note technique** : Avant Android 14, sur les terminaux sans surcouche constructeur, le paramètre de taille de la police ne permet pas d’agrandir à 200% de la taille par défaut. Ce n’est qu’à partir d’Android 14 que cela est rendu possible. Si vous testez sur un terminal Android avec une version antérieure à 14, vous pouvez cumuler le paramètre de taille de la police et le paramètre de la taille de l’affichage pour atteindre un zoom approchant des 200%. À partir d’Android 14, le paramètre de taille de la police vous permet d’atteindre les 200%. À l’inverse, sur certaines versions d’Android, la jauge du potentiomètre peut être différente et offrir des valeurs qui permettent d’atteindre un zoom supérieur à 200%, il faudra alors vérifier que le test ne se fait que pour une valeur de 200%."}'::jsonb
where identifier = '8.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"8.3":"###### iOS\n1.  Activer l’option **Différencier sans couleur** (_Réglages > Accessibilité > Affichage et taille du texte > Différencier sans couleur_).\n2.  Activer l’option **Augmenter le contraste** (_Réglages > Accessibilité > Affichage et taille du texte > Augmenter le contraste_) ou s’il est présent dans l’application, activer le mécanisme de remplacement permettant d’afficher l’application avec un rapport de contraste suffisant.\n3.  Repérer dans l’écran les composants d’interface (liens, boutons) avec du texte intégrés dans un environnement de texte (dans une phrase par exemple), signifiés uniquement par la couleur (sans autre mise en forme qui les distingue du reste du texte dans lequel ils sont intégrés).\n4.  Activer le logiciel **Colour Contrast Analyser**{lang=en} sur l’ordinateur et capturer les couleurs du texte environnant et du composant interactif sur le terminal mobile, soit :\n    *   en [diffusant l’écran du terminal mobile sur l’ordinateur](methodologie.md#diffuser-l-ecran-du-terminal-mobile) ;\n    *   en réalisant des [captures d’écran](methodologie.md#realiser-des-captures-d-ecran) des éléments à évaluer (et en les important sur l’ordinateur).\n5.  Vérifier que le contraste entre la couleur de police du composant et la couleur de police du texte environnant est de 3:1, au moins.\n6.  Si c’est le cas, le critère est validé.\n###### Android\n1.  S’il existe dans l’application, activer le mécanisme de remplacement permettant d’afficher l’application avec un rapport de contraste suffisant.\n2.  Repérer dans l’écran les composants d’interface (liens, boutons) avec du texte intégrés dans un environnement de texte (dans une phrase par exemple) signifiés uniquement par la couleur (sans autre mise en forme qui les distingue du reste du texte dans lequel ils sont intégrés).\n3.  Activer le logiciel **Colour Contrast Analyser**{lang=en} sur l’ordinateur et capturer les couleurs du texte environnant et du composant interactif sur le terminal mobile, soit :\n    *   en [diffusant l’écran du terminal mobile sur l’ordinateur](methodologie.md#diffuser-l-ecran-du-terminal-mobile) ;\n    *   en réalisant des [captures d’écran](methodologie.md#realiser-des-captures-d-ecran) des éléments à évaluer (et en les important sur l’ordinateur).\n4.  Vérifier que le contraste entre la couleur de police du composant et la couleur de police du texte environnant est de 3:1, au moins.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '8.3' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"8.4":"###### iOS et Android\n1.  Repérer dans l’écran les composants d’interface (liens, boutons) avec du texte intégrés dans un environnement de texte (dans une phrase par exemple), signifiés uniquement par la couleur (sans autre mise en forme qui les distingue du reste du texte dans lequel ils sont intégrés).\n2.  Connecter un **clavier externe** (et [paramétrer la navigation au clavier](methodologie.md#clavier-externe)).\n3.  Vérifier que la visibilité du focus telle que définie au niveau du système est préservée sur ces éléments.\n4.  Connecter une **souris**.\n5.  Vérifier que le survol des composants interactifs en environnement de texte est signifié par un autre moyen que la couleur (mise en gras, soulignement par exemple).\n6.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '8.4' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"8.5":"###### iOS\n1.  Connecter un **clavier externe** (et [paramétrer la navigation au clavier](methodologie.md#clavier-externe)).\n2.  Activer tous les [paramètres disponibles de style de focus](methodologie.md#clavier-externe).\n3.  Naviguer au clavier dans l’application et vérifier si la visibilité du focus telle que définie au niveau du système est préservée sur l’ensemble des éléments de l’application.\n4.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Connecter un **clavier externe** et [paramétrer la navigation au clavier](methodologie.md#clavier-externe).\n2.  Naviguer au clavier dans l’application et vérifier :\n    *   si le test est réalisé sans activation d’un service d’accessibilité, que le focus est visible ;\n    *   si le test est réalisé avec l’activation d’un service d’accessibilité, que le focus tel que défini dans le service est visible sur l’ensemble des éléments de l’application.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '8.5' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"8.6":"###### iOS et Android\n1.  Repérer dans l’écran les informations données par la forme, la taille ou la position dans un texte, un élément graphique, un média temporel ou non temporel. Ce peut être une icône positionnée à gauche d’un composant pour signifier qu’il est actif, ou une consigne dans l’écran qui demande d’activer un composant positionné à un certain endroit dans l’écran.\n2.  Vérifier qu’il existe un autre moyen de récupérer cette information dans l’écran (par exemple, un texte lisible par tous qui donne la même information).\n3.  Si ce n’est pas le cas, activer le **lecteur d’écran** et vérifier qu’une information alternative à la forme, la taille ou la position et restituée par le lecteur d’écran.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '8.6' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"8.7":"###### iOS\n1.  Connecter un **clavier externe** (et [paramétrer la navigation au clavier](methodologie.md#clavier-externe)).\n2.  Parcourir l’écran et repérer les contenus additionnels qui apparaissent à la prise de focus sur un composant d’interface.\n3.  Vérifier que le contenu additionnel peut être masqué par une touche du clavier (la touche ESC par exemple).\n4.  Vérifier que le contenu additionnel reste visible :\n    *   jusqu’à ce que le focus soit déplacé en dehors du composant d’interface et du contenu additionnel ;\n    *   ou tant que le focus est positionné sur le composant d’interface ou dans le contenu additionnel ;\n    *   ou tant que le contenu additionnel est valide.\n5.  Connecter une **souris**.\n6.  Balayer l’écran avec la souris et repérer les contenus additionnels qui apparaissent au survol d’un composant d’interface.\n7.  Vérifier que le contenu additionnel peut être survolé par la souris.\n8.  Vérifier que le contenu additionnel reste visible :\n    *   jusqu’à ce que le pointeur de la souris soit déplacé en dehors du composant d’interface et du contenu additionnel ;\n    *   ou tant que le pointeur de la souris survole le composant d’interface ou le contenu additionnel ;\n    *   ou tant que le contenu additionnel est valide.\n9.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Connecter un **clavier externe** (et [paramétrer la navigation au clavier](methodologie.md#clavier-externe)).\n2.  Parcourir l’écran et repérer les contenus additionnels qui apparaissent à la prise de focus sur un composant d’interface.\n3.  Vérifier que le contenu additionnel peut être masqué par une touche du clavier (généralement la touche ou la combinaison de touches qui aura été associée dans _Switch Access_{lang=en} pour le paramètre _Retour_)\n4.  Vérifier que le contenu additionnel reste visible :\n    *   jusqu’à ce que le focus soit déplacé en dehors du composant d’interface et du contenu additionnel ;\n    *   ou tant que le focus est positionné sur le composant d’interface ou dans le contenu additionnel ;\n    *   ou tant que le contenu additionnel est valide.\n5.  Connecter une **souris**.\n6.  Balayer l’écran avec la souris et repérer les contenus additionnels qui apparaissent au survol d’un composant d’interface.\n7.  Vérifier que le contenu additionnel peut être survolé par la souris.\n8.  Vérifier que le contenu additionnel reste visible :\n    *   jusqu’à ce que le pointeur de la souris soit déplacé en dehors du composant d’interface et du contenu additionnel ;\n    *   ou tant que le pointeur de la souris survole le composant d’interface ou le contenu additionnel ;\n    *   ou tant que le contenu additionnel est valide.\n9.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '8.7' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"9.1":"###### iOS et Android\n1.  Repérer dans l’écran les champs de formulaire (champ de saisie, bouton radio, case à cocher).\n2.  Vérifier la présence d’une étiquette visible adjacente.\n3.  Activer le champ de formulaire (par exemple, saisir du texte).\n4.  Vérifier que l’étiquette reste visible.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '9.1' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"9.10":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Remplir les champs de formulaire avec des valeurs susceptibles de provoquer des erreurs de saisies (entrer une adresse e-mail mal formée par exemple).\n3.  Valider le formulaire.\n4.  Pour chaque champ en erreur qui possède un contrôle du format, vérifier la présence d’un exemple réel de saisie dans le message d’erreur (par exemple, pour une adresse _e-mail_{lang=en}, vérifier la mention d’une adresse réelle sur le modèle « jean.schmitt@accessibilite.lu »).\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '9.10' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"9.11":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Remplir le formulaire.\n3.  Pour chaque donnée à caractère financier (par exemple, une indication de revenu), juridique (par exemple, une référence d’acte administratif), personnelle (par exemple, un numéro de téléphone), pour chaque formulaire qui transmet des réponses à un test ou à un examen, vérifier que l’utilisateur peut :\n    *   [modifier ou annuler les données et les actions effectuées](glossaire.md#modifier-ou-annuler-les-donnees-et-les-actions-effectuees) sur ces données en cours de saisie (par exemple la saisie du champ et la fonctionnalité d’annulation d’édition de la plateforme ne sont pas désactivées) ;\n    *   ou confirmer, de manière explicite, l’envoi de ces données via un mécanisme dédié (par exemple, un champ de formulaire ou une étape supplémentaire).\n4.  Pour chaque formulaire qui modifie ou supprime des données (par exemple la suppression d’une adresse postale), vérifier que l’utilisateur peut :\n    *   récupérer les données supprimées en cours de saisie ;\n    *   ou confirmer, de manière explicite, la suppression de ces données via un mécanisme dédié (par exemple, un champ de formulaire ou une étape supplémentaire).\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '9.11' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"9.12":"###### iOS\n1.  Accéder à chacun des champs de formulaire (taper sur le champ de saisie par exemple pour activer l’apparition des contrôles de saisie).\n2.  Pour chaque champ qui attend une donnée personnelle sur l’utilisateur, vérifier que les [contrôles natifs adéquats de la plateforme](glossaire.md#controles-natifs-de-la-plateforme) sont présentés à l’utilisateur. Par exemple :\n    *   pour un champ demandant la saisie de l’adresse _e-mail_{lang=en} de l’utilisateur, le clavier présenté possède le caractère @ sans que l’utilisateur ait de manipulation de clavier à réaliser (comme afficher le clavier secondaire) ;\n    *   pour un champ demandant la saisie d’un numéro de téléphone, le pavé numérique est présenté directement à l’utilisateur ;\n    *   etc.\n3.  Vérifier que le formulaire est compatible avec un mécanisme de remplissage automatique. Par exemple, iOS permet un remplissage automatique des champs sur la base des dernières valeurs saisies en fonction de leur nature (adresse postale, ville, nom, prénom, adresse _e-mail_{lang=en}). Vérifier que des valeurs pertinentes sont suggérées sur ces champs.\n4.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Accéder à chacun des champs de formulaire (taper sur le champ de saisie par exemple pour activer l’apparition des contrôles de saisie).\n2.  Pour chaque champ qui attend une donnée personnelle sur l’utilisateur, vérifier que les [contrôles natifs adéquats de la plateforme](glossaire.md#controles-natifs-de-la-plateforme) sont présentés à l’utilisateur. Par exemple :\n    *   pour un champ demandant la saisie de l’adresse _e-mail_{lang=en} de l’utilisateur, le clavier présenté possède le caractère @ sans que l’utilisateur ait de manipulation de clavier à réaliser (comme afficher le clavier secondaire) ;\n    *   pour un champ demandant la saisie d’un numéro de téléphone, le pavé numérique est présenté directement à l’utilisateur ;\n    *   etc.\n3.  Vérifier que le formulaire est compatible avec un mécanisme de remplissage automatique. Par exemple, Google fournit un système de remplissage automatique sur Android. Aller dans _Paramètres > Système > Langues et saisie > Paramètres avancés > Service de saisie automatique_ (selon la version de la plateforme, le chemin d’accès peut être différent) pour activer et paramétrer les données.\n4.  Sur le formulaire de l’application, vérifier que le système vous propose une option pour remplir automatiquement avec les données renseignées.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '9.12' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"9.2":"###### iOS avec VoiceOver\n1.  Activer le **lecteur d’écran**.\n2.  Naviguer jusqu’aux éléments de formulaire en utilisant les gestes du lecteur d’écran.\n3.  Vérifier qu’une étiquette est restituée lorsque le focus du lecteur d’écran est sur le champ de formulaire.\n4.  Si c’est le cas, le critère est validé.\n###### iOS avec le contrôle vocal\n1.  Activer le **contrôle vocal**.\n2.  Repérer dans l’écran tous les champs de formulaire.\n3.  Vérifier qu’une étiquette est détectée par le contrôle vocal (apparition d’une infobulle grise au-dessus du champ).\n4.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Activer le **lecteur d’écran**.\n2.  Naviguer jusqu’aux éléments de formulaire en utilisant les gestes du lecteur d’écran.\n3.  Vérifier qu’une étiquette est restituée lorsque le focus du lecteur d’écran est sur le champ de formulaire.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '9.2' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"9.3":"###### iOS avec VoiceOver\n1.  Activer le **lecteur d’écran**.\n2.  Naviguer jusqu’aux éléments de formulaire en utilisant les gestes du lecteur d’écran.\n3.  Vérifier :\n    *   que l’étiquette restituée par le lecteur d’écran est pertinente (elle permet de comprendre la nature de la saisie attendue) ;\n    *   que l’étiquette visible est contenue dans l’étiquette restituée par le lecteur d’écran.\n4.  Si c’est le cas, le critère est validé.\n###### Avec le contrôle vocal\n1.  Activer le **contrôle vocal**.\n2.  Repérer dans l’écran tous les champs de formulaire.\n3.  Vérifier :\n    *   que l’étiquette détectée par le contrôle vocal (infobulle grise) est pertinente (elle permet de comprendre la nature de la saisie attendue) ;\n    *   que l’étiquette visible est contenue dans l’étiquette détectée par le contrôle vocal (infobulle grise).\n4.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Activer le **lecteur d’écran**.\n2.  Naviguer jusqu’aux éléments de formulaire en utilisant les gestes du lecteur d’écran.\n3.  Vérifier :\n    *   que l’étiquette restituée par le lecteur d’écran est pertinente (elle permet de comprendre la nature de la saisie attendue) ;\n    *   que l’étiquette visible est contenue dans l’étiquette restituée par le lecteur d’écran.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '9.3' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"9.4":"###### iOS et Android\n1.  Repérer dans l’écran tous les champs de formulaire.\n2.  Pour chaque champ de formulaire, vérifier que l’étiquette visible est accolée au champ auquel elle est liée.\n3.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '9.4' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"9.5":"2 méthodes d’évaluation sur iOS sont proposées. Les deux méthodes aboutissent aux mêmes résultats. Une seule de ces méthodes est nécessaire pour évaluer le critère sur iOS.\n###### iOS avec VoiceOver\n1.  Activer le **lecteur d’écran**.\n2.  Naviguer jusqu’aux boutons de formulaire en utilisant les gestes du lecteur d’écran.\n3.  Vérifier :\n    *   que l’intitulé restitué par le lecteur d’écran est pertinent (il permet de comprendre l’action du bouton) ;\n    *   que l’intitulé visible est contenu dans l’intitulé restitué par le lecteur d’écran.\n4.  Si c’est le cas, le critère est validé.\n###### iOS avec le contrôle vocal\n1.  Activer le **contrôle vocal**.\n2.  Repérer dans l’écran les boutons de formulaire.\n3.  Vérifier :\n    *   que l’intitulé détecté par le contrôle vocal (infobulle grise) est pertinent (il permet de comprendre l’action du bouton) ;\n    *   que l’intitulé visible est contenu dans l’intitulé détecté par le contrôle vocal (infobulle grise) ;\n4.  Si c’est le cas, le critère est validé.\n###### Android\n1.  Activer le **lecteur d’écran**.\n2.  Naviguer jusqu’aux boutons de formulaire en utilisant les gestes du lecteur d’écran.\n3.  Vérifier :\n    *   que l’intitulé restitué par le lecteur d’écran est pertinent (il permet de comprendre l’action du bouton) ;\n    *   que l’intitulé visible est contenu dans l’intitulé restitué par le lecteur d’écran.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '9.5' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"9.6":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Repérer dans l’écran les champs de même nature qui nécessitent d’être regroupés (par exemple, les champs de saisies des différentes suites de chiffres d’un code de carte bleue).\n3.  Vérifier :\n    *   qu’une information est restituée à la prise de focus sur le premier champ, qui permette d’identifier le groupe auquel appartient le champ (bien que cela soit important pour les utilisateurs, il n’est pas requis que l’information du regroupement soit restituée sur chacun des champs de formulaire, mais seulement au moins sur le premier champ du regroupement) ;\n    *   que l’information restituée est pertinente, c’est-à-dire qu’elle permet de comprendre quelle est la nature du regroupement.\n4.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '9.6' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"9.7":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Valider le formulaire sans saisir de données afin d’identifier les champs obligatoires.\n3.  Pour chaque champ obligatoire, vérifier :\n    *   que les informations restituées par le lecteur d’écran à la prise de focus sur le champ contiennent la mention du caractère obligatoire ;\n    *   et qu’une [indication visible](glossaire.md#indication-de-champ-obligatoire) à proximité du champ indique le caractère obligatoire du champ de formulaire.\n4.  Si l’[indication visible](glossaire.md#indication-de-champ-obligatoire) est réalisée de manière non textuelle (icône, « \\* », « ! », etc.), l’explication de la signification de cette indication se situe visuellement et dans l’ordre de lecture, avant la première utilisation de l’indication.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '9.7' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"9.8":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Remplir les champs de formulaire avec des valeurs susceptibles de provoquer des erreurs de saisies (entrer une adresse _e-mail_{lang=en} mal formée par exemple).\n3.  Valider le formulaire.\n4.  Pour chaque champ de formulaire obligatoire qui possède un contrôle du format (qui sera présenté avec une erreur après la validation), vérifier :\n    *   que le type de données et/ou le format attendu sont restitués par le lecteur d’écran à la prise de focus sur le champ ;\n    *   qu’un texte visible à proximité du champ indique le type de données et/ou le format attendu.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '9.8' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

update public.criteria set test_procedures = '{"9.9":"###### iOS et Android\n1.  Activer le **lecteur d’écran**.\n2.  Remplir les champs de formulaire avec des valeurs susceptibles de provoquer des erreurs de saisie (laisser un champ vide, entrer une adresse e-mail mal formée par exemple).\n3.  Valider le formulaire.\n4.  Pour chaque champ en erreur, vérifier :\n    *   que le message d’erreur est visible à proximité du champ ;\n    *   que le message d’erreur est restitué par le lecteur d’écran à la prise de focus sur le champ.\n5.  Si c’est le cas, le critère est validé."}'::jsonb
where identifier = '9.9' and thematic_id in (select id from public.thematics where reference_id = '55555555-5555-5555-5555-555555555555');

-- Vérification : au moins 300 critères enrichis (RGAA 106 + RAWeb 136 + RAAM 108).
do $$
declare n integer;
begin
  select count(*) into n from public.criteria where test_procedures is not null;
  if n < 300 then
    raise exception 'test_procedures: seulement % critères enrichis (attendu >= 300)', n;
  end if;
end $$;

commit;
